/* ── Request-scoped handle cache ──────────────────────────────────────
   Every call into the Sheets service is a network round trip costing
   tens of milliseconds, and `openById` opens the whole spreadsheet. A
   single request used to pay that repeatedly: sending one login code
   opened the spreadsheet three times and re-fetched the same two sheets
   with them.

   Apps Script runs one request per execution context, so a handle is
   safe to hold for the length of a request and must not outlive it.
   resetRequestIdentity() clears this at the top of every doGet/doPost,
   alongside the session and the reader-name directory.
   ──────────────────────────────────────────────────────────────────── */
let __SS_SPREADSHEET__ = null;
let __SS_SHEETS__ = null;
let __SS_HEADERS_CHECKED__ = null;
let __SS_QA_MODE__ = null;
let __SS_OTP_TTL__ = null;
let __SS_OTP_MAX_SENDS__ = null;
let __SS_OTP_SEND_WINDOW__ = null;

function resetSheetCache() {
  __SS_SPREADSHEET__ = null;
  __SS_SHEETS__ = null;
  __SS_HEADERS_CHECKED__ = null;
  __SS_QA_MODE__ = null;
  __SS_OTP_TTL__ = null;
  __SS_OTP_MAX_SENDS__ = null;
  __SS_OTP_SEND_WINDOW__ = null;
  __SS_SETTINGS__ = null;
  if (typeof resetDriveCache === "function") resetDriveCache();
}

/* ── Script settings, in one round trip ───────────────────────────────
   getProperty() is a network call each time it is used. The login path
   alone consults four settings (QA mode, the code lifetime, the send
   ceiling, the send window), which was four round trips for four small
   strings. getProperties() returns the lot in one, so it is fetched once
   per request and read from memory after that.
   ──────────────────────────────────────────────────────────────────── */
let __SS_SETTINGS__ = null;

function getScriptSettings() {
  if (__SS_SETTINGS__) return __SS_SETTINGS__;
  try {
    const bulk = PropertiesService.getScriptProperties().getProperties();
    if (bulk && typeof bulk === "object") {
      __SS_SETTINGS__ = bulk;
      return __SS_SETTINGS__;
    }
  } catch (err) {
    Logger.log("Bulk script settings unavailable, falling back: " + err);
  }
  return null;
}

function getScriptSetting(key) {
  const all = getScriptSettings();
  if (all) {
    const value = all[key];
    return (value === undefined || value === null) ? null : value;
  }

  // The bulk read is an OPTIMISATION, so it must never be the only path.
  // Treating a failed getProperties() as "no settings exist" would be
  // quietly catastrophic: SESSION_SECRET would read as missing, be
  // regenerated on every call, and invalidate every token already issued
  // — signing the whole site out, repeatedly, with nothing in the logs
  // but a stale-session message. One read per key is slower and correct.
  try {
    return PropertiesService.getScriptProperties().getProperty(key);
  } catch (err) {
    Logger.log("Script setting '" + key + "' unreadable: " + err);
    return null;
  }
}

function getSpreadsheet() {
  if (__SS_SPREADSHEET__) return __SS_SPREADSHEET__;
  if (!SPREADSHEET_ID) {
    throw new Error("SPREADSHEET_ID is not configured. Please bind this script to a Google Sheet or set the SPREADSHEET_ID script property.");
  }
  try {
    __SS_SPREADSHEET__ = SpreadsheetApp.openById(SPREADSHEET_ID);
    return __SS_SPREADSHEET__;
  } catch (e) {
    throw new Error("Could not open spreadsheet with ID: " + SPREADSHEET_ID + ". Error: " + e.toString());
  }
}

