function cleanupTestQARecords(data) {
  const blocked = requireTestQAMode(data);
  if (blocked) return blocked;
  const sheetSpecs = [
    ["OTP", ["id", "email", "otp", "expiresAt", "verified", "createdAt"]],
    ["Users", DB_SCHEMA.Users],
    ["Subscriptions", subscriptionHeadersRequired()],
    ["Books", getBookHeaders()],
    ["BookRequests", ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"]],
    ["BookRequestResponses", ["responseId", "requestId", "requesterEmail", "responderEmail", "responderBookId", "responderNote", "responseStatus", "chatId", "createdAt", "updatedAt"]],
    ["Chats", ['chatId', 'bookId', 'ownerEmail', 'requesterEmail', 'adminEmail', 'chatStatus', 'createdAt', 'swapId', 'chatType', 'requestId', 'responseId']],
    ["ChatMessages", ["messageId", "chatId", "senderEmail", "senderRole", "message", "createdAt", "mediaUrl", "mediaType"]],
    ["SwapRequests", []],
    ["Notifications", ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt', 'status', 'clearedAt']],
    ["reading_space", READING_SPACE_HEADERS],
    ["current_read_circles", CURRENT_READ_CIRCLE_HEADERS],
    ["current_read_members", CURRENT_READ_MEMBER_HEADERS],
    ["current_read_messages", CURRENT_READ_MESSAGE_HEADERS]
  ];
  const deleted = {};
  sheetSpecs.forEach(spec => {
    deleted[spec[0]] = deleteTestQARows(spec[0], spec[1]);
  });
  return { success: true, message: "TEST_QA records cleaned.", deleted };
}

function seedTestQARecords(data) {
  const blocked = requireTestQAMode(data);
  if (blocked) return blocked;
  const cleanup = cleanupTestQARecords(data);
  if (!cleanup.success) return cleanup;

  const now = new Date();
  const expiry = new Date(now.getTime());
  expiry.setFullYear(expiry.getFullYear() + 1);
  Object.keys(TEST_QA_ACCOUNTS).forEach(key => seedTestQAUser(TEST_QA_ACCOUNTS[key], now, expiry));

  const memberA = TEST_QA_ACCOUNTS.MEMBER_A;
  const bookSeeds = [
    ["FAVOURITE_ONLY", { favourite: true }],
    ["TBR_ONLY", { tbr: true, bookshelf: false }],
    ["BOOKSHELF_ONLY", { bookshelf: true }],
    ["PERMANENT_EXCHANGE", { bookshelf: true, permanent_exchange: true }],
    ["TEMPORARY_EXCHANGE", { bookshelf: true, temporary_exchange: true }],
    ["RENT", { bookshelf: true, rent: true }],
    ["SELL", { bookshelf: true, sell: true }],
    ["PENDING_APPROVAL", { bookshelf: true, permanent_exchange: true }, "Pending"]
  ];
  bookSeeds.forEach(seed => {
    seedTestQABook(memberA, seed[0], seed[1], seed[2] || "Approved", now);
    seedTestQAReadingSpace(memberA, seed[0], seed[1], now);
  });
  seedTestQACurrentRead(now);
  seedTestQABookRequest(now);
  recalculateBooksListedCount(TEST_QA_ACCOUNTS.MEMBER_A.email);
  recalculateBooksListedCount(TEST_QA_ACCOUNTS.MEMBER_B.email);
  recalculateBooksListedCount(TEST_QA_ACCOUNTS.MEMBER_C.email);

  return {
    success: true,
    message: "TEST_QA records seeded.",
    fixedOtp: TEST_QA_FIXED_OTP,
    accounts: TEST_QA_ACCOUNTS,
    cleanupAction: "cleanupTestQARecords",
    cleanup
  };
}

function redactPublicRequestText(value) {
  return String(value || '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email hidden]')
    .replace(/(?:\+?91[-\s]?)?[6-9]\d{9}\b/g, '[phone hidden]');
}

function getChatById(chatId) {
  const chatSheet = getOrCreateSheet('Chats', []);
  const chatHeaders = ensureSheetHeaders(chatSheet, ['chatId', 'bookId', 'ownerEmail', 'requesterEmail', 'adminEmail', 'chatStatus', 'createdAt', 'swapId', 'chatType', 'requestId', 'responseId']);
  const values = chatSheet.getDataRange().getValues();
  const chatIdx = chatHeaders.indexOf('chatId');
  const row = values.slice(1).find(r => r[chatIdx] === chatId);
  return row ? rowToObject(chatHeaders, row) : null;
}

function canAccessChat(chat, email) {
  const normEmail = normalizeEmail(email);
  if (!chat || !normEmail) return false;
  if (isAdminEmail(normEmail)) return true;
  return [chat.ownerEmail, chat.requesterEmail, chat.adminEmail].some(participant => normalizeEmail(participant) === normEmail);
}

function createChat(swapRequestId, participantA, participantB) {
  const sheet = getOrCreateSheet('Chats', []);
  const id = generateId('SS_CHAT_');
  const now = new Date();
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
  const row = new Array(headers.length).fill("");
  headers.forEach((h, i) => {
    if (h === 'id') row[i] = id;
    else if (h === 'swapRequestId') row[i] = swapRequestId;
    else if (h === 'participantA') row[i] = normalizeEmail(participantA);
    else if (h === 'adminEmail') row[i] = normalizeEmail(participantB); // If used as admin
    else if (h === 'chatStatus') row[i] = 'Active';
    else if (h === 'createdAt') row[i] = now;
  });
  sheet.appendRow(row);
  return id;
}

function createSwapTracking(swapRequestId) {
  const sheet = getOrCreateSheet('SwapTracking', []);
  const id = generateId('SS_TRAK_');
  const now = new Date();
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
  const row = new Array(headers.length).fill("");
  headers.forEach((h, i) => {
    if (h === 'id') row[i] = id;
    else if (h === 'swapRequestId') row[i] = swapRequestId;
    else if (h === 'senderToReceiverStatus') row[i] = 'Pending';
    else if (h === 'receiverToSenderStatus') row[i] = 'Pending';
    else if (h === 'isComplete') row[i] = 'No';
    else if (h === 'updatedAt') row[i] = now;
  });
  sheet.appendRow(row);
  return id;
}

function doGet(e) { return withPopups_(doGetHandler_, e); }

function doGetHandler_(e) {
  try {
    const action = e.parameter.action;

    // Resolve who is calling BEFORE any handler runs, from the signed
    // session token rather than from the request's own email parameters.
    // applyAuthenticatedIdentity then rewrites the caller-identity fields
    // in place, so every existing handler below keeps its current shape
    // but is now reading a value the caller cannot forge.
    resetRequestIdentity();
    establishRequestIdentity(e.parameter || {});
    const gateError = requireSessionForAction(action);
    if (gateError) return respondJson(gateError);
    applyAuthenticatedIdentity(e.parameter || {}, action);

    Logger.log("doGet Action: " + action + (getAuthenticatedEmail() ? " as " + getAuthenticatedEmail() : " (guest)"));

    if (action === 'getReadingJourney' || action === 'getReaderActivities') {
      return respondJson(getReadingJourney(e.parameter || {}));
    }

    if (action === 'getCurrentReadCircles') {
      return respondJson(getCurrentReadCircles());
    }

    if (action === 'searchCurrentReadCircles') {
      return respondJson(searchCurrentReadCircles(e.parameter || {}));
    }

    if (action === 'addCurrentRead') {
      return respondJson(addCurrentRead(e.parameter || {}));
    }

    if (action === 'joinCurrentReadCircle') {
      return respondJson(joinCurrentReadCircle(e.parameter || {}));
    }

    if (action === 'getReadersCafe') {
      return respondJson(getReadersCafe(e.parameter || {}));
    }

    if (action === 'getCafeStories') {
      return respondJson(getCafeStories(e.parameter || {}));
    }

    // Coffee mugs (30 Sep): the public shelf and the admin enquiry list.
    if (action === 'getMugProducts') return respondJson(getMugProducts());
    if (action === 'getAdminCustomMugEnquiries') return respondJson(getAdminCustomMugEnquiries(e.parameter || {}));
    if (action === 'getAdminMugProducts') return respondJson(getAdminMugProducts());
    // Sponsored ads (9 Oct).
    if (action === 'getSponsoredAds') return respondJson(getSponsoredAds());

    if (action === 'getCafeStoryViewers') {
      return respondJson(getCafeStoryViewers(e.parameter || {}));
    }

    if (action === 'getCircleMessages') {
      return respondJson(getCircleMessages(e.parameter || {}));
    }

    if (action === 'getReadingRoomFeed') {
      return respondJson(getReadingRoomFeed(e.parameter || {}));
    }

    if (action === 'seedTestQARecords') {
      const adminEmail = e.parameter.adminEmail || '';
      return respondJson(seedTestQARecords({ adminEmail }));
    }

    if (action === 'cleanupTestQARecords') {
      const adminEmail = e.parameter.adminEmail || '';
      return respondJson(cleanupTestQARecords({ adminEmail }));
    }

    if (action === 'listAvailableActions') {
      return respondJson({
        success: true,
        actions: [
          'listAvailableActions',
          'seedTestQARecords',
          'cleanupTestQARecords',
          'getReadingSpace',
          'upsertReadingSpaceBook',
          'getCurrentReadCircles',
          'searchCurrentReadCircles',
          'addCurrentRead',
          'joinCurrentReadCircle',
          'getCircleMessages',
          'addCircleMessage',
          'getEvents',
          'registerEvent',
          'notifyEvent',
          'getBooks',
          'addBook',
          'editBook',
          'createBook',
          'updateUserBook',
          'createSwapRequest',
          'acceptSwapRequest',
          'getSwapRequests',
          'approveBook',
          'sendBookApprovalEmailOnce'
        ]
      });
    }
    
    // The admin panel's "Newsletter Subs" tab has always called this
    // action, but it did not exist in the backend — and unlike every
    // other admin tab it had no fallback action, so the tab rendered its
    // error state permanently. The sheet and its headers are the ones
    // subscribeNewsletter() already writes to.
    if (action === 'getNewsletterSubscribers') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      // Every member is a subscriber now; list them all, not only the few
      // who once used the old sign-up box.
      try { backfillNewsletterSubscribers(); } catch (bfErr) { Logger.log('Newsletter backfill skipped: ' + bfErr); }
      const sheet = newsletterSubscriberSheet_();
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, subscribers: [] });
      const headers = data[0].map(h => String(h).trim());
      const subscribers = data.slice(1)
        .filter(row => row.some(cell => String(cell || '').trim() !== ''))
        .map(row => rowToObject(headers, row));
      return respondJson({ success: true, subscribers: subscribers, total: subscribers.length });
    }

    // Coupons were removed on 9 Oct 2026 (owner's request): membership is free
    // and bookstores / authors register as partners instead.
    if (action === 'getMembershipCoupons' || action === 'validateMembershipCoupon') return respondJson({ success: false, error: 'COUPONS_REMOVED', message: 'Coupon codes are no longer used on SwapSutra.' });

    if (action === 'getPendingMembershipApprovals') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('Subscriptions', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, pending: [] });
      
      const headers = data[0];
      const statusIdx = headers.indexOf('adminStatus');
      const approvedAtIdx = headers.indexOf('approvedAt');
      
      const pendingStatuses = ['Pending', 'pending', 'Under Review', 'Submitted', 'Awaiting Approval', ''];
      const pending = data.slice(1).filter(row => {
        const s = String(row[statusIdx]).trim();
        return !s || pendingStatuses.includes(s) || s === 'null' || s === 'undefined';
      }).map(row => {
        const obj = {};
        headers.forEach((h, i) => {
          obj[h] = row[i];
        });
        return obj;
      });
      
      const now = new Date();
      const todayString = now.toDateString();
      
      const approvedToday = data.slice(1).filter(row => {
        if (approvedAtIdx === -1 || !row[approvedAtIdx]) return false;
        return new Date(row[approvedAtIdx]).toDateString() === todayString;
      }).length;
      
      const onHoldCount = data.slice(1).filter(row => String(row[statusIdx]).toLowerCase() === 'hold').length;
      const rejectedToday = data.slice(1).filter(row => {
        const s = String(row[statusIdx]).toLowerCase();
        // Since we don't have separate rejectedAt, we check status and assume if status is rejected it was likely recent for context or just show total rejected
        return s === 'rejected'; 
      }).length;

      return respondJson({ 
        success: true, 
        pending,
        metrics: {
          totalPending: pending.length,
          approvedToday,
          rejectedToday,
          onHold: onHoldCount,
          avgApprovalTime: "24h"
        }
      });
    }

    if (action === 'getAdminDashboardMetrics') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      
      const getRows = (sheetName) => {
        const values = getOrCreateSheet(sheetName, []).getDataRange().getValues();
        if (!values || values.length <= 1) return { headers: [], rows: [] };
        const headers = values[0];
        const rows = values.slice(1).filter(row => row.some(cell => String(cell || '').trim() !== ''));
        return { headers, rows };
      };

      const idx = (headers, candidates) => findHeaderIndex(headers, candidates);
      const statusText = (row, statusIdx) => statusIdx === -1 ? '' : String(row[statusIdx] || '').trim().toLowerCase();
      const isApprovedStatus = (status) => ['approved', 'active', 'live', 'true', 'yes', 'verified'].includes(status);
      const isPendingStatus = (status) => ['pending', 'under review', 'underreview', 'submitted', 'awaiting'].includes(status) || status.includes('pending') || status.includes('review');
      const isCompletedStatus = (status) => ['completed', 'complete', 'closed', 'archived', 'done'].includes(status);
      const isRemovedStatus = (status) => ['removed', 'inactive', 'hidden', 'deactivated'].includes(status);
      const moneyValue = (value) => Number(String(value || '').replace(/[^0-9.]/g, '')) || 0;
      const statusLabel = (status) => {
        if (isApprovedStatus(status)) return 'Approved/Live';
        if (isPendingStatus(status)) return 'Pending';
        if (isRemovedStatus(status)) return 'Removed/Inactive';
        if (status === 'rejected') return 'Rejected';
        return status ? status.charAt(0).toUpperCase() + status.slice(1) : 'Unknown';
      };
      const incrementLabel = (map, label) => map[label] = (map[label] || 0) + 1;
      const chartFromMap = (map) => Object.keys(map).sort().map(label => ({ label, value: map[label] }));
      const monthLabel = (value) => {
        if (!value) return '';
        const date = new Date(value);
        if (isNaN(date.getTime())) return '';
        return Utilities.formatDate(date, Session.getScriptTimeZone(), 'MMM yyyy');
      };
      const timelineFromRows = (rows, headers, candidates) => {
        const dateIdx = idx(headers, candidates);
        if (dateIdx === -1) return [];
        const map = {};
        rows.forEach(row => {
          const label = monthLabel(row[dateIdx]);
          if (label) incrementLabel(map, label);
        });
        return chartFromMap(map);
      };

      const settingsData = getRows('AppSettings');
      const settingsKeyIdx = idx(settingsData.headers, ['key']);
      const settingsValueIdx = idx(settingsData.headers, ['value']);
      const standardFeeRow = settingsData.rows.find(row => settingsKeyIdx !== -1 && String(row[settingsKeyIdx]).trim() === 'standardFee');
      const standardFee = standardFeeRow && settingsValueIdx !== -1 ? moneyValue(standardFeeRow[settingsValueIdx]) : 49;

      const subsData = getRows('Subscriptions');
      const subStatusIdx = idx(subsData.headers, ['adminstatus', 'status', 'membershipstatus', 'subscriptionstatus', 'computedstatus']);
      const subPaymentIdx = idx(subsData.headers, ['paymentamount', 'amount', 'standardfee']);
      const subPaymentStatusIdx = idx(subsData.headers, ['paymentstatus']);
      const subMembershipTypeIdx = idx(subsData.headers, ['membershiptype']);
      const subCouponIdx = idx(subsData.headers, ['couponcode']);
      const subListedCountIdx = idx(subsData.headers, ['bookslistedcount', 'listedcount']);
      const subExpiryIdx = idx(subsData.headers, ['subscriptionexpiry', 'expiry', 'expirydate', 'expiresat']);
      const membersByStatus = {};
      subsData.rows.forEach(row => incrementLabel(membersByStatus, statusLabel(statusText(row, subStatusIdx))));

      const approvedMembers = subsData.rows.filter(row => isApprovedStatus(statusText(row, subStatusIdx)));
      const approvedCount = approvedMembers.length;
      const pendingApprovals = subsData.rows.filter(row => isPendingStatus(statusText(row, subStatusIdx))).length;
      const totalRegisteredSubscriptions = subsData.rows.length;
      const expiredMembers = subsData.rows.filter(row => {
        if (subExpiryIdx === -1 || !row[subExpiryIdx]) return false;
        const expiry = new Date(row[subExpiryIdx]);
        return !isNaN(expiry.getTime()) && expiry < new Date();
      }).length;

      let revenueEstimate = 0;
      approvedMembers.forEach(row => {
        const paymentStatus = subPaymentStatusIdx !== -1 ? String(row[subPaymentStatusIdx] || '').toLowerCase() : '';
        const membershipType = subMembershipTypeIdx !== -1 ? String(row[subMembershipTypeIdx] || '').toLowerCase() : '';
        const coupon = subCouponIdx !== -1 ? String(row[subCouponIdx] || '').toLowerCase() : '';
        if (paymentStatus.includes('waived') || membershipType.includes('free') || coupon.includes('free')) return;
        const paidAmount = subPaymentIdx !== -1 ? moneyValue(row[subPaymentIdx]) : 0;
        revenueEstimate += paidAmount > 0 ? paidAmount : standardFee;
      });

      const booksData = getRows('Books');
      const bookStatusIdx = idx(booksData.headers, ['status', 'bookstatus', 'adminstatus']);
      const totalBooks = booksData.rows.length;
      const liveBooks = booksData.rows.filter(row => isApprovedStatus(statusText(row, bookStatusIdx))).length;
      const pendingBooks = booksData.rows.filter(row => isPendingStatus(statusText(row, bookStatusIdx))).length;
      const removedBooks = booksData.rows.filter(row => isRemovedStatus(statusText(row, bookStatusIdx))).length;
      const booksByStatus = {};
      booksData.rows.forEach(row => incrementLabel(booksByStatus, statusLabel(statusText(row, bookStatusIdx))));

      const swapsData = getRows('SwapRequests');
      const swapStatusIdx = idx(swapsData.headers, ['status', 'swapstatus', 'requeststatus']);
      const totalSwaps = swapsData.rows.length;
      const pendingSwaps = swapsData.rows.filter(row => isPendingStatus(statusText(row, swapStatusIdx))).length;
      const acceptedSwaps = swapsData.rows.filter(row => ['approved', 'accepted', 'active'].includes(statusText(row, swapStatusIdx))).length;
      const completedSwaps = swapsData.rows.filter(row => isCompletedStatus(statusText(row, swapStatusIdx))).length;

      const newsletterData = getRows('NewsletterSubscribers');
      const newsEmailIdx = idx(newsletterData.headers, ['email', 'useremail', 'subscriberemail']);
      const newsUnsubIdx = idx(newsletterData.headers, ['unsubscribed', 'unsubscribestatus', 'unsubscribe']);
      const newsletterEmails = new Set();
      newsletterData.rows.forEach(row => {
        const email = newsEmailIdx !== -1 ? normalizeEmail(row[newsEmailIdx]) : '';
        const unsubscribed = newsUnsubIdx !== -1 && isTruthyValue(row[newsUnsubIdx]);
        if (email && !unsubscribed) newsletterEmails.add(email);
      });
      const newsletterCount = newsletterEmails.size;

      const eventRegCount = getRows('EventRegistrations').rows.length;

      const supportData = getRows('SupportMessages');
      const supportStatusIdx = idx(supportData.headers, ['status', 'ticketstatus']);
      const supportMsgCount = supportData.rows.length;
      const supportResolved = supportData.rows.filter(row => ['resolved', 'closed', 'done'].includes(statusText(row, supportStatusIdx))).length;
      const supportOpen = supportMsgCount - supportResolved;

      const testimonialCount = getRows('Testimonials').rows.length;
      const couponsData = getRows('MembershipCoupons');
      const couponCodeIdx = idx(couponsData.headers, ['couponcode', 'code']);
      const couponUsedIdx = idx(couponsData.headers, ['usedcount', 'usagecount', 'used']);
      const couponsUsage = couponsData.rows
        .map(row => ({
          label: couponCodeIdx !== -1 ? String(row[couponCodeIdx] || 'Coupon') : 'Coupon',
          value: couponUsedIdx !== -1 ? Number(row[couponUsedIdx] || 0) : 0
        }))
        .filter(item => item.label && item.value > 0);

      const conversionRegToApproved = totalRegisteredSubscriptions > 0 ? ((approvedCount / totalRegisteredSubscriptions) * 100).toFixed(1) : 0;
      const approvedWithBooks = approvedMembers.filter(r => subListedCountIdx !== -1 && Number(r[subListedCountIdx]) > 0).length;
      const conversionApprovedToFirstBook = approvedCount > 0 ? ((approvedWithBooks / approvedCount) * 100).toFixed(1) : 0;
      const approvedNoBooks = approvedCount - approvedWithBooks;

      const mostUsedCouponArr = ['None', 0];
      const topAreas = [];

      return respondJson({
        success: true,
        metrics: {
          users: { total: totalRegisteredSubscriptions, approved: approvedCount, pending: pendingApprovals, expired: expiredMembers },
          books: { total: totalBooks, pending: pendingBooks, live: liveBooks, removed: removedBooks },
          swaps: { total: totalSwaps, pending: pendingSwaps, accepted: acceptedSwaps, completed: completedSwaps },
          engagement: { newsletter: newsletterCount, eventReg: eventRegCount, support: supportMsgCount, testimonials: testimonialCount },
          testimonials: testimonialCount,
          support: { total: supportMsgCount, open: supportOpen, resolved: supportResolved },
          coupons: { total: couponsData.rows.length },
          charts: {
            booksByStatus: chartFromMap(booksByStatus),
            membersByStatus: chartFromMap(membersByStatus),
            membershipsOverTime: timelineFromRows(subsData.rows, subsData.headers, ['createdat', 'approvedat', 'subscriptionstartdate']),
            booksOverTime: timelineFromRows(booksData.rows, booksData.headers, ['createdat', 'listedat']),
            supportByStatus: [{ label: 'Open', value: supportOpen }, { label: 'Resolved', value: supportResolved }],
            couponsUsage
          },
          conversions: { regToApproved: conversionRegToApproved, approvedToBook: conversionApprovedToFirstBook, approvedNoBooks },
          listingFunnel: (function () {
            try {
              const since = PropertiesService.getScriptProperties().getProperty(LISTING_FUNNEL_KEYS.since);
              let rowsSince;
              if (since) {
                const sinceDate = new Date(since);
                const createdIdx = idx(booksData.headers, ['createdat', 'listedat']);
                rowsSince = createdIdx === -1 ? undefined : booksData.rows.filter(function (r) {
                  const d = new Date(r[createdIdx]);
                  return !isNaN(d.getTime()) && d >= sinceDate;
                }).length;
              }
              return listingFunnelSnapshot_(rowsSince);
            } catch (funnelErr) {
              Logger.log('listingFunnel metrics failed: ' + funnelErr);
              return null;
            }
          })(),
          insights: { topAreas, mostUsedCoupon: { code: mostUsedCouponArr[0], count: mostUsedCouponArr[1] }, revenueEstimate }
        }
      });
    }

    if (action === 'getAppSettings') {
      const sheet = getOrCreateSheet('AppSettings', ["key", "value", "description", "updatedAt"]);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) {
        // Initialize defaults if empty
        const defaults = [
          ['standardFee', '49', 'Default membership activation fee', new Date()]
        ];
        sheet.getRange(2, 1, defaults.length, 4).setValues(defaults);
        return respondJson({ success: true, settings: { standardFee: 49 } });
      }
      const headers = data[0];
      const settings = {};
      data.slice(1).forEach(row => {
        const key = row[headers.indexOf('key')];
        const val = row[headers.indexOf('value')];
        if (key === 'offerFee') return; // Skip offerFee
        settings[key] = isNaN(val) || val === '' ? val : Number(val);
      });
      return respondJson({ success: true, settings: settings });
    }

    if (action === 'getReadingSpace') {
      return respondJson(getReadingSpace(e.parameter || {}));
    }

    if (action === 'getNewsletters') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('MonthlyNewsletters', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const newsletters = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      });
      return respondJson(newsletters);
    }

    if (action === 'backupData') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(backupSpreadsheet());
    }

    if (action === 'getSwapRequests') {
      const email = normalizeEmail(e.parameter.email);
      if (!email) return respondJson({ success: false, message: "Email required" });
      const sheet = getOrCreateSheet('SwapRequests', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const requests = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        // Populate both the current (requesterEmail/ownerEmail/requestedBookId)
        // and legacy (senderEmail/receiverEmail/receiverBookId) field names so
        // every consumer of this action — old or new — gets real values instead
        // of undefined. See resolveSwapRequestParties().
        const parties = resolveSwapRequestParties(headers, row);
        obj.requesterEmail = parties.requesterEmail;
        obj.ownerEmail = parties.ownerEmail;
        obj.requestedBookId = parties.requestedBookId;
        obj.senderEmail = parties.requesterEmail;
        obj.receiverEmail = parties.ownerEmail;
        obj.receiverBookId = parties.requestedBookId;
        return obj;
      }).filter(r => normalizeEmail(r.requesterEmail) === email || normalizeEmail(r.ownerEmail) === email);
      return respondJson(requests);
    }

    if (action === 'previewNewsletter') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const newsletterId = e.parameter.newsletterId;
      const sheet = getOrCreateSheet('MonthlyNewsletters', []);
      const data = sheet.getDataRange().getValues();
      const headers = data[0];
      const row = data.slice(1).find(r => r[headers.indexOf('newsletterId')] === newsletterId);
      if (!row) return respondJson({ success: false, message: "Newsletter not found" });
      
      let nl = {};
      headers.forEach((h, i) => nl[h] = row[i]);
      const html = stripNewsletterUnsubscribe_(buildNewsletterHtml(nl));
      return respondJson({ success: true, html });
    }

    if (action === 'getArchivedChatsForAdmin') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('Chats', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const statusIdx = headers.indexOf('chatStatus');
      const chats = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      }).filter(c => c.chatStatus === 'Archived');
      return respondJson(chats);
    }

    if (action === 'getUserChats') {
      const email = normalizeEmail(e.parameter.email);
      if (!email) return respondJson({ success: false, message: "Email required" });
      // Returns the reason alongside an empty list rather than a bare [].
      // Swallowing it meant an expired member saw "no conversations yet"
      // instead of being told their membership had lapsed — a silent
      // empty state after a real failure is the hardest kind of bug for
      // someone to report. Success still returns a plain array, so every
      // existing caller keeps working unchanged.
      const accessError = requireApprovedMember(email, 'Your conversations');
      if (accessError) return respondJson({ ...accessError, data: [], chats: [] });
      const sheet = getOrCreateSheet('Chats', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const statusIdx = headers.indexOf('chatStatus');
      const chats = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      });
      // 9 Oct 2026: an exchange the reader has reflected on & rated is closed
      // for them — it leaves their chats and appears in My orders.
      const ratedByUser = email === 'swapsutra@gmail.com' ? {} : ratedSwapIdsFor_(email);
      const visibleChats = chats.filter(c => 
        (normalizeEmail(c.ownerEmail) === email || 
        normalizeEmail(c.requesterEmail) === email || 
        normalizeEmail(c.adminEmail) === email) &&
        (c.chatStatus !== 'Archived' || email === 'swapsutra@gmail.com') &&
        !ratedByUser[String(c.swapId || '')]
      );
      return respondJson(visibleChats);
    }

    if (action === 'getChatMessages') {
      const chatId = e.parameter.chatId;
      const userEmail = normalizeEmail(e.parameter.email);
      if (!chatId) return respondJson({ success: false, message: "ChatId required" });

      // PERF (22 Sep): an open chat polls every few seconds. Each poll used
      // to read the Chats, Subscriptions and whole Messages sheets. The
      // access decision is remembered for 2 minutes and the thread itself
      // until someone writes to it (sendChatMessage / deleteChatMessage
      // clear it), so a poll is normally two cache reads.
      const accessKey = 'chatok:' + chatId + ':' + userEmail;
      const scriptCache = CacheService.getScriptCache();
      if (scriptCache.get(accessKey) !== '1') {
        const chat = getChatById(chatId);
        if (!chat) return respondJson({ success: false, message: "Chat not found", error: "NOT_FOUND" });
        if (!canAccessChat(chat, userEmail)) return respondJson({ success: false, message: "Unauthorized", error: "UNAUTHORIZED" });
        if (!isAdminEmail(userEmail)) {
          const accessError = requireApprovedMember(userEmail, 'Reader messages');
          if (accessError) return respondJson(accessError);
          if (chat.chatStatus === 'Archived') {
            return respondJson({
              success: false,
              isArchived: true,
              message: "This swap has been completed. The chat is now closed for members."
            });
          }
        }
        try { scriptCache.put(accessKey, '1', 120); } catch (cacheErr) { /* cache is an optimisation only */ }
      }

      // A partner (9 Oct 2026) never sees who the buyer is.
      const maskForPartner = (list) => (!Array.isArray(list) || !approvedPartner_(userEmail)) ? list
        : list.map(m => (normalizeEmail(m.senderEmail) === userEmail || isAdminEmail(m.senderEmail)) ? m : Object.assign({}, m, { senderEmail: 'buyer', senderName: 'Buyer' }));
      const cachedThread = chatThreadCacheGet_(chatId);
      if (cachedThread) return respondJson(maskForPartner(cachedThread));

      const sheet = getOrCreateSheet('Messages', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const messages = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      }).filter(m => m.chatId === chatId);
      chatThreadCachePut_(chatId, messages);
      return respondJson(maskForPartner(messages));
    }

    if (action === 'getNotifications') {
      const email = normalizeEmail(e.parameter.email);
      if (!email) return respondJson({ success: false, message: "Email required" });
      const sheet = getOrCreateSheet('Notifications', []);
      ensureSheetHeaders(sheet, ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt', 'status', 'clearedAt']);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const notifications = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      }).filter(n => {
        const status = String(n.status || 'Active').trim().toLowerCase();
        return normalizeEmail(n.userEmail) === email && status !== 'cleared' && status !== 'archived';
      });
      return respondJson(notifications);
    }

    if (action === 'getSwapTracking') {
      const requestId = e.parameter.swapRequestId;
      if (!requestId) return respondJson({ success: false, message: "RequestId required" });
      const sheet = getOrCreateSheet('SwapTracking', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson(null);
      const headers = data[0];
      const row = data.slice(1).find(r => r[headers.indexOf('swapRequestId')] === requestId);
      if (!row) return respondJson(null);
      let obj = {};
      headers.forEach((h, i) => obj[h] = row[i]);
      return respondJson(obj);
    }

    if (action === 'getHostEnquiries') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('HostEnquiries', ['id', 'name', 'email', 'status', 'createdAt']);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0];
      const enquiries = data.slice(1).map(row => {
          let obj = {};
          headers.forEach((h, i) => obj[h] = row[i]);
          return obj;
      });
      return respondJson({ success: true, data: enquiries });
    }

    if (action === 'getSupportMessages') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('SupportMessages', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, items: [] });
      const headers = data[0];
      const items = data.slice(1).map(row => {
          let obj = {};
          headers.forEach((h, i) => obj[mapHeaderToKey(h)] = row[i]);
          return obj;
      });
      return respondJson({ success: true, items });
    }

    if (action === 'getSubscriptions') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      syncUsersFromSubscriptions();
      const sheet = getOrCreateSheet('Subscriptions', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0];
      const userSheet = getOrCreateSheet('Users', []);
      const userData = userSheet.getDataRange().getValues();
      const userHeaders = userData.length ? userData[0].map(h => String(h).trim()) : [];
      const userEmailIdx = userHeaders.indexOf('email');
      const usersByEmail = {};
      if (userEmailIdx !== -1) {
        userData.slice(1).forEach(row => {
          const user = {};
          userHeaders.forEach((h, i) => user[h] = row[i]);
          const email = normalizeEmail(row[userEmailIdx]);
          if (email) usersByEmail[email] = user;
        });
      }
      const subs = data.slice(1).map(row => {
          let obj = {};
          headers.forEach((h, i) => obj[h] = row[i]);
          const email = normalizeEmail(obj.email || obj.userEmail);
          const user = usersByEmail[email] || {};
          obj.name = user.name || obj.name || "";
          obj.email = email || obj.email || "";
          obj.userEmail = obj.userEmail || obj.email;
          obj.phone = user.phone || obj.phone || "";
          obj.area = user.area || obj.area || "";
          obj.pincode = user.pincode || obj.pincode || "";
          obj.genres = user.genres || obj.genres || "";
          obj.bio = user.bio || obj.bio || "";
          obj.membershipStatus = user.membershipStatus || membershipStatusFromAdminStatus(obj.adminStatus);
          obj.paymentStatus = user.paymentStatus || paymentStatusFromAdminStatus(obj.adminStatus);
          obj.updatedAt = user.updatedAt || obj.updatedAt || obj.createdAt || "";
          return obj;
      });
      return respondJson({ success: true, data: subs });
    }

    if (action === 'getUsers') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('Users', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0];
      const users = data.slice(1).map(row => {
          let obj = {};
          headers.forEach((h, i) => obj[h] = row[i]);
          return obj;
      });
      return respondJson({ success: true, data: users });
    }

    if (action === 'getEventSubscribers') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('EventNotifySubscribers', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const subscribers = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => {
          const key = mapHeaderToKey(h);
          obj[key] = row[i];
        });
        return obj;
      });
      return respondJson(subscribers);
    }

    if (action === 'repairDatabase') {
        if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
        return respondJson(repairDatabase());
    }


    if (action === 'cleanupDuplicates') {
      const results = removeDuplicateUsers();
      return respondJson(results);
    }

    // --- Growth module reads over GET (the admin screens use GET) ------
    if (action === 'getFunnelMetrics') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(getFunnelMetrics(e.parameter));
    }
    if (action === 'getLiquidityMetrics') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(getLiquidityMetrics(e.parameter));
    }
    if (action === 'getEmailQuotaStatus') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(getEmailQuotaStatus());
    }
    if (action === 'getMyReferral') return respondJson(getMyReferral(e.parameter));
    if (action === 'validateReferralCode') return respondJson(validateReferralCode(e.parameter));
    if (action === 'getReferralLeaderboard') return respondJson(getReferralLeaderboard(e.parameter));
    if (action === 'getAmbassadorStanding') return respondJson(getAmbassadorStanding(e.parameter));
    if (action === 'getAmbassadorLeaderboard') return respondJson(getAmbassadorLeaderboard(e.parameter));
    if (action === 'getSwapJourney') return respondJson(getSwapJourney(e.parameter));
    if (action === 'getReturnStatus') return respondJson(getReturnStatus(e.parameter));
    if (action === 'getDeliveryAddress') return respondJson(getDeliveryAddress(e.parameter));
    if (action === 'getSwapTimeline') return respondJson(getSwapTimeline(e.parameter));
    if (action === 'getRatingPromptStatus') return respondJson(getRatingPromptStatus(e.parameter));
    if (action === 'getSwapDisputes') return respondJson(getSwapDisputes(e.parameter));
    if (action === 'getOpenDisputes') return respondJson(getOpenDisputes(e.parameter));

    if (action === 'getReaderProfile') {
      return respondJson(getReaderProfile(e.parameter || {}));
    }

    if (action === 'getPublicReaderProfile') {
      const email = normalizeEmail(e.parameter.email);
      if (!email) return respondJson({ success: false, message: "Email required" });
      const userSheet = getOrCreateSheet('Users', []);
      const userData = userSheet.getDataRange().getValues();
      if (userData.length <= 1) return respondJson({ success: false, message: "Reader not found" });
      const headers = userData[0];
      const emailIdx = headers.indexOf('email');
      const row = emailIdx !== -1 ? userData.slice(1).find(r => normalizeEmail(r[emailIdx]) === email) : null;
      if (!row) return respondJson({ success: false, message: "Reader not found" });
      const counts = getApprovedBookCountsByOwner();
      const completedCounts = getCompletedSwapCountsByEmail();
      const ratingAggs = getReaderRatingAggregatesByEmail();
      const profile = publicReaderProfileFromUserRow(headers, row, counts[email] || 0, {
        completedSwapsCount: completedCounts[email] || 0,
        rating: ratingAggs[email] || { avg: 0, count: 0 }
      });
      // Carry the opaque id so callers can move to the id-addressed
      // profile page and stop passing addresses around.
      profile.readerId = readerPublicId(email);
      return respondJson({ success: true, profile: profile });
    }

    if (action === 'getReaderDirectory') {
      const userSheet = getOrCreateSheet('Users', []);
      const userData = userSheet.getDataRange().getValues();
      if (userData.length <= 1) return respondJson({ success: true, readers: [], total: 0 });
      const headers = userData[0];
      const emailIdx = headers.indexOf('email');
      const nameIdx = headers.indexOf('name');
      const query = String(e.parameter.q || '').trim().toLowerCase();
      const excludeEmail = normalizeEmail(e.parameter.excludeEmail || '');
      const counts = getApprovedBookCountsByOwner();
      const completedCounts = getCompletedSwapCountsByEmail();
      const ratingAggs = getReaderRatingAggregatesByEmail();

      let readers = (emailIdx === -1 ? [] : userData.slice(1))
        .filter(row => {
          const email = normalizeEmail(row[emailIdx]);
          if (!email || email === excludeEmail) return false;
          if (email === 'swapsutra@gmail.com') return false; // don't list the platform/admin account
          if (nameIdx === -1 || !row[nameIdx]) return false; // skip incomplete rows with no display name
          return true;
        })
        .map(row => {
          const email = normalizeEmail(row[emailIdx]);
          const entry = publicReaderProfileFromUserRow(headers, row, counts[email] || 0, {
            completedSwapsCount: completedCounts[email] || 0,
            rating: ratingAggs[email] || { avg: 0, count: 0 }
          });
          // The id is what the directory should navigate by. The email
          // field below it is legacy and should follow it out.
          entry.readerId = readerPublicId(email);
          return entry;
        });

      if (query) {
        readers = readers.filter(r =>
          r.name.toLowerCase().includes(query) ||
          r.area.toLowerCase().includes(query) ||
          r.genres.toLowerCase().includes(query)
        );
      }

      // Most recently joined first; cap the payload so this stays fast as the
      // community grows (Apps Script + Sheets reads don't scale to unbounded lists).
      readers.sort((a, b) => new Date(b.memberSince || 0) - new Date(a.memberSince || 0));
      readers = readers.slice(0, 60);

      return respondJson({ success: true, readers: readers, total: readers.length });
    }

    if (action === 'getBookGenres') {
      return respondJson({ success: true, genres: BOOK_GENRE_OPTIONS });
    }

    // The catalogue. ISBN -> book + band, from Postgres. This is the
    // action the listing form calls; getBookPrice below is the Sheets-era
    // fallback and stays only so an older app build keeps working.
    if (action === 'catalogueLookup') {
      return respondJson(catalogueLookup({
        isbn: e.parameter.isbn,
        format: e.parameter.format,
        tier: e.parameter.tier,
        condition: e.parameter.condition
      }));
    }

    if (action === 'swapDeposits') {
      const out = supabaseRpc_('swap_deposits', {
        p_listing_a: e.parameter.listingA, p_listing_b: e.parameter.listingB
      });
      return respondJson(out
        ? Object.assign({ success: true }, out)
        : { success: false, error: 'LOOKUP_UNAVAILABLE',
            message: 'We could not work out the deposits just now.' });
    }

    // Pricing. Both are read-only quotes so the listing form and the swap
    // form can show the reader the number BEFORE they commit — the amounts
    // are not editable, so the least the screen can do is not spring them
    // on anyone at the last step. Neither action writes anything, and
    // neither accepts an amount.
    if (action === 'getBookPrice') {
      return respondJson(getBookPriceQuote({
        isbn: e.parameter.isbn,
        genre: e.parameter.genre,
        format: e.parameter.format,
        edition: e.parameter.edition
      }));
    }

    if (action === 'getDepositQuote') {
      return respondJson(getDepositQuote({
        requestedBookId: e.parameter.requestedBookId,
        offeredBookId: e.parameter.offeredBookId,
        serviceType: e.parameter.serviceType
      }));
    }

    if (action === 'getBooks') {
      // The body of this branch now lives in getBooksResponse() so the
      // computed payload can be cached across requests — see the Library
      // cache block at the end of this file. Behaviour is unchanged
      // unless the caller passes page/pageSize/pincode/area, none of
      // which any existing caller does.
      return respondJson(getBooksResponse(e.parameter));
    }

    if (action === 'getTestimonials') {
      const sheet = getOrCreateSheet('Testimonials', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      
      const headers = data[0];
      const testimonials = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      });

      if (isAuthorizedAdminEmail(e.parameter.adminEmail)) {
        return respondJson({ success: true, data: testimonials });
      }
      
      return respondJson({ success: true, data: testimonials.filter(t => String(t.status || '').toLowerCase() === 'approved') });
    }

    if (action === 'getUserBookRequests') {
      const email = normalizeEmail(e.parameter.email || e.parameter.userEmail);
      if (!email) return respondJson({ success: false, message: "Email required", data: [], error: "MISSING_EMAIL" });
      const accessError = requireApprovedMember(email, 'Your book requests');
      if (accessError) return respondJson({ ...accessError, data: [] });
      const sheet = getOrCreateSheet('BookRequests', ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"]);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0].map(h => String(h).trim());
      const emailIdx = headers.indexOf('userEmail');
      const requests = data.slice(1)
        .filter(row => normalizeEmail(row[emailIdx]) === email)
        .map(row => {
          const obj = {};
          headers.forEach((h, i) => obj[h] = row[i]);
          return obj;
        });
      return respondJson({ success: true, data: requests });
    }

    if (action === 'getBookRequestFeed') {
      const email = normalizeEmail(e.parameter.email || e.parameter.userEmail);
      const accessError = requireApprovedMember(email, 'The Wanted Shelf');
      if (accessError) return respondJson({ ...accessError, data: [] });
      const sheet = getOrCreateSheet('BookRequests', ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"]);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0].map(h => String(h).trim());
      const requests = data.slice(1)
        .filter(row => row.some(cell => String(cell || '').trim() !== ''))
        .map(row => rowToObject(headers, row))
        .filter(req => ['open', 'responded', 'in discussion'].includes(String(req.status || 'Open').trim().toLowerCase()))
        .map(req => ({
          requestId: req.requestId,
          title: redactPublicRequestText(req.title),
          author: redactPublicRequestText(req.author),
          city: redactPublicRequestText(req.city),
          requestType: req.requestType,
          note: redactPublicRequestText(req.note),
          status: req.status || 'Open',
          createdAt: req.createdAt,
          isOwnRequest: normalizeEmail(req.userEmail) === email
        }));
      return respondJson({ success: true, data: requests });
    }

    if (action === 'getBookRequestsForAdmin') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized", data: [], error: "UNAUTHORIZED" });
      const sheet = getOrCreateSheet('BookRequests', ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"]);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0].map(h => String(h).trim());
      const requests = data.slice(1).filter(row => row.some(cell => String(cell || '').trim() !== '')).map(row => {
        const obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      });
      return respondJson({ success: true, data: requests });
    }

    if (action === 'getBookRequestResponses') {
      const email = normalizeEmail(e.parameter.email || e.parameter.userEmail || e.parameter.adminEmail);
      const requestId = String(e.parameter.requestId || '').trim();
      if (!email) return respondJson({ success: false, message: "Email required", data: [], error: "MISSING_EMAIL" });
      const accessError = requireApprovedMember(email, 'Book request responses');
      if (accessError) return respondJson({ ...accessError, data: [] });
      const sheet = getOrCreateSheet('BookRequestResponses', ["responseId", "requestId", "requesterEmail", "responderEmail", "responderBookId", "responderNote", "responseStatus", "chatId", "createdAt", "updatedAt"]);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson({ success: true, data: [] });
      const headers = data[0].map(h => String(h).trim());
      const responses = data.slice(1)
        .filter(row => row.some(cell => String(cell || '').trim() !== ''))
        .map(row => rowToObject(headers, row))
        .filter(resp => {
          if (requestId && resp.requestId !== requestId) return false;
          if (isAdminEmail(email)) return true;
          return normalizeEmail(resp.requesterEmail) === email || normalizeEmail(resp.responderEmail) === email;
        });
      return respondJson({ success: true, data: responses });
    }

    if (action === 'getUserProfile') {
      // This returns the caller's full Subscriptions row — phone, payment
      // status, membership dates, admin notes. It used to accept any
      // email and hand back that person's record, which made the whole
      // member base enumerable. `email` is now overwritten with the
      // verified session identity by applyAuthenticatedIdentity (see
      // SELF_SCOPED_IDENTITY_FIELDS), so this can only ever return the
      // caller's own profile. The re-read below is defence in depth.
      const email = normalizeEmail(e.parameter.email) || getAuthenticatedEmail();
      if (!email) return respondJson({ success: false, message: "Email required" });
      // Admins may look up any member (the approvals screen does this);
      // everyone else can only ever read themselves.
      if (!isAuthenticatedAdmin() && email !== getAuthenticatedEmail()) {
        return respondJson({ success: false, message: "Unauthorized", error: "UNAUTHORIZED" });
      }

      const subSheet = getOrCreateSheet('Subscriptions', []);
      const userSheet = getOrCreateSheet('Users', []);
      const bookSheet = getOrCreateSheet('Books', getBookHeaders());
      ensureSheetHeaders(bookSheet, getBookHeaders());
      const requestSheet = getOrCreateSheet('SwapRequests', []);

      const subData = subSheet.getDataRange().getValues();
      const userData = userSheet.getDataRange().getValues();
      const bookData = bookSheet.getDataRange().getValues();
      const requestData = requestSheet.getDataRange().getValues();

      let subscription = null;
      if (subData.length > 1) {
        const headers = subData[0];
        const emailIndex = headers.indexOf('email');
        if (emailIndex !== -1) {
          const row = subData.slice(1).find(r => normalizeEmail(r[emailIndex]) === email);
          if (row) {
            subscription = {};
            headers.forEach((h, i) => subscription[h] = row[i]);
            subscription.computedStatus = computeSubscriptionStatus(subscription);
          }
        }
      }

      let profile = null;
      if (userData.length > 1) {
        const headers = userData[0];
        const emailIndex = headers.indexOf('email');
        if (emailIndex !== -1) {
          const row = userData.slice(1).find(r => normalizeEmail(r[emailIndex]) === email);
          if (row) {
            profile = {};
            headers.forEach((h, i) => profile[h] = row[i]);
          }
        }
      }

      if (!profile && subscription) {
        const syncResult = ensureUserFromPayload({
          ...subscription,
          membershipStatus: membershipStatusFromAdminStatus(subscription.adminStatus),
          paymentStatus: paymentStatusFromAdminStatus(subscription.adminStatus)
        }, { fillMissingOnly: true, syncStatuses: true });
        profile = syncResult.user;
      } else if (profile && subscription) {
        ensureUserFromPayload({
          ...subscription,
          membershipStatus: membershipStatusFromAdminStatus(subscription.adminStatus),
          paymentStatus: paymentStatusFromAdminStatus(subscription.adminStatus)
        }, { fillMissingOnly: true, syncStatuses: true });
        profile.membershipStatus = profile.membershipStatus || membershipStatusFromAdminStatus(subscription.adminStatus);
        profile.paymentStatus = profile.paymentStatus || paymentStatusFromAdminStatus(subscription.adminStatus);
      }

      if (!subscription && profile) {
        subscription = {
          id: 'SS_SUB_FREE_' + (profile.id || (profile.email ? profile.email.split('@')[0] : 'guest')),
          name: profile.name || 'Reader',
          email: profile.email || email,
          phone: profile.phone || '',
          area: profile.area || '',
          pincode: profile.pincode || '',
          genres: profile.genres || '',
          bio: profile.bio || '',
          adminStatus: 'Approved',
          computedStatus: 'Free',
          membershipType: 'free',
          activationType: 'free',
          booksListedCount: 0,
          booksRemaining: 10
        };
      }

      if (subscription && profile) {
        ['name', 'phone', 'area', 'pincode', 'genres', 'bio'].forEach(key => {
          if (profile[key]) subscription[key] = profile[key];
        });
        subscription.membershipStatus = profile.membershipStatus || membershipStatusFromAdminStatus(subscription.adminStatus);
        subscription.paymentStatus = profile.paymentStatus || paymentStatusFromAdminStatus(subscription.adminStatus);
      }

      let books = [];
      if (bookData.length > 1) {
        const headers = bookData[0];
        const emailIndex = headers.indexOf('ownerEmail');
        if (emailIndex !== -1) {
          books = bookData.slice(1)
            .filter(r => normalizeEmail(r[emailIndex]) === email)
            .map(row => {
              let obj = {};
              headers.forEach((h, i) => obj[h] = row[i]);
              Object.assign(obj, bookStatusFlags(obj));
              obj.missingPhotos = listingPhotoGaps_(obj);
              return obj;
            });
        }
      }

      let swapRequests = [];
      if (requestData.length > 1) {
        const headers = requestData[0];
        const emailIndex = headers.indexOf('requesterEmail');
        if (emailIndex !== -1) {
          swapRequests = requestData.slice(1)
            .filter(r => normalizeEmail(r[emailIndex]) === email)
            .map(row => {
              let obj = {};
              headers.forEach((h, i) => obj[h] = row[i]);
              return obj;
            });
        }
      }

      const journeyData = getReadingJourney({ email: email });

      const isRegistered = Boolean(subscription || profile);
      const computedTier = subscription 
        ? (subscription.computedStatus === 'Active' ? 'premium' : (subscription.computedStatus === 'Free' || String(subscription.activationType).toLowerCase() === 'free' ? 'free' : 'pending'))
        : (profile ? 'free' : 'pending');

      return respondJson({
        success: true,
        isRegistered: isRegistered,
        membershipStatus: computedTier,
        userTier: computedTier,
        profile: isRegistered ? {
          subscription,
          profile,
          books,
          swapRequests,
          readingSpace: getReadingSpace({ user_id: email }).data || [],
          activities: journeyData.activities || [],
          activityMetrics: journeyData.metrics || {},
          // Badges a person awarded, so a reader sees their own on their
          // profile rather than only on the public one other readers open.
          awardedBadges: awardedBadgesFor(email),
          // The reader's own public id, so "Share my shelf" can link to
          // /reader/<id> without an email ever going into a URL.
          readerId: readerPublicId(email)
        } : null
      });
    }

    if (action === 'getWhatsAppCommunityAccess') {
      return respondJson({
        success: true,
        communityUrl: getWhatsAppCommunityUrl(),
        note: "The SwapSutra WhatsApp Community is open for readers to join directly from the website."
      });
    }

    if (action === 'checkSubscription') {
      const email = normalizeEmail(e.parameter.email);
      const sheet = getOrCreateSheet('Subscriptions', []);
      const data = sheet.getDataRange().getValues();
      let sub = null;
      if (data.length > 1) {
        const headers = data[0];
        const emailIndex = findHeaderIndex(headers, ['email', 'userEmail']);
        if (emailIndex !== -1) {
          const userRowIdx = data.findIndex((row, i) => i > 0 && normalizeEmail(row[emailIndex]) === email);
          const userRow = userRowIdx !== -1 ? data[userRowIdx] : null;
          if (userRow) {
            sub = {};
            headers.forEach((h, i) => sub[h] = userRow[i]);
            sub.email = normalizeEmail(sub.email || sub.userEmail || userRow[emailIndex]);
            sub.userEmail = sub.userEmail || sub.email;
            try { healApprovedSubscriptionWindow_(sheet, headers, userRowIdx, sub); } catch (healErr) { Logger.log('Window heal skipped: ' + healErr); }
            sub.booksListedCount = recalculateBooksListedCount(email, sub.booksListedCount);
            sub.booksRemaining = Math.max(0, freeListingLimit_() - sub.booksListedCount);
            sub.computedStatus = computeSubscriptionStatus(sub);
          }
        }
      }

      // The Users sheet is only needed when there is no Subscriptions row —
      // reading it on every check was one of the slow parts of "Verifying".
      let profileUser = null;
      const userData = sub ? [] : getOrCreateSheet('Users', []).getDataRange().getValues();
      if (userData.length > 1) {
        const uHeaders = userData[0];
        const uEmailIdx = uHeaders.indexOf('email');
        if (uEmailIdx !== -1) {
          const uRow = userData.slice(1).find(r => normalizeEmail(r[uEmailIdx]) === email);
          if (uRow) {
            profileUser = {};
            uHeaders.forEach((h, i) => profileUser[h] = uRow[i]);
          }
        }
      }

      if (!sub && !profileUser) {
        return respondJson({ 
          success: true, 
          isRegistered: false, 
          status: "NotFound", 
          membershipStatus: "pending", 
          userTier: "pending", 
          isPremium: false,
          isFreeTrial: false,
          message: "No registered SwapSutra membership found." 
        });
      }

      if (freeRegistrationMode_()) {
        return respondJson(freeMemberCheckSubscriptionResponse_(email, sub, profileUser));
      }

      const now = new Date();
      // The product's 1-Month Free Trial is defined (registerFreeReader) as
      // exactly 30 days, not a calendar month — kept identical here so this
      // sanity check and the actual trial-duration math never disagree.
      const TRIAL_DURATION_MS = 30 * 24 * 60 * 60 * 1000;
      const MAX_SANE_TRIAL_DAYS = 31; // 30 days + 1 day of rounding/timezone slack

      if (sub) {
        const computed = computeSubscriptionStatus(sub);
        const isPremium = computed === 'PREMIUM' || (computed === 'Active' && String(sub.activationType).toLowerCase() !== 'free_trial' && String(sub.activationType).toLowerCase() !== 'free');
        const isTrial = computed === 'TRIAL' || computed === 'FREE_TRIAL' || computed === 'Free';
        const isPending = computed === 'PAYMENT_PENDING' || computed === 'Pending';
        const isExpired = computed === 'EXPIRED' || computed === 'Expired';
        const isFailed = computed === 'PAYMENT_FAILED' || computed === 'Rejected';
        const isCancelled = computed === 'CANCELLED' || computed === 'Cancelled';
        // A bare registration stub -- account exists but no genuine trial
        // has been activated and no payment was ever required on this row.
        // This must NEVER fall into the "else" default below (which used to
        // silently grant TRIAL access to anything unrecognized) -- it is
        // registered, but has no active membership of any kind yet.
        const isNoSubscription = computed === 'NoSubscription';

        let mStatus = 'TRIAL';
        let uTier = 'trial';
        if (isPremium) {
          mStatus = 'PREMIUM';
          uTier = 'premium';
        } else if (isExpired) {
          mStatus = 'EXPIRED';
          uTier = 'expired';
        } else if (isPending) {
          mStatus = 'PAYMENT_PENDING';
          uTier = 'pending';
        } else if (isFailed) {
          mStatus = 'PAYMENT_FAILED';
          uTier = 'pending';
        } else if (isCancelled) {
          mStatus = 'CANCELLED';
          uTier = 'expired';
        } else if (isNoSubscription) {
          // Lowercase 'pending' (distinct from the uppercase PAYMENT_PENDING
          // used above) so this never implies a payment is involved -- the
          // frontend already treats 'pending' as gated-but-not-erroring.
          mStatus = 'pending';
          uTier = 'pending';
        } else {
          mStatus = 'TRIAL';
          uTier = 'trial';
        }

        const expiryVal = sub.subscriptionExpiry || sub.trialEndDate;
        const expiryDate = expiryVal ? new Date(expiryVal) : null;
        let daysRemaining = 0;
        let daysRemainingValid = false;
        if (expiryDate && !isNaN(expiryDate.getTime())) {
          daysRemaining = Math.max(0, Math.ceil((expiryDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)));
          daysRemainingValid = true;
        }

        // Defensive sanity check: a 1-Month Free Trial can never legitimately
        // show more than ~31 days remaining. If the stored subscriptionExpiry/
        // trialEndDate is missing, unparseable, or was corrupted by unrelated
        // logic (e.g. a paid-membership approval touching a trial record —
        // see the manageMembershipApproval fix above), recompute the trial
        // window from its true anchor (trialStartDate) instead of surfacing a
        // fabricated number. This never invents a number for a real paid
        // member — it only applies when mStatus is TRIAL.
        if (mStatus === 'TRIAL' && (!daysRemainingValid || daysRemaining > MAX_SANE_TRIAL_DAYS)) {
          const trialStartVal = sub.trialStartDate || sub.subscriptionStartDate;
          const trialStartDate = trialStartVal ? new Date(trialStartVal) : null;
          if (trialStartDate && !isNaN(trialStartDate.getTime())) {
            const recomputedEnd = new Date(trialStartDate.getTime() + TRIAL_DURATION_MS);
            daysRemaining = Math.max(0, Math.ceil((recomputedEnd.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)));
            daysRemainingValid = true;
          } else {
            daysRemaining = 0;
            daysRemainingValid = false;
          }
        }

        return respondJson({
          success: true,
          isRegistered: !isExpired && !isCancelled,
          status: mStatus,
          membershipStatus: mStatus,
          userTier: uTier,
          isPremium: isPremium,
          isTrial: isTrial && !isExpired,
          isExpired: isExpired,
          daysRemaining: daysRemaining,
          daysRemainingValid: daysRemainingValid,
          trialStartDate: sub.trialStartDate || sub.subscriptionStartDate,
          trialEndDate: sub.trialEndDate || sub.subscriptionExpiry,
          subscriptionStartDate: sub.subscriptionStartDate,
          subscriptionExpiry: sub.subscriptionExpiry,
          subscription: {
            ...sub,
            computedStatus: mStatus,
            membershipStatus: mStatus
          }
        });
      }

      if (profileUser) {
        const mStatusRaw = String(profileUser.membershipStatus || '').trim().toUpperCase();
        const payStatusRaw = String(profileUser.paymentStatus || '').trim().toLowerCase();
        const isPremium = (mStatusRaw === 'PREMIUM' || mStatusRaw === 'ACTIVE') && payStatusRaw === 'paid';
        let isTrialStatus = mStatusRaw === 'TRIAL' || mStatusRaw === 'FREE_TRIAL' || mStatusRaw === 'ACTIVE' || mStatusRaw === 'FREE';

        // Anchor the 1-month trial window to the user's actual join date, not to "now".
        // createdAt is set once at account creation and never overwritten, so this is stable
        // across repeated checkSubscription calls (unlike recomputing 30 days from `now` each time).
        const joinDateVal = profileUser.createdAt;
        const rawJoinDate = joinDateVal ? new Date(joinDateVal) : now;
        // If createdAt is missing/unparseable, or somehow lands in the
        // future (clock skew, bad manual data), anchor to `now` instead of
        // letting a bad date produce a bogus multi-year trial window.
        const joinDate = (isNaN(rawJoinDate.getTime()) || rawJoinDate.getTime() > now.getTime()) ? now : rawJoinDate;
        const trialEnd = new Date(joinDate.getTime() + TRIAL_DURATION_MS);
        const isExpired = !isPremium && isTrialStatus && now > trialEnd;
        const daysRemaining = Math.max(0, Math.min(MAX_SANE_TRIAL_DAYS, Math.ceil((trialEnd.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))));

        if (isExpired) isTrialStatus = false;

        return respondJson({
          success: true,
          isRegistered: (isTrialStatus || isPremium) && !isExpired,
          status: isPremium ? 'PREMIUM' : (isExpired ? 'EXPIRED' : 'TRIAL'),
          membershipStatus: isPremium ? 'PREMIUM' : (isExpired ? 'EXPIRED' : 'TRIAL'),
          userTier: isPremium ? 'premium' : (isExpired ? 'expired' : 'trial'),
          isPremium: isPremium,
          isTrial: isTrialStatus && !isPremium,
          isExpired: isExpired,
          daysRemaining: daysRemaining,
          daysRemainingValid: true,
          trialStartDate: joinDate,
          trialEndDate: trialEnd,
          subscriptionStartDate: joinDate,
          subscriptionExpiry: trialEnd,
          subscription: {
            id: 'SS_SUB_TRIAL_' + (profileUser.id || email.split('@')[0]),
            name: profileUser.name || 'Reader',
            email: email,
            computedStatus: isPremium ? 'PREMIUM' : (isExpired ? 'EXPIRED' : 'TRIAL'),
            membershipStatus: isPremium ? 'PREMIUM' : (isExpired ? 'EXPIRED' : 'TRIAL'),
            adminStatus: 'Approved',
            activationType: isPremium ? 'paid' : 'free_trial',
            membershipType: isPremium ? 'premium' : 'trial',
            trialStartDate: joinDate,
            trialEndDate: trialEnd,
            subscriptionStartDate: joinDate,
            subscriptionExpiry: trialEnd,
            booksListedCount: 0,
            booksRemaining: 999
          }
        });
      }
    }

    if (action === 'getEvents') {
      try {
        const sheet = getOrCreateSheet('EventMaster', []);
        const data = sheet.getDataRange().getValues();
        if (data.length <= 1) return respondJson({ success: true, data: [] });
        
        const headers = data[0];
        const events = data.slice(1).map(row => {
          let obj = {};
          headers.forEach((h, i) => {
            const key = mapHeaderToKey(h);
            obj[key] = row[i];
          });
          
          // Normalize RegistrationOpen
          const statusLower = String(obj.status || "").toLowerCase();
          const upcomingOrScheduled = ['upcoming', 'scheduled', 'live'].includes(statusLower);
          if (obj.registrationOpen === "" || obj.registrationOpen === null || obj.registrationOpen === undefined) {
            obj.registrationOpen = upcomingOrScheduled;
          } else {
            obj.registrationOpen = String(obj.registrationOpen).toLowerCase() === 'true' || obj.registrationOpen === true;
          }

          // Normalize Status casing for frontend consistency
          if (statusLower === 'upcoming') obj.status = 'Upcoming';
          else if (statusLower === 'scheduled') obj.status = 'Scheduled';
          else if (statusLower === 'live') obj.status = 'Live';
          else if (statusLower === 'completed') obj.status = 'Completed';
          else if (statusLower === 'cancelled') obj.status = 'Cancelled';
          else if (statusLower === 'draft') obj.status = 'Draft';
          
          return obj;
        });
        
        return respondJson({ success: true, data: events });
      } catch (e) {
        return respondJson({ success: false, message: "Failed to fetch events: " + e.toString() });
      }
    }
    if (action === 'listSheets') {
      try {
        const ss = getSpreadsheet();
        const sheets = ss.getSheets();
        const list = sheets.map(s => {
          return {
            name: s.getName(),
            rowCount: s.getLastRow(),
            colCount: s.getLastColumn(),
            isProtected: s.isSheetProtected()
          };
        });
        return respondJson({ success: true, sheets: list });
      } catch (e) {
        return respondJson({ success: false, message: e.toString() });
      }
    }
    if (action === 'getSwapProofs') {
      return respondJson(getSwapProofs(e.parameter.chatId, e.parameter.email));
    }
    if (action === 'getNewsletters') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('MonthlyNewsletters', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const newsletters = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => obj[h] = row[i]);
        return obj;
      });
      return respondJson(newsletters);
    }
    if (action === 'getNewsletterById') {
      const sheet = getOrCreateSheet('MonthlyNewsletters', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson(null);
      const headers = data[0];
      const idIdx = headers.indexOf('newsletterId');
      const row = data.slice(1).find(r => r[idIdx] === e.parameter.newsletterId);
      if (!row) return respondJson(null);
      let obj = {};
      headers.forEach((h, i) => obj[h] = row[i]);
      return respondJson(obj);
    }

    return respondJson({ success: false, message: `Unknown action: ${action}` });
  } catch (err) {
    return respondJson({ success: false, message: err.toString() });
  }
}

function computeSubscriptionStatus(sub) {
  if (!sub) return 'NoSubscription';
  // Free registration (Oct 2026): an account is a member until an admin
  // cancels it. No trial window, no paid window, nothing expires — and the
  // public Library, which hides books from "lapsed" owners via this same
  // function, therefore never hides a registered reader's shelf.
  if (freeRegistrationMode_()) {
    const adminLower = String(sub.adminStatus || '').trim().toLowerCase();
    const memberUpper = String(sub.membershipStatus || '').trim().toUpperCase();
    return (adminLower === 'cancelled' || memberUpper === 'CANCELLED') ? 'CANCELLED' : 'FREE_TRIAL';
  }
  const now = new Date();
  const adminStatus = String(sub.adminStatus || 'Pending').trim();
  const adminStatusLower = adminStatus.toLowerCase();
  const membershipStatus = String(sub.membershipStatus || '').trim().toUpperCase();
  const activationType = String(sub.activationType || '').trim().toLowerCase();
  const membershipType = String(sub.membershipType || '').trim().toLowerCase();
  const paymentStatus = String(sub.paymentStatus || '').trim().toLowerCase();
  // The one reliable signal separating "a paid (₹49) application actually
  // awaiting approval" from "a free-tier registration stub that never
  // involved any payment at all". A Free Explorer row must NEVER be
  // reported as PAYMENT_PENDING merely because a leftover/legacy
  // membershipStatus string happens to say so -- that field alone is not
  // trustworthy evidence, this flag (set once, at the moment the
  // application actually did or didn't require payment) is.
  const paymentRequiredRaw = String(sub.paymentRequired || '').trim().toLowerCase();
  const paymentWasRequired = paymentRequiredRaw === 'yes' || paymentRequiredRaw === 'true';

  const getValLocal = (obj, keys) => {
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
    }
    return null;
  };

  // 1. CANCELLED -- always takes priority, regardless of tier.
  if (adminStatusLower === 'cancelled' || membershipStatus === 'CANCELLED') {
    return 'CANCELLED';
  }

  // 2. PAYMENT_FAILED -- only meaningful for a row that actually went
  //    through a payment attempt; a free-tier stub was never "rejected".
  if (paymentWasRequired && (adminStatusLower === 'rejected' || membershipStatus === 'PAYMENT_FAILED')) {
    return 'PAYMENT_FAILED';
  }

  // 3/4. VERIFIED (PAID) MEMBER -- evaluated strictly from the paid
  //    membership's OWN evidence: a real, dated, genuinely-approved paid
  //    window (subscriptionStartDate/subscriptionExpiry), never from a
  //    membershipType label alone. A membershipType of 'premium'/'paid'
  //    that has NOT actually been activated with a real window yet (still
  //    awaiting admin approval) is not an active Verified Member -- and a
  //    window with an implausible duration (this app's paid memberships run
  //    at most ~1 year -- see manageMembershipApproval / activate
  //    SubscriptionIfEligible) is treated as corrupted/legacy data, not as
  //    genuine evidence of an active paid period, so a stale bug that once
  //    wrote a fabricated multi-year expiry can never masquerade as PREMIUM.
  const MAX_SANE_PAID_MEMBERSHIP_MS = 400 * 24 * 60 * 60 * 1000; // ~400 days
  const isPaidMembershipType = membershipType === 'premium' || membershipType === 'paid' || membershipType === 'verified' || membershipType === 'verified_member';
  const paymentGenuinelyApproved = adminStatusLower === 'approved' || paymentStatus === 'approved' || paymentStatus === 'paid';
  if (paymentWasRequired || isPaidMembershipType) {
    const subStart = sub.subscriptionStartDate ? new Date(sub.subscriptionStartDate) : null;
    const subExpiry = sub.subscriptionExpiry ? new Date(sub.subscriptionExpiry) : null;
    const hasSaneDatedWindow = subStart && subExpiry
      && !isNaN(subStart.getTime()) && !isNaN(subExpiry.getTime())
      && (subExpiry.getTime() - subStart.getTime()) <= MAX_SANE_PAID_MEMBERSHIP_MS;
    if (paymentGenuinelyApproved && hasSaneDatedWindow) {
      if (now > subExpiry) return 'EXPIRED';
      return 'PREMIUM';
    }
    // A genuinely paid-tier application (payment was actually required)
    // that hasn't yet been approved+activated with a real window is
    // legitimately payment-pending.
    if (paymentWasRequired && !paymentGenuinelyApproved) {
      return 'PAYMENT_PENDING';
    }
    // Otherwise (isPaidMembershipType true but paymentWasRequired false,
    // or the dated window is missing/implausible): do not trust the label
    // -- fall through and let the trial/registration checks below decide.
  }

  // 5/6. ACTIVE / EXPIRED FREE EXPLORER -- evaluated strictly from genuine
  //    trial evidence (activationType/membershipType explicitly marking a
  //    trial, or a real trial date already on the row) -- never from row
  //    existence, a stray membershipStatus string, or a mislabeled
  //    membershipType. trialStartDate/trialEndDate are the sole
  //    authoritative trial-window fields; subscriptionStartDate/
  //    subscriptionExpiry are reserved for a genuine PAID window and are
  //    only consulted here as a narrow legacy fallback for rows that
  //    predate the trialStartDate/trialEndDate columns.
  const hasGenuineTrialSignal = activationType === 'free_trial' || membershipType === 'trial' || !!sub.trialStartDate || !!sub.trialEndDate;
  if (hasGenuineTrialSignal) {
    const trialStart = sub.trialStartDate ? new Date(sub.trialStartDate)
      : ((activationType === 'free_trial' || membershipType === 'trial') && sub.subscriptionStartDate ? new Date(sub.subscriptionStartDate) : null);
    const trialEnd = sub.trialEndDate ? new Date(sub.trialEndDate)
      : ((activationType === 'free_trial' || membershipType === 'trial') && sub.subscriptionExpiry ? new Date(sub.subscriptionExpiry) : null);
    if (trialStart && trialEnd && !isNaN(trialStart.getTime()) && !isNaN(trialEnd.getTime())) {
      if (now >= trialEnd) return 'EXPIRED';
      if (now >= trialStart) return 'FREE_TRIAL';
    }
    // A trial-flavored row whose real date window hasn't been written yet
    // (registration happened but activation hasn't completed) -- falls
    // through to the registration-stub case below rather than being
    // reported as any kind of "pending" (no payment is involved).
  }

  // 7. A bare registration stub: no genuine payment attempt AND no genuine
  //    trial window yet -- e.g. a free-tier Sign Up whose OTP verification /
  //    trial activation hasn't completed. This is the exact case the
  //    membership-lifecycle fix is about: a Users/Subscriptions row existing
  //    is NOT evidence of a consumed trial or a pending payment. Must never
  //    be reported as PAYMENT_PENDING or as any active membership.
  if (!paymentWasRequired && !hasGenuineTrialSignal) {
    return 'NoSubscription';
  }

  // 8. Legacy fallback -- preserves prior behavior for any row shape not
  //    covered above (e.g. very old rows predating the paymentRequired/
  //    activationType/membershipType columns).
  const expiryVal = getValLocal(sub, ["subscriptionExpiry", "subscriptionExpi", "subscriptionExp", "trialEndDate"]);
  const expiryDate = expiryVal ? new Date(expiryVal) : null;
  if (expiryDate && now > expiryDate) {
    return 'EXPIRED';
  }
  return adminStatus;
}

function safeCleanupSheets() {
  // This is the one place that deletes and renames sheets, so any handle
  // cached earlier in this request now points at something that has
  // moved or gone. Drop the cache rather than hand a dead reference to
  // whatever runs next.
  resetSheetCache();
  const ss = getSpreadsheet();
  const sheets = ss.getSheets();
  const protectedSheets = [
    "Users", "Subscriptions", "Books", "SwapRequests", "Chats", "Messages", 
    "SwapTracking", "Ratings", "Notifications", "Testimonials", "SupportMessages", 
    "OTP", "BookRatings", "SwapProofs", "MonthlyNewsletters", "NewsletterSubscribers",
    "MembershipCoupons", "EventMaster", "EventRegistrations", "EventNotifySubscribers",
    "HostEnquiries", "ActivityLogs", "AppSettings",
    "current_read_circles", "current_read_members", "current_read_messages", "reading_space",
    // ReaderActivityLog is the real, per-activity backend record that the
    // streak and achievements system is computed from (see
    // computeGamificationState / getReadingJourney). It was previously
    // missing from this list, which meant a routine admin "cleanupSheets"
    // call would archive it out from under every user's streak history the
    // moment it was non-empty. Protecting it keeps that history durable.
    "ReaderActivityLog",
    // These 8 sheets were audited (grepped every getOrCreateSheet call site)
    // and confirmed genuinely used by live features -- Book Requests,
    // Reading Room posts/reactions/comments, Saved Recommendations, Swap
    // Disputes, and Current Read chat messages -- but were missing from this
    // list, meaning the same archive-on-cleanup risk that ReaderActivityLog
    // had above applied to all of them too. Protecting them the same way.
    "BookRequests", "BookRequestResponses",
    "ReadingRoomPosts", "ReadingRoomReactions", "ReadingRoomComments",
    "SavedRecommendations", "SwapDisputes", "CurrentReadMessages",
    // Added with the Trust Gap Closure Plan's P0 work: the courier
    // journey ledger and delivery-address book already existed but were
    // missing from this list (the same gap this comment describes for
    // the 8 sheets above); ReaderRatings and DisputeEvents are new.
    "SwapJourney", "DeliveryAddresses", "ReaderRatings", "DisputeEvents"
  ];
  
  const results = [];
  const now = new Date().toISOString().split('T')[0].replace(/-/g, '');
  
  sheets.forEach(sh => {
    const name = sh.getName();
    if (protectedSheets.includes(name)) return;
    if (name.startsWith('ARCHIVE_')) return;
    
    let lastRow = 0;
    let lastCol = 0;
    try {
      lastRow = sh.getLastRow();
      lastCol = sh.getLastColumn();
    } catch(e) {}
    
    // Check if sheet is truly empty
    let isEmpty = true;
    if (lastRow > 0 && lastCol > 0) {
      const vals = sh.getRange(1, 1, Math.min(lastRow, 1), lastCol).getValues();
      isEmpty = lastRow <= 1 && vals[0].every(v => v === "" || v === null);
    }
    
    if (isEmpty) {
      if (sheets.length > 1) {
        try {
          ss.deleteSheet(sh);
          results.push({ name, action: "deleted", reason: "empty" });
        } catch(e) {
          results.push({ name, action: "failed", reason: e.toString() });
        }
      } else {
        results.push({ name, action: "skipped", reason: "last_sheet_remaining" });
      }
    } else {
      const newName = `ARCHIVE_${name}_${now}`;
      try {
        sh.setName(newName);
        results.push({ name, action: "archived", newName });
      } catch(e) {
        results.push({ name, action: "failed_archive", reason: e.toString() });
      }
    }
  });
  
  // The sheets that were deleted or renamed above may have been
  // cached before this ran; clear again so nothing downstream in this
  // request reuses a handle to a sheet that no longer exists.
  resetSheetCache();

  return results;
}

function syncUsersFromSubscriptions() {
  const subSheet = getOrCreateSheet('Subscriptions', []);
  const userSheet = getOrCreateSheet('Users', []);
  const subData = subSheet.getDataRange().getValues();
  if (subData.length <= 1) return { success: true, created: 0, updated: 0 };

  const subHeaders = subData[0].map(h => String(h).trim());
  const subEmailIdx = findHeaderIndex(subHeaders, ['email', 'userEmail']);
  if (subEmailIdx === -1) return { success: false, message: "Subscriptions sheet missing email/userEmail." };

  let created = 0;
  let updated = 0;
  subData.slice(1).forEach(row => {
    const sub = {};
    subHeaders.forEach((h, i) => sub[h] = row[i]);
    sub.email = normalizeEmail(sub.email || sub.userEmail || row[subEmailIdx]);
    sub.userEmail = sub.userEmail || sub.email;
    const result = ensureUserFromPayload({
      ...sub,
      membershipStatus: membershipStatusFromAdminStatus(sub.adminStatus),
      paymentStatus: paymentStatusFromAdminStatus(sub.adminStatus)
    }, { fillMissingOnly: true, syncStatuses: true });
    if (result.created) created++;
    else if (result.updated) updated++;
  });

  return { success: true, message: `Synced ${created} created, ${updated} updated`, created, updated };
}

function membershipStatusFromAdminStatus(status) {
  const normalized = String(status || '').trim().toLowerCase();
  if (normalized === 'approved' || normalized === 'active') return 'Active';
  if (normalized === 'rejected') return 'Rejected';
  if (normalized === 'cancelled' || normalized === 'canceled') return 'Cancelled';
  return 'Pending';
}

function paymentStatusFromAdminStatus(status) {
  const normalized = String(status || '').trim().toLowerCase();
  if (normalized === 'approved' || normalized === 'active') return 'Approved';
  if (normalized === 'rejected') return 'Rejected';
  if (normalized === 'cancelled' || normalized === 'canceled') return 'Cancelled';
  return 'Pending';
}

function userObjectFromRow(headers, row) {
  const obj = {};
  headers.forEach((h, i) => obj[h] = row[i]);
  return obj;
}

// AUTH GATE: Users sheet is the single source of truth for "does this
// person already have a SwapSutra account". Used to (a) block Login OTPs
// for emails that never registered, and (b) block duplicate Sign Ups for
// emails that already registered. Read-only — never creates/modifies rows.
function emailExistsInUsersSheet(email) {
  const normEmail = normalizeEmail(email);
  if (!normEmail) return false;
  const userHeadersDefault = ["id", "name", "email", "phone", "area", "pincode", "genres", "bio", "membershipStatus", "paymentStatus", "createdAt", "updatedAt"];
  const sheet = getOrCreateSheet('Users', userHeadersDefault);

  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return false;
  const lastCol = Math.max(sheet.getLastColumn(), 1);
  const headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0].map(h => String(h).trim());
  const emailIdx = headers.indexOf('email');
  if (emailIdx === -1) return false;

  // ONE column, not the whole sheet. This runs on every login, and
  // getDataRange().getValues() was pulling every reader's name, phone,
  // genres and bio across the wire to answer "does this address exist?".
  const column = sheet.getRange(2, emailIdx + 1, lastRow - 1, 1).getValues();
  for (let i = 0; i < column.length; i++) {
    if (normalizeEmail(column[i][0]) === normEmail) return true;
  }
  return false;
}

// Last-10-digits comparison (matches the convention already used by
// subscribeEventNotify for phone de-duplication) so "+91 98765 43210",
// "9876543210", and "09876543210" are all recognized as the same number.
function normalizePhoneLast10(phone) {
  return String(phone || '').replace(/\D/g, '').slice(-10);
}

function phoneExistsInUsersSheet(phone) {
  const normPhone = normalizePhoneLast10(phone);
  if (!normPhone || normPhone.length < 10) return false;
  const userHeadersDefault = ["id", "name", "email", "phone", "area", "pincode", "genres", "bio", "membershipStatus", "paymentStatus", "createdAt", "updatedAt"];
  const sheet = getOrCreateSheet('Users', userHeadersDefault);
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return false;
  const headers = values[0];
  const phoneIdx = headers.indexOf('phone');
  if (phoneIdx === -1) return false;
  return values.slice(1).some(row => normalizePhoneLast10(row[phoneIdx]) === normPhone);
}

function ensureUserFromPayload(payload, options) {
  const opts = options || {};
  const userHeadersDefault = ["id", "name", "email", "phone", "area", "pincode", "genres", "bio", "membershipStatus", "paymentStatus", "createdAt", "updatedAt"];
  const sheet = getOrCreateSheet('Users', userHeadersDefault);
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(h => String(h).trim());
  const email = normalizeEmail(payload.email || payload.userEmail);
  if (!email) return { success: false, message: "Email required", user: null };

  const emailIdx = headers.indexOf('email');
  let rowIndex = values.findIndex((row, idx) => idx > 0 && normalizeEmail(row[emailIdx]) === email);
  const now = new Date();
  const safeFields = {
    name: payload.name || payload.fullName || '',
    email,
    phone: payload.phone || '',
    area: payload.area || '',
    pincode: payload.pincode || '',
    genres: payload.genres || '',
    bio: payload.bio || '',
    membershipStatus: payload.membershipStatus || '',
    paymentStatus: payload.paymentStatus || ''
  };

  if (rowIndex === -1) {
    const row = new Array(headers.length).fill("");
    headers.forEach((h, i) => {
      if (h === 'id') row[i] = generateId('SS_USR_');
      else if (h === 'createdAt') row[i] = payload.createdAt || now;
      else if (h === 'updatedAt') row[i] = now;
      else if (safeFields[h] !== undefined) row[i] = safeFields[h];
    });
    sheet.appendRow(row);
    return { success: true, created: true, updated: false, user: userObjectFromRow(headers, row) };
  }

  let updated = false;
  headers.forEach((h, i) => {
    if (safeFields[h] === undefined) return;
    const incoming = safeFields[h];
    if (h === 'email') return;
    if (h === 'membershipStatus' || h === 'paymentStatus') {
      if (opts.syncStatuses && incoming && values[rowIndex][i] !== incoming) {
        sheet.getRange(rowIndex + 1, i + 1).setValue(incoming);
        updated = true;
      }
      return;
    }
    if (opts.fillMissingOnly) {
      if ((values[rowIndex][i] === '' || values[rowIndex][i] === null) && incoming !== '' && incoming !== null && incoming !== undefined) {
        sheet.getRange(rowIndex + 1, i + 1).setValue(incoming);
        updated = true;
      }
    } else if (incoming !== undefined) {
      sheet.getRange(rowIndex + 1, i + 1).setValue(incoming);
      updated = true;
    }
  });
  const updatedAtIdx = headers.indexOf('updatedAt');
  if (updatedAtIdx !== -1 && updated) sheet.getRange(rowIndex + 1, updatedAtIdx + 1).setValue(now);

  const fresh = sheet.getDataRange().getValues();
  return { success: true, created: false, updated, user: userObjectFromRow(headers, fresh[rowIndex]) };
}

function updateUserProfile(data) {
  const email = normalizeEmail(data.email);
  if (!email) return { success: false, message: "Email required" };

  const sheet = getOrCreateSheet('Users', ["id", "name", "email", "phone", "area", "pincode", "genres", "bio", "membershipStatus", "paymentStatus", "createdAt", "updatedAt"]);
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(h => String(h).trim());
  const emailIdx = headers.indexOf('email');
  let rowIndex = values.findIndex((r, idx) => idx > 0 && normalizeEmail(r[emailIdx]) === email);
  
  // If user doesn't exist, create it (part of E2E fix)
  if (rowIndex === -1) {
    const row = new Array(headers.length).fill("");
    headers.forEach((h, i) => {
      if (h === 'id') row[i] = generateId('SS_USR_');
      else if (h === 'email') row[i] = email;
      else if (h === 'name') row[i] = data.name || data.fullName || '';
      else if (h === 'phone') row[i] = data.phone;
      else if (h === 'area') row[i] = data.area;
      else if (h === 'pincode') row[i] = data.pincode;
      else if (h === 'genres') row[i] = data.genres;
      else if (h === 'bio') row[i] = data.bio;
      else if (h === 'createdAt') row[i] = new Date();
      else if (h === 'updatedAt') row[i] = new Date();
    });
    sheet.appendRow(row);
    return { success: true, message: "Profile created successfully", profile: userObjectFromRow(headers, row) };
  }

  const updates = {
    name: data.name || data.fullName,
    phone: data.phone,
    area: data.area,
    pincode: data.pincode,
    genres: data.genres,
    bio: data.bio,
    updatedAt: new Date()
  };

  for (let key in updates) {
    const colIdx = headers.indexOf(key);
    if (colIdx !== -1) {
      sheet.getRange(rowIndex + 1, colIdx + 1).setValue(updates[key]);
    }
  }

  const freshValues = sheet.getDataRange().getValues();
  return { success: true, message: "Profile updated successfully", profile: userObjectFromRow(headers, freshValues[rowIndex]) };
}

const CURRENT_READ_CIRCLE_HEADERS = [
  "circle_id", "book_title", "normalized_book_title", "author", "normalized_author",
  "cover_url", "status", "created_by_user_id", "created_at", "updated_at"
];
const CURRENT_READ_MEMBER_HEADERS = [
  "member_id", "circle_id", "user_id", "user_name", "reading_progress", "format", "note", "joined_at"
];
const CURRENT_READ_MESSAGE_HEADERS = [
  "message_id", "circle_id", "user_id", "user_name", "message", "is_spoiler", "created_at", "image_url"
];

// =====================================================================
// READER'S CAFÉ — the permanent community table
// ---------------------------------------------------------------------
// Structurally the Café is just a Readers Circle with a reserved id that
// every member implicitly belongs to. That is deliberate: it means the
// Café stores in the SAME current_read_messages sheet, with the same
// columns and the same row shape, so there is no second chat system, no
// new sheet, and no duplicated message plumbing to keep in sync.
//
// The two differences from a real circle are both about membership:
//   • nobody "joins" — there is no members row, so the membership checks
//     are skipped and replaced with the ordinary SwapSutra membership
//     gate (an active reader may post; nobody else may);
//   • history is public — a visitor can read the room before deciding to
//     join SwapSutra, which is the whole point of putting it out front.
//
// getCircleMessages is deliberately NOT made public to achieve that: it
// would expose every private circle to anyone who guessed an id. The
// Café gets its own narrow read action instead.
// =====================================================================

const READERS_CAFE_CIRCLE_ID = "SS_READERS_CAFE";
const READERS_CAFE_PAGE_SIZE = 80;

function isReadersCafeCircle(circleId) {
  return String(circleId || "").trim().toUpperCase() === READERS_CAFE_CIRCLE_ID;
}

/**
 * Public read of the Café. Returns the most recent messages plus a
 * little life-signal (how many distinct readers have spoken, when the
 * last message landed) so the homepage can show that people are already
 * here rather than an empty invitation.
 *
 * Session-exempt on purpose — a visitor should be able to listen at the
 * door. Only non-sensitive fields are returned: a first name, the text,
 * and a timestamp. No email ever leaves this function.
 */
/* ── Reactions ────────────────────────────────────────────────────────
   One row per (message, reader, emoji). Tapping the same emoji twice
   removes the row, so a reader's own reaction is a toggle rather than
   something they can stack.

   The allowlist is deliberate: an open emoji field is a moderation
   surface on a public page, and six warm ones cover what a reading room
   actually says to each other.
   ──────────────────────────────────────────────────────────────────── */
const CAFE_REACTION_HEADERS = ["reaction_id", "message_id", "user_id", "emoji", "created_at"];
const CAFE_REACTION_CHOICES = ["❤️", "😂", "😮", "😢", "🔥", "📚"];
const CAFE_REACTIONS_PER_READER = 3;

function getCafeReactionSheet() {
  const sheet = getOrCreateSheet("cafe_reactions", CAFE_REACTION_HEADERS);
  ensureSheetHeaders(sheet, CAFE_REACTION_HEADERS);
  return sheet;
}

/**
 * Adds or removes this reader's reaction. Returns the message's fresh
 * counts so the client never has to guess what the server now holds.
 */
function toggleCafeReaction(data) {
  const source = data || {};
  const userId = normalizeEmail(getAuthenticatedEmail() || source.user_id || source.userEmail || "");
  const messageId = String(source.messageId || source.message_id || "").trim();
  const emoji = String(source.emoji || "").trim();

  if (!userId) return { success: false, message: "Sign in to react.", error: "SESSION_REQUIRED" };
  if (!messageId) return { success: false, message: "Missing message.", error: "MESSAGE_NOT_FOUND" };
  if (CAFE_REACTION_CHOICES.indexOf(emoji) === -1) {
    return { success: false, message: "That reaction isn't available.", error: "REACTION_NOT_ALLOWED" };
  }

  const accessError = requireApprovedMember(userId, "Reacting in the Reader's Café");
  if (accessError) return accessError;

  const sheet = getCafeReactionSheet();
  const rows = cafeSheetObjects(sheet);

  const mine = rows.filter(function (row) {
    return String(row.message_id) === messageId && normalizeEmail(row.user_id) === userId;
  });
  const existing = mine.find(function (row) { return String(row.emoji) === emoji; });

  if (existing) {
    sheet.deleteRow(existing.__row);
  } else {
    if (mine.length >= CAFE_REACTIONS_PER_READER) {
      return {
        success: false,
        message: `You can add up to ${CAFE_REACTIONS_PER_READER} reactions to one message.`,
        error: "REACTION_LIMIT_REACHED"
      };
    }
    appendObjectRow("cafe_reactions", CAFE_REACTION_HEADERS, {
      reaction_id: "RX_" + Utilities.getUuid(),
      message_id: messageId,
      user_id: userId,
      emoji: emoji,
      created_at: new Date().toISOString()
    });
  }

  const after = cafeSheetObjects(getCafeReactionSheet())
    .filter(function (row) { return String(row.message_id) === messageId; });

  return {
    success: true,
    messageId: messageId,
    reactions: summariseReactions(after, userId)
  };
}

/**
 * Rolls raw reaction rows into what a bubble renders: the emoji, how
 * many, and whether this reader is one of them. Reader identities are
 * never published — only the count.
 */
function summariseReactions(rowsForMessage, viewerEmail) {
  const byEmoji = {};
  const order = [];
  (rowsForMessage || []).forEach(function (row) {
    const emoji = String(row.emoji || "");
    if (!emoji) return;
    if (!byEmoji[emoji]) {
      byEmoji[emoji] = { emoji: emoji, count: 0, mine: false };
      order.push(emoji);
    }
    byEmoji[emoji].count++;
    if (viewerEmail && normalizeEmail(row.user_id) === viewerEmail) byEmoji[emoji].mine = true;
  });
  return order
    .map(function (e) { return byEmoji[e]; })
    .sort(function (a, b) { return b.count - a.count; });
}

/**
 * The note at the top of the room. Set it from the Apps Script UI
 * (Project Settings → Script Properties → CAFE_PINNED_MESSAGE); leaving
 * it unset simply means no pinned bar renders, rather than a placeholder
 * pretending to be a house rule nobody wrote.
 */
function getCafePinnedMessage() {
  const raw = getScriptSetting("CAFE_PINNED_MESSAGE");
  return String(raw || "").trim().slice(0, 400);
}

function getReadersCafe(data) {
  const source = data || {};
  const limit = Math.min(Number(source.limit) || READERS_CAFE_PAGE_SIZE, 200);
  const rows = getCurrentReadRows();

  const cafeMessages = rows.messages.filter(m => isReadersCafeCircle(m.circle_id));

  const speakers = {};
  cafeMessages.forEach(m => {
    const who = String(m.user_id || "").trim().toLowerCase();
    if (who) speakers[who] = true;
  });

  const ordered = cafeMessages
    .slice()
    .sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

  // Computed here against the verified session so the room can align a
  // reader's own messages to one side. The senders' addresses themselves
  // are never part of the response.
  const viewerEmail = normalizeEmail(getAuthenticatedEmail() || "");

  // Reactions for the whole room in one read, grouped by message, rather
  // than a sheet scan per bubble.
  const reactionsByMessage = {};
  try {
    cafeSheetObjects(getCafeReactionSheet()).forEach(function (row) {
      const key = String(row.message_id || "");
      if (!key) return;
      if (!reactionsByMessage[key]) reactionsByMessage[key] = [];
      reactionsByMessage[key].push(row);
    });
  } catch (err) {
    // Reactions are decoration. A failure here must not empty the room.
    Logger.log("Café reactions unavailable: " + err);
  }

  const recent = ordered.slice(Math.max(0, ordered.length - limit)).map(message => ({
    message_id: message.message_id,
    circle_id: READERS_CAFE_CIRCLE_ID,
    is_mine: Boolean(viewerEmail) && normalizeEmail(message.user_id) === viewerEmail,
    // First name only — the Café is public, so a full name or an email
    // here would publish it to the open web. Resolved against the member
    // directory so rows written before this fix (which stored the sender's
    // address in user_name) render as a name too.
    user_name: publicReaderName(message.user_name, message.user_id),
    // Opaque, non-reversible. Lets a name in the room link to a profile
    // while the sender's address stays server-side.
    author_id: readerPublicId(message.user_id),
    message: message.message,
    is_spoiler: String(message.is_spoiler).toLowerCase() === "true" || String(message.is_spoiler).toLowerCase() === "yes",
    created_at: message.created_at,
    image_url: message.image_url || message.imageUrl || "",
    reactions: summariseReactions(reactionsByMessage[String(message.message_id)] || [], viewerEmail)
  }));

  const last = ordered.length ? ordered[ordered.length - 1] : null;

  return {
    success: true,
    circleId: READERS_CAFE_CIRCLE_ID,
    data: recent,
    totalMessages: ordered.length,
    // Everyone who has ever spoken here. NOT "online now" — nothing in
    // this stack tracks presence, and a number that claims to would be
    // invented.
    readerCount: Object.keys(speakers).length,
    pinnedMessage: getCafePinnedMessage(),
    reactionChoices: CAFE_REACTION_CHOICES,
    lastMessageAt: last ? last.created_at : "",
    lastMessagePreview: last ? String(last.message || "").slice(0, 140) : "",
    lastMessageBy: last ? publicReaderName(last.user_name, last.user_id) : ""
  };
}


// =====================================================================
// READER'S CAFÉ — STORIES
// ---------------------------------------------------------------------
// A story is a photo or short clip a reader pins to the café wall for a
// day: the shelf they just reorganised, the page that undid them, the
// queue at a book fair. It disappears after 24 hours on purpose — the
// café should feel like today, not like an archive.
//
// Two sheets, same spreadsheet, same conventions as everything else:
//   cafe_stories       one row per story
//   cafe_story_views   one row per (story, viewer) pair, written once
//
// Who sees what:
//   • Anyone may READ the wall — same as the café conversation itself.
//   • Only an approved active member may POST.
//   • Only the author (or an admin) may see the viewer list. That is the
//     whole point of the feature, and also the reason it is gated: the
//     list is a set of names attached to a browsing habit.
// =====================================================================

const CAFE_STORY_HEADERS = [
  "story_id", "user_id", "user_name", "media_type", "media_url",
  "caption", "created_at", "expires_at", "status"
];
const CAFE_STORY_VIEW_HEADERS = [
  "view_id", "story_id", "viewer_id", "viewer_name", "viewed_at"
];

const CAFE_STORY_TTL_MS = 24 * 60 * 60 * 1000;
const CAFE_STORY_MAX_PER_DAY = 10;
const CAFE_STORY_CAPTION_MAX = 240;

/**
 * Vercel caps a request body at 4.5MB and base64 inflates a file by
 * roughly a third, so the honest ceiling for anything arriving through
 * the proxy is well under that. Images are compressed client-side before
 * they get here; video is capped hard and the limit is stated in the
 * error so a reader is never left guessing why a clip vanished.
 */
const CAFE_STORY_MAX_IMAGE_BYTES = 2 * 1024 * 1024;
const CAFE_STORY_MAX_VIDEO_BYTES = 3 * 1024 * 1024;

const CAFE_STORY_IMAGE_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
const CAFE_STORY_VIDEO_TYPES = ['video/mp4', 'video/webm', 'video/quicktime'];

/**
 * The parent Drive folder for book photos, resolved once per request.
 *
 * DriveApp.getFoldersByName scans the whole drive, and listing a book
 * used to pay for that scan on top of a createFile + setSharing + getUrl
 * for every photo. Those round trips are the reason a listing with three
 * photos could outrun a serverless timeout.
 */
let __SS_BOOK_FOLDER__ = null;
function resetDriveCache() { __SS_BOOK_FOLDER__ = null; }

function getBookUploadFolder() {
  if (__SS_BOOK_FOLDER__) return __SS_BOOK_FOLDER__;
  const found = DriveApp.getFoldersByName("SwapSutra_Books");
  __SS_BOOK_FOLDER__ = found.hasNext() ? found.next() : DriveApp.createFolder("SwapSutra_Books");
  return __SS_BOOK_FOLDER__;
}

function getCafeStorySheets() {
  const storySheet = getOrCreateSheet("cafe_stories", CAFE_STORY_HEADERS);
  const viewSheet = getOrCreateSheet("cafe_story_views", CAFE_STORY_VIEW_HEADERS);
  ensureSheetHeaders(storySheet, CAFE_STORY_HEADERS);
  ensureSheetHeaders(viewSheet, CAFE_STORY_VIEW_HEADERS);
  return { storySheet: storySheet, viewSheet: viewSheet };
}

function cafeSheetObjects(sheet) {
  const values = sheet.getDataRange().getValues();
  if (!values || values.length <= 1) return [];
  const headers = values[0];
  const out = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!row.some(function (cell) { return String(cell || "").trim() !== ""; })) continue;
    const obj = {};
    headers.forEach(function (h, idx) { obj[String(h)] = row[idx]; });
    obj.__row = i + 1;
    out.push(obj);
  }
  return out;
}

function cafeStoryIsLive(story, nowMs) {
  if (String(story.status || "").trim().toLowerCase() === "removed") return false;
  const expiresAt = new Date(story.expires_at).getTime();
  if (!isNaN(expiresAt)) return expiresAt > nowMs;
  const createdAt = new Date(story.created_at).getTime();
  if (isNaN(createdAt)) return false;
  return (createdAt + CAFE_STORY_TTL_MS) > nowMs;
}

/**
 * Splits a data URL into its parts and refuses anything that is not an
 * image or a short clip. Returns { ok, mimeType, kind, bytes, message }.
 */
function inspectCafeStoryMedia(dataUrl) {
  const raw = String(dataUrl || "");
  if (!raw) return { ok: false, message: "Add a photo or a short clip to post a story." };

  const parts = raw.split(",");
  if (parts.length < 2) return { ok: false, message: "That file didn't upload correctly. Try picking it again." };

  const typeMatch = parts[0].match(/:(.*?);/);
  if (!typeMatch) return { ok: false, message: "That file didn't upload correctly. Try picking it again." };
  const mimeType = String(typeMatch[1]).toLowerCase();

  const isImage = CAFE_STORY_IMAGE_TYPES.indexOf(mimeType) !== -1;
  const isVideo = CAFE_STORY_VIDEO_TYPES.indexOf(mimeType) !== -1;
  if (!isImage && !isVideo) {
    return { ok: false, message: "Stories accept photos (JPG, PNG, WebP) and short clips (MP4, WebM)." };
  }

  // base64 -> bytes without decoding the whole payload twice.
  const b64 = parts[1].replace(/=+$/, "");
  const bytes = Math.floor(b64.length * 3 / 4);

  const cap = isVideo ? CAFE_STORY_MAX_VIDEO_BYTES : CAFE_STORY_MAX_IMAGE_BYTES;
  if (bytes > cap) {
    const capMb = Math.round(cap / (1024 * 1024) * 10) / 10;
    return {
      ok: false,
      message: isVideo
        ? `That clip is too large. Stories take videos up to about ${capMb}MB — try a shorter one (roughly 10 seconds).`
        : `That photo is too large. Stories take images up to about ${capMb}MB.`
    };
  }

  return { ok: true, mimeType: mimeType, kind: isVideo ? "video" : "image", bytes: bytes };
}

/**
 * The public wall. Returns every live story grouped by its author, with
 * the viewer count folded in for the author's own stories only.
 */
function getCafeStories(data) {
  const source = data || {};
  const viewerEmail = normalizeEmail(getAuthenticatedEmail() || source.userEmail || source.user_id || "");
  const isAdminViewer = isAuthenticatedAdmin();
  const nowMs = new Date().getTime();

  const sheets = getCafeStorySheets();
  const live = cafeSheetObjects(sheets.storySheet).filter(function (story) {
    return cafeStoryIsLive(story, nowMs);
  });

  const views = cafeSheetObjects(sheets.viewSheet);
  const viewCounts = {};
  const seenByMe = {};
  views.forEach(function (view) {
    const storyId = String(view.story_id || "");
    if (!storyId) return;
    viewCounts[storyId] = (viewCounts[storyId] || 0) + 1;
    if (viewerEmail && normalizeEmail(view.viewer_id) === viewerEmail) seenByMe[storyId] = true;
  });

  const ordered = live.slice().sort(function (a, b) {
    return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
  });

  const stories = ordered.map(function (story) {
    const authorEmail = normalizeEmail(story.user_id);
    const mine = Boolean(viewerEmail) && authorEmail === viewerEmail;
    return {
      storyId: String(story.story_id || ""),
      authorName: publicReaderName(story.user_name, story.user_id),
      // The author's address is never published. `isMine` is what the UI
      // needs, and it is computed here against the verified session.
      isMine: mine,
      mediaType: String(story.media_type || "image"),
      mediaUrl: String(story.media_url || ""),
      caption: String(story.caption || ""),
      createdAt: String(story.created_at || ""),
      expiresAt: String(story.expires_at || ""),
      viewedByMe: Boolean(seenByMe[String(story.story_id || "")]),
      // Only an author sees how many people watched. Showing it to
      // everyone turns a shelf photo into a popularity contest.
      viewCount: (mine || isAdminViewer) ? (viewCounts[String(story.story_id || "")] || 0) : null
    };
  });

  // Grouped so the wall renders as rings of readers, not a flat list.
  const groups = [];
  const byAuthor = {};
  stories.forEach(function (story) {
    const key = story.authorName + "|" + (story.isMine ? "me" : "them");
    if (!byAuthor[key]) {
      byAuthor[key] = {
        authorName: story.authorName,
        isMine: story.isMine,
        stories: [],
        latestAt: story.createdAt,
        allViewed: true
      };
      groups.push(byAuthor[key]);
    }
    const group = byAuthor[key];
    group.stories.push(story);
    if (story.createdAt > group.latestAt) group.latestAt = story.createdAt;
    if (!story.viewedByMe && !story.isMine) group.allViewed = false;
  });

  groups.sort(function (a, b) {
    if (a.isMine !== b.isMine) return a.isMine ? -1 : 1;
    if (a.allViewed !== b.allViewed) return a.allViewed ? 1 : -1;
    return new Date(b.latestAt).getTime() - new Date(a.latestAt).getTime();
  });

  return {
    success: true,
    stories: stories,
    groups: groups,
    total: stories.length,
    ttlHours: 24
  };
}

/** Post a story. Members only, rate-limited, media validated. */
function postCafeStory(data) {
  const source = data || {};
  const userId = normalizeEmail(getAuthenticatedEmail() || source.user_id || source.userEmail || "");
  if (!userId) {
    return { success: false, message: "Sign in to post a story.", error: "SESSION_REQUIRED" };
  }

  const accessError = requireApprovedMember(userId, "Posting a story to the Reader's Café");
  if (accessError) return accessError;

  const media = inspectCafeStoryMedia(source.media || source.mediaData || source.fileData);
  if (!media.ok) return { success: false, message: media.message, error: "STORY_MEDIA_REJECTED" };

  const nowMs = new Date().getTime();
  const sheets = getCafeStorySheets();
  const existing = cafeSheetObjects(sheets.storySheet);

  const mineToday = existing.filter(function (story) {
    if (normalizeEmail(story.user_id) !== userId) return false;
    return cafeStoryIsLive(story, nowMs);
  });
  if (mineToday.length >= CAFE_STORY_MAX_PER_DAY) {
    return {
      success: false,
      message: `You can have up to ${CAFE_STORY_MAX_PER_DAY} stories on the wall at once. Older ones clear themselves within a day.`,
      error: "STORY_LIMIT_REACHED"
    };
  }

  // Same server-side PII gate as every other free-text surface, and run
  // BEFORE the media upload below — a blocked caption must not leave any
  // trace, including a Drive file that would otherwise be orphaned by an
  // aborted post. Skipped only for admin, same convention as elsewhere.
  const caption = String(source.caption || "").slice(0, CAFE_STORY_CAPTION_MAX);
  if (caption && !isAdminEmail(userId)) {
    const piiScan = scanUserGeneratedContent(caption);
    if (piiScan.blocked) {
      logChatSafetyEvent({
        chatId: '',
        swapId: '',
        senderEmail: userId,
        category: piiScan.category,
        contentType: 'CAFE_STORY'
      });
      return {
        success: false,
        blocked: true,
        reason: 'PERSONAL_INFORMATION',
        category: piiScan.category,
        message: piiWarningForCategory(piiScan.category)
      };
    }
  }

  const extension = media.kind === "video" ? "mp4" : "jpg";
  const mediaUrl = saveFileToDrive(
    String(source.media || source.mediaData || source.fileData),
    "cafe_story_" + nowMs + "." + extension
  );
  if (!mediaUrl) {
    return { success: false, message: "We couldn't save that file. Try a smaller one.", error: "STORY_UPLOAD_FAILED" };
  }

  const storyId = "STORY_" + Utilities.getUuid();
  const createdAt = new Date(nowMs).toISOString();
  const expiresAt = new Date(nowMs + CAFE_STORY_TTL_MS).toISOString();
  const userName = publicReaderName(source.user_name || source.userName || source.name, userId);

  appendObjectRow("cafe_stories", CAFE_STORY_HEADERS, {
    story_id: storyId,
    user_id: userId,
    user_name: userName,
    media_type: media.kind,
    media_url: mediaUrl,
    caption: caption,
    created_at: createdAt,
    expires_at: expiresAt,
    status: "active"
  });

  return {
    success: true,
    message: "Your story is on the café wall for the next 24 hours.",
    story: {
      storyId: storyId,
      authorName: userName,
      isMine: true,
      mediaType: media.kind,
      mediaUrl: mediaUrl,
      caption: caption,
      createdAt: createdAt,
      expiresAt: expiresAt,
      viewedByMe: true,
      viewCount: 0
    }
  };
}

/**
 * Records that this reader watched a story. Written once per viewer per
 * story; a re-watch does not inflate the author's count. A signed-out
 * visitor is counted as nobody — we do not invent an identity for them.
 */
function markCafeStoryViewed(data) {
  const source = data || {};
  const viewerId = normalizeEmail(getAuthenticatedEmail() || source.user_id || source.userEmail || "");
  const storyId = String(source.storyId || source.story_id || "").trim();

  if (!storyId) return { success: false, message: "Missing story.", error: "STORY_NOT_FOUND" };
  if (!viewerId) return { success: true, skipped: "anonymous_viewer" };

  const nowMs = new Date().getTime();
  const sheets = getCafeStorySheets();

  const story = cafeSheetObjects(sheets.storySheet).find(function (row) {
    return String(row.story_id) === storyId;
  });
  if (!story || !cafeStoryIsLive(story, nowMs)) {
    return { success: false, message: "That story has already faded.", error: "STORY_EXPIRED" };
  }

  // An author watching their own story is not an audience.
  if (normalizeEmail(story.user_id) === viewerId) return { success: true, skipped: "author_is_not_a_viewer" };

  const already = cafeSheetObjects(sheets.viewSheet).some(function (view) {
    return String(view.story_id) === storyId && normalizeEmail(view.viewer_id) === viewerId;
  });
  if (already) return { success: true, skipped: "already_recorded" };

  appendObjectRow("cafe_story_views", CAFE_STORY_VIEW_HEADERS, {
    view_id: "SV_" + Utilities.getUuid(),
    story_id: storyId,
    viewer_id: viewerId,
    viewer_name: publicReaderName(source.user_name || source.userName || source.name, viewerId),
    viewed_at: new Date(nowMs).toISOString()
  });

  return { success: true };
}

/**
 * The author's own audience list. Gated on the verified session rather
 * than on an email in the payload — otherwise anyone could ask who has
 * been watching anyone else.
 */
function getCafeStoryViewers(data) {
  const source = data || {};
  const requesterId = normalizeEmail(getAuthenticatedEmail() || "");
  const storyId = String(source.storyId || source.story_id || "").trim();

  if (!requesterId) return { success: false, message: "Sign in to see who watched your story.", error: "SESSION_REQUIRED" };
  if (!storyId) return { success: false, message: "Missing story.", error: "STORY_NOT_FOUND" };

  const sheets = getCafeStorySheets();
  const story = cafeSheetObjects(sheets.storySheet).find(function (row) {
    return String(row.story_id) === storyId;
  });
  if (!story) return { success: false, message: "That story has already faded.", error: "STORY_NOT_FOUND" };

  if (normalizeEmail(story.user_id) !== requesterId && !isAuthenticatedAdmin()) {
    return { success: false, message: "Only the reader who posted a story can see who watched it.", error: "NOT_STORY_OWNER" };
  }

  const viewers = cafeSheetObjects(sheets.viewSheet)
    .filter(function (view) { return String(view.story_id) === storyId; })
    .sort(function (a, b) { return new Date(b.viewed_at).getTime() - new Date(a.viewed_at).getTime(); })
    .map(function (view) {
      return {
        name: publicReaderName(view.viewer_name, view.viewer_id),
        viewedAt: String(view.viewed_at || "")
      };
    });

  return { success: true, storyId: storyId, viewers: viewers, viewCount: viewers.length };
}

/** An author (or an admin) takes a story down before it expires. */
function deleteCafeStory(data) {
  const source = data || {};
  const requesterId = normalizeEmail(getAuthenticatedEmail() || "");
  const storyId = String(source.storyId || source.story_id || "").trim();

  if (!requesterId) return { success: false, message: "Sign in first.", error: "SESSION_REQUIRED" };
  if (!storyId) return { success: false, message: "Missing story.", error: "STORY_NOT_FOUND" };

  const sheets = getCafeStorySheets();
  const story = cafeSheetObjects(sheets.storySheet).find(function (row) {
    return String(row.story_id) === storyId;
  });
  if (!story) return { success: false, message: "That story is already gone.", error: "STORY_NOT_FOUND" };

  if (normalizeEmail(story.user_id) !== requesterId && !isAuthenticatedAdmin()) {
    return { success: false, message: "Only the reader who posted a story can remove it.", error: "NOT_STORY_OWNER" };
  }

  const headers = sheets.storySheet.getDataRange().getValues()[0].map(String);
  const statusCol = headers.indexOf("status") + 1;
  if (statusCol > 0) sheets.storySheet.getRange(story.__row, statusCol).setValue("removed");

  return { success: true, message: "Story removed." };
}

/**
 * Housekeeping for a daily trigger: clears rows whose 24 hours are up so
 * the sheet does not grow without bound. Safe to run at any time, and
 * safe to never run — every read path already filters by expiry.
 */
function purgeExpiredCafeStories() {
  const nowMs = new Date().getTime();
  const sheets = getCafeStorySheets();

  const stories = cafeSheetObjects(sheets.storySheet);
  const deadIds = {};
  const deadRows = [];
  stories.forEach(function (story) {
    if (cafeStoryIsLive(story, nowMs)) return;
    deadIds[String(story.story_id)] = true;
    deadRows.push(story.__row);
  });

  const viewRows = cafeSheetObjects(sheets.viewSheet)
    .filter(function (view) { return deadIds[String(view.story_id)]; })
    .map(function (view) { return view.__row; });

  // Bottom-up so earlier deletions do not shift the rows still to go.
  viewRows.sort(function (a, b) { return b - a; }).forEach(function (row) {
    sheets.viewSheet.deleteRow(row);
  });
  deadRows.sort(function (a, b) { return b - a; }).forEach(function (row) {
    sheets.storySheet.deleteRow(row);
  });

  return { success: true, storiesRemoved: deadRows.length, viewsRemoved: viewRows.length };
}

function normalizeCurrentReadText(value) {
  return String(value || "")
    .toLowerCase()
    .trim()
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ");
}

function currentReadRowToObject(headers, row) {
  const obj = {};
  headers.forEach((h, i) => obj[h] = row[i]);
  return obj;
}

function getCurrentReadSheets() {
  const circleSheet = getOrCreateSheet("current_read_circles", CURRENT_READ_CIRCLE_HEADERS);
  const memberSheet = getOrCreateSheet("current_read_members", CURRENT_READ_MEMBER_HEADERS);
  const messageSheet = getOrCreateSheet("current_read_messages", CURRENT_READ_MESSAGE_HEADERS);
  ensureSheetHeaders(circleSheet, CURRENT_READ_CIRCLE_HEADERS);
  ensureSheetHeaders(memberSheet, CURRENT_READ_MEMBER_HEADERS);
  ensureSheetHeaders(messageSheet, CURRENT_READ_MESSAGE_HEADERS);
  return { circleSheet, memberSheet, messageSheet };
}

function getCurrentReadRows() {
  const sheets = getCurrentReadSheets();
  const circleValues = sheets.circleSheet.getDataRange().getValues();
  const memberValues = sheets.memberSheet.getDataRange().getValues();
  const messageValues = sheets.messageSheet.getDataRange().getValues();
  const circleHeaders = circleValues[0] || CURRENT_READ_CIRCLE_HEADERS;
  const memberHeaders = memberValues[0] || CURRENT_READ_MEMBER_HEADERS;
  const messageHeaders = messageValues[0] || CURRENT_READ_MESSAGE_HEADERS;

  return {
    ...sheets,
    circleHeaders,
    memberHeaders,
    messageHeaders,
    circles: circleValues.slice(1).filter(row => row.some(Boolean)).map(row => currentReadRowToObject(circleHeaders, row)),
    members: memberValues.slice(1).filter(row => row.some(Boolean)).map(row => currentReadRowToObject(memberHeaders, row)),
    messages: messageValues.slice(1).filter(row => row.some(Boolean)).map(row => currentReadRowToObject(messageHeaders, row))
  };
}

function publicCurrentReadCircle(circle, members, messages) {
  const circleMembers = members.filter(m => String(m.circle_id) === String(circle.circle_id));
  const circleMessages = (messages || [])
    .filter(m => String(m.circle_id) === String(circle.circle_id))
    .map(m => ({
      message_id: m.message_id,
      circle_id: m.circle_id,
      user_id: m.user_id,
      user_name: publicReaderName(m.user_name, m.user_id),
      message: m.message,
      is_spoiler: String(m.is_spoiler).toLowerCase() === "true" || String(m.is_spoiler).toLowerCase() === "yes",
      created_at: m.created_at,
      image_url: m.image_url || m.imageUrl || ""
    }));

  return {
    circle_id: circle.circle_id,
    book_title: circle.book_title,
    normalized_book_title: circle.normalized_book_title,
    author: circle.author,
    normalized_author: circle.normalized_author,
    cover_url: circle.cover_url,
    status: circle.status || "Waiting",
    created_by_user_id: circle.created_by_user_id,
    created_at: circle.created_at,
    updated_at: circle.updated_at,
    reader_count: uniqueCurrentReadUserCount(circle.circle_id, members),
    members: circleMembers.map(m => ({
      member_id: m.member_id,
      circle_id: m.circle_id,
      user_id: m.user_id,
      user_name: publicReaderName(m.user_name, m.user_id),
      reading_progress: m.reading_progress,
      format: m.format,
      note: m.note,
      joined_at: m.joined_at
    })),
    messages: circleMessages
  };
}

/**
 * Turns an email address into something a human can be called in public.
 * "priya.sharma94@gmail.com" -> "Priya". Never returns anything with an
 * "@" in it, because the value it produces is published to the open web.
 */
function humanizeEmailLocalPart(value) {
  const local = String(value || "").split("@")[0];
  const cleaned = local
    .replace(/[._+\-]+/g, " ")
    .replace(/[0-9]+/g, " ")
    .trim();
  const first = cleaned.split(/\s+/)[0];
  if (!first) return "";
  return first.charAt(0).toUpperCase() + first.slice(1).toLowerCase();
}

/**
 * The single public display-name funnel. An email has no whitespace, so
 * the old `split(/\s+/)[0]` handed the whole address back and the Café
 * published it. Anything containing "@" is now treated as an address and
 * reduced to its human part before it can leave the server.
 */
function firstNameOnly(name) {
  const raw = String(name === null || name === undefined ? "" : name).trim();
  if (!raw) return "Reader";
  if (raw.indexOf("@") !== -1) {
    return humanizeEmailLocalPart(raw) || "Reader";
  }
  const first = raw.split(/\s+/)[0];
  return first || "Reader";
}

/**
 * Email -> registered name, built once per request from Subscriptions.
 * Rows written before this fix stored the sender's email in `user_name`;
 * looking the address up here means those old rows render as the reader's
 * actual name rather than a mangled local part.
 */
let __SS_READER_NAMES__ = null;
function resetReaderNameDirectory() {
  __SS_READER_NAMES__ = null;
}
function getReaderNameDirectory() {
  if (__SS_READER_NAMES__) return __SS_READER_NAMES__;
  const map = {};
  try {
    const values = getOrCreateSheet('Subscriptions', []).getDataRange().getValues();
    if (values && values.length > 1) {
      const headers = values[0].map(function (h) { return String(h || "").trim().toLowerCase(); });
      const nameIdx = headers.indexOf('name');
      const emailIdx = headers.indexOf('email');
      const userEmailIdx = headers.indexOf('useremail');
      if (nameIdx !== -1) {
        for (let i = 1; i < values.length; i++) {
          const row = values[i];
          const name = String(row[nameIdx] || "").trim();
          if (!name || name.indexOf("@") !== -1) continue;
          const addresses = [];
          if (emailIdx !== -1) addresses.push(row[emailIdx]);
          if (userEmailIdx !== -1) addresses.push(row[userEmailIdx]);
          addresses.forEach(function (candidate) {
            const email = String(candidate || "").trim().toLowerCase();
            if (email && !map[email]) map[email] = name;
          });
        }
      }
    }
  } catch (err) {
    // A missing directory must never take the Café down.
    Logger.log("Reader name directory unavailable: " + err);
  }
  __SS_READER_NAMES__ = map;
  return map;
}

/**
 * What a reader is called in public. Prefers a real stored name, then the
 * registered name on file for that address, and only then a humanized
 * local part. The return value is guaranteed free of "@".
 */
function publicReaderName(nameCandidate, email) {
  const candidate = String(nameCandidate || "").trim();
  if (candidate && candidate.indexOf("@") === -1) return firstNameOnly(candidate);

  const key = String(email || candidate || "").trim().toLowerCase();
  if (key) {
    const known = getReaderNameDirectory()[key];
    if (known) return firstNameOnly(known);
  }
  return firstNameOnly(candidate || key);
}

function findCurrentReadCircleByNormalized(circles, bookTitle, author) {
  const normalizedTitle = normalizeCurrentReadText(bookTitle);
  const normalizedAuthor = normalizeCurrentReadText(author);
  if (!normalizedTitle) return null;
  return circles.find(circle => {
    if (String(circle.normalized_book_title) !== normalizedTitle) return false;
    if (normalizedAuthor && circle.normalized_author) {
      return String(circle.normalized_author) === normalizedAuthor;
    }
    return true;
  }) || null;
}

function uniqueCurrentReadUserCount(circleId, members) {
  const users = {};
  members.forEach(member => {
    if (String(member.circle_id) === String(circleId) && member.user_id) {
      users[String(member.user_id).trim().toLowerCase()] = true;
    }
  });
  return Object.keys(users).length;
}

function isCurrentReadMember(circleId, userId, members) {
  const normalizedUser = String(userId || "").trim().toLowerCase();
  if (!circleId || !normalizedUser) return false;
  return members.some(member =>
    String(member.circle_id) === String(circleId) &&
    String(member.user_id || "").trim().toLowerCase() === normalizedUser
  );
}

function updateCurrentReadCircleStatus(circleId, members) {
  const rows = getCurrentReadRows();
  const idIdx = rows.circleHeaders.indexOf("circle_id");
  const statusIdx = rows.circleHeaders.indexOf("status");
  const updatedIdx = rows.circleHeaders.indexOf("updated_at");
  const values = rows.circleSheet.getDataRange().getValues();
  const rowIndex = values.findIndex((row, idx) => idx > 0 && String(row[idIdx]) === String(circleId));
  if (rowIndex === -1) return;

  const nextStatus = uniqueCurrentReadUserCount(circleId, members) >= 3 ? "Active Discussion" : "Waiting";
  if (statusIdx !== -1) rows.circleSheet.getRange(rowIndex + 1, statusIdx + 1).setValue(nextStatus);
  if (updatedIdx !== -1) rows.circleSheet.getRange(rowIndex + 1, updatedIdx + 1).setValue(new Date());
}

function getCurrentReadCircles() {
  const rows = getCurrentReadRows();
  const data = rows.circles.map(circle => publicCurrentReadCircle(circle, rows.members, []));
  return { success: true, data };
}

function searchCurrentReadCircles(data) {
  const rows = getCurrentReadRows();
  const bookTitle = data.book_title || data.bookTitle || "";
  const author = data.author || "";
  const match = findCurrentReadCircleByNormalized(rows.circles, bookTitle, author);
  const dataOut = match ? [publicCurrentReadCircle(match, rows.members, [])] : [];
  return { success: true, data: dataOut };
}

function addCurrentRead(data) {
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  const userName = publicReaderName(data.user_name || data.userName || data.name, userId);
  const bookTitle = String(data.book_title || data.bookTitle || "").trim();
  const author = String(data.author || "").trim();
  const previousBookTitle = String(data.previous_book_title || data.previousBookTitle || "").trim();
  const previousAuthor = String(data.previous_author || data.previousAuthor || "").trim();
  if (!userId) return { success: false, message: "User required" };
  if (!bookTitle) return { success: false, message: "Book title required" };

  const rows = getCurrentReadRows();
  const existing = findCurrentReadCircleByNormalized(rows.circles, bookTitle, author);
  if (existing) {
    return {
      success: true,
      duplicate: true,
      message: "A Readers Circle for this book already exists. You can join it.",
      circle: publicCurrentReadCircle(existing, rows.members, [])
    };
  }

  // The join `note` is free text published to every other member of this
  // circle via publicCurrentReadCircle (members[].note) — same broadcast
  // exposure as a Circle message, so it gets the same server-side PII
  // gate, before either sheet row below is ever written. Skipped only
  // for admin, same convention as the chat/Circle-message/dispute gates.
  const note = String(data.note || "").trim();
  if (note && !isAdminEmail(userId)) {
    const piiScan = scanUserGeneratedContent(note);
    if (piiScan.blocked) {
      logChatSafetyEvent({
        chatId: '',
        swapId: '',
        senderEmail: userId,
        category: piiScan.category,
        contentType: 'CIRCLE_JOIN_NOTE'
      });
      return {
        success: false,
        blocked: true,
        reason: 'PERSONAL_INFORMATION',
        category: piiScan.category,
        message: piiWarningForCategory(piiScan.category)
      };
    }
  }

  const now = new Date();
  const circleId = generateId("CRC_");
  const memberId = generateId("CRM_");
  const circle = {
    circle_id: circleId,
    book_title: bookTitle,
    normalized_book_title: normalizeCurrentReadText(bookTitle),
    author,
    normalized_author: normalizeCurrentReadText(author),
    cover_url: data.cover_url || data.coverUrl || "",
    status: "Waiting",
    created_by_user_id: userId,
    created_at: now,
    updated_at: now
  };
  const member = {
    member_id: memberId,
    circle_id: circleId,
    user_id: userId,
    user_name: userName,
    reading_progress: data.reading_progress || data.readingProgress || "Just Started",
    format: data.format || "Physical",
    note: note,
    joined_at: now
  };

  rows.circleSheet.appendRow(CURRENT_READ_CIRCLE_HEADERS.map(h => circle[h] || ""));
  rows.memberSheet.appendRow(CURRENT_READ_MEMBER_HEADERS.map(h => member[h] || ""));
  return {
    success: true,
    message: "Your Readers Circle will become active when more readers join.",
    circle: publicCurrentReadCircle(circle, [member], [])
  };
}

function joinCurrentReadCircle(data) {
  const circleId = data.circle_id || data.circleId;
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  const userName = publicReaderName(data.user_name || data.userName || data.name, userId);
  if (!circleId) return { success: false, message: "Circle required" };
  if (!userId) return { success: false, message: "User required" };

  const rows = getCurrentReadRows();
  const circle = rows.circles.find(c => String(c.circle_id) === String(circleId));
  if (!circle) return { success: false, message: "Circle not found" };
  if (isCurrentReadMember(circleId, userId, rows.members)) {
    return {
      success: true,
      alreadyJoined: true,
      message: "You have already joined this circle.",
      circle: publicCurrentReadCircle(circle, rows.members, [])
    };
  }

  // Same broadcast-exposed free-text gate as addCurrentRead's join note —
  // this note is published to every other member of the circle, so it is
  // scanned before the member row is ever written. Skipped only for admin.
  const note = String(data.note || "").trim();
  if (note && !isAdminEmail(userId)) {
    const piiScan = scanUserGeneratedContent(note);
    if (piiScan.blocked) {
      logChatSafetyEvent({
        chatId: circleId,
        swapId: '',
        senderEmail: userId,
        category: piiScan.category,
        contentType: 'CIRCLE_JOIN_NOTE'
      });
      return {
        success: false,
        blocked: true,
        reason: 'PERSONAL_INFORMATION',
        category: piiScan.category,
        message: piiWarningForCategory(piiScan.category)
      };
    }
  }

  const member = {
    member_id: generateId("CRM_"),
    circle_id: circleId,
    user_id: userId,
    user_name: userName,
    reading_progress: data.reading_progress || data.readingProgress || "Just Started",
    format: data.format || "Physical",
    note: note,
    joined_at: new Date()
  };
  rows.memberSheet.appendRow(CURRENT_READ_MEMBER_HEADERS.map(h => member[h] || ""));
  const updatedMembers = rows.members.concat([member]);
  updateCurrentReadCircleStatus(circleId, updatedMembers);

  const freshRows = getCurrentReadRows();
  const updatedCircle = freshRows.circles.find(c => String(c.circle_id) === String(circleId)) || circle;
  const circleName = updatedCircle.title || updatedCircle.book_title || updatedCircle.name || "Readers Circle";

  // Log in Reading Journey
  logReaderActivity(
    userId,
    "circle_joined",
    circleId,
    circleName,
    `Joined the "${circleName}" Circle`,
    `Stepped into the community literary salon to discuss chapters and share impressions.`,
    { circleId: circleId, circleName: circleName }
  );

  return {
    success: true,
    message: "You joined the Readers Circle.",
    circle: publicCurrentReadCircle(updatedCircle, freshRows.members, [])
  };
}

function getCircleMessages(data) {
  const circleId = data.circle_id || data.circleId;
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  const rows = getCurrentReadRows();
  if (!isCurrentReadMember(circleId, userId, rows.members)) {
    return { success: false, message: "Only circle members can view messages.", data: [] };
  }

  // Find the joining timestamp for this user in this circle
  const member = rows.members.find(m =>
    String(m.circle_id) === String(circleId) &&
    String(m.user_id || "").trim().toLowerCase() === String(userId || "").trim().toLowerCase()
  );
  const joinedAtTime = member && member.joined_at ? new Date(member.joined_at).getTime() : 0;

  const messages = rows.messages
    .filter(message => {
      if (String(message.circle_id) !== String(circleId)) return false;
      if (!joinedAtTime) return true; // fallback to showing all if no membership timestamp
      const msgTime = new Date(message.created_at).getTime();
      return msgTime >= (joinedAtTime - 2000); // 2 seconds tolerance
    })
    .map(message => ({
      message_id: message.message_id,
      circle_id: message.circle_id,
      user_id: message.user_id,
      user_name: publicReaderName(message.user_name, message.user_id),
      message: message.message,
      is_spoiler: String(message.is_spoiler).toLowerCase() === "true" || String(message.is_spoiler).toLowerCase() === "yes",
      created_at: message.created_at,
      image_url: message.image_url || message.imageUrl || ""
    }));
  return { success: true, data: messages };
}

function sendReadersCircleMessageEmail(to, senderName, bookTitle, discussionUrl) {
  try {
    const subject = "New activity in your Readers Circle 📚";
    const body = `${senderName} posted a new message in the Readers Circle for '${bookTitle}'. Open SwapSutra to continue the discussion.`;
    const content = `<p>${escapeHtml(body)}</p>`;
    const htmlBody = typeof getBrandedEmailTemplate === "function"
      ? getBrandedEmailTemplate("New message in your Readers Circle", content, discussionUrl, "Open Discussion")
      : `
        <div style="font-family: Georgia, serif; color:#3B241C; line-height:1.6;">
          <h2>New message in your Readers Circle</h2>
          ${content}
          <p><a href="${escapeHtml(discussionUrl)}">Open the Readers Circle discussion</a></p>
        </div>
      `;
    sendSwapSutraEmail({ to, subject, htmlBody });
    return true;
  } catch (e) {
    Logger.log("Readers Circle message email failed for " + to + ": " + e.toString());
    return false;
  }
}

function notifyReadersCircleMessage(circleId, messageId, senderEmail, senderName, discussionUrl, rows) {
  const currentRows = rows || getCurrentReadRows();
  const circle = currentRows.circles.find(c => String(c.circle_id) === String(circleId));
  if (!circle) return { notificationsCreated: 0, emailsAttempted: 0 };

  const bookTitle = String(circle.book_title || "your book");
  const displayName = publicReaderName(senderName, senderEmail);
  const link = buildReadersCircleDiscussionUrl(discussionUrl, circleId);
  const title = "New message in your Readers Circle";
  const notificationMessage = `${displayName} posted a new message in '${bookTitle}' Readers Circle.`;
  const dedupeKey = `readers_circle_message:${messageId}`;
  const sender = normalizeEmail(senderEmail);
  const recipients = [];

  currentRows.members.forEach(member => {
    if (String(member.circle_id) !== String(circleId)) return;
    const email = normalizeEmail(member.user_id);
    if (email && email !== sender && recipients.indexOf(email) === -1) recipients.push(email);
  });

  const created = createNotificationsBatch(recipients.map(email => ({
    userEmail: email,
    type: "readers_circle_message",
    title,
    message: notificationMessage,
    relatedId: circleId,
    link,
    dedupeKey
  })));

  let emailsAttempted = 0;
  recipients.forEach(email => {
    emailsAttempted += sendReadersCircleMessageEmail(email, displayName, bookTitle, link) ? 1 : 0;
  });

  return { notificationsCreated: created.length, emailsAttempted };
}

function addCircleMessage(data) {
  const circleId = data.circle_id || data.circleId;
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  const userName = publicReaderName(data.user_name || data.userName || data.name, userId);
  let message = String(data.message || "").trim();
  let imageUrl = data.image_url || data.imageUrl || "";

  if (data.fileData && data.fileName) {
    try {
      imageUrl = saveFileToDrive(data.fileData, data.fileName);
    } catch (e) {
      console.error(e);
    }
  }

  if (!message && !imageUrl) {
    return { success: false, message: "Message or image is required" };
  }

  const rows = getCurrentReadRows();
  const isCafe = isReadersCafeCircle(circleId);
  // Declared out here because the activity log below still needs it; the
  // Café simply has no circle row, which is the point.
  const circleObj = isCafe ? null : rows.circles.find(c => String(c.circle_id) === String(circleId));

  if (isCafe) {
    // The Café has no members table and never ends — every SwapSutra
    // member already has a seat, which is why there is no "join" step.
    // The ordinary membership gate is what decides who may speak.
    const accessError = requireApprovedMember(userId, "The Reader's Café");
    if (accessError) return accessError;
  } else {
    if (circleObj && (String(circleObj.status || '').toLowerCase() === 'ended' || String(circleObj.status || '').toLowerCase() === 'archived')) {
      return { success: false, message: "This Readers Circle has ended. New messages are disabled." };
    }

    if (!isCurrentReadMember(circleId, userId, rows.members)) {
      return { success: false, message: "Only circle members can send messages." };
    }
  }

  // Same server-side PII gate as sendChatMessage — the Café/Circles are a
  // broadcast to every member (or every circle member), so a leaked phone
  // number or address here reaches a wider audience than a 1:1 chat, not
  // a narrower one. Skipped only for admin, same as the chat gate.
  if (message && !isAdminEmail(userId)) {
    const piiScan = scanMessageForPII(message);
    if (piiScan.blocked) {
      logChatSafetyEvent({
        chatId: circleId,
        swapId: '',
        senderEmail: userId,
        category: piiScan.category,
        contentType: isCafe ? 'CAFE_MESSAGE' : 'CIRCLE_MESSAGE'
      });
      return {
        success: false,
        blocked: true,
        reason: 'PERSONAL_INFORMATION',
        category: piiScan.category,
        message: piiWarningForCategory(piiScan.category)
      };
    }
  }

  const row = {
    message_id: generateId("CRMSG_"),
    circle_id: circleId,
    user_id: userId,
    user_name: userName,
    message: message || "Shared an image",
    is_spoiler: data.is_spoiler === true || String(data.is_spoiler).toLowerCase() === "true" ? "TRUE" : "FALSE",
    created_at: new Date(),
    image_url: imageUrl
  };
  rows.messageSheet.appendRow(CURRENT_READ_MESSAGE_HEADERS.map(h => row[h] || ""));

  // Circle notifications mail every member of that circle. The Café's
  // "members" are everyone on SwapSutra, so doing that per message would
  // be a mailout, not a notification. The room is ambient by design —
  // you look in when you want company.
  const notificationResult = isCafe
    ? notifyCafeMentions_(row, userId, userName, rows)
    : notifyReadersCircleMessage(circleId, row.message_id, userId, userName, data.discussion_url || data.discussionUrl, rows);

  // Real activity signal backing the "Bookish Confidant" achievement --
  // logged only when a genuine message was actually posted above.
  try {
    logReaderActivity(
      userId,
      "circle_message_posted",
      row.message_id,
      isCafe ? "Reader's Café" : (circleObj ? (circleObj.title || circleObj.book_title || circleObj.name || "Readers Circle") : "Readers Circle"),
      isCafe ? "Posted in the Reader's Café" : "Posted in a Readers Circle",
      isCafe ? "Joined the conversation at the SwapSutra community table." : "Participated actively inside a Readers Circle discussion room.",
      { circleId: circleId, messageId: row.message_id }
    );
  } catch (e) {
    Logger.log("addCircleMessage activity log error: " + e.toString());
  }

  return { success: true, message: "Message sent.", data: row, notifications: notificationResult };
}

function leaveCurrentReadCircle(data) {
  try {
    const circleId = String(data.circle_id || data.circleId || '').trim();
    const userId = normalizeEmail(data.user_id || data.userId || data.email);
    if (!circleId || !userId) return { success: false, message: "Circle ID and User required" };

    const rows = getCurrentReadRows();
    const circle = rows.circles.find(c => String(c.circle_id) === String(circleId));
    if (!circle) return { success: false, message: "Circle not found" };

    const values = rows.memberSheet.getDataRange().getValues();
    if (values.length > 1) {
      const headers = values[0].map(h => String(h).trim());
      const cIdIdx = headers.indexOf('circle_id');
      const uIdIdx = headers.indexOf('user_id');
      const rowIdx = values.findIndex((r, idx) => idx > 0 && String(r[cIdIdx]) === circleId && normalizeEmail(r[uIdIdx]) === userId);
      if (rowIdx !== -1) {
        rows.memberSheet.deleteRow(rowIdx + 1);
      }
    }

    const freshRows = getCurrentReadRows();
    updateCurrentReadCircleStatus(circleId, freshRows.members);
    return { success: true, message: "You left the Readers Circle." };
  } catch (e) {
    Logger.log("leaveCurrentReadCircle error: " + e.toString());
    return { success: false, message: "Unable to leave circle.", error: e.toString() };
  }
}

function endCurrentReadCircle(data) {
  try {
    const circleId = String(data.circle_id || data.circleId || '').trim();
    const userId = normalizeEmail(data.user_id || data.userId || data.email);
    if (!circleId) return { success: false, message: "Circle ID required" };

    const rows = getCurrentReadRows();
    const circle = rows.circles.find(c => String(c.circle_id) === String(circleId));
    if (!circle) return { success: false, message: "Circle not found" };

    const creatorEmail = normalizeEmail(circle.created_by_user_id);
    if (creatorEmail !== userId && !isAdminEmail(userId)) {
      return { success: false, message: "Only creator or admin can end this Readers Circle.", error: "UNAUTHORIZED" };
    }

    const values = rows.circleSheet.getDataRange().getValues();
    const headers = values[0].map(h => String(h).trim());
    const idIdx = headers.indexOf('circle_id');
    const statusIdx = headers.indexOf('status');
    const updatedIdx = headers.indexOf('updated_at');
    const rowIdx = values.findIndex((r, idx) => idx > 0 && String(r[idIdx]) === circleId);

    if (rowIdx !== -1) {
      if (statusIdx !== -1) rows.circleSheet.getRange(rowIdx + 1, statusIdx + 1).setValue('ended');
      if (updatedIdx !== -1) rows.circleSheet.getRange(rowIdx + 1, updatedIdx + 1).setValue(new Date());
    }

    const bookTitle = String(circle.book_title || "Readers Circle");
    const circleMembers = rows.members.filter(m => String(m.circle_id) === circleId);
    circleMembers.forEach(m => {
      const memberEmail = normalizeEmail(m.user_id);
      if (memberEmail && memberEmail !== userId) {
        createNotification(
          memberEmail,
          "readers_circle_ended",
          "Current Read Ended 📚",
          `The '${bookTitle}' Current Read has been ended by the creator. The conversation remains available as read-only history.`,
          circleId
        );
      }
    });

    return { success: true, message: "Current Read ended. Group is now read-only.", status: 'ended' };
  } catch (e) {
    Logger.log("endCurrentReadCircle error: " + e.toString());
    return { success: false, message: "Unable to end circle.", error: e.toString() };
  }
}

function archiveCurrentReadCircle(data) {
  try {
    const circleId = String(data.circle_id || data.circleId || '').trim();
    const userId = normalizeEmail(data.user_id || data.userId || data.email);
    if (!circleId) return { success: false, message: "Circle ID required" };

    const rows = getCurrentReadRows();
    const circle = rows.circles.find(c => String(c.circle_id) === String(circleId));
    if (!circle) return { success: false, message: "Circle not found" };

    const creatorEmail = normalizeEmail(circle.created_by_user_id);
    if (creatorEmail !== userId && !isAdminEmail(userId)) {
      return { success: false, message: "Only creator or admin can archive this Readers Circle.", error: "UNAUTHORIZED" };
    }

    const values = rows.circleSheet.getDataRange().getValues();
    const headers = values[0].map(h => String(h).trim());
    const idIdx = headers.indexOf('circle_id');
    const statusIdx = headers.indexOf('status');
    const updatedIdx = headers.indexOf('updated_at');
    const rowIdx = values.findIndex((r, idx) => idx > 0 && String(r[idIdx]) === circleId);

    if (rowIdx !== -1) {
      if (statusIdx !== -1) rows.circleSheet.getRange(rowIdx + 1, statusIdx + 1).setValue('archived');
      if (updatedIdx !== -1) rows.circleSheet.getRange(rowIdx + 1, updatedIdx + 1).setValue(new Date());
    }

    return { success: true, message: "Current Read archived.", status: 'archived' };
  } catch (e) {
    Logger.log("archiveCurrentReadCircle error: " + e.toString());
    return { success: false, message: "Unable to archive circle.", error: e.toString() };
  }
}

const READING_SPACE_HEADERS = [
  "item_id", "id", "book_id", "user_id", "userEmail", "user_name", "book_title", "title", "normalized_book_title", "author", "normalized_author",
  "favourite", "currently_reading", "tbr", "bookshelf",
  "permanent_exchange", "temporary_exchange", "rent", "sell",
  "available_for_swap", "rent_sale_mode",
  "format", "reading_progress", "note", "price", "condition", "notes", "created_at", "createdAt", "updated_at", "updatedAt",
  // Reading tracker: when a book went onto "currently reading" and when it was finished.
  "started_at", "finished_at"
];

function boolFlag(value) {
  return value === true || String(value || "").toLowerCase() === "true" || String(value || "").toLowerCase() === "yes";
}

// Predefined book genres/categories (Priority 1 — Library discovery). A book
// listing's genre must be one of these, or blank ("Genre not specified") —
// there is no free-text sub-field even when "Other" is chosen, to keep
// filtering/search reliable against real, bounded backend data rather than
// arbitrary client-typed strings.
const BOOK_GENRE_OPTIONS = [
  "Fiction", "Romance", "Mystery & Thriller", "Fantasy", "Science Fiction",
  "Historical Fiction", "Young Adult", "Self Help", "Biography", "Memoir",
  "Business", "Psychology", "Philosophy", "Poetry", "Indian Literature",
  "Classics", "Children's",
  // Academic & competitive shelf. "Academic" is kept exactly as it was so
  // every listing already tagged with it stays valid; the rest give a
  // student the specific shelf they are actually looking for.
  "Academic", "Competitive Exams", "School & Board Prep",
  "Engineering & Technical", "Medical & Nursing", "Law",
  "Other"
];

// Backward-compatible, defensive normalizer: an unrecognized or missing
// genre never blocks a listing — it just stores as blank, which the UI
// renders as "Genre not specified" (existing pre-genre listings behave
// identically to a listing submitted with no genre chosen).
function normalizeBookGenre(raw) {
  const value = String(raw || '').trim();
  return BOOK_GENRE_OPTIONS.includes(value) ? value : '';
}

// ISBN scanning + transparent-copy declaration (see "ISBN Scanner From
// Scratch + Transparent Book Listing"). ISBN is purely an identification
// aid — it is never treated as proof that a physical copy is genuine, since
// a pirated/reprinted copy can carry the same barcode as the original
// edition. copyType is the reader's own declaration, not a platform
// authenticity guarantee.
const COPY_TYPE_OPTIONS = ['ORIGINAL', 'REPRINT', 'NOT_SURE'];
function normalizeCopyType(raw) {
  const value = String(raw || '').trim().toUpperCase();
  return COPY_TYPE_OPTIONS.includes(value) ? value : '';
}

// Strips spaces/hyphens and validates an ISBN-10 or ISBN-13 checksum.
// Mirrors the frontend's normalizeIsbn/isValidIsbn exactly so a listing
// created by directly calling the API (bypassing the UI) is held to the
// same standard, not merely trusted from the client.
function normalizeIsbnServer(raw) {
  return String(raw || '').replace(/[\s-]/g, '').toUpperCase();
}
function isValidIsbn10Server(isbn) {
  if (!/^\d{9}[\dX]$/.test(isbn)) return false;
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += (parseInt(isbn[i], 10)) * (10 - i);
  sum += (isbn[9] === 'X' ? 10 : parseInt(isbn[9], 10)) * 1;
  return sum % 11 === 0;
}
function isValidIsbn13Server(isbn) {
  if (!/^\d{13}$/.test(isbn)) return false;
  let sum = 0;
  for (let i = 0; i < 13; i++) sum += parseInt(isbn[i], 10) * (i % 2 === 0 ? 1 : 3);
  return sum % 10 === 0;
}
function isValidIsbnServer(raw) {
  const clean = normalizeIsbnServer(raw);
  if (!clean) return true; // ISBN is optional on a listing — blank is valid (not provided)
  return isValidIsbn10Server(clean) || isValidIsbn13Server(clean);
}

function getBookHeaders() {
  return [
    "id", "ownerEmail", "title", "author", "condition", "genre", "area", "pincode",
    "favourite", "currently_reading", "tbr", "bookshelf",
    "permanent_exchange", "temporary_exchange", "rent", "sell",
    "available_for_swap", "swapType", "rent_sale_mode",
    "imageUrls", "driveFolderId", "notes", "mrp", "audioUrl", "videoUrl",
    "latitude", "longitude", "listedAt", "expiresAt", "status", "approvedAt",
    "rejectedAt", "rejectionReason", "visibleUntil", "hiddenReason",
    // Partners (9 Oct 2026): how many copies a partner has, and who sells it.
    "stock", "sellerType", "sellerName",
    "approvalEmailSent", "bookApprovalEmailSent", "bookApprovalEmailSentAt",
    "email_error", "createdAt", "updatedAt",
    "isbn", "publisher", "copyType", "copyTypeDeclaration", "referenceCoverUrl", "conditionNotes",
    // Pricing. `mrp` above is now written by the server from these two
    // choices plus the BookPrices sheet — see resolveBookPrice. priceTier
    // and priceBasis are kept so a listing that fell back to a genre rate
    // can be found later and given a real ISBN row.
    "bookFormat", "bookEdition", "priceTier", "priceBasis",
    // Oct 2026: the owner's own asking price and monthly rent.
    "ownerSellPrice", "ownerRentPerMonth",

    // ── Authenticity ──────────────────────────────────────────────────
    // ORIGINAL / UNAUTHORISED / UNKNOWN, shown to every reader who sees
    // the listing. Kept as its own column rather than inferred from
    // bookEdition, because "which printing is this" and "is this a
    // legitimate copy" are different questions with different answers.
    "authenticityStatus",

    // ── Printed MRP ───────────────────────────────────────────────────
    // The number printed on the cover, with the strength of the evidence
    // behind it. Separate from `mrp` above, which is SwapSutra's own
    // resolved listing value and is NOT the printed MRP.
    "printedMrp", "printedMrpEvidenceTier", "printedMrpVerificationStatus",

    // ── Temporary pricing phase ─────────────────────────────────────
    // The automated/catalogue estimate (automatedMRP, still computed and
    // stored, just not authoritative right now) is currently inaccurate
    // and was blocking real transactions with a wrong security fee.
    // userEnteredMRP is the owner-typed printed MRP (validated server-side
    // — see validateUserEnteredMRP), effectiveMRP is the single number the
    // pricing engine actually reads (see effectiveBookMRP), and
    // pricingSource records which one won: USER / AUTOMATED_UNVERIFIED /
    // VERIFIED. Kept alongside — not instead of — printedMrp/mrp above so
    // nothing that already reads those two columns breaks.
    "userEnteredMRP", "automatedMRP", "effectiveMRP", "pricingSource",

    // ── Transaction types, four independent flags ─────────────────────
    // `lend` is new. Before it existed, a LEND request was answered by
    // the temporary_exchange flag, so a reader offering a temporary SWAP
    // was silently also offering a straight loan.
    "lend",

    // ── The four required media, stored separately ────────────────────
    // A pipe-joined imageUrls list cannot answer "is there a back cover",
    // so the four requirements each get their own column. imageUrls is
    // still written for backward compatibility with everything that reads
    // it, but it is no longer the record of what was provided.
    "frontCoverImage", "internalBookImage", "internalBookVideo", "backCoverImage"
  ];
}

function bookAvailabilityFlags(book) {
  const swapMode = String(book.swap_mode || book.swapType || "").toLowerCase();
  const rentSaleMode = String(book.rent_sale_mode || "").toLowerCase();
  const permanentExchange = boolFlag(book.permanent_exchange) || swapMode === "permanent" || (boolFlag(book.available_for_swap) && !swapMode);
  const temporaryExchange = boolFlag(book.temporary_exchange) || swapMode === "temporary";
  const rent = boolFlag(book.rent) || rentSaleMode === "rent";
  const sell = boolFlag(book.sell) || rentSaleMode === "sell" || rentSaleMode === "sale";
  // Lend is its own flag and is read from its own column only. It is
  // deliberately NOT derived from temporary_exchange: a temporary swap
  // trades two books for a while, a loan hands one book over for nothing
  // in return, and a reader who agreed to the first never agreed to the
  // second. Listings created before this column existed therefore report
  // lend:false, which is the honest answer — they were never asked.
  const lend = boolFlag(book.lend);
  return {
    permanent_exchange: permanentExchange,
    temporary_exchange: temporaryExchange,
    rent,
    lend,
    sell,
    available_for_swap: permanentExchange || temporaryExchange,
    rent_sale_mode: rent ? "rent" : (sell ? "sell" : "")
  };
}

function bookStatusFlags(book) {
  return Object.assign({
    favourite: boolFlag(book.favourite),
    currently_reading: boolFlag(book.currently_reading),
    tbr: boolFlag(book.tbr),
    bookshelf: book.bookshelf === undefined ? true : boolFlag(book.bookshelf)
  }, bookAvailabilityFlags(book));
}

function bookHasAnyPublicUse(book) {
  const flags = bookAvailabilityFlags(book);
  return flags.permanent_exchange || flags.temporary_exchange || flags.rent || flags.lend || flags.sell;
}

function bookHasPublicLibraryVisibility(book) {
  const flags = bookStatusFlags(book);
  return flags.favourite || flags.bookshelf || flags.permanent_exchange || flags.temporary_exchange || flags.rent || flags.sell;
}

// Internal plumbing that has no business reaching any reader's browser:
// moderation notes, the email-delivery bookkeeping, and the Drive folder
// id. Stripped for everyone except an authenticated admin.
const BOOK_INTERNAL_FIELDS = [
  'rejectionReason', 'hiddenReason', 'approvalEmailSent', 'bookApprovalEmailSent',
  'bookApprovalEmailSentAt', 'email_error', 'driveFolderId', 'visibleUntil'
];

// Additionally hidden from signed-out visitors. The Library is browsable
// without an account, but browsing is all it is: who owns a copy, and
// where exactly it is, are for members.
//
// latitude/longitude matter most here — those are a reader's real
// coordinates, and the listing form explicitly promises "Your exact
// location is never shown publicly". Area and pincode stay, since
// neighbourhood-level discovery is the point of the Library.
const BOOK_MEMBER_ONLY_FIELDS = ['ownerEmail', 'latitude', 'longitude'];

/**
 * Returns a copy of a book row carrying only what the current audience
 * should see. Called on the way out of getBooks so no caller can forget.
 */
function redactBookForAudience(book) {
  // The owner's PUBLIC id travels with every book, at every audience
  // level including admin. It is what turns a name on a book card into a
  // link to that reader's profile — without the card ever carrying their
  // address, which is exactly the field a guest is not allowed to see.
  const ownerId = readerPublicId(book.ownerEmail);

  if (isAuthenticatedAdmin()) {
    const forAdmin = {};
    for (const key in book) {
      if (Object.prototype.hasOwnProperty.call(book, key)) forAdmin[key] = book[key];
    }
    forAdmin.ownerId = ownerId;
    forAdmin.missingPhotos = listingPhotoGaps_(book);
    return forAdmin;
  }

  const safe = {};
  for (const key in book) {
    if (!Object.prototype.hasOwnProperty.call(book, key)) continue;
    if (BOOK_INTERNAL_FIELDS.indexOf(key) !== -1) continue;
    safe[key] = book[key];
  }

  if (!getAuthenticatedEmail()) {
    for (let i = 0; i < BOOK_MEMBER_ONLY_FIELDS.length; i++) {
      delete safe[BOOK_MEMBER_ONLY_FIELDS[i]];
    }
  }
  safe.ownerId = ownerId;
  // 'back' / 'inside' still to come — drives the "More photos coming" label.
  safe.missingPhotos = listingPhotoGaps_(book);
  return safe;
}

function sendBookApprovalEmailOnce(sheet, headers, rowIndex, bookId, ownerEmail, bookTitle, ownerName) {
  const now = new Date();
  let emailSentIdx = headers.indexOf("bookApprovalEmailSent");
  let emailSentAtIdx = headers.indexOf("bookApprovalEmailSentAt");
  let legacyEmailSentIdx = headers.indexOf("approvalEmailSent");
  let emailErrorIdx = headers.indexOf("email_error");
  [emailSentIdx, emailSentAtIdx, legacyEmailSentIdx, emailErrorIdx].forEach(() => {});

  if (emailSentIdx === -1 || emailSentAtIdx === -1 || legacyEmailSentIdx === -1 || emailErrorIdx === -1) {
    const required = getBookHeaders();
    ensureSheetHeaders(sheet, required);
    headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
    emailSentIdx = headers.indexOf("bookApprovalEmailSent");
    emailSentAtIdx = headers.indexOf("bookApprovalEmailSentAt");
    legacyEmailSentIdx = headers.indexOf("approvalEmailSent");
    emailErrorIdx = headers.indexOf("email_error");
  }

  const alreadySent = boolFlag(sheet.getRange(rowIndex + 1, emailSentIdx + 1).getValue()) || boolFlag(sheet.getRange(rowIndex + 1, legacyEmailSentIdx + 1).getValue());
  if (alreadySent) {
    Logger.log(JSON.stringify({ event: "bookApprovalEmail", bookId, ownerEmail, emailSent: true, skipped: "already_sent" }));
    return { sent: true, skipped: true, message: "Approval email already sent." };
  }
  if (!ownerEmail) {
    const error = "Owner email missing.";
    sheet.getRange(rowIndex + 1, emailSentIdx + 1).setValue("No");
    sheet.getRange(rowIndex + 1, emailErrorIdx + 1).setValue(error);
    Logger.log(JSON.stringify({ event: "bookApprovalEmail", bookId, ownerEmail, emailSent: false, error }));
    return { sent: false, skipped: false, message: error };
  }

  const sent = sendBookApprovalEmail(ownerEmail, ownerName || "Reader", bookTitle, bookId);
  sheet.getRange(rowIndex + 1, emailSentIdx + 1).setValue(sent ? "Yes" : "No");
  if (legacyEmailSentIdx !== -1) sheet.getRange(rowIndex + 1, legacyEmailSentIdx + 1).setValue(sent ? "Yes" : "No");
  if (sent) {
    sheet.getRange(rowIndex + 1, emailSentAtIdx + 1).setValue(now);
    sheet.getRange(rowIndex + 1, emailErrorIdx + 1).setValue("");
  } else {
    sheet.getRange(rowIndex + 1, emailErrorIdx + 1).setValue("Book approval email failed. Check Apps Script logs.");
  }
  Logger.log(JSON.stringify({ event: "bookApprovalEmail", bookId, ownerEmail, emailSent: sent, error: sent ? "" : "sendBookApprovalEmail returned false" }));
  return { sent, skipped: false, message: sent ? "Approval email sent." : "Approval email failed." };
}

function getReadingSpaceSheet() {
  const sheet = getOrCreateSheet("reading_space", READING_SPACE_HEADERS);
  ensureSheetHeaders(sheet, READING_SPACE_HEADERS);
  return sheet;
}

function readingSpaceRowToPublicItem(item, allItems) {
  const swapMode = String(item.swap_mode || item.swapType || "").toLowerCase();
  const permanentExchange = boolFlag(item.permanent_exchange) || swapMode === "permanent" || (boolFlag(item.available_for_swap) && !swapMode);
  const temporaryExchange = boolFlag(item.temporary_exchange) || swapMode === "temporary";
  const rent = boolFlag(item.rent) || String(item.rent_sale_mode || "").toLowerCase() === "rent";
  const sell = boolFlag(item.sell) || String(item.rent_sale_mode || "").toLowerCase() === "sale";
  const ownerMatches = allItems.filter(other =>
    boolFlag(other.bookshelf) &&
    String(other.normalized_book_title) === String(item.normalized_book_title) &&
    normalizeEmail(other.user_id) !== normalizeEmail(item.user_id)
  );
  const seenOwners = {};
  ownerMatches.forEach(owner => {
    const userId = normalizeEmail(owner.user_id);
    if (userId) seenOwners[userId] = publicReaderName(owner.user_name, userId);
  });
  return {
    item_id: item.item_id,
    id: item.id || item.item_id,
    book_id: item.book_id || "",
    user_id: item.user_id,
    userEmail: item.userEmail || item.user_id,
    user_name: publicReaderName(item.user_name, item.user_id),
    book_title: item.book_title,
    title: item.title || item.book_title,
    normalized_book_title: item.normalized_book_title,
    author: item.author,
    normalized_author: item.normalized_author,
    favourite: boolFlag(item.favourite),
    currently_reading: boolFlag(item.currently_reading),
    tbr: boolFlag(item.tbr),
    bookshelf: boolFlag(item.bookshelf),
    permanent_exchange: permanentExchange,
    temporary_exchange: temporaryExchange,
    rent,
    sell,
    available_for_swap: permanentExchange || temporaryExchange,
    rent_sale_mode: item.rent_sale_mode || "",
    format: item.format || "",
    reading_progress: item.reading_progress || "",
    note: item.note || "",
    price: item.price || "",
    condition: item.condition || "",
    notes: item.notes || "",
    created_at: item.created_at,
    updated_at: item.updated_at,
    started_at: item.started_at || "",
    finished_at: item.finished_at || "",
    owned_by_count: Object.keys(seenOwners).length,
    owner_previews: Object.keys(seenOwners).slice(0, 5).map(userId => ({ user_id: userId, first_name: seenOwners[userId] }))
  };
}

function getReadingSpace(data) {
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  if (!userId) return { success: false, message: "User required", data: [] };
  const sheet = getReadingSpaceSheet();
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(h => String(h).trim());
  const items = values.slice(1).filter(row => row.some(Boolean)).map(row => currentReadRowToObject(headers, row));
  const ownItems = items.filter(item => normalizeEmail(item.user_id) === userId).map(item => readingSpaceRowToPublicItem(item, items));
  return { success: true, data: ownItems };
}

function upsertReadingSpaceBook(data) {
  const userId = normalizeEmail(data.user_id || data.userId || data.email);
  const userName = publicReaderName(data.user_name || data.userName || data.name, userId);
  const bookTitle = String(data.book_title || data.bookTitle || "").trim();
  const author = String(data.author || "").trim();
  const previousBookTitle = String(data.previous_book_title || data.previousBookTitle || "").trim();
  const previousAuthor = String(data.previous_author || data.previousAuthor || "").trim();
  if (!userId) return { success: false, message: "User required" };
  if (!bookTitle) return { success: false, message: "Book title required" };

  const sheet = getReadingSpaceSheet();
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(h => String(h).trim());
  const userIdx = headers.indexOf("user_id");
  const bookIdIdx = headers.indexOf("book_id");
  const titleIdx = headers.indexOf("normalized_book_title");
  const authorIdx = headers.indexOf("normalized_author");
  const bookId = String(data.book_id || data.bookId || "").trim();
  const normalizedTitle = normalizeCurrentReadText(bookTitle);
  const normalizedAuthor = normalizeCurrentReadText(author);
  const previousNormalizedTitle = normalizeCurrentReadText(previousBookTitle);
  const previousNormalizedAuthor = normalizeCurrentReadText(previousAuthor);
  const now = new Date();

  let rowIndex = values.findIndex((row, idx) => {
    if (idx === 0) return false;
    if (normalizeEmail(row[userIdx]) !== userId) return false;
    if (bookId && bookIdIdx !== -1 && String(row[bookIdIdx] || "").trim() === bookId) return true;
    if (String(row[titleIdx]) !== normalizedTitle) return false;
    if (normalizedAuthor && row[authorIdx]) return String(row[authorIdx]) === normalizedAuthor;
    return true;
  });
  if (rowIndex === -1 && previousNormalizedTitle) {
    rowIndex = values.findIndex((row, idx) => {
      if (idx === 0) return false;
      if (normalizeEmail(row[userIdx]) !== userId) return false;
      if (String(row[titleIdx]) !== previousNormalizedTitle) return false;
      if (previousNormalizedAuthor && row[authorIdx]) return String(row[authorIdx]) === previousNormalizedAuthor;
      return true;
    });
  }

  const existingRow = rowIndex !== -1 ? values[rowIndex] : null;
  const existing = existingRow ? currentReadRowToObject(headers, existingRow) : {};
  const existingSwapMode = String(existing.swap_mode || existing.swapType || "").toLowerCase();
  const permanentExchange = data.permanent_exchange !== undefined ? boolFlag(data.permanent_exchange) : (boolFlag(existing.permanent_exchange) || existingSwapMode === "permanent" || (boolFlag(existing.available_for_swap) && !existingSwapMode));
  const temporaryExchange = data.temporary_exchange !== undefined ? boolFlag(data.temporary_exchange) : (boolFlag(existing.temporary_exchange) || existingSwapMode === "temporary");
  const rent = data.rent !== undefined ? boolFlag(data.rent) : (boolFlag(existing.rent) || String(existing.rent_sale_mode || "").toLowerCase() === "rent");
  const sell = data.sell !== undefined ? boolFlag(data.sell) : (boolFlag(existing.sell) || String(existing.rent_sale_mode || "").toLowerCase() === "sale");
  const rentSaleMode = data.rent_sale_mode !== undefined
    ? data.rent_sale_mode
    : ((data.rent !== undefined || data.sell !== undefined) ? (rent ? "rent" : (sell ? "sale" : "")) : (existing.rent_sale_mode || ""));
  const readingSpaceId = existing.item_id || existing.id || generateId("RS_");
  const next = {
    item_id: readingSpaceId,
    id: readingSpaceId,
    book_id: bookId || existing.book_id || "",
    user_id: userId,
    userEmail: userId,
    user_name: userName,
    book_title: bookTitle,
    title: bookTitle,
    normalized_book_title: normalizedTitle,
    author,
    normalized_author: normalizedAuthor,
    favourite: data.favourite !== undefined ? boolFlag(data.favourite) : boolFlag(existing.favourite),
    currently_reading: data.currently_reading !== undefined ? boolFlag(data.currently_reading) : boolFlag(existing.currently_reading),
    tbr: data.tbr !== undefined ? boolFlag(data.tbr) : boolFlag(existing.tbr),
    bookshelf: data.bookshelf !== undefined ? boolFlag(data.bookshelf) : boolFlag(existing.bookshelf),
    permanent_exchange: permanentExchange,
    temporary_exchange: temporaryExchange,
    rent,
    sell,
    available_for_swap: data.available_for_swap !== undefined ? boolFlag(data.available_for_swap) : (permanentExchange || temporaryExchange),
    rent_sale_mode: rentSaleMode,
    format: data.format || existing.format || "",
    reading_progress: data.reading_progress || existing.reading_progress || "",
    started_at: (data.currently_reading !== undefined && boolFlag(data.currently_reading) && !boolFlag(existing.currently_reading))
      ? now : (existing.started_at || ""),
    finished_at: (data.currently_reading !== undefined && !boolFlag(data.currently_reading) && boolFlag(existing.currently_reading) && data.bookshelf !== undefined && boolFlag(data.bookshelf))
      ? now : (existing.finished_at || ""),
    note: data.note || existing.note || "",
    price: data.price || existing.price || "",
    condition: data.condition || existing.condition || "",
    notes: data.notes || existing.notes || data.note || "",
    created_at: existing.created_at || now,
    updated_at: now
  };

  const row = headers.map(h => next[h] === true ? "TRUE" : next[h] === false ? "FALSE" : (next[h] || ""));
  if (rowIndex === -1) sheet.appendRow(row);
  else sheet.getRange(rowIndex + 1, 1, 1, headers.length).setValues([row]);

  if (next.currently_reading) {
    addCurrentRead({
      user_id: userId,
      user_name: userName,
      book_title: bookTitle,
      author,
      format: data.format || "Physical",
      reading_progress: data.reading_progress || "Just Started",
      note: data.notes || data.note || ""
    });
  }

  // Activity Logging for Reading Space
  try {
    if (rowIndex === -1) {
      // First book in space check
      const currentItems = getReadingSpace({ user_id: userId }).data || [];
      if (currentItems.length <= 1) {
        logReaderActivity(
          userId,
          "reading_space_created",
          userId,
          "Reading Sanctuary",
          "Created Your Reading Space",
          "You created your personalized Reading Space at SwapSutra, laying down the first stones of your virtual bookshelf.",
          {}
        );
      }
    }

    if (next.tbr && (!existing.tbr || rowIndex === -1)) {
      logReaderActivity(
        userId,
        "tbr_added",
        readingSpaceId,
        bookTitle,
        `Added "${bookTitle}" to TBR`,
        `Added to your To Be Read wishlist${author ? " by " + author : ""}.`,
        { book_title: bookTitle, author: author }
      );
    }

    if (next.currently_reading && (!existing.currently_reading || rowIndex === -1)) {
      logReaderActivity(
        userId,
        "currently_reading_started",
        readingSpaceId,
        bookTitle,
        `Started Reading "${bookTitle}"`,
        `Dived into pages of "${bookTitle}"${author ? " by " + author : ""}.`,
        { book_title: bookTitle, author: author }
      );
    }

    if (next.favourite && (!existing.favourite || rowIndex === -1)) {
      logReaderActivity(
        userId,
        "favourite_marked",
        readingSpaceId,
        bookTitle,
        `Marked "${bookTitle}" as Favourite`,
        `Added to your curated favourites shelf${author ? " by " + author : ""}.`,
        { book_title: bookTitle, author: author }
      );
    }
  } catch (actErr) {
    Logger.log("Activity log in upsertReadingSpaceBook error: " + actErr.toString());
  }

  return { success: true, message: "Reading Space updated.", item: next, readingSpace: getReadingSpace({ user_id: userId }).data };
}

function doPost(e) { return withPopups_(doPostHandler_, e); }

function doPostHandler_(e) {
  try {
    const data = e && e.postData && e.postData.contents ? JSON.parse(e.postData.contents) : (e.parameter || {});
    const action = data.action;

    // Same identity resolution as doGet — see the comment there.
    resetRequestIdentity();
    establishRequestIdentity(data);
    const gateError = requireSessionForAction(action);
    if (gateError) return respondJson(gateError);
    applyAuthenticatedIdentity(data, action);

    Logger.log("doPost Action: " + action + (getAuthenticatedEmail() ? " as " + getAuthenticatedEmail() : " (guest)"));

    if (action === 'getReadingJourney' || action === 'getReaderActivities') return respondJson(getReadingJourney(data));
    if (action === 'logReaderActivity') {
      return respondJson(logReaderActivity(
        data.user_id || data.email || data.userId,
        data.activity_type || data.activityType,
        data.reference_id || data.referenceId,
        data.reference_name || data.referenceName,
        data.title || data.activity_title,
        data.description || data.activity_description,
        data.metadata,
        data.created_at || data.createdAt
      ));
    }

    if (action === 'getCurrentReadCircles') return respondJson(getCurrentReadCircles());
    if (action === 'searchCurrentReadCircles') return respondJson(searchCurrentReadCircles(data));
    if (action === 'addCurrentRead') {
      return respondJson(addCurrentRead(data));
    }
    if (action === 'joinCurrentReadCircle') return respondJson(joinCurrentReadCircle(data));
    if (action === 'getReadersCafe') return respondJson(getReadersCafe(data));
    if (action === 'getCircleMessages') return respondJson(getCircleMessages(data));
    if (action === 'addCircleMessage') return respondJson(addCircleMessage(data));

    if (action === 'getCafeStories') return respondJson(getCafeStories(data));
    if (action === 'postCafeStory') return respondJson(postCafeStory(data));
    if (action === 'markCafeStoryViewed') return respondJson(markCafeStoryViewed(data));
    if (action === 'getCafeStoryViewers') return respondJson(getCafeStoryViewers(data));
    if (action === 'deleteCafeStory') return respondJson(deleteCafeStory(data));
    if (action === 'toggleCafeReaction') return respondJson(toggleCafeReaction(data));
    if (action === 'getReaderProfile') return respondJson(getReaderProfile(data));

    if (action === 'getReadingRoomFeed') return respondJson(getReadingRoomFeed(data));
    if (action === 'createReadingRoomPost') return respondJson(createReadingRoomPost(data));
    if (action === 'togglePostReaction') return respondJson(togglePostReaction(data));
    if (action === 'addPostComment') return respondJson(addPostComment(data));
    if (action === 'saveBookRecommendation') return respondJson(saveBookRecommendation(data));

    if (action === 'deleteChatMessage') return respondJson(deleteChatMessage(data));
    if (action === 'deleteCircleMessage') return respondJson(deleteCircleMessage(data));
    if (action === 'deleteReadingRoomPost') return respondJson(deleteReadingRoomPost(data));
    if (action === 'deletePostComment') return respondJson(deletePostComment(data));

    // --- Push subscriptions (item 13) ----------------------------------
    // getPushSubscriptions and reportPushFailure are called by the
    // sending server, not by a browser, and both are behind the same
    // session gate as everything else — the proxy forwards the caller's
    // session, and only the admin key reaches them without one.
    if (action === 'savePushSubscription') return respondJson(savePushSubscription(data));
    if (action === 'deletePushSubscription') return respondJson(deletePushSubscription(data));
    if (action === 'getPushSubscriptions') {
      // A reader may read their own devices; only an admin may read
      // everyone's, because that list is every device on the platform.
      const requested = normalizeEmail(data.userEmail || data.email || '');
      const caller = normalizeEmail(getAuthenticatedEmail() || '');
      if (!isAuthorizedAdminEmail(data.adminEmail) && (!caller || requested !== caller)) {
        return respondJson({ success: false, message: "Unauthorized", subscriptions: [] });
      }
      return respondJson(getPushSubscriptions(data));
    }
    if (action === 'reportPushFailure') return respondJson(reportPushFailure(data));
    if (action === 'getPushSubscriptionsForRelay') return respondJson(getPushSubscriptionsForRelay(data));
    if (action === 'reportPushFailureForRelay') return respondJson(reportPushFailureForRelay(data));
    // Daily book updates (27 Sep) — see the block at the end of the file.
    if (action === 'saveGuestPushSubscription') return respondJson(saveGuestPushSubscription(data));
    if (action === 'recordPushOpen') return respondJson(recordPushOpen(data));
    // Coffee mugs (30 Sep) — see the block at the end of the file.
    if (action === 'submitCustomMugEnquiry') return respondJson(submitCustomMugEnquiry(data));
    if (action === 'getMugProducts') return respondJson(getMugProducts());
    if (action === 'getAdminCustomMugEnquiries') return respondJson(getAdminCustomMugEnquiries(data));
    if (action === 'updateCustomMugEnquiry') return respondJson(updateCustomMugEnquiry(data));
    if (action === 'getAdminMugProducts') return respondJson(getAdminMugProducts());
    if (action === 'saveMugProduct') return respondJson(saveMugProduct(data));
    // Sponsored ads (9 Oct) — see the block after getMugProducts.
    if (action === 'getSponsoredAds') return respondJson(getSponsoredAds());
    if (action === 'recordAdClick') return respondJson(recordAdClick(data));
    if (action === 'getAdminSponsoredAds') return respondJson(getAdminSponsoredAds());
    if (action === 'saveSponsoredAd') return respondJson(saveSponsoredAd(data));
    if (action === 'uploadSponsoredAdImage') return respondJson(uploadSponsoredAdImage(data));
    // Payment details the admin can change (9 Oct).
    if (action === 'getPaymentDetails') return respondJson(getPaymentDetails());
    if (action === 'getAdminPaymentSettings') return respondJson(getAdminPaymentSettings());
    if (action === 'saveAdminPaymentSettings') return respondJson(saveAdminPaymentSettings(data));
    if (action === 'uploadPaymentQrImage') return respondJson(uploadPaymentQrImage(data));
    // SwapSutra partners (9 Oct) — see the PARTNERS block at the end of the file.
    if (action === 'getMyPartner') return respondJson(getMyPartner());
    if (action === 'submitPartnerApplication') return respondJson(submitPartnerApplication(data));
    if (action === 'updatePartnerProfile') return respondJson(updatePartnerProfile(data));
    if (action === 'uploadPartnerBanner') return respondJson(uploadPartnerBanner(data));
    if (action === 'savePartnerAd') return respondJson(savePartnerAd(data));
    if (action === 'submitPartnerAdPayment') return respondJson(submitPartnerAdPayment(data));
    if (action === 'setPartnerBookStock') return respondJson(setPartnerBookStock(data));
    if (action === 'adminListPartners') return respondJson(adminListPartners());
    if (action === 'adminReviewPartner') return respondJson(adminReviewPartner(data));
    if (action === 'adminReviewPartnerBanner') return respondJson(adminReviewPartnerBanner(data));
    if (action === 'adminReviewPartnerAdPayment') return respondJson(adminReviewPartnerAdPayment(data));
    if (action === 'adminMarkPartnerMonthPaid') return respondJson(adminMarkPartnerMonthPaid(data));
    if (action === 'getDailyPushAdmin' || action === 'setDailyPushSettings' || action === 'sendDailyPushTest') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: 'Unauthorized' });
      if (action === 'getDailyPushAdmin') return respondJson(getDailyPushAdmin(data));
      if (action === 'setDailyPushSettings') return respondJson(setDailyPushSettings(data));
      return respondJson(sendDailyPushTest(data));
    }

    // --- Growth module (see the block at the end of this file) ---------
    if (action === 'googleSignIn') return respondJson(googleSignIn(data));
    if (action === 'listReaderBadges') return respondJson(listReaderBadges(data));
    if (action === 'awardReaderBadge') return respondJson(awardReaderBadge(data));
    if (action === 'announceBadgeRecognition') return respondJson(announceBadgeRecognition(data));
    if (action === 'getAccountDeletionCheck') return respondJson(getAccountDeletionCheck(data));
    if (action === 'getNewsletterArchive') return respondJson(getNewsletterArchive(data));
    if (action === 'getNewsletterEdition') return respondJson(getNewsletterEdition(data));
    if (action === 'unsubscribeNewsletter') return respondJson(unsubscribeNewsletter(data));
    if (action === 'getMyNewsletterSubscription') return respondJson(getMyNewsletterSubscription(data));
    if (action === 'setMyNewsletterSubscription') return respondJson(setMyNewsletterSubscription(data));
    if (action === 'deleteMyAccount') return respondJson(deleteMyAccount(data));
    if (action === 'revokeReaderBadge') return respondJson(revokeReaderBadge(data));
    if (action === 'logFunnelEvent') return respondJson(logFunnelEvent(data));
    if (action === 'recordVisit') return respondJson(recordVisit(data));
    if (action === 'recordListingFormOpen') return respondJson(recordListingFormOpen(data));
    if (action === 'validateReferralCode') return respondJson(validateReferralCode(data));
    if (action === 'getMyReferral') return respondJson(getMyReferral(data));
    if (action === 'getReferralLeaderboard') return respondJson(getReferralLeaderboard(data));
    if (action === 'getAmbassadorStanding') return respondJson(getAmbassadorStanding(data));
    if (action === 'getAmbassadorLeaderboard') return respondJson(getAmbassadorLeaderboard(data));
    if (action === 'enrollAmbassador') return respondJson(enrollAmbassador(data));

    // --- Circulation ledger --------------------------------------------
    // Every one of these authorises against the swap's own two parties
    // before reading or writing anything — see loadSwapForCirculation.
    if (action === 'saveDeliveryAddress') return respondJson(saveDeliveryAddress(data));
    if (action === 'getDeliveryAddress') return respondJson(getDeliveryAddress(data));
    if (action === 'setSwapRoute') return respondJson(setSwapRoute(data));
    if (action === 'shareChatLocation') return respondJson(shareChatLocation(data));
    // Oct 2026 — Google location for meeting points.
    if (action === 'geocodePlace') return respondJson(geocodePlace(data));
    if (action === 'reversePlace') return respondJson(reversePlace(data));
    if (action === 'resolveMapsLink') return respondJson(resolveMapsLink(data));
    // Oct 2026 — VMS video evidence.
    if (action === 'getExchangeVideos') return respondJson(getExchangeVideos(data));
    // Oct 2026 — the Exchange Room (one place: chat + every step).
    if (action === 'getExchangeRoom') return respondJson(getExchangeRoom(data));
    if (action === 'getMyOrders') return respondJson(getMyOrders(data));
    // Oct 2026 — wishlist (saved books).
    if (action === 'getWishlist') return respondJson(getWishlist(data));
    if (action === 'toggleWishlist') return respondJson(toggleWishlist(data));
    if (action === 'exchangeRoomAction') return respondJson(exchangeRoomAction(data));
    if (action === 'vmsStartUpload') return respondJson(vmsStartUpload(data));
    if (action === 'vmsUploadChunk') return respondJson(vmsUploadChunk(data));
    if (action === 'vmsFinishUpload') return respondJson(vmsFinishUpload(data));
    if (action === 'adminDecideDeposits') return respondJson(adminDecideDeposits(data));
    // Oct 2026 — sales through SwapSutra, payout accounts.
    if (action === 'getPayoutAccount') return respondJson(getPayoutAccount(data));
    if (action === 'savePayoutAccount') return respondJson(savePayoutAccount(data));
    if (action === 'getSaleStatus') return respondJson(getSaleStatus(data));
    if (action === 'confirmSaleComplete') return respondJson(confirmSaleComplete(data));
    // Oct 2026 — 21-day return deadlines.
    if (action === 'getReturnStatus') return respondJson(getReturnStatus(data));
    if (action === 'requestReturnExtension') return respondJson(requestReturnExtension(data));
    if (action === 'respondReturnExtension') return respondJson(respondReturnExtension(data));
    if (action === 'adminListReturnForfeits') return respondJson(adminListReturnForfeits(data));
    if (action === 'adminMarkForfeitPaid') return respondJson(adminMarkForfeitPaid(data));
    if (action === 'logJourneyEvent') return respondJson(logJourneyEvent(data));
    if (action === 'getSwapJourney') return respondJson(getSwapJourney(data));
    if (action === 'getSwapTimeline') return respondJson(getSwapTimeline(data));

    // --- Master transaction state machine --------------------------------
    // See the "MASTER SWAPSUTRA TRANSACTION STATE MACHINE" block at the end
    // of this file. Every one of these re-derives identity from the
    // verified session and re-checks the full stage chain server-side —
    // none of them trust a client-supplied stage, role, amount or email.
    if (action === 'getSwapStage') return respondJson(getSwapStage(data));
    if (action === 'getSecurityFeeStatus') return respondJson(getSecurityFeeStatus(data));
    if (action === 'submitSecurityFeePayment') return respondJson(submitSecurityFeePayment(data));
    // Oct 2026 — listing allowance and platform revenue.
    if (action === 'getListingAllowance') return respondJson(getListingAllowance(data));
    if (action === 'redeemListingUnlockCoupon') return respondJson(redeemListingUnlockCoupon(data));
    if (action === 'submitListingUnlockPayment') return respondJson(submitListingUnlockPayment(data));
    if (action === 'adminListListingUnlocks') return respondJson(adminListListingUnlocks(data));
    if (action === 'adminReviewListingUnlock') return respondJson(adminReviewListingUnlock(data));
    if (action === 'adminPlatformRevenueSummary') return respondJson(adminPlatformRevenueSummary(data));
    if (action === 'getPlatformFeeQuote') return respondJson(getPlatformFeeQuote(data));
    if (action === 'adminApproveSecurityFeePayment') return respondJson(adminApproveSecurityFeePayment(data));
    if (action === 'adminListSecurityFeeBacklog') return respondJson(adminListSecurityFeeBacklog(data));
    if (action === 'submitStageEvidence') return respondJson(submitStageEvidence(data));
    if (action === 'confirmStage') return respondJson(confirmStage(data));
    if (action === 'adminSetSecurityFeeOutcome') return respondJson(adminSetSecurityFeeOutcome(data));

    if (action === 'getFunnelMetrics') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(getFunnelMetrics(data));
    }

    if (action === 'cancelSwapRequest') return respondJson(cancelSwapRequest(data));
    if (action === 'disputeSwapRequest') return respondJson(disputeSwapRequest(data));
    if (action === 'getSwapDisputes') return respondJson(getSwapDisputes(data));
    if (action === 'getOpenDisputes') return respondJson(getOpenDisputes(data));
    if (action === 'resolveDispute') return respondJson(resolveDispute(data));
    if (action === 'rateCounterparty') return respondJson(rateCounterparty(data));
    if (action === 'getRatingPromptStatus') return respondJson(getRatingPromptStatus(data));

    if (action === 'healthCheck') {
      return respondJson({
        success: true,
        message: "SwapSutra backend is working",
        spreadsheetConnected: !!SPREADSHEET_ID,
        spreadsheetId: SPREADSHEET_ID,
        availableSheets: getSpreadsheet().getSheets().map(s => s.getName()),
        timestamp: new Date().toISOString()
      });
    }

    if (action === 'listAvailableActions') {
        return respondJson({
            success: true,
            actions: [
                'updateUserProfile', 'cleanupSheets', 'manageMembershipApproval', 'manageMembershipCoupon', 
                'updateAppSettings', 'createNewsletter', 'updateNewsletter', 'scheduleNewsletter', 
                'cancelNewsletter', 'testSendNewsletter', 'createSupportMessage', 'createSwapRequest',
                'acceptSwapRequest', 'declineSwapRequest', 'sendChatMessage', 'markAsRead',
                'getHostEnquiries', 'submitHostEnquiry', 'markRefundIssued', 'markOwnerFinalConfirmation', 
                'reopenArchivedChatForAdmin', 'updateHostEnquiryStatus', 'approveSubscription', 
                'approveUser', 'approveBook', 'updateSubscriptionDates', 'checkExpiredSubscriptions',
                'approveTestimonial', 'createTestimonial', 'createEvent', 'updateEvent', 'deleteEvent', 
                'registerEvent', 'createSubscription', 'createBook', 'updateUserBook', 'removeUserBook', 'createBookRating', 'rateBook', 
                'getBookRequestFeed', 'createBookRequest', 'getUserBookRequests', 'getBookRequestsForAdmin',
                'getBookRequestResponses', 'respondToBookRequest', 'updateBookRequestStatus',
                'subscribeNewsletter', 'subscribeEventNotify', 'notifyEvent', 'unsubscribeEventNotify', 'sendOTP',
                'verifyOTP', 'uploadSwapProof', 'markHandedOver', 'syncUsersFromSubscriptions',
                'seedTestQARecords', 'cleanupTestQARecords',
                'sendTrustEmailToExistingRegisteredUsers',
                'getCurrentReadCircles', 'searchCurrentReadCircles', 'addCurrentRead',
                'joinCurrentReadCircle', 'getCircleMessages', 'addCircleMessage',
                'getReadingSpace', 'upsertReadingSpaceBook',
                'addBook', 'editBook', 'sendBookApprovalEmailOnce'
            ]
        });
    }

    if (action === 'updateUserProfile') {
      return respondJson(updateUserProfile(data));
    }

    if (action === 'seedTestQARecords') return respondJson(seedTestQARecords(data));
    if (action === 'cleanupTestQARecords') return respondJson(cleanupTestQARecords(data));

    if (action === 'getReadingSpace') return respondJson(getReadingSpace(data));
    if (action === 'upsertReadingSpaceBook') return respondJson(upsertReadingSpaceBook(data));
    if (action === 'notifyEvent') return respondJson(subscribeEventNotify(data));
    if (action === 'addBook') return bookWriteResponse(createBook(data));
    if (action === 'editBook') return bookWriteResponse(updateUserBook(data));
    if (action === 'sendBookApprovalEmailOnce') return respondJson(sendBookApprovalEmailOnceForBook(data));
    
    if (action === 'cleanupSheets') {

      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const results = safeCleanupSheets();
      return respondJson({ success: true, results });
    }

    if (action === 'syncUsersFromSubscriptions') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(syncUsersFromSubscriptions());
    }
    
    if (action === 'manageMembershipApproval') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const status = data.status; // Approved, Rejected, Hold
      const subId = data.id;
      
      const sheet = getOrCreateSheet('Subscriptions', []);
      const values = sheet.getDataRange().getValues();
      const headers = values[0];
      const idIdx = headers.indexOf('id');
      const rowIndex = values.findIndex(r => r[idIdx] === subId);
      
      if (rowIndex === -1) return respondJson({ success: false, message: "Application not found" });
      
      const now = new Date();
      const updates = { adminStatus: status, notes: data.notes || "" };
      const email = normalizeEmail(values[rowIndex][headers.indexOf('email')]);
      const name = values[rowIndex][headers.indexOf('name')];
      
      if (status === 'Approved') {
        const startDate = now;

        // BUG FIX: this action used to unconditionally write a "+1 Year"
        // subscriptionExpiry onto whatever row was being approved. Free-trial
        // signups are auto-approved by registerFreeReader() with their own
        // 30-day subscriptionExpiry/trialEndDate already set — they never
        // need to pass through this admin-approval path. But if a trial row
        // was ever approved here anyway (e.g. an admin approving a queued
        // application that turned out to already be on a trial), this
        // overwrote its correct 30-day expiry with a ~365-day one while the
        // record's activationType stayed 'free_trial' — so the UI kept
        // showing the "1-Month Free Trial" label paired with a wildly wrong
        // days-remaining count computed from that ~1-year-out date. Only
        // paid/Chapters applications should ever get the 1-year expiry here.
        const rowActivationType = String(values[rowIndex][headers.indexOf('activationType')] || '').trim().toLowerCase();
        const rowMembershipType = String(values[rowIndex][headers.indexOf('membershipType')] || '').trim().toLowerCase();
        const isTrialRow = rowActivationType === 'free_trial' || rowActivationType === 'free' || rowMembershipType === 'trial';

        updates['approvedAt'] = now;
        updates['activatedBy'] = data.adminEmail;

        let expiryDate = null;
        if (!isTrialRow) {
          expiryDate = new Date();
          expiryDate.setFullYear(expiryDate.getFullYear() + 1); // 1 Year Membership
          updates['subscriptionStartDate'] = startDate;
          updates['subscriptionExpiry'] = expiryDate;
        } else {
          // A trial row approved here WITHOUT a trial window used to stay
          // "NoSubscription" forever, so the reader — approved — kept
          // seeing "Waiting for Admin Approval". Start the 30 days now,
          // unless a real window already exists.
          const tsIdx = headers.indexOf('trialStartDate');
          const teIdx = headers.indexOf('trialEndDate');
          const hasStart = tsIdx !== -1 && values[rowIndex][tsIdx];
          const hasEnd = teIdx !== -1 && values[rowIndex][teIdx];
          if (!hasStart || !hasEnd) {
            updates['trialStartDate'] = startDate;
            updates['trialEndDate'] = new Date(startDate.getTime() + 30 * 24 * 60 * 60 * 1000);
          }
        }

        // Notify user via Email
        try {
           sendMembershipApprovalEmail(email, name);
           updates['approvalEmailSent'] = 'Yes';
        } catch (e) {
           Logger.log("Email error: " + e.toString());
           updates['email_error'] = e.toString();
        }

        // Update User Record
        try {
          const userSheet = getOrCreateSheet('Users', []);
          const uValues = userSheet.getDataRange().getValues();
          const uHeaders = uValues[0];
          const uEmailIdx = uHeaders.indexOf('email');
          const uRowIdx = uValues.findIndex(r => normalizeEmail(r[uEmailIdx]) === normalizeEmail(email));
          if (uRowIdx !== -1) {
             const userUpdates = {
               membership_status: 'Active',
               subscription_status: 'Active',
               is_verified: true,
               approved_at: now,
               activated_at: now,
               approved_by: data.adminEmail
             };
             if (expiryDate) userUpdates.expires_at = expiryDate;
             for (let k in userUpdates) {
               const idx = uHeaders.indexOf(k);
               if (idx !== -1) userSheet.getRange(uRowIdx + 1, idx + 1).setValue(userUpdates[k]);
             }
          }
        } catch (e) {
          Logger.log("User update error: " + e.toString());
        }
      } else if (status === 'Rejected') {
        updates['cancellationReason'] = data.reason || "Application Rejected";
        try {
           sendMembershipRejectionEmail(email, name, updates['cancellationReason']);
        } catch (e) {
           Logger.log("Rejection email error: " + e.toString());
        }
      }
      
      for (let key in updates) {
        const colIdx = headers.indexOf(key);
        if (colIdx !== -1) sheet.getRange(rowIndex + 1, colIdx + 1).setValue(updates[key]);
      }

      ensureUserFromPayload({
        name,
        email,
        phone: values[rowIndex][headers.indexOf('phone')],
        membershipStatus: membershipStatusFromAdminStatus(status),
        paymentStatus: paymentStatusFromAdminStatus(status)
      }, { fillMissingOnly: true, syncStatuses: true });
      
      return respondJson({ success: true, message: `Status updated to ${status}` });
    }

    if (action === 'manageSubscription') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('Subscriptions', []);
      const values = sheet.getDataRange().getValues();
      const headers = values[0];
      const idIdx = headers.indexOf('id');
      const rowIdx = values.findIndex(r => r[idIdx] === data.id);
      if (rowIdx === -1) return respondJson({ success: false, message: "Subscription not found" });

      const now = new Date();
      if (data.subAction === 'extend') {
        const expiryIdx = headers.indexOf('subscriptionExpiry');
        let expiryDate = new Date(values[rowIdx][expiryIdx]);
        expiryDate.setDate(expiryDate.getDate() + Number(data.days));
        sheet.getRange(rowIdx + 1, expiryIdx + 1).setValue(expiryDate);
        return respondJson({ success: true, message: "Subscription extended" });
      } else if (data.subAction === 'cancel') {
        const statusIdx = headers.indexOf('adminStatus');
        sheet.getRange(rowIdx + 1, statusIdx + 1).setValue('Cancelled');
        return respondJson({ success: true, message: "Subscription cancelled" });
      }
      return respondJson({ success: false, message: "Invalid subAction" });
    }

    if (action === 'manageMembershipCoupon') return respondJson({ success: false, error: 'COUPONS_REMOVED', message: 'Coupon codes are no longer used on SwapSutra.' });

    if (action === 'manageBook') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('Books', getBookHeaders());
      ensureSheetHeaders(sheet, getBookHeaders());
      const values = sheet.getDataRange().getValues();
      const headers = values[0].map(h => String(h).trim());
      const idIdx = headers.indexOf('id');
      const rowIdx = values.findIndex(r => r[idIdx] === data.id);
      if (rowIdx === -1) return respondJson({ success: false, message: "Book not found" });

      const statusIdx = headers.indexOf('status');
      const titleIdx = headers.indexOf('title');
      const ownerEmailIdx = headers.indexOf('ownerEmail') !== -1 ? headers.indexOf('ownerEmail') : headers.indexOf('userEmail');
      const approvedAtIdx = headers.indexOf('approvedAt');
      sheet.getRange(rowIdx + 1, statusIdx + 1).setValue(data.status); // Approved, Rejected, Removed

      if (data.status === 'Approved') {
        const now = new Date();
        const bookTitle = titleIdx !== -1 ? values[rowIdx][titleIdx] : 'Recent Listing';
        const ownerEmail = ownerEmailIdx !== -1 ? normalizeEmail(values[rowIdx][ownerEmailIdx]) : '';
        if (approvedAtIdx !== -1 && !values[rowIdx][approvedAtIdx]) {
          sheet.getRange(rowIdx + 1, approvedAtIdx + 1).setValue(now);
        }
        const emailResult = sendBookApprovalEmailOnce(sheet, headers, rowIdx, data.id, ownerEmail, bookTitle, "Reader");
        return bookWriteResponse({ success: true, message: emailResult.sent ? `Book approved. ${emailResult.message}` : `Book approved, but ${emailResult.message}` });
      }

      return bookWriteResponse({ success: true, message: `Book status updated to ${data.status}` });
    }

    if (action === 'manageSupport') {
       if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
       const sheet = getOrCreateSheet('SupportMessages', []);
       const values = sheet.getDataRange().getValues();
       const headers = values[0];
       const idIdx = headers.indexOf('id');
       const rowIdx = values.findIndex(r => r[idIdx] === data.id);
       if (rowIdx === -1) return respondJson({ success: false, message: "Message not found" });

       const statusIdx = headers.indexOf('status');
       sheet.getRange(rowIdx + 1, statusIdx + 1).setValue(data.status);
       return respondJson({ success: true, message: "Support status updated" });
    }

    if (action === 'updateAppSettings') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('AppSettings', ["key", "value", "description", "updatedAt"]);
      const settings = data.settings; // Object { standardFee: 25, offerFee: 12 }
      const now = new Date();
      
      const values = sheet.getDataRange().getValues();
      const headers = values[0];
      const keyIdx = headers.indexOf('key');
      const valIdx = headers.indexOf('value');
      const dateIdx = headers.indexOf('updatedAt');

      for (const key in settings) {
        const rowIndex = values.findIndex(row => row[keyIdx] === key);
        if (rowIndex !== -1) {
          sheet.getRange(rowIndex + 1, valIdx + 1).setValue(settings[key]);
          sheet.getRange(rowIndex + 1, dateIdx + 1).setValue(now);
        } else {
          sheet.appendRow([key, settings[key], 'Admin updated', now]);
        }
      }
      return respondJson({ success: true, message: "Settings updated successfully" });
    }

    if (action === 'createNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(createNewsletter(data));
    }
    if (action === 'updateNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(updateNewsletter(data));
    }
    if (action === 'scheduleNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(updateNewsletterStatus(data.newsletterId, 'Scheduled'));
    }
    if (action === 'cancelNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(updateNewsletterStatus(data.newsletterId, 'Cancelled'));
    }
    if (action === 'testSendNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(sendNewsletterToRecipients(data.newsletterId, [data.adminEmail]));
    }
    if (action === 'sendNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      return respondJson(sendNewsletterToRecipients(data.newsletterId));
    }

    if (["createSupportMessage", "createSupport", "submitSupport", "contactSupport"].includes(action)) {
      return createSupportMessage(data);
    }

    let result = { success: false, message: 'Invalid Action' };

    if (action === 'createSwapRequest' || action === 'createBookServiceRequest') {
      const res = createSwapRequest(data);
      return respondJson(res);
    }

    if (action === 'acceptSwapRequest') {
      const id = data.requestId;
      // Authorization is decided by the verified session, never by the
      // ownerEmail the client happened to send — that value is public
      // (it is shown on the request itself), so trusting it let anyone
      // who knew a swap's owner address accept it on that owner's behalf.
      const ownerEmail = normalizeEmail(getAuthenticatedEmail());
      if (!ownerEmail) return respondJson({ success: false, error: 'SESSION_REQUIRED', message: "Sign in to accept this request." });

      const sheet = getOrCreateSheet('SwapRequests', []);
      const dataRange = sheet.getDataRange();
      const values = dataRange.getValues();
      const headers = values[0];
      const idIdx = headers.indexOf('id');

      const rowIndex = values.findIndex(r => r[idIdx] === id);
      if (rowIndex === -1) return respondJson({ success: false, message: "Request not found" });

      const parties = resolveSwapRequestParties(headers, values[rowIndex]);
      if (normalizeEmail(parties.ownerEmail) !== ownerEmail && !isAuthenticatedAdmin()) {
        return respondJson({ success: false, message: "Unauthorized: Only book owner can accept." });
      }

      sheet.getRange(rowIndex + 1, headers.indexOf('status') + 1).setValue('Accepted');
      sheet.getRange(rowIndex + 1, headers.indexOf('updatedAt') + 1).setValue(new Date());

      const request = {};
      headers.forEach((h, i) => request[h] = values[rowIndex][i]);
      request.requesterEmail = parties.requesterEmail;
      request.ownerEmail = parties.ownerEmail;
      request.requestedBookId = parties.requestedBookId;
      request.senderEmail = parties.requesterEmail;
      request.receiverEmail = parties.ownerEmail;

      // Create Chat with 3 participants
      const chatSheet = getOrCreateSheet('Chats', []);
      const chatId = generateId('SS_CHAT_');
      const now = new Date();
      const chatHeaders = chatSheet.getRange(1, 1, 1, chatSheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
      const chatRow = new Array(chatHeaders.length).fill("");
      chatHeaders.forEach((h, i) => {
        if (h === 'chatId') chatRow[i] = chatId;
        else if (h === 'bookId') chatRow[i] = request.requestedBookId;
        else if (h === 'ownerEmail') chatRow[i] = request.ownerEmail;
        else if (h === 'requesterEmail') chatRow[i] = request.requesterEmail;
        else if (h === 'adminEmail') chatRow[i] = 'swapsutra@gmail.com';
        else if (h === 'chatStatus') chatRow[i] = 'Active';
        else if (h === 'createdAt') chatRow[i] = now;
        else if (h === 'swapId') chatRow[i] = id;
      });
      chatSheet.appendRow(chatRow);

      // Update request with chatId
      const chatIdIdx = headers.indexOf('chatId');
      if (chatIdIdx !== -1) {
        sheet.getRange(rowIndex + 1, chatIdIdx + 1).setValue(chatId);
      }

      // Initial Message
      sendChatMessage({
        chatId: chatId,
        senderEmail: 'swapsutra@gmail.com',
        senderRole: 'Admin',
        message: 'SwapSutra admin is part of this conversation for safety. Please do not share OTPs, UPI PINs, or sensitive banking details.'
      });

      // SwapSutra Protection Protocol Message
      sendChatMessage({
        chatId: chatId,
        senderEmail: 'swapsutra@gmail.com',
        senderRole: 'Admin',
        message: roomIntroMessage_(request)
      });
      
      createNotification(request.senderEmail, 'swap_accepted', 'Swap Request Accepted!', `Your request was accepted. Open the exchange room to chat and follow the steps — the owner records the condition video first, then you have 48 hours to pay.`, id);
      try { appendStageEvent({ swapId: id, stage: 'ROOM', party: 'owner', actionType: 'accepted', actorEmail: ownerEmail, note: 'Request accepted; exchange room opened.' }); } catch (e) { /* the chat row is the record */ }
      
      // Notify sender via Email
      try {
        const subject = "Your SwapSutra Request was Approved";
        const content = `
          <p>Hi Reader,</p>
          <p>Great news! Your swap request has been **Accepted**.</p>
          <p>You can now start chatting with the owner to coordinate the exchange.</p>
        `;
        const htmlBody = getBrandedEmailTemplate("Swap Approved", content, "https://swapsutra.in/profile", "Go to Chat");
        sendSwapSutraEmail({ to: request.senderEmail, subject: subject, htmlBody: htmlBody });
      } catch (e) {
        Logger.log("Email error in acceptSwapRequest: " + e.toString());
      }
      
      return respondJson({ success: true, chatId: chatId });
    }

    if (action === 'declineSwapRequest') {
      const id = data.requestId;
      // Same session-only authorization as acceptSwapRequest above.
      const ownerEmail = normalizeEmail(getAuthenticatedEmail());
      if (!ownerEmail) return respondJson({ success: false, error: 'SESSION_REQUIRED', message: "Sign in to decline this request." });

      const sheet = getOrCreateSheet('SwapRequests', []);
      const dataRange = sheet.getDataRange();
      const values = dataRange.getValues();
      const headers = values[0];
      const idIdx = headers.indexOf('id');

      const rowIndex = values.findIndex(r => r[idIdx] === id);
      if (rowIndex === -1) return respondJson({ success: false, message: "Request not found" });

      const parties = resolveSwapRequestParties(headers, values[rowIndex]);
      if (normalizeEmail(parties.ownerEmail) !== ownerEmail && !isAuthenticatedAdmin()) {
        return respondJson({ success: false, message: "Unauthorized: Only book owner can decline." });
      }

      sheet.getRange(rowIndex + 1, headers.indexOf('status') + 1).setValue('Declined');
      sheet.getRange(rowIndex + 1, headers.indexOf('updatedAt') + 1).setValue(new Date());

      const request = {};
      headers.forEach((h, i) => request[h] = values[rowIndex][i]);
      request.requesterEmail = parties.requesterEmail;
      request.ownerEmail = parties.ownerEmail;
      createNotification(parties.requesterEmail, 'swap_declined', 'Swap Request Declined', `Your swap request was unfortunately declined.`, id);
      
      return respondJson({ success: true });
    }

    if (action === 'sendChatMessage') {
      return respondJson(sendChatMessage(data));
    }

    if (action === 'markAsRead') {
      const type = data.type; // 'notification' or 'message'
      const id = data.id;
      if (type === 'notification') {
        return respondJson(markNotificationRead(data));
      }
      const sheetName = type === 'notification' ? 'Notifications' : 'Messages';
      const sheet = getOrCreateSheet(sheetName, []);
      const dataRange = sheet.getDataRange();
      const values = dataRange.getValues();
      const headers = values[0];
      const idIdx = headers.indexOf('id');
      const isReadIdx = headers.indexOf('isRead');
      
      const rowIndex = values.findIndex(r => r[idIdx] === id);
      if (rowIndex !== -1 && isReadIdx !== -1) {
        sheet.getRange(rowIndex + 1, isReadIdx + 1).setValue('Yes');
        const chatIdIdx = headers.indexOf('chatId');
        if (sheetName === 'Messages' && chatIdIdx !== -1) chatThreadCacheClear_(values[rowIndex][chatIdIdx]);
      }
      return respondJson({ success: true });
    }
    if (action === 'getHostEnquiries') {
      if (!isAuthorizedAdminEmail(e.parameter.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      const sheet = getOrCreateSheet('HostEnquiries', []);
      const data = sheet.getDataRange().getValues();
      if (data.length <= 1) return respondJson([]);
      const headers = data[0];
      const enquiries = data.slice(1).map(row => {
        let obj = {};
        headers.forEach((h, i) => {
          obj[mapHeaderToKey(h)] = row[i];
        });
        return obj;
      });
      return respondJson(enquiries);
    }
    if (action === 'markRefundIssued') result = markRefundIssued(data);
    if (action === 'markOwnerFinalConfirmation') result = markOwnerFinalConfirmation(data);
    if (action === 'reopenArchivedChatForAdmin') result = reopenArchivedChatForAdmin(data);
    if (action === 'updateAdminNotes') result = updateAdminNotes(data);

    if (action === 'updateHostEnquiryStatus') result = updateHostEnquiryStatus(data);
    if (action === 'approveSubscription' || action === 'approveUser') result = approveSubscription(data);
    if (action === 'approveBook') result = approveBook(data);
    if (action === 'sendBookApprovalEmailOnce') result = sendBookApprovalEmailOnceForBook(data);
    if (action === 'updateSubscriptionDates') result = updateSubscriptionDates(data);
    if (action === 'checkExpiredSubscriptions') result = checkExpiredSubscriptions();
    if (action === 'sendExpiryReminders') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = sendMembershipExpiryReminders();
    }
    if (action === 'approveTestimonial') result = approveTestimonial(data);
    if (action === 'createTestimonial' || action === 'submitTestimonial' || action === 'addTestimonial') {
      result = createTestimonial(data);
    }
    if (action === 'createEvent') result = createEvent(data);
    if (action === 'updateEvent') result = updateEvent(data);
    if (action === 'deleteEvent') result = deleteEvent(data);
    if (action === 'registerEvent') result = registerEvent(data);
    if (action === 'getCurrentReadCircles') result = getCurrentReadCircles();
    if (action === 'searchCurrentReadCircles') result = searchCurrentReadCircles(data);
    if (action === 'addCurrentRead') result = addCurrentRead(data);
    if (action === 'joinCurrentReadCircle') result = joinCurrentReadCircle(data);
    if (action === 'getCircleMessages') result = getCircleMessages(data);
    if (action === 'addCircleMessage') result = addCircleMessage(data);
    if (action === 'leaveCurrentReadCircle') result = leaveCurrentReadCircle(data);
    if (action === 'endCurrentReadCircle') result = endCurrentReadCircle(data);
    if (action === 'archiveCurrentReadCircle') result = archiveCurrentReadCircle(data);
    if (action === 'cancelBookRequest') result = updateBookRequestStatus({ ...data, status: 'Cancelled' });
    if (action === 'getReadingSpace') result = getReadingSpace(data);
    if (action === 'upsertReadingSpaceBook') result = upsertReadingSpaceBook(data);
    if (action === 'submitHostEnquiry') result = submitHostEnquiry(data);
    if (action === 'createSubscription' || action === 'submitSubscription') result = createSubscription(data);
    if (action === 'registerFreeReader' || action === 'activateFreeMembership') result = registerFreeReader(data);
    // Joining makes you a newsletter subscriber (unless you opted out before).
    if (['createSubscription', 'submitSubscription', 'registerFreeReader', 'activateFreeMembership'].includes(action) && result && result.success) {
      try {
        ensureNewsletterSubscriber_(result.email || data.email || data.user_id || data.userId, data.name, 'signup');
      } catch (nlErr) { Logger.log('Newsletter auto-subscribe skipped: ' + nlErr); }
    }
    if (action === 'createBook' || action === 'listBook' || action === 'addBook') result = createBook(data);
    if (action === 'updateUserBook' || action === 'editBook') result = updateUserBook(data);
    if (action === 'removeUserBook') result = removeUserBook(data);
    if (action === 'createBookRequest') result = createBookRequest(data);
    if (action === 'respondToBookRequest') result = respondToBookRequest(data);
    if (action === 'updateBookRequestStatus') result = updateBookRequestStatus(data);
    if (action === 'createNotification') result = handleCreateNotificationApi(data);
    if (action === 'markNotificationRead') result = markNotificationRead(data);
    if (action === 'markNotificationsReadBulk') result = markNotificationsReadBulk(data);
    if (action === 'clearNotification') result = clearNotification(data);
    if (action === 'clearAllNotifications') result = clearAllNotifications(data);
    if (action === 'createBookRating' || action === 'rateBook') result = createBookRating(data);
    if (action === 'subscribeNewsletter') result = subscribeNewsletter(data);
    if (action === 'subscribeEventNotify' || action === 'notifyEvent') result = subscribeEventNotify(data);
    if (action === 'unsubscribeEventNotify') result = unsubscribeEventNotify(data);
    if (action === 'sendOTP') result = sendOTP(data.email, data.purpose);
    if (action === 'verifyOTP') result = verifyOTP(data.email, data.otp);
    if (action === 'resolveSession') result = resolveSessionForProxy(data);
    if (action === 'sendChatMessage') result = sendChatMessage(data);
    if (action === 'uploadSwapProof') result = uploadSwapProof(data);
    if (action === 'markHandedOver') result = markHandedOver(data);
    if (action === 'sendTrustEmailToExistingRegisteredUsers') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = sendTrustEmailToExistingRegisteredUsers(data);
    }
    if (action === 'seedTestQARecords') result = seedTestQARecords(data);
    if (action === 'cleanupTestQARecords') result = cleanupTestQARecords(data);
    
    // Newsletter Admin Actions
    if (action === 'createNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = createNewsletter(data);
    }
    if (action === 'updateNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = updateNewsletter(data);
    }
    if (action === 'scheduleNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = updateNewsletterStatus(data.newsletterId, 'Scheduled');
    }
    if (action === 'cancelNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = updateNewsletterStatus(data.newsletterId, 'Cancelled');
    }
    if (action === 'testSendNewsletter') {
      if (!isAuthorizedAdminEmail(data.adminEmail)) return respondJson({ success: false, message: "Unauthorized" });
      result = sendNewsletterToRecipients(data.newsletterId, [data.adminEmail]);
    }

    // Any write that can change what the Library shows drops the cached
    // payload, so a new or edited listing appears on the next request
    // rather than up to two minutes later. Done here, after the write,
    // rather than inside each mutator: one place, and no window in which
    // a concurrent read could re-cache the pre-write state.
    if (LIBRARY_MUTATING_ACTIONS[action]) invalidateLibraryCache();

    return respondJson(result);
  } catch (err) {
    return respondJson({ success: false, message: 'Server Error: ' + err.toString() });
  }
}

function jsonResponse(data) {
  return respondJson(data);
}

function subscriptionHeadersRequired() {
  return ["id", "name", "email", "userEmail", "phone", "utr", "screenshotUrl", "originalAmount", "paymentAmount", "payableAmount", "finalAmount", "paymentRequired", "activationType", "membershipType", "membershipStatus", "paymentStatus", "couponCode", "adminStatus", "approvedAt", "subscriptionStartDate", "subscriptionExpiry", "trialStartDate", "trialEndDate", "booksListedCount", "reminderSent", "reminderSentAt", "approvalEmailSent", "cancellationReason", "createdAt", "updatedAt"];
}

function getSubscriptionEmail(row, headers) {
  const emailIdx = findHeaderIndex(headers, ['email', 'userEmail']);
  return emailIdx === -1 ? '' : normalizeEmail(row[emailIdx]);
}

function createSubscription(data) {
  const subHeaders = subscriptionHeadersRequired();
  const sheet = getOrCreateSheet('Subscriptions', subHeaders);

  const normalizedEmail = normalizeEmail(data.email);
  if (!normalizedEmail) return { success: false, message: "Email is required" };

  const headers = ensureSheetHeaders(sheet, subHeaders);
  const values = sheet.getDataRange().getValues();

  const existingRowIndex = values.length > 1 ? values.slice(1).findIndex(row => getSubscriptionEmail(row, headers) === normalizedEmail) : -1;
  const isExistingAccount = existingRowIndex !== -1 || emailExistsInUsersSheet(normalizedEmail);

  // An already-authenticated existing account applying for the paid ₹49
  // Chapters membership (the "Join Chapters" upgrade offered on the
  // membership-selection screen to a registered Free Explorer) legitimately
  // already has a Subscriptions row -- that is not a duplicate signup, it
  // is the same person upgrading. Only honored when a real existing row is
  // there to update in place; a bare isUpgrade claim with nothing to attach
  // to is treated exactly like an ordinary registration attempt below.
  const isUpgradeRequest = data.isUpgrade === true || String(data.isUpgrade || '').toLowerCase() === 'true';
  const canUpgradeInPlace = isUpgradeRequest && existingRowIndex !== -1;

  // RULE 1 / RULE 4: block duplicate Sign Ups. Check both the Subscriptions
  // sheet (existing check) and the Users sheet directly (source of truth
  // per the auth spec) so a user who exists in Users but has no
  // Subscriptions row yet still can't register a second account.
  if (isExistingAccount && !canUpgradeInPlace) {
    return { success: false, code: "EMAIL_EXISTS", message: "You already have a SwapSutra account. Please log in to continue." };
  }

  // Also block on a duplicate MOBILE NUMBER, not just email -- someone
  // re-registering with a different/typo'd email but the same phone they
  // already used is still the same person, and must not end up with a
  // second account or a second free trial. Never revealed which email the
  // existing account uses (that would leak account existence tied to a
  // phone number to anyone probing); the response is intentionally the
  // same generic "already have an account" message either way. Skipped for
  // a genuine upgrade -- the phone submitted there is expected to match
  // the account's own existing phone, which is not a duplicate.
  const phoneInput = data.phone || '';
  if (!canUpgradeInPlace && phoneInput && (phoneExistsInUsersSheet(phoneInput) || (values.length > 1 && values.slice(1).some(row => {
    const phoneIdx = findHeaderIndex(headers, ['phone']);
    return phoneIdx !== -1 && normalizePhoneLast10(row[phoneIdx]) === normalizePhoneLast10(phoneInput);
  })))) {
    return { success: false, code: "PHONE_EXISTS", message: "You already have a SwapSutra account. Please log in to continue." };
  }

  const couponCodeInput = (data.couponCode || "").trim().toUpperCase();
  const originalAmount = Number(data.originalAmount || 49);
  const finalAmount = Number(data.finalAmount || data.payableAmount || data.paymentAmount || data.amount || 49);
  const hasPaymentRequiredFlag = data.paymentRequired !== undefined || data.isPaymentRequired !== undefined;
  const paymentRequired = hasPaymentRequiredFlag
    ? (data.paymentRequired === true || String(data.paymentRequired || data.isPaymentRequired || '').toLowerCase() === 'true')
    : finalAmount > 0;
  const id = canUpgradeInPlace ? String(values[existingRowIndex + 1][headers.indexOf('id')] || generateId('SS_SUB_')) : generateId('SS_SUB_');
  let screenshotUrl = '';
  if (paymentRequired) {
    const screenshotData = data.screenshot || data.paymentScreenshot;
    if (!screenshotData) {
      return { success: false, message: "Payment screenshot is required for paid activation.", error: "PAYMENT_SCREENSHOT_REQUIRED" };
    }
    screenshotUrl = saveFileToDrive(screenshotData, `SUB_${id}_Payment.png`);
    if (!screenshotUrl) {
      return { success: false, message: "Payment screenshot upload failed. Please try again with a JPG, PNG, or WebP image under 3 MB.", error: "PAYMENT_SCREENSHOT_UPLOAD_FAILED" };
    }
  }

  const now = new Date();

  // registrationType/membershipType must reflect how this application was
  // ACTUALLY made -- derived by the backend from paymentRequired (computed
  // above from amount/flags this function itself validated), never blindly
  // trusted from an arbitrary client-supplied membershipType. Previously
  // this was hardcoded to 'premium' for every row regardless of tier
  // (mislabeling every Free Explorer stub as premium and overcounting them
  // in the admin revenue estimate), and even the interim fix still let a
  // client-supplied data.membershipType override paymentRequired outright
  // -- so a manipulated or stale payload with paymentRequired:false could
  // still claim membershipType:'premium'. Now: paymentRequired:false can
  // NEVER resolve to a paid-sounding membershipType, and vice versa.
  // registerFreeReader() is still the ONLY place that ever sets
  // membershipType to 'trial' (real trial evidence), so this never
  // collides with that check.
  const CANONICAL_FREE_MEMBERSHIP_TYPE = 'free';
  const CANONICAL_PAID_MEMBERSHIP_TYPE = 'premium';
  const clientMembershipTypeLower = String(data.membershipType || '').trim().toLowerCase();
  const clientClaimsPaidVariant = ['premium', 'paid', 'verified', 'verified_member', 'coupon_discount', 'coupon_free'].includes(clientMembershipTypeLower);
  const resolvedMembershipType = !paymentRequired
    ? CANONICAL_FREE_MEMBERSHIP_TYPE
    : (clientClaimsPaidVariant ? clientMembershipTypeLower : CANONICAL_PAID_MEMBERSHIP_TYPE);

  if (canUpgradeInPlace) {
    // Update the SAME Subscriptions row in place rather than appending a
    // second row for this email -- one row per email stays true, and the
    // account's history (including trialStartDate/trialEndDate from a
    // prior Free Explorer trial, if any) is preserved rather than
    // overwritten. Only the fields a fresh paid application would set are
    // touched; subscriptionStartDate/subscriptionExpiry are intentionally
    // reset to blank here (same as a brand-new paid row below) since the
    // NEW paid period begins only once admin approval + first-book
    // activation complete it -- exactly the existing paid-membership
    // activation flow, just applied to an existing row instead of a new one.
    const sheetRow = existingRowIndex + 2; // +1 header row, +1 to 1-index
    headers.forEach((h, i) => {
      const col = i + 1;
      if (h === 'trialStartDate' || h === 'trialEndDate' || h === 'id' || h === 'email' || h === 'userEmail' || h === 'createdAt') return; // preserved as history, never overwritten
      if (h === 'name') sheet.getRange(sheetRow, col).setValue(data.name);
      else if (h === 'phone') sheet.getRange(sheetRow, col).setValue(data.phone);
      else if (h === 'utr') sheet.getRange(sheetRow, col).setValue(paymentRequired ? (data.utr || data.utrNumber || '') : '');
      else if (h === 'screenshotUrl') sheet.getRange(sheetRow, col).setValue(screenshotUrl);
      else if (h === 'originalAmount') sheet.getRange(sheetRow, col).setValue(originalAmount);
      else if (h === 'paymentAmount' || h === 'payableAmount' || h === 'finalAmount') sheet.getRange(sheetRow, col).setValue(finalAmount);
      else if (h === 'paymentRequired') sheet.getRange(sheetRow, col).setValue(paymentRequired ? 'Yes' : 'No');
      else if (h === 'activationType') sheet.getRange(sheetRow, col).setValue(data.activationType || (paymentRequired ? (couponCodeInput ? 'coupon_discount' : 'paid') : 'coupon_free'));
      else if (h === 'membershipType') sheet.getRange(sheetRow, col).setValue(resolvedMembershipType);
      // A Free Explorer (no payment involved) is never "payment pending" --
      // that value must be reserved for an actual ₹49 application awaiting
      // approval. See the matching fix in the fresh-row branch below.
      else if (h === 'membershipStatus') sheet.getRange(sheetRow, col).setValue(paymentRequired ? 'PAYMENT_PENDING' : 'REGISTERED');
      else if (h === 'paymentStatus') sheet.getRange(sheetRow, col).setValue(data.paymentStatus || (paymentRequired ? 'Pending' : 'Coupon Applied'));
      else if (h === 'couponCode') sheet.getRange(sheetRow, col).setValue(couponCodeInput);
      else if (h === 'adminStatus') sheet.getRange(sheetRow, col).setValue(data.adminStatus || 'Pending');
      else if (h === 'subscriptionStartDate') sheet.getRange(sheetRow, col).setValue('');
      else if (h === 'subscriptionExpiry') sheet.getRange(sheetRow, col).setValue('');
      else if (h === 'approvedAt') sheet.getRange(sheetRow, col).setValue('');
      else if (h === 'reminderSent') sheet.getRange(sheetRow, col).setValue('No');
      else if (h === 'approvalEmailSent') sheet.getRange(sheetRow, col).setValue('No');
      else if (h === 'updatedAt') sheet.getRange(sheetRow, col).setValue(now);
    });

    const userResult = ensureUserFromPayload({
      name: data.name,
      email: normalizedEmail,
      phone: data.phone,
      area: data.area,
      pincode: data.pincode,
      genres: data.genres,
      bio: data.bio,
      membershipStatus: 'Pending',
      paymentStatus: paymentRequired ? 'Pending' : 'Coupon Applied',
      createdAt: now
    }, { fillMissingOnly: true, syncStatuses: true });
    if (!userResult.success) return { success: false, message: "Application saved, but user profile sync failed.", error: "USER_SYNC_FAILED", id, email: normalizedEmail };

    try {
      sendTrustEmail(normalizedEmail);
      Logger.log("Membership upgrade submitted for: " + normalizedEmail);
    } catch (e) {
      Logger.log("Auto email error in createSubscription (upgrade): " + e.toString());
    }

    return { success: true, id: id, email: normalizedEmail, screenshotUrl: screenshotUrl, message: "Saved successfully" };
  }

  const row = new Array(headers.length).fill("");
  headers.forEach((h, i) => {
    if (h === 'id') row[i] = id;
    else if (h === 'name') row[i] = data.name;
    else if (h === 'email') row[i] = normalizedEmail;
    else if (h === 'userEmail') row[i] = normalizedEmail;
    else if (h === 'phone') row[i] = data.phone;
    else if (h === 'utr') row[i] = paymentRequired ? (data.utr || data.utrNumber || '') : '';
    else if (h === 'screenshotUrl') row[i] = screenshotUrl;
    else if (h === 'originalAmount') row[i] = originalAmount;
    else if (h === 'paymentAmount') row[i] = finalAmount;
    else if (h === 'payableAmount') row[i] = finalAmount;
    else if (h === 'finalAmount') row[i] = finalAmount;
    else if (h === 'paymentRequired') row[i] = paymentRequired ? 'Yes' : 'No';
    else if (h === 'activationType') row[i] = data.activationType || (paymentRequired ? (couponCodeInput ? 'coupon_discount' : 'paid') : 'coupon_free');
    else if (h === 'membershipType') row[i] = resolvedMembershipType;
    // ROOT CAUSE of the reported bug: this used to be hardcoded to
    // 'PAYMENT_PENDING' for every row regardless of tier, and
    // computeSubscriptionStatus() checked that flag BEFORE ever checking
    // whether the row was trial-flavored -- so a Free Explorer's plain
    // registration stub (paymentRequired: No) was reported as
    // PAYMENT_PENDING, with a fake 10-year "subscription" underneath it
    // (see subscriptionStartDate/subscriptionExpiry immediately below),
    // instead of as "registered, trial not yet activated". A Free Explorer
    // never has a payment pending -- only a genuine ₹49 application does.
    else if (h === 'membershipStatus') row[i] = paymentRequired ? 'PAYMENT_PENDING' : 'REGISTERED';
    else if (h === 'paymentStatus') row[i] = data.paymentStatus || (paymentRequired ? 'Pending' : 'Coupon Applied');
    else if (h === 'couponCode') row[i] = couponCodeInput;
    else if (h === 'adminStatus') row[i] = data.adminStatus || 'Pending';
    // ROOT CAUSE #2: these used to trust data.activatedAt/data.expiresAt --
    // CLIENT-SUPPLIED values -- directly. The free-tier Sign Up payload
    // (App.tsx) used to send expiresAt = now + 10 years for every free
    // registration, which landed here verbatim as subscriptionExpiry,
    // producing exactly the fabricated 10-year "membership" window this fix
    // removes. The backend must never trust client-supplied dates for a
    // membership window. subscriptionStartDate/subscriptionExpiry are
    // reserved EXCLUSIVELY for a genuine, backend-activated PAID
    // membership (set only by activateSubscriptionIfEligible / the admin
    // approval pipeline once payment is actually approved) -- never written
    // here at application time, for either tier. A Free Explorer's trial
    // window lives ONLY in trialStartDate/trialEndDate, written ONLY by
    // registerFreeReader() at the moment the trial is genuinely activated.
    else if (h === 'subscriptionStartDate') row[i] = '';
    else if (h === 'subscriptionExpiry') row[i] = '';
    else if (h === 'trialStartDate') row[i] = '';
    else if (h === 'trialEndDate') row[i] = '';
    else if (h === 'booksListedCount') row[i] = 0;
    else if (h === 'reminderSent') row[i] = 'No';
    else if (h === 'approvalEmailSent') row[i] = 'No';
    else if (h === 'createdAt') row[i] = now;
    else if (h === 'updatedAt') row[i] = now;
  });

  sheet.appendRow(row);
  const savedValues = sheet.getDataRange().getValues();
  const saved = savedValues.slice(1).some(savedRow => getSubscriptionEmail(savedRow, headers) === normalizedEmail && String(savedRow[headers.indexOf('id')]) === id);
  if (!saved) return { success: false, message: "Subscription could not be saved. Please try again.", error: "SUBSCRIPTION_SAVE_FAILED" };

  const userResult = ensureUserFromPayload({
    name: data.name,
    email: normalizedEmail,
    phone: data.phone,
    area: data.area,
    pincode: data.pincode,
    genres: data.genres,
    bio: data.bio,
    membershipStatus: 'Pending',
    paymentStatus: paymentRequired ? 'Pending' : 'Coupon Applied',
    createdAt: now
  }, { fillMissingOnly: true, syncStatuses: true });
  if (!userResult.success) return { success: false, message: "Subscription saved, but user profile sync failed.", error: "USER_SYNC_FAILED", id, email: normalizedEmail };

  try {
    sendTrustEmail(normalizedEmail);
    Logger.log("Membership submitted for: " + normalizedEmail);
  } catch (e) {
    Logger.log("Auto email error in createSubscription: " + e.toString());
  }

  return { success: true, id: id, email: normalizedEmail, screenshotUrl: screenshotUrl, message: "Saved successfully" };
}

function registerFreeReader(data) {
  const normEmail = normalizeEmail(data.email || data.user_id || data.userId || data.ownerEmail);
  if (!normEmail) return { success: false, message: "Email is required to register." };

  // If they arrived on someone's invite link, record the claim now — as
  // Pending. Nothing is granted here: the reward is paid only once this
  // reader lists their first book (see maybeQualifyReferral in createBook),
  // which is what makes the loop buy supply rather than empty accounts.
  // Recorded before the trial logic so a duplicate-registration path that
  // returns early still attributes the invite; it is idempotent, refuses
  // self-referral, and can never fail the registration.
  if (data.referralCode) {
    try { recordReferralClaim(normEmail, data.referralCode); } catch (referralErr) { Logger.log('Referral claim skipped: ' + referralErr.toString()); }
  }

  const name = data.name || (normEmail ? normEmail.split('@')[0] : 'Reader');
  const now = new Date();
  const trialEnd = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000); // 1 Month Free Trial

  // ATOMICITY: "Continue as Free Reader" must be idempotent under a
  // double-click / duplicate submit (two near-simultaneous requests for the
  // same email).
  //
  // This used to take Apps Script's SCRIPT-level lock — a single mutex for
  // the whole project. It was correct, but it meant every registration on
  // the platform queued behind every other one, holding the lock through
  // several sheet reads and writes. Fifty people signing up in a minute
  // (a campus drive, a press mention — precisely the moments that matter)
  // would push later arrivals past the ten-second timeout and show them
  // "your trial is already being activated" when nothing of the sort was
  // happening.
  //
  // The race being defended against is same-email only: two requests for
  // ONE address racing between the "does a row exist?" read and the write.
  // Two different addresses never touch the same row, and appendRow is
  // serialised by Sheets itself, so they never needed to wait for each
  // other. The guard is therefore keyed by email: a duplicate submit for
  // the same reader is refused exactly as before, and unrelated signups
  // now run concurrently.
  //
  // CacheService rather than LockService because LockService offers only
  // script- and user-scoped locks, and "user" here is the script owner —
  // the same global mutex under another name.
  const registrationGuardKey = 'reg_' + normEmail;
  const registrationCache = (function () {
    try { return CacheService.getScriptCache(); } catch (e) { return null; }
  })();
  let gotLock = true;
  if (registrationCache) {
    if (registrationCache.get(registrationGuardKey)) {
      gotLock = false;
    } else {
      // Held only for the duration of this call; released in the finally
      // below. The TTL is a safety net so a crashed execution cannot lock
      // an address out permanently.
      registrationCache.put(registrationGuardKey, '1', 30);
    }
  }
  if (!gotLock) {
    // A concurrent request is already processing this exact operation.
    // This is a transient contention state, NOT evidence the trial was
    // ever consumed -- must never be reported with alreadyUsedTrial/the
    // "already taken" message, or a double-click would show a false
    // rejection to a genuinely new user.
    return {
      success: false,
      error: "TRIAL_ACTIVATION_BUSY",
      message: "Your trial is already being activated. Please wait a moment and check My Profile."
    };
  }

  try {
    // 0. Determine FIRST whether this email has any existing Subscriptions
    //    row, and if so, whether it is actual evidence of a previously
    //    CONSUMED trial (or an active paid membership) -- as opposed to a
    //    plain registration/payment stub. Registered != Trial Consumed:
    //      - createSubscription() runs at ordinary Sign Up (including the
    //        "free" tier tab every brand-new user's Sign Up form submits
    //        through) and always leaves trialStartDate/trialEndDate BLANK
    //        and never sets membershipType to 'trial'. That row proves only
    //        that an account was registered, never that a trial ran.
    //      - registerFreeReader() (this function) is the ONLY code path
    //        that ever sets activationType='free_trial', membershipType=
    //        'trial', and non-blank trialStartDate/trialEndDate. Those
    //        three fields are therefore reliable, mutually-redundant
    //        evidence of a genuinely activated trial -- and nothing else
    //        (an incomplete registration, a pending/failed/cancelled
    //        payment attempt, an OTP verification, or simply opening the
    //        membership page) may ever be treated as equivalent to it.
    const subHeaders = subscriptionHeadersRequired();
    const subSheet = getOrCreateSheet('Subscriptions', subHeaders);
    const headers = ensureSheetHeaders(subSheet, subHeaders);
    const values = subSheet.getDataRange().getValues();

    let existingSubRowIndex = -1;
    if (values.length > 1) {
      const emailIndex = findHeaderIndex(headers, ['email', 'userEmail']);
      if (emailIndex !== -1) {
        existingSubRowIndex = values.slice(1).findIndex(row => normalizeEmail(row[emailIndex]) === normEmail);
      }
    }

    if (existingSubRowIndex !== -1) {
      const existingRow = values[existingSubRowIndex + 1];
      const existingSub = {};
      headers.forEach((h, i) => { existingSub[h] = existingRow[i]; });

      const hasGenuineTrialRecord =
        String(existingSub.activationType || '').trim().toLowerCase() === 'free_trial' ||
        String(existingSub.membershipType || '').trim().toLowerCase() === 'trial' ||
        !!existingSub.trialStartDate ||
        !!existingSub.trialEndDate;

      const computed = computeSubscriptionStatus(existingSub);
      const isPremium = computed === 'PREMIUM' || computed === 'Active';

      // IDEMPOTENT REPLAY: a double-click (or a retried request after a
      // dropped response) can send a second "Continue as Free Reader"
      // request for the same email while the FIRST request's trial is only
      // seconds old. Thanks to the script lock above, that second request
      // now sees a genuine trial record too (the first request's) -- but it
      // must not be told "already taken"; that would be a false rejection
      // of the very click that just succeeded. Recognize "this trial was
      // just activated, moments ago, and is still active" as this same
      // activation completing, and reply with the same success instead of
      // an error. A trial genuinely consumed minutes/days/weeks ago (Test 2,
      // Test 6) falls well outside this window and is still correctly
      // blocked below.
      const RECENT_ACTIVATION_WINDOW_MS = 60 * 1000;
      if (hasGenuineTrialRecord && computed === 'FREE_TRIAL' && existingSub.trialStartDate) {
        const startedMsAgo = now.getTime() - new Date(existingSub.trialStartDate).getTime();
        if (startedMsAgo >= 0 && startedMsAgo <= RECENT_ACTIVATION_WINDOW_MS) {
          return {
            success: true,
            isRegistered: true,
            message: "Welcome to SwapSutra! Your 1-Month Free Trial is now active.",
            membershipStatus: "TRIAL",
            userTier: "trial",
            isTrial: true,
            isPremium: false,
            daysRemaining: 30,
            trialStartDate: existingSub.trialStartDate,
            trialEndDate: existingSub.trialEndDate,
            subscription: {
              id: existingSub.id,
              name: existingSub.name || name,
              email: normEmail,
              computedStatus: 'TRIAL',
              membershipStatus: 'TRIAL',
              adminStatus: 'Approved',
              activationType: 'free_trial',
              membershipType: 'trial',
              trialStartDate: existingSub.trialStartDate,
              trialEndDate: existingSub.trialEndDate,
              subscriptionStartDate: '',
              subscriptionExpiry: '',
              booksListedCount: existingSub.booksListedCount || 0,
              booksRemaining: 999
            }
          };
        }
      }

      if (hasGenuineTrialRecord || isPremium) {
        // Genuinely returning user: either they already consumed a trial
        // (active, expired, or cancelled since -- consumption already
        // happened, so it stays blocked either way) or they already hold
        // an active paid membership. Do NOT touch their existing row.
        const isExpired = computed === 'EXPIRED' || computed === 'Expired';

        logActivity(normEmail, "Free Trial Re-request Blocked", hasGenuineTrialRecord
          ? "Existing user attempted to re-activate a previously-consumed free trial; trial is new-readers-only."
          : "Existing user with an active paid membership attempted to start a free trial.", "Info", "Auth");

        return {
          success: false,
          isRegistered: !isExpired,
          alreadyUsedTrial: true,
          message: isPremium
            ? "You already have an active SwapSutra Chapters membership."
            : "You have already taken your 30-day free trial. Please subscribe to SwapSutra Chapters (₹49/month) to continue.",
          membershipStatus: computed,
          userTier: isPremium ? 'premium' : (isExpired ? 'expired' : 'trial'),
          isTrial: computed === 'TRIAL' || computed === 'FREE_TRIAL',
          isPremium: isPremium,
          isExpired: isExpired
        };
      }

      // A Subscriptions row exists but it is only a registration/payment
      // stub -- no trial was ever consumed and there is no active paid
      // membership (e.g. the row Sign Up creates for every brand-new
      // account, an abandoned/incomplete registration, a duplicate/test
      // record, or a previously failed/cancelled payment attempt). This
      // reader is still genuinely trial-eligible: activate the real 30-day
      // trial by converting THIS row in place, rather than appending a
      // second row for the same email (keeps one Subscriptions row per
      // email and avoids leaving stale duplicate stubs behind).
      ensureUserFromPayload({
        name: name,
        email: normEmail,
        phone: data.phone || '',
        area: data.area || '',
        pincode: data.pincode || '',
        genres: data.genres || '',
        bio: data.bio || '',
        membershipStatus: 'TRIAL',
        paymentStatus: 'Free Trial',
        createdAt: now
      }, { fillMissingOnly: false, syncStatuses: true });

      const sheetRow = existingSubRowIndex + 2; // +1 for header row, +1 to 1-index
      headers.forEach((h, i) => {
        const col = i + 1;
        if (h === 'activationType') subSheet.getRange(sheetRow, col).setValue('free_trial');
        else if (h === 'membershipType') subSheet.getRange(sheetRow, col).setValue('trial');
        else if (h === 'membershipStatus') subSheet.getRange(sheetRow, col).setValue('TRIAL');
        else if (h === 'paymentStatus') subSheet.getRange(sheetRow, col).setValue('Free Trial');
        else if (h === 'adminStatus') subSheet.getRange(sheetRow, col).setValue('Approved');
        else if (h === 'paymentRequired') subSheet.getRange(sheetRow, col).setValue('No');
        // subscriptionStartDate/subscriptionExpiry are reserved for a
        // genuine PAID membership window only -- a Free Explorer trial's
        // window lives solely in trialStartDate/trialEndDate below. Blanked
        // (not duplicated) here so a later ₹49 upgrade's real paid window
        // is never confused with this trial's dates.
        else if (h === 'subscriptionStartDate') subSheet.getRange(sheetRow, col).setValue('');
        else if (h === 'subscriptionExpiry') subSheet.getRange(sheetRow, col).setValue('');
        else if (h === 'trialStartDate') subSheet.getRange(sheetRow, col).setValue(now);
        else if (h === 'trialEndDate') subSheet.getRange(sheetRow, col).setValue(trialEnd);
        else if (h === 'updatedAt') subSheet.getRange(sheetRow, col).setValue(now);
      });

      logActivity(normEmail, "Free Trial Activated", "Reader started 1-month Free Trial (converted from existing registration record)", "Success", "Auth");

      const existingId = existingSub.id || ('SS_SUB_TRIAL_' + normEmail.split('@')[0]);
      return {
        success: true,
        isRegistered: true,
        message: "Welcome to SwapSutra! Your 1-Month Free Trial is now active.",
        membershipStatus: "TRIAL",
        userTier: "trial",
        isTrial: true,
        isPremium: false,
        daysRemaining: 30,
        trialStartDate: now,
        trialEndDate: trialEnd,
        subscription: {
          id: existingId,
          name: name,
          email: normEmail,
          computedStatus: 'TRIAL',
          membershipStatus: 'TRIAL',
          adminStatus: 'Approved',
          activationType: 'free_trial',
          membershipType: 'trial',
          trialStartDate: now,
          trialEndDate: trialEnd,
          subscriptionStartDate: '',
          subscriptionExpiry: '',
          booksListedCount: 0,
          booksRemaining: 999
        }
      };
    }

    // 1. Truly first contact with this system for this email: ensure in
    //    Users sheet with TRIAL status (unchanged from before this fix).
    const userResult = ensureUserFromPayload({
      name: name,
      email: normEmail,
      phone: data.phone || '',
      area: data.area || '',
      pincode: data.pincode || '',
      genres: data.genres || '',
      bio: data.bio || '',
      membershipStatus: 'TRIAL',
      paymentStatus: 'Free Trial',
      createdAt: now
    }, { fillMissingOnly: false, syncStatuses: true });

    // 2. Create the 1-Month Free Trial tier record in Subscriptions sheet
    const subId = 'SS_SUB_TRIAL_' + (userResult?.user?.id || normEmail.split('@')[0]);

    const row = new Array(headers.length).fill("");
    headers.forEach((h, i) => {
      if (h === 'id') row[i] = subId;
      else if (h === 'name') row[i] = name;
      else if (h === 'email' || h === 'userEmail') row[i] = normEmail;
      else if (h === 'paymentRequired') row[i] = 'No';
      else if (h === 'originalAmount') row[i] = 49;
      else if (h === 'paymentAmount' || h === 'finalAmount' || h === 'payableAmount') row[i] = 0;
      else if (h === 'activationType') row[i] = 'free_trial';
      else if (h === 'membershipType') row[i] = 'trial';
      else if (h === 'membershipStatus') row[i] = 'TRIAL';
      else if (h === 'paymentStatus') row[i] = 'Free Trial';
      else if (h === 'adminStatus') row[i] = 'Approved';
      // subscriptionStartDate/subscriptionExpiry reserved for a genuine
      // PAID window only -- see the matching comment in the stub-conversion
      // branch above.
      else if (h === 'subscriptionStartDate') row[i] = '';
      else if (h === 'subscriptionExpiry') row[i] = '';
      else if (h === 'trialStartDate') row[i] = now;
      else if (h === 'trialEndDate') row[i] = trialEnd;
      else if (h === 'booksListedCount') row[i] = 0;
      else if (h === 'createdAt' || h === 'updatedAt') row[i] = now;
    });
    subSheet.appendRow(row);

    logActivity(normEmail, "Free Trial Activated", "Reader started 1-month Free Trial", "Success", "Auth");

    return {
      success: true,
      isRegistered: true,
      message: "Welcome to SwapSutra! Your 1-Month Free Trial is now active.",
      membershipStatus: "TRIAL",
      userTier: "trial",
      isTrial: true,
      isPremium: false,
      daysRemaining: 30,
      trialStartDate: now,
      trialEndDate: trialEnd,
      subscription: {
        id: subId,
        name: name,
        email: normEmail,
        computedStatus: 'TRIAL',
        membershipStatus: 'TRIAL',
        adminStatus: 'Approved',
        activationType: 'free_trial',
        membershipType: 'trial',
        trialStartDate: now,
        trialEndDate: trialEnd,
        subscriptionStartDate: '',
        subscriptionExpiry: '',
        booksListedCount: 0,
        booksRemaining: 999
      }
    };
  } finally {
    // Release this reader's guard. Wrapped because a cache outage must not
    // turn a completed registration into a thrown error.
    try {
      if (registrationCache) registrationCache.remove(registrationGuardKey);
    } catch (releaseErr) {
      Logger.log('Registration guard release failed for ' + normEmail + ': ' + releaseErr.toString());
    }
  }
}

// ===========================================================================
// ONE-OFF MANUAL REPAIR: existing Subscriptions rows already corrupted by
// the two bugs fixed above (a hardcoded membershipType and client-trusted
// subscriptionStartDate/subscriptionExpiry dates) are NOT deleted -- they
// are repaired in place, exactly like registerFreeReader() already does for
// an ordinary registration stub. This is a diagnostic/remediation tool, not
// an application feature: run it manually from the Apps Script editor
// (select "repairAllCorruptedFreeExplorerStubs" in the function dropdown,
// then Run), NOT wired into doGet/doPost, so it never becomes a
// network-callable endpoint.
//
// A row is treated as a corrupted Free Explorer stub -- and only repaired
// -- when ALL of these hold:
//   - paymentRequired is NOT 'Yes' (this app never asks a genuine paid
//     applicant to skip payment, so this reliably rules out real paid rows)
//   - trialStartDate AND trialEndDate are both blank (no genuine trial was
//     ever actually activated on this row)
//   - subscriptionStartDate/subscriptionExpiry are both present AND span an
//     implausible duration (> ~400 days -- this app's real paid memberships
//     run at most ~1 year; a multi-year window can only be the old
//     fabrication bug, never real data)
// A row that doesn't match every one of these is left completely untouched
// -- in particular, a genuinely paid row (paymentRequired: 'Yes') is never
// touched by this function, per "determine paid status from actual payment
// evidence before changing anything".
//
// Repair converts the row exactly the way a fresh, correct trial activation
// would: trialStartDate/trialEndDate are set to a real 30-day window
// starting at repair time (the moment this is run is the closest available
// approximation of "genuine activation", since the corrupted row itself
// carries no trustworthy earlier activation timestamp), membershipType
// becomes the canonical 'free', membershipStatus becomes 'REGISTERED'
// (matching what a correct registration-stub-awaiting-activation row now
// looks like) -- or callers can choose to fully activate instead (see
// ACTIVATE_ON_REPAIR below). subscriptionStartDate/subscriptionExpiry are
// cleared, since they must never represent a Free Explorer's trial window.
function repairAllCorruptedFreeExplorerStubs() {
  // Set to true to activate the real 30-day trial immediately as part of
  // repair (matches "the free registration itself activates the trial").
  // Set to false to only strip the fabricated paid-looking data and leave
  // the row as a clean, correctly-labeled registration stub that the
  // person can then activate themselves via "Continue as Free Reader".
  const ACTIVATE_ON_REPAIR = true;

  const subHeaders = subscriptionHeadersRequired();
  const subSheet = getOrCreateSheet('Subscriptions', subHeaders);
  const headers = ensureSheetHeaders(subSheet, subHeaders);
  const values = subSheet.getDataRange().getValues();
  if (values.length <= 1) {
    Logger.log('repairAllCorruptedFreeExplorerStubs: no Subscriptions rows found.');
    return { repaired: [] };
  }

  const MAX_SANE_PAID_MEMBERSHIP_MS = 400 * 24 * 60 * 60 * 1000;
  const now = new Date();
  const trialEnd = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
  const repaired = [];

  for (let r = 1; r < values.length; r++) {
    const row = values[r];
    const sub = {};
    headers.forEach((h, i) => { sub[h] = row[i]; });

    const paymentRequiredRaw = String(sub.paymentRequired || '').trim().toLowerCase();
    const paymentWasRequired = paymentRequiredRaw === 'yes' || paymentRequiredRaw === 'true';
    if (paymentWasRequired) continue; // never touch a genuinely paid application

    const hasGenuineTrial = !!sub.trialStartDate || !!sub.trialEndDate;
    if (hasGenuineTrial) continue; // real trial evidence already exists -- not corrupted, leave alone

    const subStart = sub.subscriptionStartDate ? new Date(sub.subscriptionStartDate) : null;
    const subExpiry = sub.subscriptionExpiry ? new Date(sub.subscriptionExpiry) : null;
    const hasFabricatedWindow = subStart && subExpiry
      && !isNaN(subStart.getTime()) && !isNaN(subExpiry.getTime())
      && (subExpiry.getTime() - subStart.getTime()) > MAX_SANE_PAID_MEMBERSHIP_MS;
    if (!hasFabricatedWindow) continue; // no fake long window -- nothing to repair here

    const sheetRow = r + 1; // 1-indexed sheet row
    headers.forEach((h, i) => {
      const col = i + 1;
      if (h === 'membershipType') subSheet.getRange(sheetRow, col).setValue('free');
      else if (h === 'activationType') subSheet.getRange(sheetRow, col).setValue(ACTIVATE_ON_REPAIR ? 'free_trial' : 'free');
      else if (h === 'membershipStatus') subSheet.getRange(sheetRow, col).setValue(ACTIVATE_ON_REPAIR ? 'TRIAL' : 'REGISTERED');
      else if (h === 'paymentStatus') subSheet.getRange(sheetRow, col).setValue(ACTIVATE_ON_REPAIR ? 'Free Trial' : (sub.paymentStatus || ''));
      else if (h === 'subscriptionStartDate') subSheet.getRange(sheetRow, col).setValue('');
      else if (h === 'subscriptionExpiry') subSheet.getRange(sheetRow, col).setValue('');
      else if (h === 'trialStartDate') subSheet.getRange(sheetRow, col).setValue(ACTIVATE_ON_REPAIR ? now : '');
      else if (h === 'trialEndDate') subSheet.getRange(sheetRow, col).setValue(ACTIVATE_ON_REPAIR ? trialEnd : '');
      else if (h === 'updatedAt') subSheet.getRange(sheetRow, col).setValue(now);
    });

    if (ACTIVATE_ON_REPAIR) {
      ensureUserFromPayload({
        email: sub.email || sub.userEmail,
        membershipStatus: 'TRIAL',
        paymentStatus: 'Free Trial'
      }, { fillMissingOnly: false, syncStatuses: true });
    }

    const emailForLog = normalizeEmail(sub.email || sub.userEmail);
    logActivity(emailForLog, 'Corrupted Free Explorer Stub Repaired', 'id=' + sub.id + '; old subscriptionExpiry=' + subExpiry.toISOString() + '; ' + (ACTIVATE_ON_REPAIR ? 'trial activated at repair time' : 'reset to clean registration stub'), 'Success', 'Auth');
    repaired.push({ id: sub.id, email: emailForLog, oldSubscriptionExpiry: subExpiry.toISOString() });
  }

  Logger.log('repairAllCorruptedFreeExplorerStubs: repaired ' + repaired.length + ' row(s): ' + JSON.stringify(repaired));
  return { repaired: repaired };
}

// =====================================================================
// LISTING APPROVAL
// ---------------------------------------------------------------------
// Every listing used to be created as 'Pending', and the public Library
// only returns 'approved'/'live'. There was no auto-approval, no queue
// alert and no digest — so listings stayed invisible until someone
// happened to open Admin → Books and approve each one by hand. Miss a
// few days and the Library is empty, which is exactly the reported bug.
//
// Listings from members in good standing now go live immediately. The
// admin keeps every existing control: manageBook can still Reject or
// Remove a listing at any time, so this is reactive moderation rather
// than no moderation.
//
// To go back to reviewing every listing before it appears, set the
// Script Property REQUIRE_BOOK_APPROVAL to "true".
// =====================================================================
function requiresManualBookApproval() {
  try {
    const value = PropertiesService.getScriptProperties().getProperty("REQUIRE_BOOK_APPROVAL");
    return String(value || "").toLowerCase() === "true";
  } catch (e) {
    // If the setting can't be read, prefer the state that keeps the
    // Library working; a bad listing can still be removed afterwards.
    return false;
  }
}

function initialBookStatus() {
  return requiresManualBookApproval() ? 'Pending' : 'Approved';
}

function createBook(data) {
  const bookHeaders = getBookHeaders();
  const sheet = getOrCreateSheet('Books', bookHeaders);
  ensureSheetHeaders(sheet, bookHeaders);
  const ownerEmail = normalizeEmail(data.ownerEmail);

  // Server-side membership gate. Previously this action had no membership
  // check at all — only the frontend hid the "List a Book" button from
  // unregistered/expired users, so anyone who could call the API directly
  // could still create listings. isApprovedActiveMember() is the same check
  // already used by createBookRequest/createSwapRequest for consistency.
  if (!isApprovedActiveMember(ownerEmail)) {
    return {
      success: false,
      message: "An active SwapSutra membership (free trial or Chapters) is required to list books.",
      error: "MEMBERSHIP_REQUIRED"
    };
  }

  // Backend validation for the transparent-listing fields — never trust the
  // frontend alone, since a direct API call could otherwise bypass the copy
  // type declaration and the required physical-copy photos entirely.
  const copyType = normalizeCopyType(data.copyType);
  if (!copyType) {
    return {
      success: false,
      message: "Please declare what kind of copy this is (Original / Reprint / Not Sure) before listing.",
      error: "COPY_TYPE_REQUIRED"
    };
  }
  if (!data.copyTypeDeclaration) {
    return {
      success: false,
      message: "Please confirm the copy-type declaration before listing.",
      error: "COPY_TYPE_DECLARATION_REQUIRED"
    };
  }

  // The price. Note what is NOT here: anything from data.mrp. The amount
  // a listing is worth decides how much the OTHER reader has to deposit,
  // so it is resolved from the price sheets and the owner's format/edition
  // choice, never sent by the client. A payload carrying its own mrp is
  // ignored rather than rejected — an old app build should keep working.
  const resolvedListingFormat = normalizeBookFormat(data.bookFormat || data.format) || 'PAPERBACK';
  const resolvedListingEdition = normalizeBookEdition(data.bookEdition || data.edition || copyType) || 'NOT_SURE';

  // The price decision, made by the catalogue in Postgres. It validates the
  // reader's chosen SELL price against a band it computes itself, records
  // the listing, and returns the deposit — which comes from the REFERENCE
  // price, never from what the reader chose.
  //
  // The id is generated here rather than after the row is written, because
  // the pricing record is keyed on it and the two must match.
  // ISBN is required on every new listing (owner's decision, 23 Sep): the
  // shelf shows the publisher's cover fetched by ISBN, and a book without
  // one has nothing to fetch. Checked before pricing so the reader hears
  // about the missing ISBN, not a price-band error that follows from it.
  if (!normalizeIsbnServer(data.isbn)) {
    return {
      success: false,
      message: "ISBN is required. Scan the barcode on the back cover or type the ISBN printed there.",
      error: "ISBN_REQUIRED"
    };
  }
  const id = generateId('SS_BOOK_');
  // Oct 2026: the owner sets their own selling price and monthly rent. The
  // catalogue still values the book (for the deposit and for swaps), but it
  // no longer gets a veto over the price, so the owner's asking price is
  // kept out of its band check.
  const listingFlags = bookStatusFlags(data);
  const ownerSellPrice = ownerPrice_(data.sellPrice);
  const ownerRentPerMonth = ownerPrice_(data.rentPerMonth);
  if (listingFlags.sell && ownerSellPrice === null) {
    return {
      success: false, error: 'SELL_PRICE_REQUIRED',
      message: 'Enter the price you want to sell this book for (₹1 to ₹' + OWNER_PRICE_CEILING.toLocaleString('en-IN') + ').'
    };
  }
  if (listingFlags.rent && ownerRentPerMonth === null) {
    return {
      success: false, error: 'RENT_PRICE_REQUIRED',
      message: 'Enter the rent you want per month for this book (₹1 to ₹' + OWNER_PRICE_CEILING.toLocaleString('en-IN') + ').'
    };
  }
  const pricing = resolveListingPricing(Object.assign({}, data, { sellPrice: null }), id);
  if (!pricing.ok) {
    return {
      success: false,
      message: pricing.message,
      error: pricing.error,
      allowedMin: pricing.allowedMin,
      allowedMax: pricing.allowedMax,
      suggested: pricing.suggested
    };
  }
  // Kept for the Books sheet columns, which the admin panel reads.
  const resolvedListingPrice = {
    amount: pricing.referencePrice || 0,
    tier: pricing.methodology || '',
    basis: pricing.source || ''
  };
  if (data.isbn && !isValidIsbnServer(data.isbn)) {
    return {
      success: false,
      message: "That doesn't look like a valid ISBN. Please scan again or check the number.",
      error: "INVALID_ISBN"
    };
  }
  // ── The four required media ───────────────────────────────────────────
  // Checked as four separate questions, not as a count. `images.length >= 2`
  // was the old rule, and it passed a listing with two front covers and no
  // inside page just as happily as a correct one — the server never knew
  // which slot any file belonged to, because the client sent an unlabelled
  // array and the order was taken on trust.
  const mediaCheck = validateRequiredBookMedia(data);
  if (!mediaCheck.ok) {
    return {
      success: false,
      message: mediaCheck.message,
      error: "REQUIRED_MEDIA_MISSING",
      missing: mediaCheck.missing
    };
  }
  const submittedImages = mediaCheck.imagesForLegacyArray;

  const listingPartner = approvedPartner_(ownerEmail);
  const currentCount = recalculateBooksListedCount(ownerEmail);
  // 20 books free; a one-time ₹20 payment or a coupon lifts the limit for
  // good. See getListingAllowanceFor_ in the platform-fee section.
  const allowance = getListingAllowanceFor_(ownerEmail, currentCount);
  if (!allowance.canList) {
    return {
      success: false,
      message: listingLimitMessage_(allowance),
      error: "LISTING_LIMIT_REACHED",
      allowance: allowance
    };
  }

  // Update firstBookListedAt in Subscriptions if not set
  const subSheet = getOrCreateSheet('Subscriptions', []);
  const subData = subSheet.getDataRange().getValues();
  if (subData.length > 1) {
    const subHeaders = subData[0];
    const subEmailIdx = subHeaders.indexOf('email');
    const firstListedIdx = subHeaders.indexOf('firstBookListedAt');
    const subRowIdx = subData.findIndex(r => normalizeEmail(r[subEmailIdx]) === ownerEmail);
    if (subRowIdx !== -1 && firstListedIdx !== -1) {
      if (!subData[subRowIdx][firstListedIdx]) {
        subSheet.getRange(subRowIdx + 1, firstListedIdx + 1).setValue(new Date());
      }
    }
  }

  // `id` is declared earlier, beside the pricing call: the pricing record
  // is keyed on it, so it has to exist before the price is resolved rather
  // than after the row is built.
  // The four required media go up as four known slots, so the row can
  // record which file is which. The joined imageUrls string is derived
  // from the same uploads afterwards, for the screens that still read it.
  const mediaUpload = uploadRequiredBookMedia(id, mediaCheck.accepted);
  const uploadResult = {
    folderId: mediaUpload.folderId,
    imageUrls: REQUIRED_BOOK_MEDIA
      .filter(function (spec) { return spec.kind === 'image'; })
      .map(function (spec) { return mediaUpload.urls[spec.field] || ''; })
      .filter(function (u) { return u; })
      .join('|')
  };

  // The reader's own declaration about the copy, and the printed MRP they
  // typed.
  //
  // TEMPORARY PRICING PHASE: the automated/catalogue estimate has been
  // found inaccurate and was blocking real transactions with a wrong
  // security fee. Until it is fixed and re-verified, this user-entered
  // MRP is the AUTHORITATIVE pricing input server-side (see
  // effectiveBookMRP / computeMutualDeposit), so it is validated here with
  // the same rigor as any other money figure — required for any listing
  // that needs a price, numeric, positive, and under a sanity ceiling.
  // validateUserEnteredMRP() is the one place that rule lives; never trust
  // whatever normalization the client already did.
  const declaredAuthenticity = normalizeAuthenticity(
    data.authenticityStatus || (resolvedListingEdition === 'UNOFFICIAL' ? 'UNAUTHORISED' : ''));

  const noUserMrp = Boolean(data.noPrintedMrp || data.noUserMrp);
  const rawUserMrp = data.userEnteredMRP !== undefined ? data.userEnteredMRP
    : (data.printedMrp !== undefined ? data.printedMrp : data.mrp);
  const earlyAvailabilityFlags = bookAvailabilityFlags(data);
  const needsPricing = declaredAuthenticity !== 'UNAUTHORISED'
    && (earlyAvailabilityFlags.permanent_exchange || earlyAvailabilityFlags.temporary_exchange
        || earlyAvailabilityFlags.rent || earlyAvailabilityFlags.lend || earlyAvailabilityFlags.sell);
  const rawUserMrpProvided = rawUserMrp !== undefined && rawUserMrp !== null && String(rawUserMrp).trim() !== '';

  let claimedPrintedMrp = null;
  if (rawUserMrpProvided) {
    // A value was typed, so it is validated regardless of the "I don't
    // have the MRP" checkbox — a stray box left checked cannot make an
    // otherwise-invalid number pass.
    const mrpCheck = validateUserEnteredMRP(rawUserMrp);
    if (!mrpCheck.valid) {
      return { success: false, message: mrpCheck.message, error: mrpCheck.error };
    }
    claimedPrintedMrp = mrpCheck.value;
  } else if (needsPricing && !noUserMrp) {
    // Nothing typed, and the reader did not honestly say they have no MRP
    // to give us: required, not silently optional, for any listing whose
    // transaction types need a price at all.
    return {
      success: false,
      message: "Please enter the MRP printed on your book, or tick \"I don't have the MRP\" if you can't find it.",
      error: "USER_ENTERED_MRP_REQUIRED"
    };
  }
  // `noUserMrp` with nothing typed reaches here with claimedPrintedMrp
  // still null — an honest "unknown", not a fabricated number. Every
  // caller downstream (effectiveBookMRP, RENT eligibility, the deposit
  // resolvers) already treats null as "unresolved" and blocks accordingly,
  // exactly the same path an old pre-this-feature listing takes.
  const printedMrpTier = claimedPrintedMrp === null ? '' : 'USER_PROVISIONAL';
  const printedMrpStatus = claimedPrintedMrp === null ? 'UNRESOLVED' : 'PROVISIONAL';

  ensureSheetHeaders(sheet, ['ownerSellPrice', 'ownerRentPerMonth']);
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
  const row = new Array(headers.length).fill("");
  // 'Approved' unless the site owner has turned manual review back on —
  // see requiresManualBookApproval(). The membership, copy-type, ISBN and
  // photo checks above have all already passed at this point.
  const bookStatus = initialBookStatus();
  const flags = bookStatusFlags(data);
  const swapType = flags.permanent_exchange ? "Permanent" : (flags.temporary_exchange ? "Temporary" : "");
  headers.forEach((h, i) => {
    if (h === 'id') row[i] = id;
    else if (h === 'ownerEmail') row[i] = ownerEmail;
    else if (h === 'title') row[i] = data.title;
    else if (h === 'author') row[i] = data.author;
    else if (h === 'condition') row[i] = data.condition;
    else if (h === 'genre') row[i] = normalizeBookGenre(data.genre);
    else if (h === 'area') row[i] = data.area;
    else if (h === 'pincode') row[i] = data.pincode;
    else if (h === 'favourite') row[i] = flags.favourite ? "TRUE" : "FALSE";
    else if (h === 'currently_reading') row[i] = flags.currently_reading ? "TRUE" : "FALSE";
    else if (h === 'tbr') row[i] = flags.tbr ? "TRUE" : "FALSE";
    else if (h === 'bookshelf') row[i] = flags.bookshelf ? "TRUE" : "FALSE";
    else if (h === 'swapType') row[i] = data.swapType || swapType;
    else if (h === 'permanent_exchange') row[i] = flags.permanent_exchange ? "TRUE" : "FALSE";
    else if (h === 'temporary_exchange') row[i] = flags.temporary_exchange ? "TRUE" : "FALSE";
    else if (h === 'rent') row[i] = flags.rent ? "TRUE" : "FALSE";
    // Lend is written from its own input. It is not derived from
    // temporary_exchange, and ticking Rent does not set it.
    else if (h === 'lend') row[i] = flags.lend ? "TRUE" : "FALSE";
    else if (h === 'sell') row[i] = flags.sell ? "TRUE" : "FALSE";
    else if (h === 'available_for_swap') row[i] = flags.available_for_swap ? "TRUE" : "FALSE";
    else if (h === 'rent_sale_mode') row[i] = flags.rent_sale_mode;
    else if (h === 'imageUrls') row[i] = uploadResult.imageUrls;
    else if (h === 'driveFolderId') row[i] = uploadResult.folderId;
    else if (h === 'notes') row[i] = data.notes;
    // A partner (bookstore, publisher…) keeps a stock count; readers have one copy.
    else if (h === 'stock') row[i] = listingPartner ? Math.max(1, Math.min(9999, Math.floor(Number(data.stock) || 1))) : '';
    else if (h === 'sellerType') row[i] = listingPartner ? listingPartner.type : '';
    else if (h === 'sellerName') row[i] = listingPartner ? listingPartner.name : '';
    // SwapSutra's resolved listing value. An unresolved price is written
    // as an empty cell, never as 0 — a blank reads as "not known" to every
    // parser here, and 0 reads as "this book is worth nothing".
    else if (h === 'mrp') row[i] = (resolvedListingPrice.amount === null
      || resolvedListingPrice.amount === undefined) ? '' : resolvedListingPrice.amount;
    // The printed MRP is a separate fact from the line above.
    else if (h === 'printedMrp') row[i] = claimedPrintedMrp === null ? '' : claimedPrintedMrp;
    else if (h === 'printedMrpEvidenceTier') row[i] = printedMrpTier;
    else if (h === 'printedMrpVerificationStatus') row[i] = printedMrpStatus;
    // ── Temporary pricing-phase columns ──────────────────────────────
    // userEnteredMRP mirrors printedMrp above (same validated claim, same
    // column meaning) under the name the pricing engine now reads first.
    // automatedMRP is whatever the automated/catalogue engine computed for
    // this listing (resolvedListingPrice, above) — kept and still written,
    // just no longer authoritative. effectiveMRP/pricingSource are the
    // engine's own decision, computed once here and read verbatim by every
    // caller from now on rather than re-derived from a live read of the
    // other two, so a swap created against this listing today is provably
    // pinned to the number the owner actually saw.
    else if (h === 'userEnteredMRP') row[i] = claimedPrintedMrp === null ? '' : claimedPrintedMrp;
    else if (h === 'automatedMRP') row[i] = (resolvedListingPrice.amount === null
      || resolvedListingPrice.amount === undefined || resolvedListingPrice.amount <= 0) ? '' : resolvedListingPrice.amount;
    else if (h === 'effectiveMRP') row[i] = claimedPrintedMrp !== null ? claimedPrintedMrp
      : ((resolvedListingPrice.amount === null || resolvedListingPrice.amount === undefined
          || resolvedListingPrice.amount <= 0) ? '' : resolvedListingPrice.amount);
    else if (h === 'pricingSource') row[i] = claimedPrintedMrp !== null ? 'USER'
      : ((resolvedListingPrice.amount > 0) ? 'AUTOMATED_UNVERIFIED' : '');
    else if (h === 'authenticityStatus') row[i] = declaredAuthenticity;
    else if (h === 'frontCoverImage') row[i] = mediaUpload.urls.frontCoverImage || '';
    else if (h === 'internalBookImage') row[i] = mediaUpload.urls.internalBookImage || '';
    else if (h === 'internalBookVideo') row[i] = mediaUpload.urls.internalBookVideo || '';
    else if (h === 'backCoverImage') row[i] = mediaUpload.urls.backCoverImage || '';
    else if (h === 'bookFormat') row[i] = resolvedListingFormat;
    else if (h === 'ownerSellPrice') row[i] = listingFlags.sell && ownerSellPrice !== null ? ownerSellPrice : '';
    else if (h === 'ownerRentPerMonth') row[i] = listingFlags.rent && ownerRentPerMonth !== null ? ownerRentPerMonth : '';
    else if (h === 'bookEdition') row[i] = resolvedListingEdition;
    else if (h === 'priceTier') row[i] = resolvedListingPrice.tier;
    else if (h === 'priceBasis') row[i] = resolvedListingPrice.basis;
    else if (h === 'audioUrl') row[i] = data.audioUrl || '';
    else if (h === 'videoUrl') row[i] = data.videoUrl || '';
    else if (h === 'latitude') row[i] = data.latitude || '';
    else if (h === 'longitude') row[i] = data.longitude || '';
    else if (h === 'listedAt') row[i] = new Date();
    else if (h === 'status') row[i] = bookStatus;
    else if (h === 'approvedAt') row[i] = bookStatus === 'Approved' ? new Date() : '';
    else if (h === 'createdAt') row[i] = new Date();
    else if (h === 'isbn') row[i] = normalizeIsbnServer(data.isbn);
    else if (h === 'publisher') row[i] = data.publisher || '';
    else if (h === 'copyType') row[i] = copyType;
    else if (h === 'copyTypeDeclaration') row[i] = data.copyTypeDeclaration ? 'TRUE' : 'FALSE';
    else if (h === 'referenceCoverUrl') row[i] = data.referenceCoverUrl || '';
    else if (h === 'conditionNotes') row[i] = data.conditionNotes || '';
  });

  sheet.appendRow(row);
  // Listing funnel (24 Sep): completions, and how many went live with the
  // front cover only — so the front-cover-only change can be judged.
  recordListingCreated_(listingPhotoGaps_({
    frontCoverImage: mediaUpload.urls.frontCoverImage || '',
    backCoverImage: mediaUpload.urls.backCoverImage || '',
    internalBookImage: mediaUpload.urls.internalBookImage || '',
    internalBookVideo: mediaUpload.urls.internalBookVideo || ''
  }).length > 0);
  recalculateBooksListedCount(ownerEmail);

  // A referral becomes worth paying for at the moment the invited reader
  // puts a book on the shelf, not at the moment they sign up — see
  // maybeQualifyReferral(). Idempotent, so every later listing is a
  // no-op, and it can never fail the listing itself.
  try { maybeQualifyReferral(ownerEmail); } catch (referralErr) { Logger.log('Referral qualification skipped: ' + referralErr.toString()); }

  // Tell the readers who have been waiting for this exact title. Only
  // for a listing that is actually visible — alerting someone about a
  // book still in the approval queue sends them to an empty Library.
  // Best-effort and time-budgeted; a listing never fails on this.
  if (bookStatus === 'Approved') {
    try {
      notifyTbrMatches({
        id: id,
        title: data.title,
        author: data.author,
        ownerEmail: ownerEmail,
        pincode: data.pincode,
        area: data.area
      });
    } catch (tbrErr) {
      Logger.log('TBR match alerts skipped: ' + tbrErr.toString());
    }
  }

  // Log in Reading Journey
  logReaderActivity(
    ownerEmail,
    "book_listed",
    id,
    data.title || "Book",
    `Listed "${data.title || "Book"}"`,
    `Offered your copy${data.author ? " by " + data.author : ""} to fellow book lovers in the SwapSutra community library.`,
    { title: data.title, author: data.author, bookId: id }
  );

  return {
    success: true,
    id: id,
    status: bookStatus,
    message: bookStatus === 'Approved'
      ? "Your book is live in the Library."
      : "Book submitted for approval."
  };
}

function updateUserBook(data) {
  try {
    const userEmail = normalizeEmail(data.userEmail || data.ownerEmail || data.email);
    const bookId = String(data.bookId || data.id || '').trim();
    if (!userEmail) return { success: false, message: "User email required.", error: "MISSING_USER_EMAIL" };
    if (!bookId) return { success: false, message: "Book id required.", error: "MISSING_BOOK_ID" };

    const bookHeaders = getBookHeaders();
    const sheet = getOrCreateSheet('Books', bookHeaders);
    ensureSheetHeaders(sheet, bookHeaders);
    const values = sheet.getDataRange().getValues();
    if (values.length <= 1) return { success: false, message: "Book not found.", error: "BOOK_NOT_FOUND" };

    const headers = values[0].map(h => String(h).trim());
    const idIdx = headers.indexOf('id');
    const ownerIdx = headers.indexOf('ownerEmail');
    const rowIndex = values.findIndex((row, idx) => idx > 0 && String(row[idIdx]) === bookId);
    if (rowIndex === -1) return { success: false, message: "Book not found.", error: "BOOK_NOT_FOUND" };
    if (ownerIdx === -1 || normalizeEmail(values[rowIndex][ownerIdx]) !== userEmail) {
      return { success: false, message: "You can only update your own books.", error: "UNAUTHORIZED" };
    }

    // "Finish your listing": the owner adds the back cover and/or an inside
    // photo/video to a listing that went live with only its front cover.
    // Photos only — nothing else on the row is touched, and the book stays
    // live (an ordinary edit sends it back for review; adding the photos
    // readers were promised should not hide the book while it happens).
    if (data.finishListingPhotos) {
      return finishListingPhotos_(sheet, headers, values[rowIndex], rowIndex, bookId, data);
    }

    // Transparent-listing fields (ISBN Scanner). All optional on an edit —
    // a legacy listing that has never had a copyType/isbn is left alone
    // unless the reader actively sets one here, so old listings never get
    // newly blocked from ordinary edits (title, area, etc.). Once a value
    // IS actively provided, though, it's held to the same validation as a
    // brand-new listing so the requirement can't be bypassed by editing
    // around it.
    let copyType;
    if (data.copyType !== undefined && String(data.copyType).trim() !== '') {
      copyType = normalizeCopyType(data.copyType);
      if (!copyType) {
        return { success: false, message: "Please select a valid copy type (Original / Reprint / Not Sure).", error: "INVALID_COPY_TYPE" };
      }
      if (!data.copyTypeDeclaration) {
        return { success: false, message: "Please confirm the copy-type declaration before saving.", error: "COPY_TYPE_DECLARATION_REQUIRED" };
      }
    }
    if (data.isbn && !isValidIsbnServer(data.isbn)) {
      return { success: false, message: "That doesn't look like a valid ISBN. Please scan again or check the number.", error: "INVALID_ISBN" };
    }

    // Physical photos: left completely untouched unless the reader
    // explicitly submits a replacement set (edit UI's "Replace photos"
    // toggle) — an ordinary text-only edit never disturbs existing photos.
    // The API reference cover can never substitute for these, same as on
    // create.
    // A replacement is all four or none. An owner who sends nothing keeps
    // the media they already have — which is what lets every listing made
    // before these four requirements existed stay editable.
    const replacingMedia = REQUIRED_BOOK_MEDIA.some(function (spec) { return data && data[spec.payload]; });

    let uploadResult = null;
    let mediaUrls = null;
    if (replacingMedia) {
      const mediaCheck = validateRequiredBookMedia(data);
      if (!mediaCheck.ok) {
        return { success: false, message: mediaCheck.message,
                 error: "REQUIRED_MEDIA_MISSING", missing: mediaCheck.missing };
      }
      const upload = uploadRequiredBookMedia(bookId, mediaCheck.accepted);
      mediaUrls = upload.urls;
      uploadResult = {
        folderId: upload.folderId,
        imageUrls: REQUIRED_BOOK_MEDIA
          .filter(function (spec) { return spec.kind === 'image'; })
          .map(function (spec) { return upload.urls[spec.field] || ''; })
          .filter(function (u) { return u; })
          .join('|')
      };
    }

    const flags = bookStatusFlags(data);
    const nextSwapType = data.swapType || (flags.permanent_exchange ? "Permanent" : (flags.temporary_exchange ? "Temporary" : ""));
    const updatePayload = Object.assign({}, data, {
      swapType: nextSwapType,
      genre: normalizeBookGenre(data.genre),
      favourite: flags.favourite ? "TRUE" : "FALSE",
      currently_reading: flags.currently_reading ? "TRUE" : "FALSE",
      tbr: flags.tbr ? "TRUE" : "FALSE",
      bookshelf: flags.bookshelf ? "TRUE" : "FALSE",
      permanent_exchange: flags.permanent_exchange ? "TRUE" : "FALSE",
      temporary_exchange: flags.temporary_exchange ? "TRUE" : "FALSE",
      rent: flags.rent ? "TRUE" : "FALSE",
      sell: flags.sell ? "TRUE" : "FALSE",
      available_for_swap: flags.available_for_swap ? "TRUE" : "FALSE",
      rent_sale_mode: flags.rent_sale_mode
    });
    if (data.isbn !== undefined) updatePayload.isbn = normalizeIsbnServer(data.isbn);
    if (data.publisher !== undefined) updatePayload.publisher = data.publisher || '';
    if (data.conditionNotes !== undefined) updatePayload.conditionNotes = data.conditionNotes || '';
    if (copyType) {
      updatePayload.copyType = copyType;
      updatePayload.copyTypeDeclaration = data.copyTypeDeclaration ? 'TRUE' : 'FALSE';
    }
    if (data.referenceCoverUrl) {
      updatePayload.referenceCoverUrl = data.referenceCoverUrl;
    }
    const allowedFields = ['title', 'author', 'condition', 'genre', 'area', 'pincode', 'favourite', 'currently_reading', 'tbr', 'bookshelf', 'swapType', 'permanent_exchange', 'temporary_exchange', 'rent', 'sell', 'available_for_swap', 'rent_sale_mode', 'notes', 'audioUrl', 'videoUrl', 'latitude', 'longitude', 'isbn', 'publisher', 'conditionNotes', 'copyType', 'copyTypeDeclaration', 'referenceCoverUrl',
    // 'mrp' is deliberately ABSENT. It was editable here, which meant an
    // owner could list a book at the sheet's price and then edit the
    // amount afterwards — reopening exactly the hole that server-side
    // pricing closes. Changing format or edition re-resolves it below.
    // 'lend' is editable and 'rent' is editable, separately. Neither one
    // is derived from the other here or anywhere else.
    'bookFormat', 'bookEdition', 'lend', 'authenticityStatus'];
    allowedFields.forEach(field => {
      const colIdx = headers.indexOf(field);
      if (colIdx !== -1 && updatePayload[field] !== undefined) {
        sheet.getRange(rowIndex + 1, colIdx + 1).setValue(updatePayload[field]);
      }
    });

    // Oct 2026: the owner's prices are theirs to change, but only to a
    // real whole-rupee amount. A sent value that isn't one is refused
    // rather than silently stored as blank.
    [['sellPrice', 'ownerSellPrice', 'selling price'], ['rentPerMonth', 'ownerRentPerMonth', 'monthly rent']].forEach(function (pair) {
      if (data[pair[0]] === undefined) return;
      const colIdx = headers.indexOf(pair[1]);
      if (colIdx === -1) return;
      if (data[pair[0]] === '' || data[pair[0]] === null) {
        sheet.getRange(rowIndex + 1, colIdx + 1).setValue('');
        return;
      }
      const v = ownerPrice_(data[pair[0]]);
      if (v !== null) sheet.getRange(rowIndex + 1, colIdx + 1).setValue(v);
    });

    // The four media columns, written only when the owner actually
    // replaced them. Each is written to its own column, so replacing the
    // video cannot disturb the back cover.
    if (mediaUrls) {
      // A replacement is a new set: a slot not chosen again is cleared, so
      // the four columns always agree with the imageUrls string written
      // below (and an owner who replaces with a front cover only is asked
      // to finish the listing again, honestly).
      REQUIRED_BOOK_MEDIA.forEach(function (spec) {
        const idx = headers.indexOf(spec.field);
        if (idx !== -1) {
          sheet.getRange(rowIndex + 1, idx + 1).setValue(mediaUrls[spec.field] || '');
        }
      });
    }

    // A printed MRP typed on an edit is validated exactly like one typed
    // at listing time — see validateUserEnteredMRP — and, once accepted,
    // becomes this book's effectiveMRP going forward. This is the
    // deliberately minimal "edit book" path for correcting an existing
    // listing's MRP: it touches only the pricing fields, nothing else
    // about the listing.
    //
    // What it does NOT do: touch any already-created SwapRequest. A swap
    // accepted before this correction keeps the securityDeposit/
    // ownerDeposit computeMutualDeposit fixed for it at creation time —
    // this block only ever writes to the Books sheet.
    const rawMrpEdit = data.userEnteredMRP !== undefined ? data.userEnteredMRP : data.printedMrp;
    if (rawMrpEdit !== undefined) {
      const setCell = function (name, value) {
        const i = headers.indexOf(name);
        if (i !== -1) sheet.getRange(rowIndex + 1, i + 1).setValue(value);
      };
      // A blank submission clears nothing — an owner deleting the box
      // should not silently erase a verified MRP somebody else confirmed.
      if (String(rawMrpEdit).trim() !== '') {
        const mrpCheck = validateUserEnteredMRP(rawMrpEdit);
        if (!mrpCheck.valid) {
          return { success: false, message: mrpCheck.message, error: mrpCheck.error };
        }
        const claimed = mrpCheck.value;
        const existingTier = String(readBookCell(sheet, headers, rowIndex, 'printedMrpEvidenceTier') || '');
        if (MRP_ANCHORING_TIERS.indexOf(existingTier) === -1) {
          setCell('printedMrp', claimed);
          setCell('printedMrpEvidenceTier', 'USER_PROVISIONAL');
          setCell('printedMrpVerificationStatus', 'PROVISIONAL');
          setCell('userEnteredMRP', claimed);
          setCell('effectiveMRP', claimed);
          setCell('pricingSource', 'USER');
        }
      }
    }

    // Price follows the book, so it is recomputed from whatever the row
    // now says rather than from the payload. Editing an edition down from
    // hardcover to budget reprint must move the deposit down with it, and
    // an owner must not be able to hold a high price while changing the
    // thing that justified it.
    (function reprice() {
      const readCell = (name) => {
        const i = headers.indexOf(name);
        return i === -1 ? '' : sheet.getRange(rowIndex + 1, i + 1).getValue();
      };
      const quote = resolveBookPrice({
        isbn: readCell('isbn'),
        genre: readCell('genre'),
        format: normalizeBookFormat(readCell('bookFormat')) || 'PAPERBACK',
        edition: normalizeBookEdition(readCell('bookEdition') || readCell('copyType')) || 'NOT_SURE'
      });
      const write = (name, value) => {
        const i = headers.indexOf(name);
        if (i !== -1) sheet.getRange(rowIndex + 1, i + 1).setValue(value);
      };
      // Only write a resolved amount. An unresolved re-price used to
      // overwrite a perfectly good stored value with 0 whenever an owner
      // edited genre or format into a combination the price sheets did not
      // cover — the listing silently became "Rs. 0" on an unrelated edit.
      if (quote.amount !== null && quote.amount !== undefined) {
        write('mrp', quote.amount);
        write('priceTier', quote.tier);
        write('priceBasis', quote.basis);
        write('automatedMRP', quote.amount);
        // effectiveMRP only follows the automated re-price when this book
        // has no userEnteredMRP of its own — a book the owner has already
        // priced keeps their number no matter what an edition/genre edit
        // does to the automated estimate underneath it.
        const existingUserMrp = parsePrintedMrp(readCell('userEnteredMRP') || readCell('printedMrp'));
        if (existingUserMrp === null) {
          write('effectiveMRP', quote.amount);
          write('pricingSource', 'AUTOMATED_UNVERIFIED');
        }
      }
    })();

    if (uploadResult) {
      const imageUrlsIdx = headers.indexOf('imageUrls');
      if (imageUrlsIdx !== -1) sheet.getRange(rowIndex + 1, imageUrlsIdx + 1).setValue(uploadResult.imageUrls);
      const driveFolderIdx = headers.indexOf('driveFolderId');
      if (driveFolderIdx !== -1) sheet.getRange(rowIndex + 1, driveFolderIdx + 1).setValue(uploadResult.folderId);
    }

    const statusIdx = headers.indexOf('status');
    if (statusIdx !== -1) sheet.getRange(rowIndex + 1, statusIdx + 1).setValue('Pending');
    const updatedAtIdx = headers.indexOf('updatedAt');
    if (updatedAtIdx !== -1) sheet.getRange(rowIndex + 1, updatedAtIdx + 1).setValue(new Date());
    const approvedAtIdx = headers.indexOf('approvedAt');
    if (approvedAtIdx !== -1) sheet.getRange(rowIndex + 1, approvedAtIdx + 1).setValue('');
    const rejectedAtIdx = headers.indexOf('rejectedAt');
    if (rejectedAtIdx !== -1) sheet.getRange(rowIndex + 1, rejectedAtIdx + 1).setValue('');
    const rejectionReasonIdx = headers.indexOf('rejectionReason');
    if (rejectionReasonIdx !== -1) sheet.getRange(rowIndex + 1, rejectionReasonIdx + 1).setValue('');

    recalculateBooksListedCount(userEmail);
    return {
      success: true,
      message: "Book updated and sent for review.",
      data: { id: bookId, status: "Pending" }
    };
  } catch (e) {
    Logger.log("updateUserBook error: " + e.toString());
    return { success: false, message: "Unable to update book.", error: e.toString() };
  }
}

function removeUserBook(data) {
  try {
    const userEmail = normalizeEmail(data.userEmail || data.ownerEmail || data.email);
    const bookId = String(data.bookId || data.id || '').trim();
    if (!userEmail) return { success: false, message: "User email required.", error: "MISSING_USER_EMAIL" };
    if (!bookId) return { success: false, message: "Book id required.", error: "MISSING_BOOK_ID" };

    const sheet = getOrCreateSheet('Books', []);
    const values = sheet.getDataRange().getValues();
    if (values.length <= 1) return { success: false, message: "Book not found.", error: "BOOK_NOT_FOUND" };

    const headers = values[0].map(h => String(h).trim());
    const idIdx = headers.indexOf('id');
    const ownerIdx = headers.indexOf('ownerEmail');
    const rowIndex = values.findIndex((row, idx) => idx > 0 && String(row[idIdx]) === bookId);
    if (rowIndex === -1) return { success: false, message: "Book not found.", error: "BOOK_NOT_FOUND" };
    if (ownerIdx === -1 || normalizeEmail(values[rowIndex][ownerIdx]) !== userEmail) {
      return { success: false, message: "You can only remove your own books.", error: "UNAUTHORIZED" };
    }

    const statusIdx = headers.indexOf('status');
    if (statusIdx !== -1) sheet.getRange(rowIndex + 1, statusIdx + 1).setValue('Removed');
    const updatedAtIdx = headers.indexOf('updatedAt');
    if (updatedAtIdx !== -1) sheet.getRange(rowIndex + 1, updatedAtIdx + 1).setValue(new Date());
    const hiddenReasonIdx = headers.indexOf('hiddenReason');
    if (hiddenReasonIdx !== -1) sheet.getRange(rowIndex + 1, hiddenReasonIdx + 1).setValue('Removed by owner');

    recalculateBooksListedCount(userEmail);
    return {
      success: true,
      message: "Book removed from the Library.",
      data: { id: bookId, status: "Removed" }
    };
  } catch (e) {
    Logger.log("removeUserBook error: " + e.toString());
    return { success: false, message: "Unable to remove book.", error: e.toString() };
  }
}

function createBookRequest(data) {
  try {
    const userEmail = normalizeEmail(data.userEmail || data.email);
    const title = String(data.title || '').trim();
    if (!userEmail) return { success: false, message: "Please sign in before requesting a book.", error: "MISSING_USER_EMAIL" };
    const accessError = requireApprovedMember(userEmail, 'Requesting a book');
    if (accessError) return accessError;
    if (!title) return { success: false, message: "Book title is required.", error: "MISSING_TITLE" };

    const headers = ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"];
    const sheet = getOrCreateSheet('BookRequests', headers);
    const currentHeaders = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0].map(h => String(h).trim());
    const requestId = generateId('SS_REQ_BOOK_');
    const row = new Array(currentHeaders.length).fill("");
    currentHeaders.forEach((h, i) => {
      if (h === 'requestId') row[i] = requestId;
      else if (h === 'userEmail') row[i] = userEmail;
      else if (h === 'title') row[i] = title;
      else if (h === 'author') row[i] = data.author || '';
      else if (h === 'city') row[i] = data.city || data.area || '';
      else if (h === 'requestType') row[i] = data.requestType || 'Any';
      else if (h === 'note') row[i] = data.note || '';
      else if (h === 'status') row[i] = 'Open';
      else if (h === 'createdAt') row[i] = new Date();
      else if (h === 'updatedAt') row[i] = new Date();
    });
    sheet.appendRow(row);

    // Real activity signal backing the "Generous Heart" achievement --
    // logged only when a genuine book request was actually created above.
    try {
      logReaderActivity(
        userEmail,
        "book_requested",
        requestId,
        title,
        `Requested "${title}"`,
        `Asked the community for "${title}"${data.author ? " by " + data.author : ""}.`,
        { requestId: requestId, title: title, author: data.author }
      );
    } catch (e) {
      Logger.log("createBookRequest activity log error: " + e.toString());
    }

    return { success: true, message: "Book request submitted.", data: { requestId, status: "Open" } };
  } catch (e) {
    Logger.log("createBookRequest error: " + e.toString());
    return { success: false, message: "Unable to create book request.", error: e.toString() };
  }
}

function updateBookRequestStatus(data) {
  try {
    const requestId = String(data.requestId || data.id || '').trim();
    const status = String(data.status || '').trim();
    const userEmail = normalizeEmail(data.userEmail || data.email || data.adminEmail);
    const allowed = ['Open', 'Responded', 'In Discussion', 'Fulfilled', 'Closed', 'Cancelled'];
    if (!requestId) return { success: false, message: "Request ID required.", error: "MISSING_REQUEST_ID" };
    if (!allowed.includes(status)) return { success: false, message: "Invalid status.", error: "INVALID_STATUS" };

    const sheet = getOrCreateSheet('BookRequests', ["requestId", "userEmail", "title", "author", "city", "requestType", "note", "status", "createdAt", "updatedAt"]);
    const values = sheet.getDataRange().getValues();
    if (values.length <= 1) return { success: false, message: "Book request not found.", error: "NOT_FOUND" };
    const headers = values[0].map(h => String(h).trim());
    const idIdx = headers.indexOf('requestId');
    const ownerEmailIdx = headers.indexOf('userEmail');
    const statusIdx = headers.indexOf('status');
    const updatedAtIdx = headers.indexOf('updatedAt');
    const rowIndex = values.findIndex((row, idx) => idx > 0 && String(row[idIdx]) === requestId);
    if (rowIndex === -1) return { success: false, message: "Book request not found.", error: "NOT_FOUND" };

    const ownerEmail = normalizeEmail(values[rowIndex][ownerEmailIdx]);
    if (ownerEmail !== userEmail && !isAdminEmail(userEmail)) {
      return { success: false, message: "Unauthorized", error: "UNAUTHORIZED" };
    }

    if (statusIdx !== -1) sheet.getRange(rowIndex + 1, statusIdx + 1).setValue(status);
    if (updatedAtIdx !== -1) sheet.getRange(rowIndex + 1, updatedAtIdx + 1).setValue(new Date());
    return { success: true, message: "Book request status updated.", data: { requestId, status } };
  } catch (e) {
    Logger.log("updateBookRequestStatus error: " + e.toString());
    return { success: false, message: "Unable to update book request.", error: e.toString() };
  }
}

function handleCreateNotificationApi(data) {
  try {
    const userEmail = normalizeEmail(data.userEmail || data.recipientEmail || data.email);
    if (!userEmail) return { success: false, message: "userEmail required" };
    const type = data.type || 'general';
    const title = data.title || 'Notification';
    const message = data.message || '';
    const relatedId = data.entityId || data.relatedId || '';
    const options = {
      link: data.targetUrl || data.link || '',
      dedupeKey: data.dedupeKey || ''
    };
    const id = createNotification(userEmail, type, title, message, relatedId, options);
    if (id) {
      return { success: true, id, message: "Notification created." };
    } else {
      return { success: false, message: "Failed to create notification." };
    }
  } catch (e) {
    return { success: false, message: "Unable to create notification.", error: e.toString() };
  }
}

function markNotificationRead(data) {
  try {
    const id = String(data.id || data.notificationId || '').trim();
    const email = normalizeEmail(data.userEmail || data.email);
    if (!id) return { success: false, message: "Notification id required.", error: "MISSING_NOTIFICATION_ID" };
    if (!email) return { success: false, message: "Email required.", error: "MISSING_EMAIL" };

    const sheet = getOrCreateSheet('Notifications', ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt']);
    const headers = ensureSheetHeaders(sheet, ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt']);
    const values = sheet.getDataRange().getValues();
    const idIdx = headers.indexOf('id');
    const emailIdx = headers.indexOf('userEmail');
    const readIdx = headers.indexOf('isRead');
    const readAtIdx = headers.indexOf('readAt');
    const rowIndex = values.findIndex((row, idx) => idx > 0 && String(row[idIdx]) === id);
    if (rowIndex === -1) return { success: false, message: "Notification not found.", error: "NOT_FOUND" };
    const ownerEmail = normalizeEmail(values[rowIndex][emailIdx]);
    if (ownerEmail !== email && !isAdminEmail(email)) return { success: false, message: "Unauthorized", error: "UNAUTHORIZED" };
    if (readIdx !== -1) sheet.getRange(rowIndex + 1, readIdx + 1).setValue('Yes');
    if (readAtIdx !== -1) sheet.getRange(rowIndex + 1, readAtIdx + 1).setValue(new Date());
    return { success: true, data: { id, isRead: 'Yes' } };
  } catch (e) {
    Logger.log("markNotificationRead error: " + e.toString());
    return { success: false, message: "Unable to mark notification read.", error: e.toString() };
  }
}

function markNotificationsReadBulk(data) {
  try {
    const email = normalizeEmail(data.userEmail || data.email);
    const ids = Array.isArray(data.ids) ? data.ids.map(id => String(id || '').trim()).filter(Boolean) : [];
    if (!email) return { success: false, message: "Email required.", error: "MISSING_EMAIL" };
    if (ids.length === 0) return { success: true, data: { updated: 0 } };

    const sheet = getOrCreateSheet('Notifications', ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt']);
    const headers = ensureSheetHeaders(sheet, ['id', 'userEmail', 'type', 'title', 'message', 'isRead', 'relatedId', 'createdAt', 'readAt']);
    const values = sheet.getDataRange().getValues();
    const idIdx = headers.indexOf('id');
    const emailIdx = headers.indexOf('userEmail');
    const readIdx = headers.indexOf('isRead');
    const readAtIdx = headers.indexOf('readAt');
    const idSet = {};
    ids.forEach(id => idSet[id] = true);
    let updated = 0;
    values.forEach((row, idx) => {
      if (idx === 0 || !idSet[String(row[idIdx])]) return;
      const ownerEmail = normalizeEmail(row[emailIdx]);
      if (ownerEmail !== email && !isAdminEmail(email)) return;
      if (readIdx !== -1 && String(row[readIdx] || '').trim().toLowerCase() !== 'yes') {
        sheet.getRange(idx + 1, readIdx + 1).setValue('Yes');
        if (readAtIdx !== -1) sheet.getRange(idx + 1, readAtIdx + 1).setValue(new Date());
        updated++;
      }
    });
    return { success: true, data: { updated } };
  } catch (e) {
    Logger.log("markNotificationsReadBulk error: " + e.toString());
    return { success: false, message: "Unable to mark notifications read.", error: e.toString() };
  }
}

