function dayNumber_(day) { return Math.round(Date.parse(day + 'T00:00:00Z') / 86400000); }

/**
 * The festival that colours a day: one happening today (or during a
 * multi-day festival) beats one coming up; among those coming up, the
 * nearest wins. Returns null on an ordinary day.
 */
function festivalFor_(day) {
  const today = dayNumber_(day);
  let best = null;
  DAILY_PUSH_FESTIVALS.forEach(function (f) {
    const start = dayNumber_(f.date);
    const end = start + (f.days || 1) - 1;
    let phase = '', away = start - today;
    if (today === start) phase = 'today';
    else if (today > start && today <= end) phase = 'during';
    else if (away > 0 && away <= (f.lead || 0) && f.nudge && !f.approx) phase = 'soon';
    if (!phase) return;
    const rank = phase === 'soon' ? 10 + away : (phase === 'today' ? 0 : 1);
    if (!best || rank < best.rank) best = { key: f.key, name: f.name, emoji: f.emoji, phase: phase, daysAway: Math.max(0, away), greet: f.greet, nudge: f.nudge || null, rank: rank };
  });
  if (best) delete best.rank;
  return best;
}

/** Festivals in the next `n` days (for Gemini's context and the admin panel). */
function upcomingFestivals_(day, n) {
  const today = dayNumber_(day);
  return DAILY_PUSH_FESTIVALS.filter(function (f) {
    const d = dayNumber_(f.date) - today;
    return d >= 0 && d <= n;
  }).map(function (f) { return { name: f.name, date: f.date, inDays: dayNumber_(f.date) - today, approx: !!f.approx }; });
}

// ── Gemini copy (28 Sep) ─────────────────────────────────────────────
// Once a day, Gemini writes the four slots' lines in English for that
// day's festival and numbers. It runs on the website (Vercel already
// has GEMINI_API_KEY for Quill), reached through the push relay's secret:
// PUSH_RELAY_URL …/relay → …/daily-copy. The answer is checked there and
// again here, cached for the day, and anything missing or odd falls back
// to the hand-written lines below — so a Gemini outage never stops a push.
const DAILY_PUSH_LINKS = {
  library: '/library', list: '/library?list=1', wanted: '/book-requests',
  cafe: '/readers-cafe', events: '/events', tracker: '/tracker'
};
const DAILY_COPY_KEY = 'DAILY_PUSH_COPY_';

function cleanAiLine_(s, max) {
  s = String(s || '').replace(/[\u0000-\u001f<>]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!s || s.length > max) return '';
  if (/https?:|www\.|@|\.com\b|\bdiscount\b|\bfree gift\b|\bprize\b|\bcash\b/i.test(s)) return '';
  // Allow at most the {name} placeholder; any other braces mean a broken template.
  if (/[{}]/.test(s.replace(/\{name\}/g, ''))) return '';
  return s;
}

/** Keeps only well-formed slots; returns null if nothing usable. */
function validateDailyCopy_(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const out = {};
  let n = 0;
  ['morning', 'afternoon', 'evening', 'night'].forEach(function (slot) {
    const s = raw[slot];
    if (!s || typeof s !== 'object') return;
    const title = cleanAiLine_(s.title, 70);
    const message = cleanAiLine_(s.message, 170);
    const link = DAILY_PUSH_LINKS[String(s.link || '')] ? String(s.link) : '';
    if (!title || !message || !link) return;
    out[slot] = { title: title, message: message, link: link };
    n++;
  });
  return n ? out : null;
}

/** What Gemini is told about the day — counts and public titles only, never anyone's email or name. */
function dailyCopyBrief_(ctx) {
  return {
    date: ctx.day,
    weekday: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][ctx.weekday],
    festival: ctx.festival ? { name: ctx.festival.name, phase: ctx.festival.phase, daysAway: ctx.festival.daysAway } : null,
    upcomingFestivals: upcomingFestivals_(ctx.day, 21),
    newBooksLast24h: ctx.fresh.length,
    booksOnShelf: ctx.live.length,
    mostWantedTitles: ctx.wanted.slice(0, 3).map(function (w) { return w.title.slice(0, 60); }),
    cafeMessagesToday: ctx.cafeToday,
    nextEvent: ctx.nextEvent ? { title: ctx.nextEvent.title.slice(0, 80), when: dailyEventWhen_(ctx.nextEvent.date, ctx) } : null
  };
}

/** Today's Gemini copy, fetched at most once a day (retried after 2 h on failure). */
function dailyGeminiCopy_(ctx, opts) {
  opts = opts || {};
  const props = PropertiesService.getScriptProperties();
  if (String(props.getProperty('DAILY_PUSH_AI') || '') === 'off') return null;
  const key = DAILY_COPY_KEY + ctx.day;
  try {
    const cached = JSON.parse(props.getProperty(key) || 'null');
    if (cached && cached.copy && !opts.refresh) return validateDailyCopy_(cached.copy);
    if (cached && cached.failedAt && !opts.refresh && Date.now() - Date.parse(cached.failedAt) < 2 * 3600 * 1000) return null;
  } catch (e) { /* re-fetch */ }
  const relay = String(props.getProperty('PUSH_RELAY_URL') || '').trim();
  const secret = String(props.getProperty('PUSH_RELAY_SECRET') || '').trim();
  if (!/^https:\/\/.+\/relay$/i.test(relay) || !secret) return null;
  let copy = null;
  try {
    const res = UrlFetchApp.fetch(relay.replace(/\/relay$/i, '/daily-copy'), {
      method: 'post', contentType: 'application/json', headers: { 'X-Relay-Secret': secret },
      payload: JSON.stringify({ brief: dailyCopyBrief_(ctx) }), muteHttpExceptions: true
    });
    const body = JSON.parse(res.getContentText() || '{}');
    copy = body && body.success ? validateDailyCopy_(body.copy) : null;
  } catch (e) { Logger.log('daily copy (Gemini) failed: ' + e); }
  try {
    props.setProperty(key, JSON.stringify(copy ? { copy: copy, at: new Date().toISOString() } : { failedAt: new Date().toISOString() }));
    // Forget earlier days' copy.
    (typeof props.getKeys === 'function' ? props.getKeys() : []).forEach(function (k) {
      if (k.indexOf(DAILY_COPY_KEY) === 0 && k !== key) props.deleteProperty(k);
    });
  } catch (e) { /* cache only */ }
  return copy;
}

// ── The copy (English) ───────────────────────────────────────────────

function dailyEventWhen_(date, ctx) {
  const d = istParts_(date);
  if (d.day === ctx.day) return 'today';
  const diff = dayNumber_(d.day) - dayNumber_(ctx.day);
  if (diff === 1) return 'tomorrow';
  const names = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  return 'on ' + names[d.weekday];
}

/**
 * One push for one reader in one slot. Order of preference:
 *   1. something about this reader (a book near them, their listing's
 *      missing photo, a meetup) — the most specific thing wins;
 *   2. today's Gemini line for the slot (festival-aware);
 *   3. the hand-written festival line;
 *   4. data-driven lines (new books, Wanted shelf, café, tonight's pick);
 *   5. a line that needs no data at all — so an empty shelf still sends.
 */
function composeDailyPush_(slot, who, ctx) {
  const guest = isGuestPushId_(who);
  const me = guest ? null : (ctx.users[who] || { name: '', pincode: '' });
  const name = me && me.name ? me.name : '';
  const hi = name ? ', ' + name : '';
  const seed = who + '|' + ctx.day + '|' + slot;
  const fest = ctx.festival || null;
  const notMine = function (b) { return b && b.owner !== who; };
  const pickOf = function (list, salt) { return dailyPick_((list || []).filter(notMine), seed + salt); };
  const by = function (b) { return b.author ? ' by ' + shortTitle_(b.author, 24) : ''; };
  const out = function (title, message, targetUrl, variant) {
    return {
      userEmail: who,
      title: title,
      message: message,
      targetUrl: targetUrl + (targetUrl.indexOf('?') === -1 ? '?' : '&') + 'ss_push=' + slot,
      tag: 'ss-daily-' + slot + '-' + ctx.day,
      type: 'daily_' + slot,
      variant: variant
    };
  };
  const ai = ctx.aiCopy && ctx.aiCopy[slot];
  const fromAi = function () {
    const fill = function (s) {
      return name ? s.replace(/\{name\}/g, name) : s.replace(/,?\s*\{name\}/g, '');
    };
    return out(fill(ai.title), fill(ai.message), DAILY_PUSH_LINKS[ai.link], 'ai_' + slot);
  };

  if (slot === 'morning') {
    const near = me && me.pincode ? (ctx.nearbyByPin[me.pincode] || []).filter(notMine) : [];
    if (near.length) {
      const b = pickOf(near, 'near');
      return out('📦 A new book near you',
        '"' + shortTitle_(b.title) + '"' + by(b) + ' was just listed near ' + me.pincode + '. Request it before someone else does!',
        '/book/' + encodeURIComponent(b.id), 'morning_near');
    }
    if (ai) return fromAi();
    if (fest && (fest.phase === 'today' || fest.phase === 'during')) {
      return out(fest.emoji + ' Happy ' + fest.name + hi + '!', fest.greet, '/library', 'morning_festival');
    }
    const fresh = ctx.fresh.filter(notMine);
    if (fresh.length >= 2) {
      const b = pickOf(fresh.slice(0, 10), 'fresh');
      return out(dailyPick_(['☀️ Fresh on the shelf: ' + fresh.length + ' new books', '☀️ Good morning' + hi + '! ' + fresh.length + ' new books today'], seed),
        '"' + shortTitle_(b.title) + '" and ' + (fresh.length - 1) + ' more arrived since yesterday. Take a look with your chai?',
        '/library', 'morning_fresh');
    }
    if (fresh.length === 1) {
      return out('☀️ A new book landed last night',
        '"' + shortTitle_(fresh[0].title) + '"' + by(fresh[0]) + '. Have a look before someone else requests it.',
        '/book/' + encodeURIComponent(fresh[0].id), 'morning_fresh1');
    }
    const b = pickOf(ctx.live, 'pick');
    if (b) {
      return out('☀️ Good morning' + hi + '! Today\'s pick',
        '"' + shortTitle_(b.title) + '"' + by(b) + ' is waiting for you on the shelf.',
        '/book/' + encodeURIComponent(b.id), 'morning_pick');
    }
    return out('☀️ Good morning' + hi + '!', 'Which story will you start today? See what readers are sharing on SwapSutra.', '/library', 'morning_plain');
  }

  if (slot === 'afternoon') {
    // The lunchtime push is the one that asks for a listing.
    if (!guest && ctx.partialByOwner[who]) {
      const b = ctx.partialByOwner[who];
      return out('📸 Just one photo left',
        'Add the back cover or an inside photo of "' + shortTitle_(b.title) + '" — readers see its condition and swaps happen faster.',
        '/profile', 'afternoon_finish');
    }
    if (ai) return fromAi();
    if (fest && fest.nudge) return out(fest.nudge.title, fest.nudge.message, '/library?list=1', 'afternoon_festival');
    const wanted = ctx.wanted.filter(function (w) { return w.askers.indexOf(who) === -1; });
    if (wanted.length && dailyHash_(seed + 'w') % 2 === 0) {
      const w = wanted[dailyHash_(seed + 'wt') % Math.min(3, wanted.length)];
      const n = w.askers.length;
      return out('🔎 ' + (n > 1 ? n + ' readers are' : 'A reader is') + ' looking for "' + shortTitle_(w.title, 30) + '"',
        'Have a copy? List it — a photo of the front cover is enough.',
        '/book-requests', 'afternoon_wanted');
    }
    if (guest) {
      return out(dailyPick_(['📚 Books gathering dust at home?', '📚 Your old book is someone\'s next story'], seed),
        'List them on SwapSutra and swap them for new reads. Joining is free.',
        '/library?list=1', 'afternoon_guest');
    }
    const mine = ctx.byOwner[who] || 0;
    if (!mine) {
      return out(dailyPick_(['📚 ' + (name ? name + ', which' : 'Which') + ' book will be your first?', '📚 Your old book is someone\'s next story', '⏱️ A 30-second job for your lunch break'], seed),
        'Just snap a photo of the front cover and your listing is ready. List one book today?',
        '/library?list=1', 'afternoon_first');
    }
    return out(dailyPick_(['📚 You have ' + mine + ' ' + (mine === 1 ? 'book' : 'books') + ' on your shelf', '➕ One more book, one more swap'], seed),
      'The bigger your shelf, the more swaps come your way. Add one more over lunch?',
      '/library?list=1', 'afternoon_more');
  }

  if (slot === 'evening') {
    if (ctx.nextEvent && dailyHash_(seed + 'e') % 3 !== 0) {
      return out('🎟️ ' + shortTitle_(ctx.nextEvent.title, 50),
        'Readers are meeting ' + dailyEventWhen_(ctx.nextEvent.date, ctx) + '. Join them — save your seat.',
        '/events', 'evening_event');
    }
    if (ai) return fromAi();
    if (ctx.cafeToday >= 3) {
      return out('☕ ' + ctx.cafeToday + ' conversations in the Café today',
        ctx.cafeSpeakersToday + ' readers are talking books over evening chai. Join in!',
        '/readers-cafe', 'evening_cafe');
    }
    return out(dailyPick_(['☕ What are you reading this week?', '☕ Evening chai and a book chat?'], seed),
      'Drop a line in the Café' + hi + ' — fellow readers will reply.',
      '/readers-cafe', 'evening_ask');
  }

  // night
  if (ai) return fromAi();
  if (fest && fest.phase === 'today') {
    return out('🌙 ' + fest.emoji + ' Happy ' + fest.name + hi + '!', 'End the day with a story. See what is on the shelf tonight.', '/library', 'night_festival');
  }
  if (!guest && dailyHash_(seed + 't') % 3 === 0) {
    return out('📖 How many pages did you read today?', 'Log them in your tracker and keep your reading streak alive 🔥', '/tracker', 'night_tracker');
  }
  const pick = pickOf(ctx.live, 'night');
  if (pick) {
    return out('🌙 Tonight\'s pick: "' + shortTitle_(pick.title, 34) + '"',
      (pick.author ? shortTitle_(pick.author, 24) + '\'s book' : 'This book') + ' is on the shelf. Send a request and chat with the owner directly.',
      '/book/' + encodeURIComponent(pick.id), 'night_pick');
  }
  return out('🌙 10 pages before bed?', 'A fresh list of books will be waiting for you in the morning.', '/library', 'night_plain');
}

// ── Sending ──────────────────────────────────────────────────────────

function sendDailyPushItems_(items) {
  const props = PropertiesService.getScriptProperties();
  const url = String(props.getProperty('PUSH_RELAY_URL') || '').trim();
  const secret = String(props.getProperty('PUSH_RELAY_SECRET') || '').trim();
  if (!url || !secret || !/^https:\/\//i.test(url)) return { configured: false, sent: 0, failed: 0, calls: 0 };
  const requests = [];
  for (let i = 0; i < items.length; i += DAILY_PUSH_BATCH) {
    requests.push({
      url: url, method: 'post', contentType: 'application/json',
      headers: { 'X-Relay-Secret': secret },
      payload: JSON.stringify({ items: items.slice(i, i + DAILY_PUSH_BATCH) }),
      muteHttpExceptions: true
    });
  }
  let sent = 0, failed = 0;
  for (let i = 0; i < requests.length; i += DAILY_PUSH_PARALLEL) {
    const group = requests.slice(i, i + DAILY_PUSH_PARALLEL);
    let responses = [];
    try {
      responses = typeof UrlFetchApp.fetchAll === 'function'
        ? UrlFetchApp.fetchAll(group)
        : group.map(function (g) { return UrlFetchApp.fetch(g.url, g); });
    } catch (e) { Logger.log('daily push relay failed: ' + e); failed += group.length; continue; }
    responses.forEach(function (res) {
      try {
        const body = JSON.parse(res.getContentText() || '{}');
        sent += Number(body.sent || 0);
        failed += Number(body.failed || 0);
      } catch (e) { /* counts are best-effort */ }
    });
  }
  return { configured: true, sent: sent, failed: failed, calls: requests.length };
}

function bumpDailyPushStats_(day, slot, field, n) {
  let lock = null;
  try {
    if (typeof LockService !== 'undefined') { lock = LockService.getScriptLock(); lock.tryLock(3000); }
    const props = PropertiesService.getScriptProperties();
    let stats = {};
    try { stats = JSON.parse(props.getProperty(DAILY_PUSH_KEYS.stats) || '{}') || {}; } catch (e) { stats = {}; }
    stats[day] = stats[day] || {};
    stats[day][slot] = stats[day][slot] || { readers: 0, sent: 0, opens: 0 };
    stats[day][slot][field] = (Number(stats[day][slot][field]) || 0) + n;
    // Two weeks is enough to see what works; the property has a size limit.
    Object.keys(stats).sort().slice(0, Math.max(0, Object.keys(stats).length - 14)).forEach(function (k) { delete stats[k]; });
    props.setProperty(DAILY_PUSH_KEYS.stats, JSON.stringify(stats));
  } catch (e) {
    Logger.log('daily push stats: ' + e);
  } finally {
    try { if (lock) lock.releaseLock(); } catch (e) { /* ignore */ }
  }
}

/**
 * The hourly trigger. Sends only in a slot hour, once per slot per day.
 * opts (for tests and the admin's "send now"): { now, force: 'morning'|…, only: [emails] }
 */
function runDailyEngagementPush(opts) {
  opts = (opts && typeof opts === 'object' && !opts.triggerUid) ? opts : {};
  const started = Date.now();
  const now = opts.now ? new Date(opts.now) : new Date();
  const ist = istParts_(now);
  const props = PropertiesService.getScriptProperties();
  const summary = { day: ist.day, hour: ist.hour, slot: '', readers: 0, items: 0, sent: 0, failed: 0, skipped: '' };

  const forced = opts.force && DAILY_PUSH_SLOT_NAMES[opts.force] ? opts.force : '';
  if (!forced && String(props.getProperty(DAILY_PUSH_KEYS.paused) || '') === 'true') { summary.skipped = 'paused'; return summary; }
  const slot = forced || dailyPushSlotName_(ist.hour, dailyPushSlots_());
  summary.slot = slot;
  if (!slot) { summary.skipped = 'not a slot hour'; return summary; }

  const doneKey = DAILY_PUSH_KEYS.donePrefix + ist.day + '_' + slot;
  if (!forced) {
    if (props.getProperty(doneKey)) { summary.skipped = 'already sent'; return summary; }
    // Claimed before sending: a second trigger run in the same hour must
    // not send the slot twice.
    props.setProperty(doneKey, new Date().toISOString());
    // Forget the claims from before yesterday.
    try {
      const keys = typeof props.getKeys === 'function' ? props.getKeys() : [];
      keys.forEach(function (k) {
        if (k.indexOf(DAILY_PUSH_KEYS.donePrefix) === 0 && k.slice(DAILY_PUSH_KEYS.donePrefix.length, DAILY_PUSH_KEYS.donePrefix.length + 10) < istParts_(now.getTime() - 2 * 24 * 3600 * 1000).day) props.deleteProperty(k);
      });
    } catch (e) { /* tidy-up only */ }
  }

  try {
    let audience = dailyPushAudience_();
    if (Array.isArray(opts.only)) {
      const only = {};
      opts.only.forEach(function (e) { only[normalizeEmail(e)] = true; });
      Object.keys(audience).forEach(function (k) { if (!only[k]) delete audience[k]; });
    }
    const readers = Object.keys(audience);
    summary.readers = readers.length;
    if (!readers.length) { summary.skipped = 'no devices'; return summary; }

    const ctx = dailyPushContext_(now);
    ctx.aiCopy = dailyGeminiCopy_(ctx);
    summary.festival = ctx.festival ? ctx.festival.name + ' (' + ctx.festival.phase + ')' : '';
    summary.copy = ctx.aiCopy && ctx.aiCopy[slot] ? 'gemini' : 'templates';
    const items = [];
    readers.forEach(function (who) {
      if (Date.now() - started > DAILY_PUSH_TIME_BUDGET_MS) return;
      try {
        const p = composeDailyPush_(slot, who, ctx);
        items.push({ userEmail: p.userEmail, title: p.title, message: p.message, targetUrl: p.targetUrl, tag: p.tag, type: p.type, devices: audience[who] });
      } catch (e) { Logger.log('daily push compose failed for one reader: ' + e); }
    });
    summary.items = items.length;
    const res = sendDailyPushItems_(items);
    summary.sent = res.sent;
    summary.failed = res.failed;
    if (!res.configured) summary.skipped = 'relay not configured';
    if (!forced) {
      bumpDailyPushStats_(ist.day, slot, 'readers', items.length);
      bumpDailyPushStats_(ist.day, slot, 'sent', res.sent);
    }
  } catch (err) {
    Logger.log('runDailyEngagementPush failed: ' + err);
    summary.skipped = 'error: ' + err;
  }
  Logger.log('runDailyEngagementPush: ' + JSON.stringify(summary));
  return summary;
}

/** Public: a daily push was tapped (the app sees ?ss_push=<slot>). Counts only. */
function recordPushOpen(data) {
  const slot = String((data && data.slot) || '');
  if (!DAILY_PUSH_SLOT_NAMES[slot]) return { success: false, message: 'Unknown slot.' };
  try {
    const cache = CacheService.getScriptCache();
    const burst = Number(cache.get('push_open_burst') || 0);
    if (burst >= 500) return { success: true, counted: false };
    cache.put('push_open_burst', String(burst + 1), 600);
  } catch (e) { /* never block on the cache */ }
  bumpDailyPushStats_(istParts_(new Date()).day, slot, 'opens', 1);
  return { success: true, counted: true };
}

// ── Admin ────────────────────────────────────────────────────────────

function getDailyPushAdmin(data) {
  const props = PropertiesService.getScriptProperties();
  let stats = {};
  try { stats = JSON.parse(props.getProperty(DAILY_PUSH_KEYS.stats) || '{}') || {}; } catch (e) { stats = {}; }
  const audience = dailyPushAudience_();
  const readers = Object.keys(audience);
  const guests = readers.filter(isGuestPushId_).length;
  const relayReady = Boolean(String(props.getProperty('PUSH_RELAY_URL') || '').trim() && String(props.getProperty('PUSH_RELAY_SECRET') || '').trim());
  // What each slot would say to the admin today — the preview.
  const me = normalizeEmail(getAuthenticatedEmail() || '');
  const slots = dailyPushSlots_();
  let preview = [];
  let festival = null, upcoming = [], copySource = 'templates';
  try {
    const ctx = dailyPushContext_(new Date());
    ctx.aiCopy = dailyGeminiCopy_(ctx, { refresh: !!(data && data.refreshCopy) });
    festival = ctx.festival;
    upcoming = upcomingFestivals_(ctx.day, 45);
    copySource = ctx.aiCopy ? 'gemini' : 'templates';
    const sampleGuest = 'guest:preview';
    preview = slots.map(function (h) {
      const slot = dailyPushSlotName_(h, slots);
      return { hour: h, slot: slot, member: composeDailyPush_(slot, me || 'admin@preview', ctx), visitor: composeDailyPush_(slot, sampleGuest, ctx) };
    });
  } catch (e) { Logger.log('daily push preview: ' + e); }
  return {
    success: true,
    paused: String(props.getProperty(DAILY_PUSH_KEYS.paused) || '') === 'true',
    slots: slots,
    relayReady: relayReady,
    devicesReached: readers.reduce(function (n, k) { return n + audience[k].length; }, 0),
    readers: readers.length - guests,
    visitors: guests,
    stats: stats,
    preview: preview,
    festival: festival,
    upcomingFestivals: upcoming,
    copySource: copySource,
    aiEnabled: String(props.getProperty('DAILY_PUSH_AI') || '') !== 'off'
  };
}

function setDailyPushSettings(data) {
  const props = PropertiesService.getScriptProperties();
  if (data && data.paused !== undefined) props.setProperty(DAILY_PUSH_KEYS.paused, (data.paused === true || data.paused === 'true') ? 'true' : 'false');
  if (data && data.ai !== undefined) props.setProperty('DAILY_PUSH_AI', (data.ai === false || data.ai === 'off') ? 'off' : 'on');
  if (data && data.slots !== undefined) {
    const list = String(Array.isArray(data.slots) ? data.slots.join(',') : data.slots || '');
    if (!list.trim()) props.deleteProperty(DAILY_PUSH_KEYS.slots);
    else props.setProperty(DAILY_PUSH_KEYS.slots, list);
  }
  return getDailyPushAdmin(data);
}

/** Admin: send one slot right now, to the admin's own devices only. */
function sendDailyPushTest(data) {
  const me = normalizeEmail(getAuthenticatedEmail() || '');
  if (!me) return { success: false, message: 'Sign in first.' };
  const slot = String((data && data.slot) || 'morning');
  if (!DAILY_PUSH_SLOT_NAMES[slot]) return { success: false, message: 'Unknown slot.' };
  const summary = runDailyEngagementPush({ force: slot, only: [me] });
  return { success: true, summary: summary };
}

// =====================================================================
// COFFEE MUGS — marketplace shelf + custom mug enquiries (30 Sep 2026)
// ---------------------------------------------------------------------
// Two sheet tabs, both created on first use:
//
//   MugProducts          What the /mugs shelf shows. EMPTY at launch: it is
//                        filled only from authorised sources (an affiliate
//                        feed, a merchant's own product data, products
//                        SwapSutra has permission to list). Nothing is
//                        scraped or copied from Amazon/Flipkart. A row is
//                        shown only when status = "live".
//
//   CustomMugEnquiries   One row per "Create My Mug" request. Written ONLY
//                        after the server has re-validated every field; the
//                        website shows "on its way" only when this returns
//                        success with the new id. adminNotes and
//                        assignedManufacturer are internal and are never
//                        returned to a customer.
//
// Manufacturer workflow the statuses follow: new → reviewing →
// manufacturer_search → prototype → quoted → customer_approval →
// manufacturing → shipped → completed (or rejected). Nothing here promises
// feasibility, a price, a manufacturer or a date.
// =====================================================================

const MUG_PRODUCT_HEADERS = [
  'id', 'title', 'description', 'category', 'imageUrl', 'price', 'mrp', 'currency',
  'availability', 'sourceMarketplace', 'sourceUrl', 'affiliateUrl', 'vendor',
  'rating', 'ratingCount', 'ratingSource', 'status', 'sortOrder', 'updatedAt'
];
const MUG_CATEGORY_IDS = ['bookish', 'minimal', 'funny-reader', 'cafe-style', 'aesthetic', 'personalized'];

const MUG_ENQUIRY_HEADERS = [
  'id', 'createdAt', 'name', 'email', 'phone', 'idea', 'referenceImageUrl',
  'mugType', 'volumeMl', 'volumeRange', 'quantityRange', 'quantityExact',
  'budgetType', 'budgetAmount', 'budgetRange', 'pincode', 'city', 'state',
  'timeline', 'specificDate', 'additionalNotes',
  'status', 'adminNotes', 'assignedManufacturer', 'lastUpdatedAt'
];
const MUG_ENQUIRY_STATUSES = ['new', 'reviewing', 'manufacturer_search', 'prototype', 'quoted',
  'customer_approval', 'manufacturing', 'shipped', 'completed', 'rejected'];
// The website (src/utils/mugEnquiry.ts) offers exactly these; the server
// accepts nothing else. tests/test_custom_mug_enquiry.cjs keeps them equal.
const MUG_TYPES = ['Coffee Mug', 'Café Mug', 'Travel Mug', 'Handleless Mug', 'Large Mug', 'Mini Mug', 'Espresso Cup', 'Tea Cup', 'Other'];
const MUG_VOLUME_RANGES = {
  '100-150': { label: '100–150 ml — Espresso / Mini', min: 100, max: 150 },
  '150-200': { label: '150–200 ml — Small', min: 150, max: 200 },
  '200-250': { label: '200–250 ml — Regular', min: 200, max: 250 },
  '250-300': { label: '250–300 ml — Medium', min: 250, max: 300 },
  '300-350': { label: '300–350 ml — Large', min: 300, max: 350 },
  '350-450': { label: '350–450 ml — Extra Large', min: 350, max: 450 },
  '450-600': { label: '450–600 ml — Oversized', min: 450, max: 600 }
};
const MUG_CUSTOM_VOLUME = { min: 30, max: 2000 };
const MUG_QUANTITY_RANGES = { '1': [1, 1], '2-5': [2, 5], '6-20': [6, 20], '21-50': [21, 50], '50+': [51, 100000] };
const MUG_BUDGET_TYPES = { per_mug: 'per mug', total: 'total project' };
const MUG_BUDGET_RANGES = ['Under ₹500', '₹500–₹1,000', '₹1,000–₹2,000', '₹2,000–₹5,000', '₹5,000–₹10,000', '₹10,000+'];
const MUG_TIMELINES = {
  no_rush: 'No rush', within_2_weeks: 'Within 2 weeks', within_1_month: 'Within 1 month',
  '1_3_months': '1–3 months', specific_date: 'Need it by a specific date'
};
const MUG_IMAGE_MAX_BYTES = 1.5 * 1024 * 1024;

/**
 * Admin: list mugs sold on Amazon, Flipkart or another store (30 Sep 2026).
 * The admin pastes the product's own link and the details shown on its
 * page — nothing is scraped. Visitors click "Buy on Amazon/Flipkart" and
 * the store opens in a new tab; the order is placed there, not here.
 * Status: live (on the shelf), draft (saved, hidden) or removed.
 */
const MUG_PRODUCT_STATUSES = ['live', 'draft', 'removed'];

/** "Amazon" / "Flipkart" from a product link, or '' for any other store. */
function mugMarketplaceFromUrl_(url) {
  const m = String(url || '').toLowerCase().match(/^https:\/\/([^\/?#]+)/);
  const host = m ? m[1].replace(/^www\./, '') : '';
  if (/(^|\.)amazon\.(in|com)$|^amzn\.(to|in|eu)$|^a\.co$/.test(host)) return 'Amazon';
  if (/(^|\.)flipkart\.com$|^fkrt\.(it|cc|co)$|^fktr\.in$/.test(host)) return 'Flipkart';
  return '';
}

function getAdminMugProducts() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const sheet = getOrCreateSheet('MugProducts', MUG_PRODUCT_HEADERS);
  ensureSheetHeaders(sheet, MUG_PRODUCT_HEADERS);
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(function (h) { return String(h).trim(); });
  const items = values.slice(1).map(function (r) {
    const o = {};
    headers.forEach(function (h, i) { o[h] = r[i] instanceof Date ? r[i].toISOString() : r[i]; });
    return o;
  }).filter(function (o) { return String(o.id || '').trim() && String(o.status || '').toLowerCase() !== 'removed'; });
  return { success: true, items: items, categories: MUG_CATEGORY_IDS, statuses: MUG_PRODUCT_STATUSES };
}

function saveMugProduct(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  data = data || {};
  const https = function (u) { u = String(u || '').trim(); return /^https:\/\/[^\s]+$/i.test(u) ? u.slice(0, 1000) : ''; };
  const money = function (n) { if (n === '' || n === null || n === undefined) return ''; n = Number(n); return isFinite(n) && n > 0 && n < 1000000 ? Math.round(n) : NaN; };
  const status = String(data.status || 'draft').toLowerCase();
  if (MUG_PRODUCT_STATUSES.indexOf(status) === -1) return { success: false, message: 'Unknown status.' };

  const title = mugText_(data.title, 120);
  const category = String(data.category || '').trim();
  const sourceUrl = https(data.sourceUrl);
  const affiliateUrl = https(data.affiliateUrl);
  const imageUrl = https(data.imageUrl);
  const price = money(data.price), mrp = money(data.mrp);
  const errors = {};
  if (status !== 'removed') {
    if (!title) errors.title = 'Give the mug a name.';
    if (MUG_CATEGORY_IDS.indexOf(category) === -1) errors.category = 'Pick a category.';
    if (!sourceUrl) errors.sourceUrl = 'Paste the product link (it must start with https://).';
    if (String(data.affiliateUrl || '').trim() && !affiliateUrl) errors.affiliateUrl = 'The affiliate link must start with https://.';
    if (String(data.imageUrl || '').trim() && !imageUrl) errors.imageUrl = 'The image link must start with https://.';
    if (price !== '' && isNaN(price)) errors.price = 'Price must be a number in rupees.';
    if (mrp !== '' && isNaN(mrp)) errors.mrp = 'MRP must be a number in rupees.';
    if (status === 'live' && !imageUrl) errors.imageUrl = 'Add the product photo link before putting it live.';
  }
  if (Object.keys(errors).length) return { success: false, errors: errors, message: 'Please fix the highlighted fields.' };

  const marketplace = mugMarketplaceFromUrl_(sourceUrl) || mugText_(data.sourceMarketplace, 40);
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const sheet = getOrCreateSheet('MugProducts', MUG_PRODUCT_HEADERS);
    ensureSheetHeaders(sheet, MUG_PRODUCT_HEADERS);
    const values = sheet.getDataRange().getValues();
    const headers = values[0].map(function (h) { return String(h).trim(); });
    const col = function (h) { return headers.indexOf(h); };
    const id = String(data.id || '').trim();
    let rowIndex = -1;
    if (id) {
      for (let i = 1; i < values.length; i++) if (String(values[i][col('id')]) === id) { rowIndex = i; break; }
      if (rowIndex === -1) return { success: false, message: 'That mug no longer exists.' };
    }
    const row = rowIndex === -1 ? headers.map(function () { return ''; }) : values[rowIndex].slice();
    const set = function (h, v) { if (col(h) !== -1) row[col(h)] = v; };
    const newId = id || ('MUGP-' + Utilities.formatDate(new Date(), 'Asia/Kolkata', 'yyyyMMdd') + '-' + Utilities.getUuid().slice(0, 5).toUpperCase());
    set('id', newId);
    set('status', status);
    set('updatedAt', new Date().toISOString());
    if (status !== 'removed') {
      set('title', title);
      set('description', mugText_(data.description, 400));
      set('category', category);
      set('imageUrl', imageUrl);
      set('price', price === '' ? '' : price);
      set('mrp', mrp !== '' && price !== '' && mrp > price ? mrp : '');
      set('currency', 'INR');
      set('availability', mugText_(data.availability, 40));
      set('sourceMarketplace', marketplace);
      set('sourceUrl', sourceUrl);
      set('affiliateUrl', affiliateUrl);
      set('vendor', mugText_(data.vendor, 60));
      set('sortOrder', Number(data.sortOrder) || 0);
      // Ratings are never typed in by hand: a number with no verifiable
      // source is exactly the fake review this shop refuses to show.
      set('rating', ''); set('ratingCount', ''); set('ratingSource', '');
    }
    if (rowIndex === -1) sheet.appendRow(row);
    else sheet.getRange(rowIndex + 1, 1, 1, row.length).setValues([row]);
    return { success: true, id: newId, sourceMarketplace: marketplace };
  } finally {
    lock.releaseLock();
  }
}

function mugText_(v, max) {
  return String(v === undefined || v === null ? '' : v).replace(/\u0000/g, '').trim().slice(0, max);
}

/** Server-side validation. Returns { ok, errors, clean }. Never trusts the browser. */
function validateCustomMugEnquiry_(data, now) {
  const d = data || {};
  const errors = {};
  const clean = {};
  now = now || new Date();

  clean.name = mugText_(d.name, 80);
  if (clean.name.length < 2) errors.name = 'Please tell us your name.';

  clean.email = mugText_(d.email, 120).toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(clean.email)) errors.email = 'Please enter a valid email address.';

  const digits = String(d.phone || '').replace(/[\s\-().]/g, '');
  const m = digits.match(/^(?:\+?91|0)?([6-9]\d{9})$/);
  if (!m) errors.phone = 'Please enter a 10-digit Indian mobile number.';
  else clean.phone = '+91' + m[1];

  clean.idea = mugText_(d.idea, 3000);
  if (clean.idea.length < 20) errors.idea = 'Tell us a little more about your mug idea (at least 20 characters).';

  clean.mugType = mugText_(d.mugType, 40);
  if (MUG_TYPES.indexOf(clean.mugType) === -1) errors.mugType = 'Please choose a mug style.';

  const volumeRange = mugText_(d.volumeRange, 20);
  if (volumeRange === 'custom') {
    const ml = Number(d.volumeMl);
    if (!isFinite(ml) || ml < MUG_CUSTOM_VOLUME.min || ml > MUG_CUSTOM_VOLUME.max) {
      errors.volumeMl = 'Enter a capacity between ' + MUG_CUSTOM_VOLUME.min + ' and ' + MUG_CUSTOM_VOLUME.max + ' ml.';
    } else {
      clean.volumeMl = Math.round(ml);
      clean.volumeRange = 'Custom';
    }
  } else if (MUG_VOLUME_RANGES[volumeRange]) {
    const r = MUG_VOLUME_RANGES[volumeRange];
    // A range is stored as its midpoint in ml (a number the manufacturer
    // can work with) plus the range itself.
    clean.volumeMl = Math.round((r.min + r.max) / 2);
    clean.volumeRange = r.min + '–' + r.max + ' ml';
  } else {
    errors.volumeRange = 'Please choose how much it should hold.';
  }

  const qRange = mugText_(d.quantityRange, 10);
  if (!MUG_QUANTITY_RANGES[qRange]) errors.quantityRange = 'Please choose how many mugs you need.';
  else clean.quantityRange = qRange;
  if (d.quantityExact !== undefined && d.quantityExact !== null && String(d.quantityExact).trim() !== '') {
    const q = Number(d.quantityExact);
    if (!Number.isInteger(q) || q < 1 || q > 100000) errors.quantityExact = 'Exact quantity must be a whole number.';
    else if (clean.quantityRange && (q < MUG_QUANTITY_RANGES[clean.quantityRange][0] || q > MUG_QUANTITY_RANGES[clean.quantityRange][1])) {
      errors.quantityExact = 'That number does not match the range you picked.';
    } else clean.quantityExact = q;
  } else clean.quantityExact = '';

  clean.budgetType = mugText_(d.budgetType, 20);
  if (!MUG_BUDGET_TYPES[clean.budgetType]) errors.budgetType = 'Is the budget per mug or for the whole order?';
  const amount = Number(d.budgetAmount);
  if (!isFinite(amount) || amount <= 0 || amount > 10000000) errors.budgetAmount = 'Please enter a budget in rupees.';
  else clean.budgetAmount = Math.round(amount);
  clean.budgetRange = MUG_BUDGET_RANGES.indexOf(String(d.budgetRange || '')) !== -1 ? String(d.budgetRange) : '';

  clean.pincode = mugText_(d.pincode, 6);
  if (!/^[1-9]\d{5}$/.test(clean.pincode)) errors.pincode = 'Please enter a valid 6-digit pincode.';
  clean.city = mugText_(d.city, 60);
  clean.state = mugText_(d.state, 60);

  clean.timeline = mugText_(d.timeline, 20);
  if (!MUG_TIMELINES[clean.timeline]) errors.timeline = 'When do you need it?';
  clean.specificDate = '';
  if (clean.timeline === 'specific_date') {
    const s = mugText_(d.specificDate, 10);
    const when = /^\d{4}-\d{2}-\d{2}$/.test(s) ? new Date(s + 'T00:00:00Z') : null;
    // "Today" in India, whatever the script's own time zone.
    const todayIst = new Date(now.getTime() + 330 * 60 * 1000).toISOString().slice(0, 10);
    const startOfToday = new Date(todayIst + 'T00:00:00Z');
    if (!when || isNaN(when.getTime())) errors.specificDate = 'Please pick the date you need it by.';
    else if (when < startOfToday) errors.specificDate = 'That date has already passed.';
    else if (when.getTime() - startOfToday.getTime() > 2 * 366 * 24 * 3600 * 1000) errors.specificDate = 'Please pick a date within the next two years.';
    else clean.specificDate = s;
  }

  clean.additionalNotes = mugText_(d.additionalNotes, 1000);
  return { ok: Object.keys(errors).length === 0, errors: errors, clean: clean };
}

function mugTimelineText_(row) {
  const t = MUG_TIMELINES[row.timeline] || row.timeline || '';
  return row.timeline === 'specific_date' && row.specificDate ? 'By ' + row.specificDate : t;
}

function mugBudgetText_(row) {
  const amount = Number(row.budgetAmount) || 0;
  return '₹' + amount.toLocaleString('en-IN') + ' ' + (MUG_BUDGET_TYPES[row.budgetType] || row.budgetType || '')
    + (row.budgetRange ? ' (' + row.budgetRange + ')' : '');
}

function mugQuantityText_(row) {
  return row.quantityExact ? row.quantityExact + ' mugs' : (row.quantityRange === '1' ? '1 mug' : row.quantityRange + ' mugs');
}

/**
 * The manufacturer RFQ text for one enquiry: the same block can be sent
 * to several ceramic manufacturers for a quote. It carries no customer
 * contact details (those stay with SwapSutra) and states that capacity is
 * approximate until prototyping.
 */
function buildMugManufacturerBrief_(row) {
  const lines = [
    'CUSTOM MUG REQUEST',
    'Reference: ' + row.id,
    '',
    'Idea:',
    String(row.idea || ''),
    '',
    'Style: ' + (row.mugType || ''),
    'Capacity: ' + (row.volumeMl ? row.volumeMl + ' ml' : '') + (row.volumeRange && row.volumeRange !== 'Custom' ? ' (range ' + row.volumeRange + ')' : '')
      + ' — approximate; final usable volume to be confirmed at prototype',
    'Quantity: ' + mugQuantityText_(row),
    'Customer budget: ' + mugBudgetText_(row),
    'Delivery pincode: ' + (row.pincode || '') + (row.city || row.state ? ' (' + [row.city, row.state].filter(String).join(', ') + ')' : ''),
    'Timeline: ' + mugTimelineText_(row),
    'Reference image: ' + (row.referenceImageUrl || 'none'),
    'Additional notes: ' + (row.additionalNotes || 'none')
  ];
  return lines.join('\n');
}

function mugEnquirySheet_() {
  const sheet = getOrCreateSheet('CustomMugEnquiries', MUG_ENQUIRY_HEADERS);
  ensureSheetHeaders(sheet, MUG_ENQUIRY_HEADERS);
  return sheet;
}

function newMugEnquiryId_(now) {
  const ymd = new Date(now.getTime() + 330 * 60 * 1000).toISOString().slice(0, 10).replace(/-/g, '');
  return 'MUG-' + ymd + '-' + Utilities.getUuid().replace(/-/g, '').slice(0, 5).toUpperCase();
}

/** Public: a visitor sends a custom mug idea. */
function submitCustomMugEnquiry(data) {
  try {
    const d = data || {};
    // Honeypot: a hidden field a person never fills. Answer as if it
    // worked so a bot learns nothing, but store nothing.
    if (String(d.website || '').trim()) return { success: true, id: 'MUG-RECEIVED' };

    const v = validateCustomMugEnquiry_(d, new Date());
    if (!v.ok) return { success: false, error: 'VALIDATION', message: 'Please check the highlighted fields.', fieldErrors: v.errors };

    // Rate limits: the same email at most 5 an hour; the whole form at
    // most 120 an hour, so a script cannot flood the sheet or Drive.
    try {
      const cache = CacheService.getScriptCache();
      const perEmailKey = 'mug_enq_' + v.clean.email.replace(/[^a-z0-9]/g, '').slice(0, 60);
      const mine = Number(cache.get(perEmailKey) || 0);
      const all = Number(cache.get('mug_enq_all') || 0);
      if (mine >= 5 || all >= 120) return { success: false, error: 'RATE_LIMITED', message: 'We have received several ideas from you already. Please try again in an hour.' };
      cache.put(perEmailKey, String(mine + 1), 3600);
      cache.put('mug_enq_all', String(all + 1), 3600);
    } catch (e) { /* the cache is a courtesy, not a gate */ }

    // Optional reference image: jpg / png / webp only, already shrunk by the
    // browser; refused (not silently dropped) if it is anything else.
    let imageUrl = '';
    const img = String(d.referenceImage || '');
    if (img) {
      const mm = img.match(/^data:(image\/(?:jpeg|jpg|png|webp));base64,/);
      if (!mm) return { success: false, error: 'VALIDATION', message: 'The reference image must be a JPG, PNG or WebP.', fieldErrors: { referenceImage: 'Use a JPG, PNG or WebP image.' } };
      const bytes = Math.floor((img.length - mm[0].length) * 3 / 4);
      if (bytes > MUG_IMAGE_MAX_BYTES) return { success: false, error: 'VALIDATION', message: 'The reference image is too large.', fieldErrors: { referenceImage: 'Please use an image under 1.5 MB.' } };
      imageUrl = saveFileToDrive(img, 'mug-reference.' + (mm[1].split('/')[1] === 'jpeg' ? 'jpg' : mm[1].split('/')[1]));
      if (!imageUrl) return { success: false, error: 'UPLOAD_FAILED', message: 'We could not save your reference image. Please try again, or send the idea without it.' };
    }

    const now = new Date();
    const row = Object.assign({}, v.clean, {
      id: newMugEnquiryId_(now),
      createdAt: now,
      referenceImageUrl: imageUrl,
      status: 'new',
      adminNotes: '',
      assignedManufacturer: '',
      lastUpdatedAt: now
    });
    const sheet = mugEnquirySheet_();
    const headers = sheet.getDataRange().getValues()[0].map(function (h) { return String(h).trim(); });
    sheet.appendRow(headers.map(function (h) { return row[h] === undefined ? '' : row[h]; }));

    // Emails are best-effort: the idea is already safely stored.
    try {
      const owner = String(PropertiesService.getScriptProperties().getProperty('MUG_ENQUIRY_NOTIFY_EMAIL') || 'swapsutra@gmail.com').trim();
      sendSwapSutraEmail(owner, 'New custom mug idea — ' + row.id + ' (' + mugQuantityText_(row) + ', ' + mugBudgetText_(row) + ')',
        buildMugManufacturerBrief_(row) + '\n\nCustomer (internal only): ' + row.name + ' · ' + row.email + ' · ' + row.phone);
    } catch (e) { Logger.log('mug enquiry owner email failed: ' + e); }
    try {
      const first = escapeHtml(row.name.split(' ')[0]);
      sendSwapSutraEmail({
        to: row.email,
        subject: 'Your mug idea is on its way (' + row.id + ')',
        htmlBody: getBrandedEmailTemplate('Your mug idea is on its way',
          '<p>Hi ' + first + ',</p>'
          + '<p>Thank you for sending us your mug idea. We will review it, check what kind of manufacturing it needs, and get back to you with the next step.</p>'
          + '<p style="padding:14px;border-left:4px solid #8E4A59;background:#FAF7F2;">' + escapeHtml(row.idea.slice(0, 400)) + (row.idea.length > 400 ? '…' : '') + '</p>'
          + '<p>Your reference: <strong>' + row.id + '</strong>. Nothing is confirmed yet — no price, maker or delivery date — until we have reviewed it with you.</p>')
      });
    } catch (e) { Logger.log('mug enquiry customer email failed: ' + e); }

    return { success: true, id: row.id };
  } catch (err) {
    Logger.log('submitCustomMugEnquiry failed: ' + err);
    return { success: false, error: 'SERVER', message: 'We could not save your idea just now. Please try again in a minute.' };
  }
}

/** Admin: every enquiry, newest first, with its manufacturer brief. */
function getAdminCustomMugEnquiries(data) {
  if (!isAuthenticatedAdmin()) return { success: false, message: 'Unauthorized' };
  const values = mugEnquirySheet_().getDataRange().getValues();
  const headers = values[0].map(function (h) { return String(h).trim(); });
  const items = values.slice(1).filter(function (r) { return r.some(String); }).map(function (r) {
    const row = {};
    headers.forEach(function (h, i) { row[h] = r[i] instanceof Date ? r[i].toISOString() : r[i]; });
    row.manufacturerBrief = buildMugManufacturerBrief_(row);
    return row;
  }).reverse();
  return { success: true, items: items, statuses: MUG_ENQUIRY_STATUSES };
}

/** Admin: status, internal notes, manufacturer. Nothing else can change. */
function updateCustomMugEnquiry(data) {
  if (!isAuthenticatedAdmin()) return { success: false, message: 'Unauthorized' };
  const id = String((data && data.id) || '');
  const sheet = mugEnquirySheet_();
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(function (h) { return String(h).trim(); });
  const idIdx = headers.indexOf('id');
  for (let r = 1; r < values.length; r++) {
    if (String(values[r][idIdx]) !== id) continue;
    const set = function (name, value) { const i = headers.indexOf(name); if (i !== -1) sheet.getRange(r + 1, i + 1).setValue(value); };
    if (data.status !== undefined) {
      if (MUG_ENQUIRY_STATUSES.indexOf(String(data.status)) === -1) return { success: false, message: 'Unknown status.' };
      set('status', String(data.status));
    }
    if (data.adminNotes !== undefined) set('adminNotes', mugText_(data.adminNotes, 5000));
    if (data.assignedManufacturer !== undefined) set('assignedManufacturer', mugText_(data.assignedManufacturer, 200));
    set('lastUpdatedAt', new Date());
    return { success: true, message: 'Enquiry updated.' };
  }
  return { success: false, message: 'Enquiry not found.' };
}

/**
 * Public: the mug shelf. Only rows marked live, only http(s) links, and
 * only the fields a shopper needs. A price cut (MRP) and a rating are
 * passed on only when the row actually carries them from its source.
 */
function getMugProducts() {
  try {
    const sheet = getOrCreateSheet('MugProducts', MUG_PRODUCT_HEADERS);
    ensureSheetHeaders(sheet, MUG_PRODUCT_HEADERS);
    const values = sheet.getDataRange().getValues();
    const headers = values[0].map(function (h) { return String(h).trim(); });
    const httpUrl = function (u) { u = String(u || '').trim(); return /^https:\/\/[^\s]+$/i.test(u) ? u : ''; };
    const num = function (n) { n = Number(n); return isFinite(n) && n > 0 ? n : null; };
    const items = values.slice(1).map(function (r) {
      const o = {};
      headers.forEach(function (h, i) { o[h] = r[i]; });
      return o;
    }).filter(function (o) {
      return String(o.status || '').toLowerCase() === 'live' && String(o.title || '').trim()
        && MUG_CATEGORY_IDS.indexOf(String(o.category || '').trim()) !== -1;
    }).map(function (o) {
      const price = num(o.price), mrp = num(o.mrp);
      const rating = Number(o.rating);
      const hasRating = isFinite(rating) && rating > 0 && rating <= 5 && String(o.ratingSource || '').trim();
      return {
        id: String(o.id || ''), title: mugText_(o.title, 120), description: mugText_(o.description, 400),
        category: String(o.category).trim(), imageUrl: httpUrl(o.imageUrl),
        price: price, mrp: mrp && price && mrp > price ? mrp : null, currency: String(o.currency || 'INR'),
        availability: mugText_(o.availability, 40), sourceMarketplace: mugText_(o.sourceMarketplace, 40),
        sourceUrl: httpUrl(o.sourceUrl), affiliateUrl: httpUrl(o.affiliateUrl), vendor: mugText_(o.vendor, 60),
        rating: hasRating ? Math.round(rating * 10) / 10 : null, ratingCount: hasRating ? (Number(o.ratingCount) || null) : null,
        ratingSource: hasRating ? mugText_(o.ratingSource, 40) : '', sortOrder: Number(o.sortOrder) || 0
      };
    }).sort(function (a, b) { return a.sortOrder - b.sortOrder; });
    return { success: true, items: items };
  } catch (err) {
    Logger.log('getMugProducts failed: ' + err);
    return { success: false, items: [], message: 'The mug shelf could not be loaded.' };
  }
}


// =====================================================================
// SPONSORED ADS — bookstores, authors and books (9 Oct 2026)
// ---------------------------------------------------------------------
// The admin places an ad for a bookstore, an author or a particular book.
// It shows on the Library's banner, between the books on the shelf, or
// both. Every ad is labelled "Sponsored" on the site and its link opens
// with rel="sponsored". A "book" ad may point at a SwapSutra listing
// (bookId) instead of an outside link.
//
//   SponsoredAds   one row per ad; status live / paused / removed.
//                  startDate / endDate (optional, yyyy-mm-dd, IST) limit
//                  when a live ad shows. clicks is a simple counter.
// =====================================================================

const AD_HEADERS = [
  'id', 'kind', 'sponsor', 'headline', 'tagline', 'imageUrl', 'linkUrl', 'bookId',
  'ctaLabel', 'placement', 'status', 'startDate', 'endDate', 'clicks',
  'createdAt', 'updatedAt', 'createdBy',
  // A partner's own ad (9 Oct 2026): it waits as "pending" until the admin approves it.
  'partnerId', 'reviewNote'
];
const AD_KINDS = ['bookstore', 'author', 'book'];
const AD_PLACEMENTS = ['both', 'banner', 'shelf'];
const AD_STATUSES = ['live', 'paused', 'removed', 'pending', 'rejected'];
const AD_IMAGE_MAX_BYTES = 2 * 1024 * 1024;

function adSheet_() {
  const sheet = getOrCreateSheet('SponsoredAds', AD_HEADERS);
  ensureSheetHeaders(sheet, AD_HEADERS);
  return sheet;
}

function adRows_() {
  const values = adSheet_().getDataRange().getValues();
  if (!values.length) return { headers: AD_HEADERS.slice(), rows: [] };
  const headers = values[0].map(function (h) { return String(h).trim(); });
  const rows = [];
  for (let i = 1; i < values.length; i++) {
    const o = {};
    headers.forEach(function (h, j) { o[h] = values[i][j] instanceof Date ? values[i][j].toISOString() : values[i][j]; });
    if (String(o.id || '').trim()) rows.push({ rowIndex: i, obj: o });
  }
  return { headers: headers, rows: rows };
}

/** yyyy-mm-dd for "today" in India. */
function adTodayIst_(now) {
  const d = new Date((now ? now.getTime() : Date.now()) + 5.5 * 3600e3);
  return d.toISOString().slice(0, 10);
}
function adDate_(v) {
  if (v instanceof Date) return new Date(v.getTime() + 5.5 * 3600e3).toISOString().slice(0, 10);
  const s = String(v || '').trim();
  return /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0, 10) : '';
}

/** Is this ad on the site right now? */
function adIsShowing_(o, today) {
  if (String(o.status || '').toLowerCase() !== 'live') return false;
  const start = adDate_(o.startDate), end = adDate_(o.endDate);
  if (start && today < start) return false;
  if (end && today > end) return false;
  return true;
}

/**
 * Public: the ads to show now. Only what a visitor needs — no click
 * counts, no admin details.
 */
function getSponsoredAds() {
  try {
    const today = adTodayIst_();
    const https = function (u) { u = String(u || '').trim(); return /^https:\/\/[^\s]+$/i.test(u) ? u : ''; };
    const partnersById = {};
    try { partnerRows_().rows.forEach(function (r) { partnersById[String(r.obj.id)] = r.obj; }); } catch (e) { /* no partners yet */ }
    const items = adRows_().rows.map(function (r) { return r.obj; })
      .filter(function (o) { return adIsShowing_(o, today) && String(o.headline || '').trim() && (https(o.linkUrl) || String(o.bookId || '').trim()); })
      // A partner's ad runs only while their promotion is paid up (or free) and they want ads.
      .filter(function (o) { return !String(o.partnerId || '') || partnerPromotionLive_(partnersById[String(o.partnerId)], 'ads'); })
      .map(function (o) {
        const placement = AD_PLACEMENTS.indexOf(String(o.placement)) === -1 ? 'both' : String(o.placement);
        return {
          id: String(o.id), kind: AD_KINDS.indexOf(String(o.kind)) === -1 ? 'book' : String(o.kind),
          sponsor: mugText_(o.sponsor, 80), headline: mugText_(o.headline, 90), tagline: mugText_(o.tagline, 160),
          imageUrl: https(o.imageUrl), linkUrl: https(o.linkUrl), bookId: mugText_(o.bookId, 60),
          ctaLabel: mugText_(o.ctaLabel, 30), placement: placement, partner: !!String(o.partnerId || '')
        };
      }).concat(partnerBannerAds_());
    return { success: true, items: items };
  } catch (err) {
    Logger.log('getSponsoredAds failed: ' + err);
    return { success: true, items: [] };
  }
}

/** Public: count a click (no reader details are stored). */
function recordAdClick(data) {
  const id = String((data || {}).id || '').trim();
  if (!id) return { success: false };
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(3000)) return { success: false };
  try {
    const sheet = adSheet_();
    const all = adRows_();
    const hit = all.rows.find(function (r) { return String(r.obj.id) === id; });
    if (!hit || !adIsShowing_(hit.obj, adTodayIst_())) return { success: false };
    const col = all.headers.indexOf('clicks');
    sheet.getRange(hit.rowIndex + 1, col + 1).setValue((Number(hit.obj.clicks) || 0) + 1);
    return { success: true };
  } finally {
    lock.releaseLock();
  }
}

function getAdminSponsoredAds() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const today = adTodayIst_();
  const items = adRows_().rows.map(function (r) { return r.obj; })
    .filter(function (o) { return String(o.status || '').toLowerCase() !== 'removed'; })
    .map(function (o) {
      const partner = String(o.partnerId || '') ? ((partnerRows_().rows.find(function (r) { return String(r.obj.id) === String(o.partnerId); }) || {}).obj || null) : null;
      return Object.assign({}, o, { startDate: adDate_(o.startDate), endDate: adDate_(o.endDate), clicks: Number(o.clicks) || 0,
        showingNow: adIsShowing_(o, today) && (!partner || partnerPromotionLive_(partner, 'ads')),
        partnerName: partner ? partner.name : '', partnerPromotionActive: partner ? partnerPromotionLive_(partner, 'ads') : null });
    });
  return { success: true, items: items, kinds: AD_KINDS, placements: AD_PLACEMENTS, statuses: AD_STATUSES };
}

/** Validation shared by save and the tests. Returns { errors, clean }. */
function validateSponsoredAd_(data) {
  const d = data || {};
  const errors = {};
  const https = function (u) { u = String(u || '').trim(); return /^https:\/\/[^\s]+$/i.test(u) ? u.slice(0, 1000) : ''; };
  const status = String(d.status || 'live').toLowerCase();
  const clean = {
    kind: String(d.kind || '').toLowerCase(), sponsor: mugText_(d.sponsor, 80), headline: mugText_(d.headline, 90),
    tagline: mugText_(d.tagline, 160), imageUrl: https(d.imageUrl), linkUrl: https(d.linkUrl), bookId: mugText_(d.bookId, 60),
    ctaLabel: mugText_(d.ctaLabel, 30), placement: String(d.placement || 'both').toLowerCase(), status: status,
    startDate: adDate_(d.startDate), endDate: adDate_(d.endDate)
  };
  if (AD_STATUSES.indexOf(status) === -1) errors.status = 'Unknown status.';
  if (status === 'removed') return { errors: errors, clean: clean };
  if (status === 'rejected') { clean.status = 'rejected'; }
  if (AD_KINDS.indexOf(clean.kind) === -1) errors.kind = 'Choose bookstore, author or book.';
  if (AD_PLACEMENTS.indexOf(clean.placement) === -1) errors.placement = 'Choose where the ad shows.';
  if (!clean.sponsor) errors.sponsor = 'Who is the ad for? (the bookstore, author or publisher)';
  if (!clean.headline) errors.headline = 'Write a short headline.';
  if (String(d.linkUrl || '').trim() && !clean.linkUrl) errors.linkUrl = 'The link must start with https://.';
  if (!clean.linkUrl && !(clean.kind === 'book' && clean.bookId)) errors.linkUrl = clean.kind === 'book'
    ? 'Paste a link (https://) or pick the SwapSutra listing.' : 'Paste the link the ad opens (https://).';
  if (String(d.imageUrl || '').trim() && !clean.imageUrl) errors.imageUrl = 'The image link must start with https://.';
  if (!clean.imageUrl) errors.imageUrl = 'Add the ad picture (upload one or paste an https:// link).';
  if (String(d.startDate || '').trim() && !clean.startDate) errors.startDate = 'Use a date like 2026-10-15.';
  if (String(d.endDate || '').trim() && !clean.endDate) errors.endDate = 'Use a date like 2026-10-31.';
  if (clean.startDate && clean.endDate && clean.endDate < clean.startDate) errors.endDate = 'The end date is before the start date.';
  return { errors: errors, clean: clean };
}

function saveSponsoredAd(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const v = validateSponsoredAd_(data);
  if (Object.keys(v.errors).length) return { success: false, errors: v.errors, message: 'Please fix the highlighted fields.' };
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const sheet = adSheet_();
    const all = adRows_();
    const headers = all.headers;
    const id = String((data || {}).id || '').trim();
    const hit = id ? all.rows.find(function (r) { return String(r.obj.id) === id; }) : null;
    if (id && !hit) return { success: false, message: 'That ad no longer exists.' };
    const now = new Date().toISOString();
    const rec = hit ? Object.assign({}, hit.obj) : { id: 'AD-' + Utilities.getUuid().slice(0, 8).toUpperCase(), clicks: 0, createdAt: now, createdBy: getAuthenticatedEmail() || '' };
    const wasPending = hit && String(hit.obj.status) === 'pending';
    if (v.clean.status === 'removed') rec.status = 'removed';
    else Object.keys(v.clean).forEach(function (k) { rec[k] = v.clean[k]; });
    if (rec.partnerId && hit) rec.sponsor = hit.obj.sponsor; // a partner's ad keeps the partner's name
    rec.reviewNote = v.clean.status === 'rejected' ? mugText_((data || {}).reviewNote, 300) : '';
    rec.updatedAt = now;
    if (rec.partnerId && wasPending && (rec.status === 'live' || rec.status === 'rejected')) {
      try {
        const partner = (partnerRows_().rows.find(function (r) { return String(r.obj.id) === String(rec.partnerId); }) || {}).obj;
        if (partner) returnNotify_(partner.email, 'partner_ad_review', rec.status === 'live' ? 'Your ad is approved' : 'Your ad needs a change',
          rec.status === 'live' ? '"' + rec.headline + '" is approved and runs on the Library page.' : '"' + rec.headline + '" was not approved' + (rec.reviewNote ? ': ' + rec.reviewNote : '.'),
          '', 'partner_ad_rev_' + rec.id + '_' + Date.now());
      } catch (e) { /* saved */ }
    }
    const row = headers.map(function (h) { return rec[h] !== undefined ? rec[h] : ''; });
    if (hit) sheet.getRange(hit.rowIndex + 1, 1, 1, row.length).setValues([row]);
    else sheet.appendRow(row);
    return { success: true, id: rec.id };
  } finally {
    lock.releaseLock();
  }
}

/** Admin: upload the ad picture to Drive and get back a link for it. */
function uploadSponsoredAdImage(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  return savePublicImage_(data, 'SwapSutra_Ads', 'ad_');
}

// =====================================================================
// PAYMENT DETAILS — editable by the admin (9 Oct 2026, owner's request:
// "admin kabhi bhi chahe toh apna personal qr code or bank details change
// kar sakta hai"). Stored in the Script Property PAYMENT_DETAILS_JSON; every
// payment box on the site (exchange payments, listing unlock, partner ad
// fees, Support SwapSutra) reads paymentDetails_(). Each change is logged
// in the PaymentSettingsLog sheet.
// =====================================================================

const PAYMENT_DETAILS_PROP = 'PAYMENT_DETAILS_JSON';
const PAYMENT_LOG_HEADERS = ['changedAt', 'changedBy', 'vpa', 'payee', 'qrImageUrl', 'useQrImage', 'bankAccountName', 'bankAccountLast4', 'ifsc', 'bankName'];

function paymentDetails_() {
  let saved = {};
  try { saved = JSON.parse(readScriptProperty_(PAYMENT_DETAILS_PROP) || '{}') || {}; } catch (e) { saved = {}; }
  const bank = saved.bank || {};
  const hasBank = !!(bank.accountNumber || bank.ifsc);
  return {
    vpa: String(saved.vpa || SWAPSM_UPI_VPA),
    payee: String(saved.payee || SWAPSM_UPI_PAYEE),
    qrImageUrl: String(saved.qrImageUrl || ''),
    useQrImage: !!(saved.useQrImage && saved.qrImageUrl),
    bank: hasBank ? { accountName: String(bank.accountName || ''), accountNumber: String(bank.accountNumber || ''), ifsc: String(bank.ifsc || ''), bankName: String(bank.bankName || '') } : null
  };
}

/** Public: what a payer needs to pay SwapSutra. */
function getPaymentDetails() {
  return { success: true, upi: paymentDetails_() };
}

function getAdminPaymentSettings() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  let meta = {};
  try { meta = JSON.parse(readScriptProperty_(PAYMENT_DETAILS_PROP) || '{}') || {}; } catch (e) { meta = {}; }
  return { success: true, upi: paymentDetails_(), updatedAt: meta.updatedAt || '', updatedBy: meta.updatedBy || '' };
}

function validatePaymentSettings_(data) {
  const d = data || {};
  const errors = {};
  const vpa = String(d.vpa || '').trim();
  const payee = mugText_(d.payee, 60);
  const qrImageUrl = String(d.qrImageUrl || '').trim();
  const b = d.bank || {};
  const accountNumber = String(b.accountNumber || '').replace(/\s+/g, '');
  const ifsc = String(b.ifsc || '').trim().toUpperCase();
  if (!/^[a-zA-Z0-9.\-_]{2,256}@[a-zA-Z][a-zA-Z0-9.\-]{1,64}$/.test(vpa)) errors.vpa = 'Enter a UPI ID like name@okhdfcbank.';
  if (payee.length < 2) errors.payee = 'Enter the name shown in UPI apps.';
  if (qrImageUrl && !/^https:\/\/[^\s]+$/i.test(qrImageUrl)) errors.qrImageUrl = 'The QR picture link must start with https://.';
  if (d.useQrImage && !qrImageUrl) errors.qrImageUrl = 'Upload your QR picture first.';
  if (accountNumber && !/^\d{6,20}$/.test(accountNumber)) errors.accountNumber = 'Account number: 6 to 20 digits.';
  if (ifsc && !/^[A-Z]{4}0[A-Z0-9]{6}$/.test(ifsc)) errors.ifsc = 'IFSC looks like HDFC0001234.';
  if ((accountNumber && !ifsc) || (!accountNumber && ifsc)) errors[accountNumber ? 'ifsc' : 'accountNumber'] = 'Give both the account number and the IFSC (or neither).';
  return {
    errors: errors,
    clean: {
      vpa: vpa, payee: payee, qrImageUrl: qrImageUrl, useQrImage: !!(d.useQrImage && qrImageUrl),
      bank: accountNumber ? { accountName: mugText_(b.accountName, 80), accountNumber: accountNumber, ifsc: ifsc, bankName: mugText_(b.bankName, 60) } : null
    }
  };
}

function saveAdminPaymentSettings(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const v = validatePaymentSettings_(data);
  if (Object.keys(v.errors).length) return { success: false, errors: v.errors, message: 'Please fix the highlighted fields.' };
  const who = getAuthenticatedEmail() || '';
  const rec = Object.assign({}, v.clean, { updatedAt: new Date().toISOString(), updatedBy: who });
  PropertiesService.getScriptProperties().setProperty(PAYMENT_DETAILS_PROP, JSON.stringify(rec));
  try {
    const sheet = getOrCreateSheet('PaymentSettingsLog', PAYMENT_LOG_HEADERS);
    const h = ensureSheetHeaders(sheet, PAYMENT_LOG_HEADERS);
    const b = rec.bank || {};
    const row = { changedAt: new Date(), changedBy: who, vpa: rec.vpa, payee: rec.payee, qrImageUrl: rec.qrImageUrl, useQrImage: rec.useQrImage ? 'yes' : 'no',
      bankAccountName: b.accountName || '', bankAccountLast4: b.accountNumber ? String(b.accountNumber).slice(-4) : '', ifsc: b.ifsc || '', bankName: b.bankName || '' };
    sheet.appendRow(h.map(function (k) { return row[k] !== undefined ? row[k] : ''; }));
  } catch (e) { /* the saved setting is what matters */ }
  return { success: true, upi: paymentDetails_() };
}

/** Admin: upload SwapSutra's own UPI QR picture. */
function uploadPaymentQrImage(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  return savePublicImage_(data, 'SwapSutra_Payment', 'upi_qr_');
}

/** A JPG/PNG/WebP data URL (≤2 MB) → a public picture link in a Drive folder. */
function savePublicImage_(data, folderName, prefix) {
  const raw = String((data || {}).dataUrl || '');
  const m = /^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+\/=]+)$/.exec(raw);
  if (!m) return { success: false, message: 'Choose a JPG, PNG or WebP picture.' };
  const bytes = Utilities.base64Decode(m[2]);
  if (bytes.length > 2 * 1024 * 1024) return { success: false, message: 'The picture is too large (2 MB at most).' };
  try {
    const folder = getOrCreateFolder(folderName);
    const file = folder.createFile(Utilities.newBlob(bytes, m[1], prefix + Date.now() + '.' + m[1].split('/')[1]));
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return { success: true, url: 'https://drive.google.com/thumbnail?id=' + file.getId() + '&sz=w1600' };
  } catch (err) {
    Logger.log('savePublicImage_ failed: ' + err);
    return { success: false, message: 'The picture could not be saved. Try again.' };
  }
}


/* =========================================================================
   SwapSutra — free registration, per-exchange platform fee, listing allowance
   (Oct 2026)

   Wired into: computeSubscriptionStatus, hasApprovedActiveSubscription,
   checkSubscription, createBook, securityFeeRequirements,
   ensureSecurityFeeRecords, securityFeeStatus and doPost.

   WHAT CHANGES
   1. Registration is free and permanent. Name + email + phone, verified by
      OTP, is a full member. No ₹49, no 30-day trial, nothing expires.
   2. Every swap / lend / rent / sell charges a small platform fee to BOTH
      readers, paid by UPI QR after the owner accepts. It rides on the
      existing SecurityFeePayments flow: one QR, one UTR, one admin approval,
      and the chat unlocks when both are approved. Where a refundable deposit
      also applies, the QR amount is deposit + fee, and the two are stored
      separately so refunds never touch the fee.
   3. Every reader may list up to 20 books free. A one-time ₹20 (QR, admin
      verified) or the code BOOKSTORE2627 removes the limit for good.

   SETTINGS can be overridden without redeploying, via Project Settings →
   Script Properties:
     PLATFORM_FEE_PER_PARTY   e.g. "10"
     FREE_LISTING_LIMIT       e.g. "20"
     LISTING_UNLOCK_FEE       e.g. "20"
     LISTING_UNLOCK_COUPONS   comma-separated, e.g. "BOOKSTORE2627,LAUNCHWEEK"
   ========================================================================= */

// The switch. A function rather than a const so it is hoisted: it is read
// from computeSubscriptionStatus, which other code may call before this
// part of the file has been evaluated.
function freeRegistrationMode_() { return true; }

const PLATFORM_FEE_DEFAULT = 10;          // ₹ per reader, per exchange
// Exchanges created before this moment keep the old rules, so no chat that
// is already open gets locked behind a new fee. Set it to your launch time.
const PLATFORM_FEE_START_ISO = '2026-10-06T00:00:00+05:30';

const FREE_LISTING_LIMIT_DEFAULT = 20;
const LISTING_UNLOCK_FEE_DEFAULT = 20;    // ₹, one time, unlimited after
const LISTING_UNLOCK_COUPONS_DEFAULT = ['BOOKSTORE2627'];

const LISTING_UNLOCK_SHEET = 'ListingUnlocks';
const LISTING_UNLOCK_HEADERS = [
  'id', 'email', 'method', 'amount', 'couponCode', 'utr', 'screenshotUrl',
  'status', 'rejectedReason', 'reviewedBy', 'reviewedAt', 'createdAt', 'updatedAt'
];
const LISTING_UTR_PATTERN = /^[A-Za-z0-9]{4,25}$/;

// ── Settings ────────────────────────────────────────────────────────────

function readScriptProperty_(key) {
  try {
    return PropertiesService.getScriptProperties().getProperty(key);
  } catch (e) {
    return null;
  }
}

function numberSetting_(key, fallback) {
  const raw = readScriptProperty_(key);
  const n = Number(raw);
  return raw !== null && raw !== '' && isFinite(n) && n >= 0 ? Math.round(n) : fallback;
}

function platformFeePerParty_() { return numberSetting_('PLATFORM_FEE_PER_PARTY', PLATFORM_FEE_DEFAULT); }
function freeListingLimit_() { return numberSetting_('FREE_LISTING_LIMIT', FREE_LISTING_LIMIT_DEFAULT); }
function listingUnlockFee_() { return numberSetting_('LISTING_UNLOCK_FEE', LISTING_UNLOCK_FEE_DEFAULT); }

function listingUnlockCoupons_() {
  const raw = readScriptProperty_('LISTING_UNLOCK_COUPONS');
  const list = raw ? String(raw).split(',') : LISTING_UNLOCK_COUPONS_DEFAULT;
  return list.map(c => String(c).trim().toUpperCase()).filter(Boolean);
}

// ── 1. Free registration ────────────────────────────────────────────────

/** A reader is a member once they have an account row. Nothing expires. */
function isRegisteredReader_(email) {
  const normEmail = normalizeEmail(email);
  if (!normEmail) return false;
  if (isAdminEmail(normEmail)) return true;
  if (approvedPartner_(normEmail)) return true;

  const sub = findRowByEmail_('Subscriptions', normEmail);
  if (sub) {
    const admin = String(sub.adminStatus || '').trim().toLowerCase();
    const status = String(sub.membershipStatus || '').trim().toUpperCase();
    // Cancelled is the one way an account stops being a member: it is how
    // an admin suspends someone.
    return admin !== 'cancelled' && status !== 'CANCELLED';
  }
  return !!findRowByEmail_('Users', normEmail);
}

function findRowByEmail_(sheetName, normEmail) {
  const values = getOrCreateSheet(sheetName, []).getDataRange().getValues();
  if (values.length <= 1) return null;
  const headers = values[0].map(h => String(h).trim());
  const emailIdx = headers.indexOf('email');
  if (emailIdx === -1) return null;
  const row = values.slice(1).find(r => normalizeEmail(r[emailIdx]) === normEmail);
  return row ? rowToObject(headers, row) : null;
}

/**
 * The checkSubscription answer for a registered reader in free mode.
 *
 * Status is reported as 'TRIAL' on purpose: the proxy, server.ts and the
 * app all already treat TRIAL as "active member", so nothing downstream
 * needs to learn a new word. daysRemainingValid is false so no countdown
 * is shown, and nothing ever flips it to EXPIRED.
 */
function freeMemberCheckSubscriptionResponse_(email, sub, profileUser) {
  const normEmail = normalizeEmail(email);
  const source = sub || profileUser || {};
  const admin = String(source.adminStatus || '').trim().toLowerCase();
  const mStatus = String(source.membershipStatus || '').trim().toUpperCase();
  if (admin === 'cancelled' || mStatus === 'CANCELLED') {
    return {
      success: true, isRegistered: false, status: 'CANCELLED', membershipStatus: 'CANCELLED',
      userTier: 'expired', isPremium: false, isTrial: false, isExpired: false,
      message: 'This account has been suspended. Contact swapsutra@gmail.com.'
    };
  }

  const booksListedCount = recalculateBooksListedCount(normEmail);
  return {
    success: true,
    isRegistered: true,
    isFreeMember: true,
    status: 'TRIAL',
    membershipStatus: 'TRIAL',
    userTier: 'trial',
    isPremium: false,
    isTrial: true,
    isExpired: false,
    daysRemainingValid: false,
    trialStartDate: '',
    trialEndDate: '',
    subscriptionStartDate: '',
    subscriptionExpiry: '',
    listingAllowance: getListingAllowanceFor_(normEmail, booksListedCount),
    subscription: Object.assign({}, source, {
      email: normEmail,
      name: source.name || 'Reader',
      computedStatus: 'TRIAL',
      membershipStatus: 'TRIAL',
      activationType: 'free',
      membershipType: 'free',
      adminStatus: 'Approved',
      paymentRequired: 'No',
      booksListedCount: booksListedCount,
      booksRemaining: Math.max(0, freeListingLimit_() - booksListedCount),
      subscriptionExpiry: '',
      trialEndDate: ''
    })
  };
}

// ── 2. Platform fee on every exchange ───────────────────────────────────

function platformFeeAppliesToSwap_(swapObj) {
  const created = new Date(swapObj && swapObj.createdAt);
  if (isNaN(created.getTime())) return true; // undated rows are new rows
  return created.getTime() >= new Date(PLATFORM_FEE_START_ISO).getTime();
}

/**
 * Replaces the body of securityFeeRequirements(). Who pays what on an
 * exchange, from amounts the server already resolved — never from the
 * request payload.
 *
 *   SWAP          requester: deposit + fee     owner: deposit + fee
 *   RENT/LEND/SELL requester: deposit + fee    owner: fee
 *
 * A party owing nothing (pre-launch exchange, zero deposit) gets no row,
 * exactly as before. The admin account never pays a platform fee.
 */
function computeExchangePayments_(swap) {
  const obj = swap.obj || {};
  const serviceType = String(obj.serviceType || 'SWAP').trim().toUpperCase();
  const feeApplies = platformFeeAppliesToSwap_(obj);
  const baseFee = feeApplies ? platformFeePerParty_() : 0;

  const requesterDeposit = Math.max(0, Math.round(Number(obj.securityDeposit || 0)));
  const ownerDeposit = serviceType === 'SWAP'
    ? Math.max(0, Math.round(Number(obj.ownerDeposit || 0)))
    : 0;

  const reqs = [];
  // A sale through SwapSutra (Oct 2026): the buyer pays the owner's price
  // plus the platform fee to SwapSutra; SwapSutra holds the price until the
  // buyer confirms they have the book, then pays the seller. The seller
  // pays nothing up front — their own fee comes out of the payout.
  if (serviceType === 'SELL' && saleEscrowAppliesToSwap_(obj)) {
    const saleAmount = Math.max(0, Math.round(Number(obj.amount || 0)));
    const fee = isAdminEmail(swap.requesterEmail) ? 0 : baseFee;
    if (swap.requesterEmail && saleAmount + fee > 0) {
      reqs.push({ payerRole: 'requester', payerEmail: swap.requesterEmail, requiredAmount: saleAmount + fee,
        depositAmount: 0, platformFee: fee, saleAmount: saleAmount });
    }
    return reqs;
  }
  // 9 Oct 2026 (owner's rule): in a swap the ₹10 fee is not paid up front —
  // it is taken out of the deposit when the deposit is refunded.
  const feeFromDeposit = serviceType === 'SWAP' && swapFeeFromDeposit_(obj);
  const add = (payerRole, payerEmail, depositAmount) => {
    if (!payerEmail) return;
    // Partners (9 Oct 2026) pay no platform fee; a buyer always pays it.
    const platformFee = isAdminEmail(payerEmail) || approvedPartner_(payerEmail) || (feeFromDeposit && depositAmount > 0) ? 0 : baseFee;
    const requiredAmount = depositAmount + platformFee;
    if (requiredAmount <= 0) return;
    reqs.push({ payerRole, payerEmail, requiredAmount, depositAmount, platformFee, saleAmount: 0 });
  };
  add('requester', swap.requesterEmail, requesterDeposit);
  // 9 Oct 2026 (owner's rule): on a lend only the borrower pays the fee.
  if (serviceType !== 'LEND') add('owner', swap.ownerEmail, ownerDeposit);
  return reqs;
}

// Swaps requested from this moment take the ₹10 fee from the deposit refund;
// earlier swaps keep the fee they were quoted (paid with the deposit).
const SWAP_FEE_FROM_DEPOSIT_START_ISO = '2026-10-09T22:30:00+05:30';
function swapFeeFromDeposit_(obj) {
  if (String((obj && obj.serviceType) || 'SWAP').toUpperCase() !== 'SWAP') return false;
  if (!platformFeeAppliesToSwap_(obj)) return false;
  const created = new Date(obj && obj.createdAt);
  if (isNaN(created.getTime())) return true;
  return created.getTime() >= new Date(SWAP_FEE_FROM_DEPOSIT_START_ISO).getTime();
}

/** The fee SwapSutra keeps from this reader's swap deposit (0 when it was paid up front). */
function feeTakenFromDeposit_(swapObj, payerEmail, feeRec) {
  if (!swapFeeFromDeposit_(swapObj) || isAdminEmail(payerEmail) || approvedPartner_(payerEmail)) return 0;
  // Never charge twice: a reader who already paid the fee up front (e.g. a
  // payment made before this rule went live) has nothing taken.
  if (feeRec && feeRecordBreakdown_(feeRec).platformFee > 0) return 0;
  return platformFeePerParty_();
}
function myFeeRecord_(swapId, role) {
  try {
    const rows = loadSecurityFeeRows(String(swapId)).rows.map(r => r.obj).filter(o => o.payerRole === role && o.adminStatus !== 'NOT_REQUIRED');
    return rows.find(o => o.adminStatus === 'ADMIN_APPROVED') || rows[0] || null;
  } catch (e) { return null; }
}

// Sales made from this moment on go through SwapSutra (escrow). Earlier
// sales keep their old arrangement (paid directly between readers).
const SALE_ESCROW_START_ISO = '2026-10-08T00:00:00+05:30';
/**
 * Is SwapSutra actually holding the price of this sale? Escrow by date, unless
 * the buyer's payment was already verified for the fee alone (a sale whose
 * payment row predates escrow) — then the price was paid between readers and
 * SwapSutra must not pay the seller from money it never received. (9 Oct 2026)
 */
function saleEscrowActive_(swap) {
  if (!saleEscrowAppliesToSwap_(swap.obj)) return false;
  try {
    const buyerRow = loadSecurityFeeRows(swap.obj.id).rows.map(r => r.obj)
      .find(r => r.payerRole === 'requester' && (r.adminStatus === 'ADMIN_APPROVED' || r.adminStatus === 'ADMIN_PENDING'));
    if (buyerRow && !(feeRecordBreakdown_(buyerRow).saleAmount > 0)) return false;
  } catch (e) { /* no rows yet: escrow by date */ }
  return true;
}

function saleEscrowAppliesToSwap_(obj) {
  const created = new Date(obj && obj.createdAt);
  if (isNaN(created.getTime())) return true;
  return created.getTime() >= new Date(SALE_ESCROW_START_ISO).getTime();
}

/** Splits a SecurityFeePayments row into deposit and fee (old rows: all deposit). */
function feeRecordBreakdown_(rec) {
  const total = Number(rec.requiredAmount || 0);
  const fee = Number(rec.platformFee || 0);
  const sale = Number(rec.saleAmount || 0);
  const depositRaw = rec.depositAmount;
  const deposit = depositRaw === '' || depositRaw === undefined || depositRaw === null
    ? Math.max(0, total - fee - sale)
    : Number(depositRaw);
  return { depositAmount: deposit, platformFee: fee, saleAmount: sale };
}

/** Public quote for the request modal, so readers see the fee before asking. */
function getPlatformFeeQuote() {
  return {
    success: true,
    platformFeePerParty: platformFeePerParty_(),
    freeListingLimit: freeListingLimit_(),
    listingUnlockFee: listingUnlockFee_()
  };
}

// ── 3. Listing allowance ────────────────────────────────────────────────

function getListingUnlockSheet_() {
  const sheet = getOrCreateSheet(LISTING_UNLOCK_SHEET, LISTING_UNLOCK_HEADERS);
  ensureSheetHeaders(sheet, LISTING_UNLOCK_HEADERS);
  return sheet;
}

function loadListingUnlockRows_() {
  const sheet = getListingUnlockSheet_();
  const values = sheet.getDataRange().getValues();
  const headers = (values[0] || LISTING_UNLOCK_HEADERS).map(h => String(h).trim());
  const rows = [];
  for (let r = 1; r < values.length; r++) {
    rows.push({ rowIndex: r, obj: rowToObject(headers, values[r]) });
  }
  return { sheet, headers, rows };
}

// Oct 2026 (owner's rule): a paid unlock (₹20) lasts 3 months; after that
// the reader pays again to add more books (books already listed stay). A
// coupon unlock (a partner code) does not expire.
const LISTING_UNLOCK_DAYS = 90;

/** When a paid unlock stops covering new listings (ms), or Infinity for a coupon. */
function listingUnlockExpiresAt_(obj) {
  if (String(obj.method || '').toUpperCase() === 'COUPON') return Infinity;
  const from = new Date(obj.reviewedAt || obj.createdAt).getTime();
  return isFinite(from) ? from + LISTING_UNLOCK_DAYS * 24 * 60 * 60 * 1000 : Infinity;
}

function listingUnlockStateFor_(normEmail, rows) {
  const mine = (rows || loadListingUnlockRows_().rows).filter(r => normalizeEmail(r.obj.email) === normEmail);
  const now = Date.now();
  const approvedAll = mine.filter(r => String(r.obj.status).toUpperCase() === 'APPROVED');
  const approved = approvedAll.filter(r => listingUnlockExpiresAt_(r.obj) > now)
    .sort((a, b) => listingUnlockExpiresAt_(b.obj) - listingUnlockExpiresAt_(a.obj))[0] || null;
  const expired = !approved && approvedAll.length ? approvedAll[approvedAll.length - 1] : null;
  const pending = mine.find(r => String(r.obj.status).toUpperCase() === 'PENDING') || null;
  const rejected = mine.filter(r => String(r.obj.status).toUpperCase() === 'REJECTED').pop() || null;
  return { approved, pending, rejected, expired };
}

/** How many books this reader may list, and how to lift the limit. */
function getListingAllowanceFor_(email, knownUsed) {
  const normEmail = normalizeEmail(email);
  const used = typeof knownUsed === 'number' ? knownUsed : recalculateBooksListedCount(normEmail);
  const limit = freeListingLimit_();
  // Partners (9 Oct 2026) list without a limit.
  const state = isAdminEmail(normEmail) ? { approved: { obj: { method: 'ADMIN' } } }
    : approvedPartner_(normEmail) ? { approved: { obj: { method: 'PARTNER' } } }
    : listingUnlockStateFor_(normEmail);
  const unlimited = !!state.approved;
  return {
    used: used,
    limit: unlimited ? null : limit,
    unlimited: unlimited,
    unlockedVia: unlimited ? String(state.approved.obj.method || '') : '',
    // A paid unlock lasts 3 months (Oct 2026).
    unlockedUntil: unlimited && state.approved.obj && isFinite(listingUnlockExpiresAt_(state.approved.obj)) ? new Date(listingUnlockExpiresAt_(state.approved.obj)).toISOString() : '',
    unlockExpired: !unlimited && !!state.expired,
    unlockDays: LISTING_UNLOCK_DAYS,
    remaining: unlimited ? null : Math.max(0, limit - used),
    canList: unlimited || used < limit,
    unlockFee: listingUnlockFee_(),
    pendingUnlock: state.pending ? {
      id: state.pending.obj.id,
      submittedAt: state.pending.obj.createdAt,
      utr: state.pending.obj.utr
    } : null,
    lastRejection: !unlimited && !state.pending && state.rejected ? {
      reason: state.rejected.obj.rejectedReason || '',
      at: state.rejected.obj.reviewedAt || ''
    } : null
  };
}

function listingLimitMessage_(allowance) {
  if (allowance.pendingUnlock) {
    return `You've listed ${allowance.used} of ${allowance.limit} free books. Your ₹${allowance.unlockFee} unlock payment is being verified — you can add more as soon as it's approved.`;
  }
  if (allowance.unlockExpired) {
    return `Your 3 months of extra listings have ended. Pay ₹${allowance.unlockFee} to list more books for another 3 months — your books already listed stay.`;
  }
  return `You've listed ${allowance.used} of ${allowance.limit} free books. If you'd like to list more, it's ₹${allowance.unlockFee} for 3 months.`;
}

/** Action: getListingAllowance */
function getListingAllowance() {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to see your listing allowance.' };
  return {
    success: true,
    allowance: getListingAllowanceFor_(caller),
    upi: paymentDetails_()
  };
}

/**
 * Action: redeemListingUnlockCoupon — removed 9 Oct 2026 (owner's request).
 * Coupon codes are no longer accepted; bookstores, authors, publishers and
 * promoters register as SwapSutra partners (unlimited listings) instead.
 * Unlocks already granted by a coupon stay as they are.
 */
function redeemListingUnlockCoupon() {
  return { success: false, error: 'COUPONS_REMOVED',
    message: 'Coupon codes are no longer used. A bookstore, author, publisher or promoter can register as a SwapSutra partner at /partners to list without a limit.' };
}

/** Action: submitListingUnlockPayment { utr, fileData, fileName } */
function submitListingUnlockPayment(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to submit a payment.' };
  if (!isRegisteredReader_(caller)) return { success: false, error: 'MEMBERSHIP_REQUIRED', message: 'Sign up first — it is free.' };

  const { sheet, headers, rows } = loadListingUnlockRows_();
  const state = listingUnlockStateFor_(caller, rows);
  if (state.approved) return { success: false, message: 'You can already list more books' + (isFinite(listingUnlockExpiresAt_(state.approved.obj)) ? ' until ' + returnDateLabel_(new Date(listingUnlockExpiresAt_(state.approved.obj))) : '') + '.' };
  if (state.pending) return { success: false, message: 'Your payment is already being verified. You will be notified when it is approved.' };

  const utr = String((data && data.utr) || '').trim();
  if (!LISTING_UTR_PATTERN.test(utr)) return { success: false, message: 'Enter the UTR / transaction reference from your UPI app (letters and numbers only).' };
  if (utrAlreadyUsed_(utr, rows)) return { success: false, message: 'That UTR has already been submitted. Each payment can only be used once.' };

  let screenshotUrl = '';
  if (data && data.fileData) {
    screenshotUrl = saveFileToDrive(data.fileData, data.fileName || 'listing_unlock_payment.jpg') || '';
  }
  if (!screenshotUrl) return { success: false, message: 'Attach a screenshot of the payment (JPG or PNG).' };

  const now = new Date();
  const amount = listingUnlockFee_();
  appendUnlockRow_(sheet, headers, {
    id: generateId('SS_UNLOCK_'), email: caller, method: 'PAYMENT', amount: amount, utr: utr,
    screenshotUrl: screenshotUrl, status: 'PENDING', createdAt: now, updatedAt: now
  });

  createNotification(
    'swapsutra@gmail.com', 'listing_unlock_submitted', 'Listing unlock payment to verify',
    `${caller} paid ₹${amount} to list more books for 3 months (UTR ${utr}). Please review.`,
    '', { link: '/management' }
  );
  return { success: true, allowance: getListingAllowanceFor_(caller), message: 'Payment submitted. SwapSutra will verify it shortly.' };
}

function utrAlreadyUsed_(utr, unlockRows) {
  const target = String(utr).trim().toUpperCase();
  const inUnlocks = (unlockRows || loadListingUnlockRows_().rows).some(r =>
    String(r.obj.utr || '').trim().toUpperCase() === target &&
    String(r.obj.status).toUpperCase() !== 'REJECTED');
  if (inUnlocks) return true;
  try {
    const values = getOrCreateSheet('SecurityFeePayments', []).getDataRange().getValues();
    if (values.length <= 1) return false;
    const h = values[0].map(x => String(x).trim());
    const utrIdx = h.indexOf('utr');
    const adminIdx = h.indexOf('adminStatus');
    if (utrIdx === -1) return false;
    return values.slice(1).some(r =>
      String(r[utrIdx] || '').trim().toUpperCase() === target &&
      String(r[adminIdx] || '') !== 'ADMIN_REJECTED');
  } catch (e) {
    return false;
  }
}

function appendUnlockRow_(sheet, headers, obj) {
  sheet.appendRow(headers.map(h => obj[h] !== undefined ? obj[h] : ''));
}

/** Admin action: adminListListingUnlocks { includeReviewed? } */
function adminListListingUnlocks(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  const includeReviewed = !!(data && data.includeReviewed);
  const items = loadListingUnlockRows_().rows
    .map(r => r.obj)
    .filter(o => includeReviewed || String(o.status).toUpperCase() === 'PENDING')
    .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  return { success: true, items: items, count: items.length };
}

/** Admin action: adminReviewListingUnlock { id, decision: APPROVE|REJECT, reason? } */
function adminReviewListingUnlock(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  const id = String((data && data.id) || '').trim();
  const decision = String((data && data.decision) || '').trim().toUpperCase() === 'REJECT' ? 'REJECT' : 'APPROVE';
  const reason = String((data && data.reason) || '').trim().slice(0, 500);

  const { sheet, headers, rows } = loadListingUnlockRows_();
  const row = rows.find(r => String(r.obj.id) === id);
  if (!row) return { success: false, message: 'Unlock request not found.' };
  if (String(row.obj.status).toUpperCase() !== 'PENDING') return { success: false, message: 'This request has already been reviewed.' };
  if (decision === 'REJECT' && !reason) return { success: false, message: 'Give the reader a reason, so they know what to fix.' };

  const now = new Date();
  const setCell = (name, value) => {
    const idx = headers.indexOf(name);
    if (idx !== -1) sheet.getRange(row.rowIndex + 1, idx + 1).setValue(value);
  };
  setCell('status', decision === 'APPROVE' ? 'APPROVED' : 'REJECTED');
  setCell('rejectedReason', decision === 'REJECT' ? reason : '');
  setCell('reviewedBy', normalizeEmail(getAuthenticatedEmail()));
  setCell('reviewedAt', now);
  setCell('updatedAt', now);

  createNotification(
    row.obj.email,
    decision === 'APPROVE' ? 'listing_unlock_approved' : 'listing_unlock_rejected',
    decision === 'APPROVE' ? 'More listings unlocked for 3 months' : 'Your listing unlock payment needs attention',
    decision === 'APPROVE'
      ? 'Your payment is verified. You can list as many books as you like for the next 3 months.'
      : `We couldn't verify your payment: ${reason}. Please submit it again from Add a book.`,
    row.obj.id,
    { link: '/profile', dedupeKey: 'unlock_' + decision.toLowerCase() + '_' + row.obj.id }
  );
  return { success: true, message: decision === 'APPROVE' ? 'Approved.' : 'Rejected.' };
}

/** Admin action: adminPlatformRevenueSummary — fees actually verified. */
function adminPlatformRevenueSummary() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  let exchangeFees = 0;
  let exchangePayments = 0;
  const feeValues = getOrCreateSheet('SecurityFeePayments', []).getDataRange().getValues();
  if (feeValues.length > 1) {
    const h = feeValues[0].map(x => String(x).trim());
    feeValues.slice(1).forEach(r => {
      const rec = rowToObject(h, r);
      if (rec.adminStatus !== 'ADMIN_APPROVED') return;
      const fee = feeRecordBreakdown_(rec).platformFee;
      if (fee > 0) { exchangeFees += fee; exchangePayments++; }
    });
  }
  // Swap fees taken from deposit refunds (9 Oct 2026).
  readSheetObjects_(getReturnForfeitSheet_()).rows.forEach(r => {
    if (String(r.obj.payoutStatus) !== 'KEPT_AS_FEE' || String(r.obj.leg) === 'commission') return;
    exchangeFees += Number(r.obj.amount || 0); exchangePayments++;
  });
  const partnerMoney = partnerRevenue_();
  let unlockFees = 0;
  let unlocksPaid = 0;
  let unlocksByCoupon = 0;
  loadListingUnlockRows_().rows.forEach(r => {
    if (String(r.obj.status).toUpperCase() !== 'APPROVED') return;
    if (r.obj.method === 'COUPON') { unlocksByCoupon++; return; }
    unlockFees += Number(r.obj.amount || 0);
    unlocksPaid++;
  });
  return {
    success: true,
    exchangeFees, exchangePayments,
    unlockFees, unlocksPaid, unlocksByCoupon,
    partnerAdFees: partnerMoney.partnerAdFees, partnerAdPayments: partnerMoney.partnerAdPayments, partnerCommission: partnerMoney.partnerCommission,
    total: Math.round((exchangeFees + unlockFees + partnerMoney.partnerAdFees + partnerMoney.partnerCommission) * 100) / 100
  };
}


/* ════════════════════════════════════════════════════════════════════════
   SWAP MATCHING (Oct 2026)
   ────────────────────────────────────────────────────────────────────────
   Owner's rule: two books can be swapped only when they are
     • the same condition grade,
     • the same type — Paperback, Hardcover or Budget copy (a reprint), and
     • the same rate — printed MRPs within 10% of each other.
   src/utils/swapMatch.ts mirrors this so the swap form can grey out books
   that won't qualify; this copy is the one that decides.
   ════════════════════════════════════════════════════════════════════════ */

const SWAP_MRP_TOLERANCE = 0.10;

/** PAPERBACK, HARDCOVER or BUDGET (a reprint, whatever its binding); UNKNOWN otherwise. */
function swapBookType_(book) {
  if (!book) return 'UNKNOWN';
  if (bookEditionFrom(book) === 'REPRINT') return 'BUDGET';
  const fmt = normalizeBookFormat(book.bookFormat || book.format);
  return fmt === 'HARDCOVER' || fmt === 'PAPERBACK' ? fmt : 'UNKNOWN';
}

const SWAP_TYPE_LABELS = { PAPERBACK: 'paperback', HARDCOVER: 'hardcover', BUDGET: 'budget copy', UNKNOWN: 'unknown type' };
const SWAP_CONDITION_LABELS = { AS_NEW: 'Like New', VERY_GOOD: 'Very Good', GOOD: 'Good', FAIR: 'Fair', POOR: 'Poor' };

function swapBooksMatch_(a, b) {
  if (!a || !b) return { ok: false, reasons: ['missing'], message: 'Choose one of your books to offer in exchange.' };
  const reasons = [];
  const parts = [];

  const ca = normalizeConditionGrade(a.condition), cb = normalizeConditionGrade(b.condition);
  if (ca !== cb) {
    reasons.push('condition');
    parts.push('condition (' + SWAP_CONDITION_LABELS[ca] + ' vs ' + SWAP_CONDITION_LABELS[cb] + ')');
  }

  const ta = swapBookType_(a), tb = swapBookType_(b);
  if (ta === 'UNKNOWN' || tb === 'UNKNOWN') {
    reasons.push('type_unknown');
    parts.push('type (one of the books has no type set — edit the listing to add Paperback, Hardcover or Budget copy)');
  } else if (ta !== tb) {
    reasons.push('type');
    parts.push('type (' + SWAP_TYPE_LABELS[ta] + ' vs ' + SWAP_TYPE_LABELS[tb] + ')');
  }

  const ma = effectiveBookMRP(a), mb = effectiveBookMRP(b);
  if (ma === null || mb === null || !(Number(ma) > 0) || !(Number(mb) > 0)) {
    reasons.push('mrp_unknown');
    parts.push('MRP (one of the books has no MRP yet)');
  } else {
    const hi = Math.max(Number(ma), Number(mb));
    if (Math.abs(Number(ma) - Number(mb)) > hi * SWAP_MRP_TOLERANCE) {
      reasons.push('mrp');
      parts.push('MRP (₹' + Math.round(ma) + ' vs ₹' + Math.round(mb) + ' — more than 10% apart)');
    }
  }

  if (!reasons.length) return { ok: true, reasons: [], message: '' };
  return {
    ok: false,
    reasons: reasons,
    message: 'These two books can\'t be swapped: they differ in ' + parts.join(', ') + '. A swap needs the same condition, the same type and an MRP within 10%.'
  };
}


/* ════════════════════════════════════════════════════════════════════════
   LOCATION IN THE EXCHANGE CHAT (Oct 2026)
   ────────────────────────────────────────────────────────────────────────
   The chat blocks typed phone numbers and addresses (scanMessageForPII), so
   a meeting point travels as structured data instead: a pin (lat/lng) and a
   short place name, sent as a message with mediaType 'location' and
   mediaUrl 'geo:<lat>,<lng>?q=<name>'. The app draws it as a map card.
   ════════════════════════════════════════════════════════════════════════ */

/** A place name for a pin: short, and with long digit runs (phone numbers) removed. */
function cleanPlaceLabel_(raw) {
  return String(raw || '')
    .replace(/\d[\d\s-]{5,}\d/g, '')   // no phone numbers smuggled in as a "place"
    .replace(/[<>]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 80);
}

function locationMediaUrl_(pin, label) {
  return 'geo:' + pin.lat + ',' + pin.lng + (label ? '?q=' + encodeURIComponent(label) : '');
}

/** Action: shareChatLocation { chatId, lat, lng, label } — sender is the session. */
function shareChatLocation(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to share a location.' };
  const chatId = String((data && data.chatId) || '').trim();
  const chat = getChatById(chatId);
  if (!chat) return { success: false, message: 'Chat not found.' };
  if (!canAccessChat(chat, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  const pin = cleanLatLng_(data && data.lat, data && data.lng);
  if (!pin) return { success: false, message: 'That location could not be read. Try placing the pin again.' };
  const label = cleanPlaceLabel_(data && data.label);
  // sendChatMessage applies every existing gate: membership, the
  // security-fee lock, archived chats, and the PII scan on the text.
  return sendChatMessage({
    chatId: chatId,
    senderEmail: caller,
    senderRole: isAdminEmail(caller) ? 'Admin' : 'User',
    message: '📍 ' + (label ? 'Meeting point: ' + label : 'Shared a location'),
    mediaUrl: locationMediaUrl_(pin, label),
    mediaType: 'location'
  });
}

/** Posts the agreed route into the exchange chat, as SwapSutra. Never throws. */
function postRouteNoticeToChat_(swap, method, place, pin, isReturn) {
  try {
    const chat = findChatBySwapId(swap.obj.id);
    const chatId = chat && (chat.chatId || chat.id);
    if (!chatId) return;
    const label = cleanPlaceLabel_(place);
    sendChatMessage({
      chatId: chatId,
      senderEmail: 'swapsutra@gmail.com',
      senderRole: 'Admin',
      message: (isReturn ? '📌 Step 12 · Return route: ' : '📌 Step 6 · Route: ') + (method === 'courier'
        ? 'courier. Your addresses and phone numbers are now visible to each other at the top of this room. Add the courier and tracking ID there once the parcel is booked.'
        : 'meeting in person' + (label ? ' at ' + label : '') + '. Meet somewhere public, record the handover video, and both mark it at the top of this room.'),
      mediaUrl: pin ? locationMediaUrl_(pin, label) : '',
      mediaType: pin ? 'location' : ''
    });
  } catch (err) {
    Logger.log('postRouteNoticeToChat_ failed: ' + err);
  }
}


/* ════════════════════════════════════════════════════════════════════════
   RETURN DEADLINES — 21 days, strict (Oct 2026, owner's rules)
   ────────────────────────────────────────────────────────────────────────
   Applies to every exchange where a book has to come back: RENT, LEND and
   a TEMPORARY swap (in which both books come back).

   • The clock starts when the book reaches the borrower — the first
     handed_over / delivered / received on the way out.
   • By the end of day 21 the book must be ON ITS WAY BACK: handed over in
     person, or posted with the courier name and tracking ID filled in.
     A courier that is slow after that is not the borrower's fault — the
     deadline is met the moment it is posted (courier-delay exception).
   • One extension of +7 days: with 7 days left a reminder goes into the
     exchange chat; in the next 3 days the reader who has the book can ask
     for +7, and it applies if the owner agrees (Exchange Room, Oct 2026).
   • If the deadline passes and the book is not on its way back, the
     borrower's security deposit is forfeited to the book's owner. That
     is recorded here and SwapSutra pays it out to the owner.
   • Reminders go out at the start, with 7, 3 and 1 days left, on the last
     day, and when a deposit is forfeited — in the app, by email, and on
     WhatsApp when the WhatsApp Business API is configured.

   runReturnDeadlines() is the daily job (installReturnDeadlineTrigger()
   sets it up once).
   ════════════════════════════════════════════════════════════════════════ */

// RETURN_WINDOW_DAYS (21) is defined once, with the stage machine above.
// Oct 2026 (owner's rule, Exchange Room): one extension of +7 days, asked
// for by the reader who has the book in the 3 days after the "7 days left"
// reminder, and agreed by the owner.
const RETURN_EXTENSION_CHOICES = [7];
const RETURN_MAX_EXTENSION_DAYS = 7;
const RETURN_EXTENSION_NOTICE_DAYS = 7;   // the reminder goes out with 7 days left
const RETURN_EXTENSION_WINDOW_DAYS = 3;   // ...and +7 can be asked for in the 3 days after it
const RETURN_REMINDER_DAYS_LEFT = [7, 3, 1];
const RETURN_DAY_MS = 24 * 60 * 60 * 1000;

const RETURN_EXTENSION_SHEET = 'ReturnExtensions';
const RETURN_EXTENSION_HEADERS = ['id', 'swapId', 'requestedBy', 'days', 'reason', 'status', 'decidedBy', 'createdAt', 'decidedAt'];
const RETURN_FORFEIT_SHEET = 'ReturnForfeits';
const RETURN_FORFEIT_HEADERS = ['id', 'swapId', 'leg', 'bookTitle', 'defaulterEmail', 'ownerEmail', 'amount', 'dueAt', 'forfeitedAt', 'payoutStatus', 'paidAt', 'paidBy', 'note',
  // Partners (9 Oct 2026): the month a partner payout is paid in, and the amount before commission.
  'payoutCycle', 'grossAmount'];

const RETURN_POLICY_TEXT =
  'Return rule: the book must be on its way back within 21 days of reaching you — handed over in person, ' +
  'or posted with the courier name and tracking ID added by the end of day 21. With 7 days left you get a reminder, ' +
  'and in the next 3 days the reader who has the book can ask for +7 days once; it applies if the owner agrees. If the book is not on its way back by the deadline, the security deposit ' +
  'is forfeited and paid to the book\'s owner. Courier delays after the book is posted are not held against you.';

/** Does this exchange have to come back, and which legs carry the returns? */
function returnLegsFor_(swapObj) {
  const type = String(swapObj.serviceType || 'SWAP').toUpperCase();
  if (type === 'RENT' || type === 'LEND') return [{ leg: 'return', outLeg: 'outbound', borrower: 'requester', owner: 'owner', deposit: 'securityDeposit' }];
  const temporary = String(swapObj.swapPreference || swapObj.swapType || '').toLowerCase() === 'temporary';
  if (type === 'SWAP' && temporary) {
    return [
      // The requester returns the owner's book; their deposit protects it.
      { leg: 'return', outLeg: 'outbound', borrower: 'requester', owner: 'owner', deposit: 'securityDeposit' },
      // The owner returns the requester's book; the owner's deposit protects it.
      { leg: 'counter_return', outLeg: 'counter', borrower: 'owner', owner: 'requester', deposit: 'ownerDeposit' }
    ];
  }
  return [];
}

function getReturnExtensionSheet_() {
  const sheet = getOrCreateSheet(RETURN_EXTENSION_SHEET, RETURN_EXTENSION_HEADERS);
  ensureSheetHeaders(sheet, RETURN_EXTENSION_HEADERS);
  return sheet;
}
function getReturnForfeitSheet_() {
  const sheet = getOrCreateSheet(RETURN_FORFEIT_SHEET, RETURN_FORFEIT_HEADERS);
  ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  return sheet;
}
function readSheetObjects_(sheet) {
  const values = sheet.getDataRange().getValues();
  if (values.length <= 1) return { headers: (values[0] || []).map(h => String(h).trim()), rows: [] };
  const headers = values[0].map(h => String(h).trim());
  return { headers: headers, rows: values.slice(1).map((r, i) => ({ rowIndex: i + 1, obj: rowToObject(headers, r) })) };
}

/** All journey events, grouped by swap id. */
function journeyEventsBySwap_() {
  const out = {};
  readSheetObjects_(getJourneySheet()).rows.forEach(r => {
    const id = String(r.obj.swapId);
    (out[id] = out[id] || []).push(r.obj);
  });
  return out;
}

/**
 * The full return picture for one exchange. Pure apart from its inputs, so
 * the rules can be tested without a spreadsheet.
 *   events      — that swap's journey rows
 *   extensions  — that swap's ReturnExtensions rows
 *   forfeits    — that swap's ReturnForfeits rows
 */
function computeReturnState_(swapObj, events, extensions, forfeits, nowMs, stageInfo) {
  const legs = returnLegsFor_(swapObj);
  if (!legs.length) return { applies: false };
  const now = typeof nowMs === 'number' ? nowMs : Date.now();
  const at = e => new Date(e.createdAt).getTime();
  const stage = stageInfo || {};

  // Start: the first moment a book reached its borrower — from the delivery
  // timeline, or from the Stages panel's receipt confirmation.
  const outLegs = legs.map(l => l.outLeg);
  const arrivals = (events || [])
    .filter(e => outLegs.indexOf(String(e.leg)) !== -1 && ['handed_over', 'delivered', 'received'].indexOf(String(e.event)) !== -1)
    .map(at).filter(t => isFinite(t));
  if (isFinite(stage.receiptAt)) arrivals.push(stage.receiptAt);
  if (!arrivals.length) {
    return { applies: true, started: false, windowDays: RETURN_WINDOW_DAYS, policy: RETURN_POLICY_TEXT, legs: [] };
  }
  const startedAt = Math.min.apply(null, arrivals);
  const approved = (extensions || []).filter(x => String(x.status).toUpperCase() === 'APPROVED');
  const extensionDays = Math.min(RETURN_MAX_EXTENSION_DAYS, approved.reduce((n, x) => n + (Number(x.days) || 0), 0));
  const baseDueAt = startedAt + RETURN_WINDOW_DAYS * RETURN_DAY_MS;
  const dueAt = baseDueAt + extensionDays * RETURN_DAY_MS;
  const pending = (extensions || []).filter(x => String(x.status).toUpperCase() === 'PENDING')[0] || null;

  const legStates = legs.map(l => {
    const sent = (events || []).filter(e => String(e.leg) === l.leg && (
      e.event === 'handed_over' ||
      (e.event === 'dispatched' && String(e.awb || '').trim()) ||
      e.event === 'delivered' || e.event === 'received'))
      .map(at).filter(t => isFinite(t));
    // The borrower confirming the return in the Stages panel counts too.
    const stageReturn = stage.returnByRole && stage.returnByRole[l.borrower];
    if (l.leg === 'return' && isFinite(stageReturn)) sent.push(stageReturn);
    sent.sort((a, b) => a - b);
    const firstSent = sent.length ? sent[0] : null;
    const forfeited = (forfeits || []).some(f => String(f.leg) === l.leg);
    let state;
    if (forfeited) state = 'FORFEITED';
    else if (firstSent !== null && firstSent <= dueAt) state = 'RETURNED_ON_TIME';
    else if (firstSent !== null) state = 'RETURNED_LATE';   // after the deadline — the forfeit job decides
    else if (now > dueAt) state = 'OVERDUE';
    else state = 'DUE';
    return { leg: l.leg, borrower: l.borrower, owner: l.owner, deposit: l.deposit, state: state, sentAt: firstSent };
  });

  const msLeft = dueAt - now;
  // The +7 window: from the "7 days left" reminder, for 3 days.
  const windowOpensAt = baseDueAt - RETURN_EXTENSION_NOTICE_DAYS * RETURN_DAY_MS;
  const windowClosesAt = windowOpensAt + RETURN_EXTENSION_WINDOW_DAYS * RETURN_DAY_MS;
  const askedBefore = (extensions || []).length > 0;
  const anyDue = legStates.some(l => l.state === 'DUE');
  return {
    applies: true,
    started: true,
    extensionWindow: {
      opensAt: new Date(windowOpensAt).toISOString(),
      closesAt: new Date(windowClosesAt).toISOString(),
      open: now >= windowOpensAt && now <= windowClosesAt && !askedBefore && extensionDays < RETURN_MAX_EXTENSION_DAYS && anyDue,
      used: askedBefore
    },
    windowDays: RETURN_WINDOW_DAYS,
    startedAt: new Date(startedAt).toISOString(),
    baseDueAt: new Date(baseDueAt).toISOString(),
    dueAt: new Date(dueAt).toISOString(),
    extensionDays: extensionDays,
    extensionDaysLeft: RETURN_MAX_EXTENSION_DAYS - extensionDays,
    extensionChoices: RETURN_EXTENSION_CHOICES.filter(d => d <= RETURN_MAX_EXTENSION_DAYS - extensionDays),
    pendingExtension: pending ? { id: pending.id, days: Number(pending.days), requestedBy: pending.requestedBy, reason: pending.reason || '' } : null,
    daysLeft: Math.ceil(msLeft / RETURN_DAY_MS),
    overdue: msLeft < 0,
    legs: legStates,
    policy: RETURN_POLICY_TEXT
  };
}

/**
 * From the Stages panel's event log: when the book was confirmed received
 * (the latest RECEIPT confirmation, i.e. when both had confirmed), and when
 * each party first confirmed a RETURN.
 */
function stageReturnInfoBySwap_() {
  const out = {};
  readSheetObjects_(getStageEventsSheet()).rows.forEach(r => {
    const o = r.obj;
    const id = String(o.swapId);
    const t = new Date(o.createdAt).getTime();
    if (!isFinite(t)) return;
    const info = out[id] = out[id] || { receiptAt: NaN, returnByRole: {} };
    if (o.stage === 'RECEIPT') info.receiptAt = isFinite(info.receiptAt) ? Math.max(info.receiptAt, t) : t;
    if (o.stage === 'RETURN' && (o.party === 'requester' || o.party === 'owner')) {
      const prev = info.returnByRole[o.party];
      info.returnByRole[o.party] = isFinite(prev) ? Math.min(prev, t) : t;
    }
  });
  return out;
}

/** Loads everything for one swap and computes its return state. */
function returnStateForSwap_(swap) {
  const id = String(swap.obj.id);
  const events = (journeyEventsBySwap_()[id]) || [];
  const exts = readSheetObjects_(getReturnExtensionSheet_()).rows.map(r => r.obj).filter(o => String(o.swapId) === id);
  const forfeits = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj).filter(o => String(o.swapId) === id);
  let stage = null;
  try { stage = stageReturnInfoBySwap_()[id] || null; } catch (e) { stage = null; }
  return computeReturnState_(swap.obj, events, exts, forfeits, undefined, stage);
}

/** Action: getReturnStatus { swapId } — either party. */
function getReturnStatus(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (!callerIsPartyTo(swap, caller) && !isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  const state = returnStateForSwap_(swap);
  const myRole = caller === swap.ownerEmail ? 'owner' : 'requester';
  if (state.legs) state.legs.forEach(l => { l.youAreBorrower = l.borrower === myRole; l.youAreOwner = l.owner === myRole; });
  if (state.pendingExtension) state.pendingExtension.youAsked = normalizeEmail(state.pendingExtension.requestedBy) === caller;
  delete (state.pendingExtension || {}).requestedBy;
  return Object.assign({ success: true, policy: RETURN_POLICY_TEXT }, state);
}

/** Action: requestReturnExtension { swapId, days: 7|14, reason? } */
function requestReturnExtension(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (!callerIsPartyTo(swap, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  const days = Number(data && data.days);
  const state = returnStateForSwap_(swap);
  if (!state.applies) return { success: false, message: 'This exchange has no return date.' };
  if (!state.started) return { success: false, message: 'The return clock starts when the book reaches the borrower.' };
  if (state.overdue) return { success: false, error: 'DEADLINE_PASSED', message: 'The return deadline has passed, so it can no longer be extended.' };
  if (state.legs.every(l => l.state !== 'DUE')) return { success: false, message: 'The book is already on its way back.' };
  if (state.pendingExtension) return { success: false, message: 'There is already an extension request waiting for an answer.' };
  if (RETURN_EXTENSION_CHOICES.indexOf(days) === -1) return { success: false, message: 'An extension is +7 days.' };
  // The reader who has the book asks; the owner agrees. (In a temporary
  // swap both readers hold a book, so either may ask.)
  if (String(swap.obj.serviceType || 'SWAP').toUpperCase() !== 'SWAP' && caller !== swap.requesterEmail) {
    return { success: false, error: 'WRONG_PARTY', message: 'The reader who has the book asks for more time; you agree or decline it.' };
  }
  if (state.extensionWindow && state.extensionWindow.used) {
    return { success: false, error: 'EXTENSION_LIMIT', message: 'An extension can be asked for once per exchange.' };
  }
  if (state.extensionWindow && !state.extensionWindow.open) {
    return { success: false, error: 'EXTENSION_WINDOW', message: '+7 days can be asked for between ' +
      returnDateLabel_(new Date(state.extensionWindow.opensAt)) + ' and ' + returnDateLabel_(new Date(state.extensionWindow.closesAt)) + ' (the 3 days after the 7-days-left reminder).' };
  }
  if (days > state.extensionDaysLeft) {
    return { success: false, error: 'EXTENSION_LIMIT', message: state.extensionDaysLeft > 0
      ? 'Only ' + state.extensionDaysLeft + ' more days can be added.'
      : 'This exchange has already been extended by 7 days.' };
  }
  const sheet = getReturnExtensionSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_EXTENSION_HEADERS);
  const obj = {
    id: generateId('SS_EXT_'), swapId: swap.obj.id, requestedBy: caller, days: days,
    reason: String((data && data.reason) || '').trim().slice(0, 200), status: 'PENDING', createdAt: new Date()
  };
  sheet.appendRow(headers.map(h => obj[h] !== undefined ? obj[h] : ''));
  const other = caller === swap.ownerEmail ? swap.requesterEmail : swap.ownerEmail;
  returnNotify_(other, 'return_extension_requested', 'Return extension requested',
    'The other reader has asked to extend the return of "' + (swap.obj.requestedBookTitle || 'the book') + '" by ' + days +
    ' days. Open the exchange to accept or decline. It only applies if you agree.',
    swap.obj.id, 'ext_req_' + obj.id, { whatsapp: false });
  return { success: true, message: 'Extension requested. It applies once the other reader agrees.' };
}

/** Action: respondReturnExtension { swapId, extensionId, accept: true|false } — the OTHER party only. */
function respondReturnExtension(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (!callerIsPartyTo(swap, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  const sheet = getReturnExtensionSheet_();
  const t = readSheetObjects_(sheet);
  const row = t.rows.find(r => String(r.obj.id) === String(data && data.extensionId) && String(r.obj.swapId) === String(swap.obj.id));
  if (!row) return { success: false, message: 'That extension request could not be found.' };
  if (String(row.obj.status).toUpperCase() !== 'PENDING') return { success: false, message: 'That request has already been answered.' };
  if (normalizeEmail(row.obj.requestedBy) === caller) return { success: false, error: 'WRONG_PARTY', message: 'The other reader has to agree to an extension, not the one who asked.' };
  const state = returnStateForSwap_(swap);
  const accept = data && (data.accept === true || data.accept === 'true');
  if (accept && state.overdue) return { success: false, error: 'DEADLINE_PASSED', message: 'The deadline has already passed, so the extension can no longer be agreed.' };
  if (accept && Number(row.obj.days) > state.extensionDaysLeft) return { success: false, error: 'EXTENSION_LIMIT', message: 'That would take the total extension past 7 days.' };
  // RENT / LEND: the owner answers (the borrower asked).
  if (String(swap.obj.serviceType || 'SWAP').toUpperCase() !== 'SWAP' && caller !== swap.ownerEmail) {
    return { success: false, error: 'WRONG_PARTY', message: 'The book\'s owner answers an extension request.' };
  }
  const set = (name, v) => { const i = t.headers.indexOf(name); if (i !== -1) sheet.getRange(row.rowIndex + 1, i + 1).setValue(v); };
  set('status', accept ? 'APPROVED' : 'DECLINED');
  set('decidedBy', caller);
  set('decidedAt', new Date());
  const newDue = accept ? new Date(new Date(state.dueAt).getTime() + Number(row.obj.days) * RETURN_DAY_MS) : null;
  [swap.requesterEmail, swap.ownerEmail].forEach(email => returnNotify_(email,
    accept ? 'return_extension_approved' : 'return_extension_declined',
    accept ? 'Return date extended' : 'Extension declined',
    accept
      ? 'The return of "' + (swap.obj.requestedBookTitle || 'the book') + '" is now due by ' + returnDateLabel_(newDue) + '. This is the new strict deadline.'
      : 'The extension was declined. The return is still due by ' + returnDateLabel_(new Date(state.dueAt)) + '.',
    swap.obj.id, 'ext_' + (accept ? 'ok_' : 'no_') + row.obj.id, { whatsapp: accept }));
  return { success: true, message: accept ? 'Extension agreed.' : 'Extension declined.' };
}

function returnDateLabel_(d) {
  try { return Utilities.formatDate(d, 'Asia/Kolkata', 'd MMM yyyy, h:mm a'); }
  catch (e) { return new Date(d).toDateString(); }
}

/** One message, every channel: in the app, by email, and on WhatsApp when configured. */
function returnNotify_(email, type, title, body, swapId, dedupeKey, opts) {
  if (!email) return;
  const o = opts || {};
  let isNew = true;
  try {
    // createNotification de-duplicates on dedupeKey, which is what stops the
    // daily job repeating a reminder. Its result tells us whether it was new.
    const res = createNotification(email, type, title, body, swapId, { link: '/profile', dedupeKey: dedupeKey });
    if (res && (res.duplicate || res.deduped || res.skipped)) isNew = false;
  } catch (e) { Logger.log('returnNotify_ in-app failed: ' + e); }
  if (!isNew) return;
  try {
    sendSwapSutraEmail({
      to: email, subject: 'SwapSutra: ' + title,
      htmlBody: '<p>' + body.replace(/</g, '&lt;') + '</p><p style="font-size:13px;color:#555">' + RETURN_POLICY_TEXT + '</p><p>— SwapSutra</p>'
    });
  } catch (e) { Logger.log('returnNotify_ email failed: ' + e); }
  if (o.whatsapp !== false) {
    try { sendWhatsAppNotice_(email, title, body); } catch (e) { Logger.log('returnNotify_ WhatsApp failed: ' + e); }
  }
}

/* ── WhatsApp (Meta WhatsApp Business Cloud API) ─────────────────────────
   Off until configured. Business-initiated WhatsApp messages must use a
   template Meta has approved, so set these Script Properties:
     WHATSAPP_TOKEN          permanent access token
     WHATSAPP_PHONE_ID       the sender phone-number ID
     WHATSAPP_TEMPLATE       approved template name, with two body
                             variables: {{1}} title, {{2}} message
     WHATSAPP_TEMPLATE_LANG  optional, default "en"
   The reader's number is the one they joined with. Nothing is sent, and
   nothing fails, while any of these is missing. */
function sendWhatsAppNotice_(email, title, body) {
  const props = PropertiesService.getScriptProperties();
  const token = props.getProperty('WHATSAPP_TOKEN');
  const phoneId = props.getProperty('WHATSAPP_PHONE_ID');
  const template = props.getProperty('WHATSAPP_TEMPLATE');
  if (!token || !phoneId || !template) return false;
  const to = whatsappNumberFor_(email);
  if (!to) return false;
  const res = UrlFetchApp.fetch('https://graph.facebook.com/v20.0/' + phoneId + '/messages', {
    method: 'post', contentType: 'application/json', muteHttpExceptions: true,
    headers: { Authorization: 'Bearer ' + token },
    payload: JSON.stringify({
      messaging_product: 'whatsapp', to: to, type: 'template',
      template: {
        name: template, language: { code: props.getProperty('WHATSAPP_TEMPLATE_LANG') || 'en' },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: String(title).slice(0, 60) },
          { type: 'text', text: String(body).replace(/\s+/g, ' ').slice(0, 900) }
        ] }]
      }
    })
  });
  const code = res.getResponseCode();
  if (code < 200 || code >= 300) Logger.log('WhatsApp send failed (' + code + '): ' + res.getContentText().slice(0, 300));
  return code >= 200 && code < 300;
}

/** The reader's phone in international form (Indian numbers get 91), or ''. */
function whatsappNumberFor_(email) {
  const norm = normalizeEmail(email);
  const row = findRowByEmail_('Subscriptions', norm) || findRowByEmail_('Users', norm) || {};
  const digits = String(row.phone || row.whatsapp || row.phoneNumber || '').replace(/\D/g, '');
  if (digits.length === 10) return '91' + digits;
  if (digits.length === 12 && digits.indexOf('91') === 0) return digits;
  if (digits.length === 11 && digits.charAt(0) === '0') return '91' + digits.slice(1);
  return '';
}

/**
 * The daily job. For every live exchange with a return date: sends the
 * start notice and the 7 / 3 / 1-day and last-day reminders, and forfeits
 * the deposit on any leg whose book is not on its way back after the
 * deadline. Safe to run more often — every message is de-duplicated and a
 * leg is only ever forfeited once.
 */
function runReturnDeadlines() {
  const started = Date.now();
  const summary = { checked: 0, reminders: 0, forfeited: 0, errors: 0 };
  const swapsSheet = getOrCreateSheet('SwapRequests', DB_SCHEMA.SwapRequests);
  const swaps = readSheetObjects_(swapsSheet);
  const eventsBySwap = journeyEventsBySwap_();
  const exts = readSheetObjects_(getReturnExtensionSheet_()).rows.map(r => r.obj);
  const forfeitSheet = getReturnForfeitSheet_();
  const forfeits = readSheetObjects_(forfeitSheet).rows.map(r => r.obj);
  let stageInfo = {};
  try { stageInfo = stageReturnInfoBySwap_(); } catch (e) { stageInfo = {}; }
  // Sales whose buyer never closed them (Oct 2026).
  try { summary.sales = runSaleAutoRelease_(); } catch (e) { Logger.log('runSaleAutoRelease_ failed: ' + e); }
  // Exchange Room timers: 48-hour condition video / payment, the +7 notice,
  // refunds, and closing rooms after the rating step.
  try { summary.rooms = runExchangeRoomTicks_(); } catch (e) { Logger.log('runExchangeRoomTicks_ failed: ' + e); }

  swaps.rows.forEach(r => {
    if (Date.now() - started > 4.5 * 60 * 1000) return;
    const o = r.obj;
    const status = String(o.status || '').toLowerCase();
    if (['pending', 'declined', 'rejected', 'cancelled', 'expired', 'completed'].indexOf(status) !== -1) return;
    if (!returnLegsFor_(o).length) return;
    try {
      const id = String(o.id);
      const state = computeReturnState_(o, eventsBySwap[id] || [],
        exts.filter(x => String(x.swapId) === id), forfeits.filter(x => String(x.swapId) === id), undefined, stageInfo[id] || null);
      if (!state.started) return;
      summary.checked++;
      const swap = loadSwapForCirculation(id);
      if (!swap) return;
      const title = String(o.requestedBookTitle || 'the book');
      const due = returnDateLabel_(new Date(state.dueAt));

      state.legs.forEach(leg => {
        const borrowerEmail = leg.borrower === 'owner' ? swap.ownerEmail : swap.requesterEmail;
        const ownerEmail = leg.owner === 'owner' ? swap.ownerEmail : swap.requesterEmail;
        const bookLabel = leg.leg === 'counter_return' ? 'the book you received in this swap' : '"' + title + '"';
        if (leg.state === 'DUE') {
          returnNotify_(borrowerEmail, 'return_started', 'Return due by ' + due,
            'You have ' + bookLabel + '. It must be on its way back by ' + due + '. ' + RETURN_POLICY_TEXT,
            id, 'ret_start_' + id + '_' + leg.leg + '_' + state.dueAt);
          RETURN_REMINDER_DAYS_LEFT.forEach(n => {
            if (state.daysLeft <= n && state.daysLeft > 0) {
              returnNotify_(borrowerEmail, 'return_reminder', n + (n === 1 ? ' day' : ' days') + ' left to return the book',
                'Please return ' + bookLabel + ' by ' + due + '. Hand it over in person, or post it and add the courier name and tracking ID. ' +
                'If it is not on its way back by then, your security deposit will be forfeited to the owner.',
                id, 'ret_left' + n + '_' + id + '_' + leg.leg + '_' + state.dueAt);
              summary.reminders++;
            }
          });
          if (state.daysLeft <= 0 && !state.overdue) {
            returnNotify_(borrowerEmail, 'return_last_day', 'Last day to return the book',
              'Today is the last day. Add the courier tracking ID or hand ' + bookLabel + ' over in person before ' + due + ', or the security deposit is forfeited.',
              id, 'ret_last_' + id + '_' + leg.leg + '_' + state.dueAt);
          }
        }
        if ((leg.state === 'OVERDUE' || leg.state === 'RETURNED_LATE') && swapHasOpenDispute(id)) {
          // A dispute is open: SwapSutra decides this deposit from the
          // exchange videos (adminDecideDeposits) instead of the timer.
          returnNotify_('swapsutra@gmail.com', 'return_overdue_disputed', 'Overdue return under dispute',
            'Exchange ' + id + ' is past its return deadline but has an open dispute. Review the videos and decide the deposit.',
            id, 'ret_overdue_disp_' + id + '_' + leg.leg, { whatsapp: false });
          return;
        }
        if (leg.state === 'OVERDUE' || leg.state === 'RETURNED_LATE') {
          // A swap (9 Oct 2026): SwapSutra's fee comes out of a forfeited deposit too.
          const fullDeposit = Number(o[leg.deposit] || 0);
          const feeKept = Math.min(fullDeposit, feeTakenFromDeposit_(o, borrowerEmail, myFeeRecord_(id, leg.borrower)));
          const amount = fullDeposit - feeKept;
          const headers = ensureSheetHeaders(forfeitSheet, RETURN_FORFEIT_HEADERS);
          const rec = {
            id: generateId('SS_FORFEIT_'), swapId: id, leg: leg.leg, bookTitle: title,
            defaulterEmail: borrowerEmail, ownerEmail: ownerEmail, amount: amount,
            dueAt: new Date(state.dueAt), forfeitedAt: new Date(), payoutStatus: amount > 0 ? 'TO_PAY_OWNER' : 'NO_DEPOSIT'
          };
          forfeitSheet.appendRow(headers.map(h => rec[h] !== undefined ? rec[h] : ''));
          forfeits.push(rec);
          if (feeKept > 0) {
            const feeRec = { id: generateId('SS_FEE_KEPT_'), swapId: id, leg: 'fee:' + leg.borrower, bookTitle: title, defaulterEmail: borrowerEmail,
              ownerEmail: 'swapsutra@gmail.com', amount: feeKept, dueAt: '', forfeitedAt: new Date(), payoutStatus: 'KEPT_AS_FEE',
              note: 'Platform fee taken from the forfeited ₹' + fullDeposit + ' deposit.' };
            forfeitSheet.appendRow(headers.map(h => feeRec[h] !== undefined ? feeRec[h] : ''));
            forfeits.push(feeRec);
          }
          summary.forfeited++;
          try {
            appendStageEvent({ swapId: id, stage: 'RETURN', party: 'system', actionType: 'deposit_forfeited',
              actorEmail: 'swapsutra@gmail.com', note: 'Not returned by ' + due + '. ₹' + amount + ' forfeited to the owner.' });
          } catch (e) { /* the forfeit record above is the source of truth */ }
          returnNotify_(borrowerEmail, 'return_forfeited', 'Security deposit forfeited',
            bookLabel + ' was not on its way back by ' + due + ', so your ₹' + fullDeposit + ' security deposit has been forfeited' + (feeKept > 0 ? ' (₹' + amount + ' to the owner, ₹' + feeKept + ' platform fee)' : ' and will be paid to the owner') + '. You must still return the book.',
            id, 'ret_forfeit_' + id + '_' + leg.leg);
          returnNotify_(ownerEmail, 'return_forfeited_owner', 'The deposit is coming to you',
            'Your book was not returned by ' + due + '. The borrower\'s ₹' + amount + ' security deposit has been forfeited and SwapSutra will pay it to you' + (readPayoutAccount_(ownerEmail) ? '' : ' — add your UPI ID in Profile → Settings so we can') + '. SwapSutra will also help you get the book back.',
            id, 'ret_forfeit_owner_' + id + '_' + leg.leg);
          returnNotify_('swapsutra@gmail.com', 'return_forfeit_admin', 'Pay out a forfeited deposit',
            'Exchange ' + id + ': ₹' + amount + ' forfeited by ' + borrowerEmail + ' — pay it to ' + ownerEmail + ' and mark it paid in Admin → Returns.',
            id, 'ret_forfeit_admin_' + id + '_' + leg.leg, { whatsapp: false });
        }
      });
    } catch (err) {
      summary.errors++;
      Logger.log('runReturnDeadlines failed for ' + o.id + ': ' + err);
    }
  });
  return summary;
}

/** Run once from the editor: schedules runReturnDeadlines every hour. */
function installReturnDeadlineTrigger() {
  ScriptApp.getProjectTriggers()
    .filter(t => t.getHandlerFunction() === 'runReturnDeadlines')
    .forEach(t => ScriptApp.deleteTrigger(t));
  ScriptApp.newTrigger('runReturnDeadlines').timeBased().everyHours(1).create();
  return 'runReturnDeadlines will run every hour.';
}

/** Admin action: adminListReturnForfeits — forfeits waiting to be paid to owners. */
function adminListReturnForfeits() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  // Partner payouts and commission (rows with a payoutCycle) are paid monthly
  // from Management → Partners, so they are not listed here.
  const items = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj)
    .filter(it => !it.payoutCycle)
    .sort((a, b) => new Date(b.forfeitedAt) - new Date(a.forfeitedAt));
  // Where each payout goes: the recipient's saved UPI ID / QR (Oct 2026).
  items.forEach(it => { it.payTo = it.payoutStatus === 'TO_PAY_OWNER' ? readPayoutAccount_(it.ownerEmail) : null; });
  return { success: true, items: items };
}

/** Admin action: adminMarkForfeitPaid { id, note? } — after paying the owner. */
function adminMarkForfeitPaid(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  const sheet = getReturnForfeitSheet_();
  const t = readSheetObjects_(sheet);
  const row = t.rows.find(r => String(r.obj.id) === String(data && data.id));
  if (!row) return { success: false, message: 'Not found.' };
  if (row.obj.payoutStatus !== 'TO_PAY_OWNER') return { success: false, message: 'This one is not waiting for a payout.' };
  if (row.obj.payoutCycle) return { success: false, message: 'This is a partner payout — pay it with the month in Management → Partners.' };
  const set = (name, v) => { const i = t.headers.indexOf(name); if (i !== -1) sheet.getRange(row.rowIndex + 1, i + 1).setValue(v); };
  set('payoutStatus', 'PAID_TO_OWNER');
  set('paidAt', new Date());
  set('paidBy', normalizeEmail(getAuthenticatedEmail()));
  set('note', String((data && data.note) || '').slice(0, 300));
  const kindOfPayout = String(row.obj.leg) === 'sale' ? 'the payment for your sale of "' + row.obj.bookTitle + '" (price minus the platform fee)'
    : String(row.obj.leg).indexOf('refund:') === 0 ? 'the refund of your payment / security deposit on "' + row.obj.bookTitle + '"'
    : String(row.obj.leg) === 'rent' ? 'the rent for "' + row.obj.bookTitle + '" (taken from the renter\'s deposit)'
    : String(row.obj.leg).indexOf('dispute:') === 0 ? 'the deposit awarded to you after SwapSutra reviewed the exchange videos'
    : 'the deposit forfeited when your book was not returned on time';
  const account = readPayoutAccount_(row.obj.ownerEmail);
  returnNotify_(row.obj.ownerEmail, 'return_forfeit_paid', 'SwapSutra has paid you ₹' + row.obj.amount,
    'SwapSutra has sent you ₹' + row.obj.amount + (account ? ' to ' + account.upiId : '') + ' — ' + kindOfPayout + '.',
    row.obj.swapId, 'ret_paid_' + row.obj.id);
  return { success: true };
}


/* ════════════════════════════════════════════════════════════════════════
   VMS — VIDEO EVIDENCE FOR EVERY EXCHANGE (Oct 2026, owner's rules)
   ────────────────────────────────────────────────────────────────────────
   For every book that travels — swap (both books), rent, lend and sale,
   on the way out and, where it comes back, on the way back:

     the SENDER records   QUALITY   the book's condition, before it goes
                          PACKING   packing the parcel (courier route only)
     the RECEIVER records RECEIVING opening the parcel / checking the book

   The delivery timeline will not accept "posted" / "handed over" until the
   sender's videos are in, nor "received" until the receiver's video is.
   If a dispute is raised, SwapSutra reviews these videos in the admin
   console and decides each deposit: returned to the payer, or forfeited
   (fully or partly) to the reader who is owed it. A forfeit becomes a
   payout record (ReturnForfeits sheet), paid by UPI and marked paid there.

   Upload: phones make videos far larger than the 4.5 MB a single request
   can carry, so the app sends a video in 2.5 MB pieces. Each piece is
   passed straight on to a Google Drive resumable upload session, so Apps
   Script never holds the whole video in memory.
   ════════════════════════════════════════════════════════════════════════ */

const VMS_VIDEO_SHEET = 'ExchangeVideos';
const VMS_VIDEO_HEADERS = ['id', 'swapId', 'leg', 'kind', 'uploaderEmail', 'role', 'method', 'fileId', 'url', 'mimeType',
  'sizeBytes', 'durationSec', 'recordedInApp', 'stampCode', 'createdAt'];
const VMS_UPLOAD_SHEET = 'VmsUploads';
const VMS_UPLOAD_HEADERS = ['id', 'swapId', 'leg', 'kind', 'uploaderEmail', 'mimeType', 'sizeBytes', 'totalChunks',
  'nextIndex', 'sessionUrl', 'fileId', 'status', 'createdAt', 'updatedAt'];
const VMS_CHUNK_BYTES = 2621440;           // 2.5 MB — a multiple of 256 KB, as Drive requires
const VMS_MAX_BYTES = 80 * 1024 * 1024;    // 80 MB per video
const VMS_ALLOWED_TYPES = ['video/mp4', 'video/webm', 'video/quicktime', 'video/x-m4v', 'video/3gpp'];
// Oct 2026 (Exchange Room): the sender records three videos for every book,
// whichever route — condition, packaging and handover — and the receiver one.
const VMS_KIND_LABELS = { QUALITY: 'book condition video', PACKING: 'packaging video', HANDOVER: 'handover video', RECEIVING: 'receiving / unboxing video' };

function getVmsVideoSheet_() { const s = getOrCreateSheet(VMS_VIDEO_SHEET, VMS_VIDEO_HEADERS); ensureSheetHeaders(s, VMS_VIDEO_HEADERS); return s; }
function getVmsUploadSheet_() { const s = getOrCreateSheet(VMS_UPLOAD_SHEET, VMS_UPLOAD_HEADERS); ensureSheetHeaders(s, VMS_UPLOAD_HEADERS); return s; }

/** The legs a book travels on for this exchange. */
function vmsLegsFor_(swap) {
  const type = String(swap.obj.serviceType || 'SWAP').toUpperCase();
  const back = swapNeedsReturn(swap);
  const legs = ['outbound'];
  if (type === 'SWAP') legs.push('counter');
  if (back) legs.push('return');
  if (type === 'SWAP' && back) legs.push('counter_return');
  return legs;
}

/** Which videos a leg needs: sender QUALITY + PACKING + HANDOVER, receiver RECEIVING (any route). */
function vmsKindsFor_(method) {
  return {
    sender: ['QUALITY', 'PACKING', 'HANDOVER'],
    receiver: ['RECEIVING']
  };
}

function vmsVideosForSwap_(swapId) {
  return readSheetObjects_(getVmsVideoSheet_()).rows.map(r => r.obj).filter(v => String(v.swapId) === String(swapId));
}

/** Kinds this party still owes on this leg (empty = done). */
function vmsMissing_(swap, leg, side, method, videos) {
  const parties = journeyLegParties_(swap, leg);
  const email = side === 'sender' ? parties.sender : parties.receiver;
  const have = (videos || vmsVideosForSwap_(swap.obj.id)).filter(v =>
    String(v.leg) === leg && normalizeEmail(v.uploaderEmail) === normalizeEmail(email));
  return vmsKindsFor_(method)[side].filter(k => !have.some(v => v.kind === k));
}

/** Action: getExchangeVideos { swapId } — the checklist and every video, for either party or admin. */
function getExchangeVideos(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  const admin = isAuthenticatedAdmin();
  if (!admin && !callerIsPartyTo(swap, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  const route = latestSwapRoute_(swap.obj.id);
  const method = route ? route.method : '';
  const videos = vmsVideosForSwap_(swap.obj.id);
  const legs = vmsLegsFor_(swap).map(leg => {
    const parties = journeyLegParties_(swap, leg);
    const kinds = vmsKindsFor_(method || 'courier');
    const item = (side, kind) => {
      const email = side === 'sender' ? parties.sender : parties.receiver;
      const v = videos.filter(x => String(x.leg) === leg && x.kind === kind && normalizeEmail(x.uploaderEmail) === normalizeEmail(email));
      return {
        side: side, kind: kind, label: VMS_KIND_LABELS[kind],
        byYou: normalizeEmail(email) === caller,
        done: v.length > 0,
        videos: v.map(x => ({ id: x.id, url: x.url, at: x.createdAt, durationSec: Number(x.durationSec) || null, recordedInApp: String(x.recordedInApp) === 'true', stampCode: x.stampCode }))
      };
    };
    return {
      leg: leg,
      youSend: parties.sender === caller,
      youReceive: parties.receiver === caller,
      items: kinds.sender.map(k => item('sender', k)).concat(kinds.receiver.map(k => item('receiver', k)))
    };
  });
  return { success: true, swapId: swap.obj.id, routeMethod: method, legs: legs, stampCode: vmsStampCode_(swap.obj.id),
    rule: 'Every book that travels needs four videos: its condition, its packaging and its handover (sender) and its opening (receiver). In a dispute SwapSutra decides the deposit from these videos.' };
}

/** A short code the in-app recorder burns into every frame, tying a video to this exchange. */
function vmsStampCode_(swapId) {
  const digest = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, 'vms:' + String(swapId));
  return 'SS-' + digest.slice(0, 3).map(b => ('0' + ((b + 256) % 256).toString(16)).slice(-2)).join('').toUpperCase();
}

/** Action: vmsStartUpload { swapId, leg, kind, mimeType, sizeBytes } */
function vmsStartUpload(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (!callerIsPartyTo(swap, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  const route = latestSwapRoute_(swap.obj.id);
  const routeMethod = route ? route.method : 'courier'; // no route yet: allow every video

  const leg = String((data && data.leg) || '');
  if (vmsLegsFor_(swap).indexOf(leg) === -1) return { success: false, message: 'That book does not travel on this exchange.' };
  const kind = String((data && data.kind) || '').toUpperCase();
  // Exchange Room (Oct 2026): the condition video comes BEFORE payment, so
  // the reader paying can see the book first. Every other video waits for
  // the payment to be verified.
  if (!roomSwapAccepted_(swap.obj.status)) {
    return { success: false, error: 'NOT_ACCEPTED', message: 'Videos start once the request is accepted.' };
  }
  const conditionFirst = kind === 'QUALITY' && (leg === 'outbound' || leg === 'counter');
  if (!conditionFirst && !swapChatUnlocked(swap.obj.id)) {
    return { success: false, error: 'SECURITY_FEE_PENDING', message: 'This video unlocks once the payment on this exchange is verified.' };
  }
  const parties = journeyLegParties_(swap, leg);
  const side = parties.sender === caller ? 'sender' : parties.receiver === caller ? 'receiver' : '';
  const allowed = side ? vmsKindsFor_(routeMethod)[side] : [];
  if (allowed.indexOf(kind) === -1) {
    return { success: false, error: 'WRONG_PARTY', message: side === 'sender'
      ? 'As the sender you record the condition, packaging and handover videos.'
      : 'As the receiver you record the receiving / unboxing video.' };
  }
  const mimeType = String((data && data.mimeType) || '').split(';')[0].trim().toLowerCase();
  if (VMS_ALLOWED_TYPES.indexOf(mimeType) === -1) return { success: false, message: 'Please record a video (MP4, WebM or MOV).' };
  const size = Math.floor(Number(data && data.sizeBytes));
  if (!(size > 0)) return { success: false, message: 'That video is empty.' };
  if (size > VMS_MAX_BYTES) return { success: false, error: 'TOO_LARGE', message: 'Keep the video under ' + Math.round(VMS_MAX_BYTES / 1048576) + ' MB — about a minute is plenty.' };

  const folder = getOrCreateFolder('ExchangeVideos_' + swap.obj.id);
  const name = [swap.obj.id, leg, kind, caller.split('@')[0], new Date().toISOString()].join('_') + vmsExtension_(mimeType);
  const res = UrlFetchApp.fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id', {
    method: 'post',
    contentType: 'application/json; charset=UTF-8',
    headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken(), 'X-Upload-Content-Type': mimeType, 'X-Upload-Content-Length': String(size) },
    payload: JSON.stringify({ name: name, parents: [folder.getId()], mimeType: mimeType }),
    muteHttpExceptions: true
  });
  const h = res.getHeaders() || {};
  const sessionUrl = h.Location || h.location || '';
  if (res.getResponseCode() >= 300 || !sessionUrl) {
    Logger.log('vmsStartUpload: Drive session failed ' + res.getResponseCode() + ' ' + res.getContentText().slice(0, 300));
    return { success: false, message: 'The video store is not reachable right now. Please try again in a minute.' };
  }
  const sheet = getVmsUploadSheet_();
  const headers = ensureSheetHeaders(sheet, VMS_UPLOAD_HEADERS);
  const now = new Date();
  const rec = {
    id: generateId('SS_VUP_'), swapId: swap.obj.id, leg: leg, kind: kind, uploaderEmail: caller, mimeType: mimeType,
    sizeBytes: size, totalChunks: Math.ceil(size / VMS_CHUNK_BYTES), nextIndex: 0, sessionUrl: sessionUrl,
    status: 'UPLOADING', createdAt: now, updatedAt: now
  };
  sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  return { success: true, uploadId: rec.id, chunkBytes: VMS_CHUNK_BYTES, totalChunks: rec.totalChunks };
}

function vmsExtension_(mime) {
  return { 'video/mp4': '.mp4', 'video/webm': '.webm', 'video/quicktime': '.mov', 'video/x-m4v': '.m4v', 'video/3gpp': '.3gp' }[mime] || '.mp4';
}

/** Action: vmsUploadChunk { uploadId, index, data (base64 of the raw bytes) } — pieces go in order. */
function vmsUploadChunk(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const sheet = getVmsUploadSheet_();
  const t = readSheetObjects_(sheet);
  const row = t.rows.find(r => String(r.obj.id) === String(data && data.uploadId));
  if (!row) return { success: false, message: 'That upload has expired. Please record again.' };
  const up = row.obj;
  if (normalizeEmail(up.uploaderEmail) !== caller) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  if (up.status !== 'UPLOADING') return { success: false, message: 'That upload is already finished.' };
  const index = Number(data && data.index);
  if (index !== Number(up.nextIndex)) return { success: false, error: 'OUT_OF_ORDER', expected: Number(up.nextIndex), message: 'Pieces arrived out of order.' };
  let bytes;
  try { bytes = Utilities.base64Decode(String((data && data.data) || '')); } catch (e) { bytes = null; }
  const size = Number(up.sizeBytes);
  const start = index * VMS_CHUNK_BYTES;
  const isLast = index === Number(up.totalChunks) - 1;
  const expectedLen = isLast ? size - start : VMS_CHUNK_BYTES;
  if (!bytes || bytes.length !== expectedLen) return { success: false, message: 'A piece of the video arrived damaged. Please try again.' };

  const res = UrlFetchApp.fetch(up.sessionUrl, {
    method: 'put', contentType: up.mimeType, payload: bytes, muteHttpExceptions: true,
    headers: { 'Content-Range': 'bytes ' + start + '-' + (start + bytes.length - 1) + '/' + size }
  });
  const code = res.getResponseCode();
  const set = (name, v) => { const i = t.headers.indexOf(name); if (i !== -1) sheet.getRange(row.rowIndex + 1, i + 1).setValue(v); };
  if (code === 308 && !isLast) {
    set('nextIndex', index + 1); set('updatedAt', new Date());
    return { success: true, next: index + 1 };
  }
  if ((code === 200 || code === 201) && isLast) {
    let fileId = '';
    try { fileId = JSON.parse(res.getContentText()).id || ''; } catch (e) { fileId = ''; }
    if (!fileId) return { success: false, message: 'The video was stored but could not be confirmed. Please try again.' };
    set('fileId', fileId); set('nextIndex', index + 1); set('status', 'STORED'); set('updatedAt', new Date());
    return { success: true, stored: true };
  }
  Logger.log('vmsUploadChunk: Drive answered ' + code + ' for piece ' + index + ': ' + res.getContentText().slice(0, 300));
  set('status', 'FAILED');
  return { success: false, message: 'The upload failed part-way. Please record and send again.' };
}

/** Action: vmsFinishUpload { uploadId, durationSec, recordedInApp } — registers the stored video. */
function vmsFinishUpload(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const usheet = getVmsUploadSheet_();
  const t = readSheetObjects_(usheet);
  const row = t.rows.find(r => String(r.obj.id) === String(data && data.uploadId));
  if (!row) return { success: false, message: 'That upload could not be found.' };
  const up = row.obj;
  if (normalizeEmail(up.uploaderEmail) !== caller) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  if (up.status !== 'STORED' || !up.fileId) return { success: false, message: 'The video has not finished uploading yet.' };

  const swap = loadSwapForCirculation(up.swapId);
  const route = latestSwapRoute_(up.swapId);
  let url = '';
  try {
    const file = DriveApp.getFileById(up.fileId);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    url = file.getUrl();
  } catch (e) {
    return { success: false, message: 'The video was stored but could not be opened for viewing. Please try again.' };
  }
  const parties = journeyLegParties_(swap, up.leg);
  const vsheet = getVmsVideoSheet_();
  const headers = ensureSheetHeaders(vsheet, VMS_VIDEO_HEADERS);
  const rec = {
    id: generateId('SS_VID_'), swapId: up.swapId, leg: up.leg, kind: up.kind, uploaderEmail: caller,
    role: parties.sender === caller ? 'sender' : 'receiver', method: route ? route.method : '',
    fileId: up.fileId, url: url, mimeType: up.mimeType, sizeBytes: up.sizeBytes,
    durationSec: Math.max(0, Math.round(Number(data && data.durationSec) || 0)),
    recordedInApp: data && (data.recordedInApp === true || data.recordedInApp === 'true') ? 'true' : 'false',
    stampCode: vmsStampCode_(up.swapId), createdAt: new Date()
  };
  vsheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  const set = (name, v) => { const i = t.headers.indexOf(name); if (i !== -1) usheet.getRange(row.rowIndex + 1, i + 1).setValue(v); };
  set('status', 'DONE'); set('sessionUrl', ''); set('updatedAt', new Date());

  try {
    const chat = findChatBySwapId(up.swapId);
    const chatId = chat && (chat.chatId || chat.id);
    if (chatId) {
      sendChatMessage({ chatId: chatId, senderEmail: 'swapsutra@gmail.com', senderRole: 'Admin',
        message: '🎥 Step ' + roomStepForVideo_(up.leg, up.kind) + ' · ' + roomName_(caller) + ' recorded the ' + VMS_KIND_LABELS[up.kind] + '. It is saved with this exchange in case it is ever needed.' });
    }
  } catch (e) { Logger.log('vmsFinishUpload chat notice failed: ' + e); }
  return { success: true, video: { id: rec.id, url: url, kind: rec.kind, leg: rec.leg } };
}


/**
 * The videos a party still owes before confirming a Stages-panel stage:
 *   HANDOVER — the sender's videos on each leg going OUT that they send
 *   RECEIPT  — the receiver's video on each leg going OUT that they receive
 *   RETURN   — both, on each leg coming BACK, by their role on it
 * Without an agreed route the exchange is treated as in person (quality
 * video only for the sender), since there is no parcel to pack.
 */
function vmsStageMissing_(swap, stage, role) {
  const legs = vmsLegsFor_(swap);
  const out = legs.filter(l => l === 'outbound' || l === 'counter');
  const back = legs.filter(l => l === 'return' || l === 'counter_return');
  const route = latestSwapRoute_(swap.obj.id);
  const method = route ? route.method : 'in_person';
  const email = role === 'owner' ? swap.ownerEmail : swap.requesterEmail;
  const videos = vmsVideosForSwap_(swap.obj.id);
  const missing = [];
  const add = (leg, side) => vmsMissing_(swap, leg, side, method, videos).forEach(k => { if (missing.indexOf(k) === -1) missing.push(k); });
  (stage === 'RETURN' ? back : out).forEach(leg => {
    const p = journeyLegParties_(swap, leg);
    if ((stage === 'HANDOVER' || stage === 'RETURN') && p.sender === email) add(leg, 'sender');
    if ((stage === 'RECEIPT' || stage === 'RETURN') && p.receiver === email) add(leg, 'receiver');
  });
  return missing;
}

/**
 * Admin action: adminDecideDeposits { swapId, disputeId?, decisions: [{ payerRole, outcome, amount?, reason }] }
 *
 * After reviewing the exchange's videos, SwapSutra decides each deposit:
 *   REFUND   — goes back to the reader who paid it
 *   FORFEIT  — goes to the other reader, in full or (with amount) in part;
 *              any rest is refunded
 * Every forfeit becomes a payout record in ReturnForfeits (shown in Admin →
 * Payments → "Deposits to pay out"); both readers are told the decision.
 * SwapSutra moves the money by UPI and marks each payout paid.
 */
function adminDecideDeposits(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'Unauthorized' };
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  const decisions = Array.isArray(data && data.decisions) ? data.decisions : [];
  if (!decisions.length) return { success: false, message: 'Choose what happens to each deposit.' };

  const deposits = { requester: Number(swap.obj.securityDeposit || 0), owner: Number(swap.obj.ownerDeposit || 0) };
  const emailOf = { requester: swap.requesterEmail, owner: swap.ownerEmail };
  const disputeId = String((data && data.disputeId) || '').trim();
  const title = String(swap.obj.requestedBookTitle || 'the book');
  const sheet = getReturnForfeitSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  const existing = readSheetObjects_(sheet).rows.map(r => r.obj);
  const results = [];

  for (let i = 0; i < decisions.length; i++) {
    const d = decisions[i] || {};
    const payerRole = d.payerRole === 'owner' ? 'owner' : d.payerRole === 'requester' ? 'requester' : '';
    if (!payerRole) return { success: false, message: 'Each decision needs the deposit it is about.' };
    const held = deposits[payerRole];
    if (!(held > 0)) return { success: false, message: 'There is no ' + payerRole + ' deposit on this exchange.' };
    const outcome = String(d.outcome || '').toUpperCase();
    const reason = String(d.reason || '').trim().slice(0, 500);
    if (!reason) return { success: false, message: 'Write the reason for each decision — both readers will see it.' };
    const leg = 'dispute:' + (disputeId || 'review') + ':' + payerRole;
    if (existing.some(f => String(f.swapId) === String(swap.obj.id) && String(f.leg) === leg)) {
      return { success: false, message: 'The ' + payerRole + ' deposit on this exchange has already been decided.' };
    }
    let forfeit = 0;
    if (outcome === 'FORFEIT') {
      forfeit = d.amount === undefined || d.amount === '' || d.amount === null ? held : Math.round(Number(d.amount));
      if (!(forfeit > 0) || forfeit > held) return { success: false, message: 'The amount to forfeit must be between ₹1 and ₹' + held + '.' };
    } else if (outcome !== 'REFUND') {
      return { success: false, message: 'Each deposit is either refunded or forfeited.' };
    }
    const payer = emailOf[payerRole];
    const other = emailOf[payerRole === 'owner' ? 'requester' : 'owner'];
    if (forfeit > 0) {
      const rec = {
        id: generateId('SS_FORFEIT_'), swapId: swap.obj.id, leg: leg, bookTitle: title,
        defaulterEmail: payer, ownerEmail: other, amount: forfeit, dueAt: '', forfeitedAt: new Date(),
        payoutStatus: 'TO_PAY_OWNER', note: 'Dispute decision: ' + reason
      };
      sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
      existing.push(rec);
    } else {
      const rec = {
        id: generateId('SS_FORFEIT_'), swapId: swap.obj.id, leg: leg, bookTitle: title,
        defaulterEmail: '', ownerEmail: payer, amount: 0, dueAt: '', forfeitedAt: new Date(),
        payoutStatus: 'NO_DEPOSIT', note: 'Dispute decision: deposit refunded — ' + reason
      };
      sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
      existing.push(rec);
    }
    const refund = held - forfeit;
    const message = forfeit > 0
      ? '₹' + forfeit + ' of the ₹' + held + ' deposit is forfeited to the other reader' + (refund > 0 ? ' and ₹' + refund + ' is refunded' : '') + '. Reason: ' + reason
      : 'The ₹' + held + ' deposit is refunded in full. Reason: ' + reason;
    [payer, other].forEach(email => returnNotify_(email, 'deposit_decided', 'Decision on the security deposit',
      'After reviewing the exchange videos for "' + title + '": ' + message + (email === other && forfeit > 0 && !readPayoutAccount_(other) ? ' Add your UPI ID in Profile → Settings so SwapSutra can pay you.' : ''), swap.obj.id, 'dep_dec_' + leg));
    results.push({ payerRole: payerRole, held: held, forfeit: forfeit, refund: refund });
  }
  try {
    appendStageEvent({ swapId: swap.obj.id, stage: 'OUTCOME', party: 'system', actionType: 'deposit_decided',
      actorEmail: normalizeEmail(getAuthenticatedEmail()),
      note: results.map(r => r.payerRole + ': forfeit ₹' + r.forfeit + ', refund ₹' + r.refund).join('; ') });
  } catch (e) { /* the payout records are the source of truth */ }
  return { success: true, results: results, message: 'Decision recorded. Forfeits are in Deposits to pay out.' };
}


/* ════════════════════════════════════════════════════════════════════════
   SALES THROUGH SWAPSUTRA + PAYOUT ACCOUNTS (Oct 2026, owner's rules)
   ────────────────────────────────────────────────────────────────────────
   1. The buyer pays SwapSutra the owner's price + the ₹10 platform fee
      (one QR, verified like every other payment; the chat then opens).
   2. The book travels with its videos (VMS). The buyer records the
      receiving video and confirms receipt.
   3. The buyer closes the purchase — "I have the book and I'm happy" —
      which creates the seller's payout: the price minus the seller's own
      ₹10 platform fee, to the UPI ID / QR the seller gave. SwapSutra pays
      it and marks it paid (Admin → Payments → Payouts to make).
   4. Not happy? The buyer reports a problem instead; the payout waits for
      SwapSutra's decision from the videos.
   5. After closing, the buyer is invited (optionally) to leave a Google
      review.

   Payout accounts serve every payout, not only sales: a forfeited deposit
   is paid to the beneficiary's UPI the same way.
   ════════════════════════════════════════════════════════════════════════ */

const PAYOUT_ACCOUNT_SHEET = 'PayoutAccounts';
const PAYOUT_ACCOUNT_HEADERS = ['email', 'upiId', 'payeeName', 'qrUrl', 'updatedAt'];
const UPI_ID_PATTERN = /^[a-zA-Z0-9.\-_]{2,256}@[a-zA-Z][a-zA-Z0-9.\-]{1,63}$/;
const GOOGLE_REVIEW_URL = 'https://g.page/r/CTKbe5CpoGNPEAI/review';

function getPayoutAccountSheet_() { const s = getOrCreateSheet(PAYOUT_ACCOUNT_SHEET, PAYOUT_ACCOUNT_HEADERS); ensureSheetHeaders(s, PAYOUT_ACCOUNT_HEADERS); return s; }

function readPayoutAccount_(email) {
  const norm = normalizeEmail(email);
  const row = readSheetObjects_(getPayoutAccountSheet_()).rows.find(r => normalizeEmail(r.obj.email) === norm);
  return row ? { upiId: row.obj.upiId || '', payeeName: row.obj.payeeName || '', qrUrl: row.obj.qrUrl || '', updatedAt: row.obj.updatedAt || '' } : null;
}

/** Action: getPayoutAccount — your own. */
function getPayoutAccount() {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in first.' };
  return { success: true, account: readPayoutAccount_(caller) };
}

/** Action: savePayoutAccount { upiId, payeeName, fileData? (QR image) } */
function savePayoutAccount(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in first.' };
  const upiId = String((data && data.upiId) || '').trim();
  const payeeName = String((data && data.payeeName) || '').trim().slice(0, 80);
  if (!UPI_ID_PATTERN.test(upiId)) return { success: false, message: 'Enter a UPI ID like name@okbank or 98xxxxxxxx@upi.' };
  if (!payeeName) return { success: false, message: 'Enter the name on the account, so SwapSutra can check it before paying.' };
  let qrUrl = '';
  if (data && data.fileData) {
    qrUrl = saveFileToDrive(data.fileData, 'payout_qr_' + caller.split('@')[0] + '.jpg') || '';
    if (!qrUrl) return { success: false, message: 'That QR image could not be saved. Use a JPG or PNG under 10 MB.' };
  }
  const sheet = getPayoutAccountSheet_();
  const t = readSheetObjects_(sheet);
  const existing = t.rows.find(r => normalizeEmail(r.obj.email) === caller);
  const now = new Date();
  if (existing) {
    const set = (k, v) => { const i = t.headers.indexOf(k); if (i !== -1) sheet.getRange(existing.rowIndex + 1, i + 1).setValue(v); };
    set('upiId', upiId); set('payeeName', payeeName); if (qrUrl) set('qrUrl', qrUrl); set('updatedAt', now);
  } else {
    const headers = ensureSheetHeaders(sheet, PAYOUT_ACCOUNT_HEADERS);
    const rec = { email: caller, upiId: upiId, payeeName: payeeName, qrUrl: qrUrl, updatedAt: now };
    sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  }
  return { success: true, account: readPayoutAccount_(caller), message: 'Saved. Payouts will go to ' + upiId + '.' };
}

/** The sale's state for the buyer and seller: what was paid, whether it can be closed, the payout. */
function saleStatusFor_(swap) {
  const id = String(swap.obj.id);
  const fee = platformFeePerParty_();
  const price = Math.max(0, Math.round(Number(swap.obj.amount || 0)));
  // A partner seller (9 Oct 2026) pays no ₹10 fee; SwapSutra keeps its commission instead.
  const partnerSeller = approvedPartner_(swap.ownerEmail);
  const sellerFee = isAdminEmail(swap.ownerEmail) || partnerSeller ? 0 : fee;
  const payout = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj)
    .find(f => String(f.swapId) === id && String(f.leg) === 'sale') || null;
  const commission = partnerSeller ? partnerCommissionFor_(partnerSeller, price, payout && payout.forfeitedAt ? payout.forfeitedAt : new Date()) : { rate: 0, commission: 0 };
  const events = journeyEventsBySwap_()[id] || [];
  const received = events.some(e => e.leg === 'outbound' && e.event === 'received');
  return {
    escrow: saleEscrowActive_(swap),
    price: price,
    buyerPays: price + (isAdminEmail(swap.requesterEmail) ? 0 : fee),
    sellerReceives: Math.max(0, Math.round((price - sellerFee - commission.commission) * 100) / 100),
    sellerFee: sellerFee,
    commission: commission.commission, commissionRate: commission.rate, partnerSeller: !!partnerSeller,
    received: received,
    closed: !!payout,
    payoutStatus: payout ? payout.payoutStatus : '',
    paidAt: payout ? payout.paidAt || '' : '',
    disputeOpen: swapHasOpenDispute(id),
    reviewUrl: GOOGLE_REVIEW_URL
  };
}

/**
 * A partner's sale (9 Oct 2026): the payout is paid with the month's
 * statement, SwapSutra's commission is recorded, and one copy leaves stock.
 */
function salePartnerPayout_(swap, st, rec, sheet, headers) {
  if (!st.partnerSeller) return;
  const parts = partnerPayoutParts_(swap.ownerEmail, st.price, rec.forfeitedAt);
  if (!parts) return;
  rec.payoutCycle = parts.cycle;
  rec.grossAmount = st.price;
  rec.amount = parts.net;
  rec.payoutStatus = parts.net > 0 ? 'TO_PAY_OWNER' : 'NO_DEPOSIT';
  rec.note = 'Partner sale: price ₹' + st.price + (parts.commission ? ' − ₹' + parts.commission + ' commission (' + Math.round(parts.rate * 100) + '%)' : ' (no commission)') + '. Paid with the ' + parts.cycle + ' statement.';
  appendCommissionRow_(sheet, headers, swap.obj.id, rec.bookTitle, swap.ownerEmail, parts.commission, parts.cycle,
    Math.round(parts.rate * 100) + '% commission on a ₹' + st.price + ' sale.');
  decrementPartnerStock_(swap.obj.requestedBookId, swap.ownerEmail);
}

/** Action: getSaleStatus { swapId } — buyer, seller or admin. */
function getSaleStatus(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (!isAuthenticatedAdmin() && !callerIsPartyTo(swap, caller)) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
  if (String(swap.obj.serviceType || '').toUpperCase() !== 'SELL') return { success: true, applies: false };
  const st = saleStatusFor_(swap);
  const you = caller === swap.ownerEmail ? 'seller' : caller === swap.requesterEmail ? 'buyer' : 'admin';
  const out = Object.assign({ success: true, applies: true, you: you }, st);
  if (you === 'seller') out.payoutAccount = readPayoutAccount_(caller);
  return out;
}

/**
 * Action: confirmSaleComplete { swapId, happy: true, note? } — the buyer only.
 * Needs: the book confirmed received (which itself needs the receiving
 * video), no open dispute, and the purchase not already closed.
 * Creates the seller's payout (price − seller's platform fee).
 */
function confirmSaleComplete(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
  if (!swap) return { success: false, message: 'That exchange could not be found.' };
  if (String(swap.obj.serviceType || '').toUpperCase() !== 'SELL') return { success: false, message: 'Only a purchase is closed this way.' };
  if (caller !== swap.requesterEmail) return { success: false, error: 'WRONG_PARTY', message: 'Only the buyer can close the purchase.' };
  if (!(data && (data.happy === true || data.happy === 'true'))) {
    return { success: false, message: 'If something is wrong with the book, report a problem instead — SwapSutra will review the videos.' };
  }
  const st = saleStatusFor_(swap);
  if (!st.escrow) return { success: false, message: 'This sale was paid directly between readers, so there is nothing for SwapSutra to release.' };
  if (st.closed) return { success: false, message: 'This purchase is already closed.' };
  if (st.disputeOpen) return { success: false, error: 'DISPUTE_OPEN', message: 'A problem is being reviewed on this purchase. SwapSutra will decide from the videos.' };
  if (!st.received) return { success: false, error: 'NOT_RECEIVED', message: 'Confirm you received the book first (with your receiving video) in the Delivery panel.' };
  if (vmsMissing_(swap, 'outbound', 'receiver', (latestSwapRoute_(swap.obj.id) || {}).method || 'courier').length) {
    return { success: false, error: 'VIDEO_REQUIRED', message: 'Record the receiving video of the book first.' };
  }

  const sheet = getReturnForfeitSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  const note = String((data && data.note) || '').trim().slice(0, 300);
  const rec = {
    id: generateId('SS_PAYOUT_'), swapId: swap.obj.id, leg: 'sale', bookTitle: String(swap.obj.requestedBookTitle || 'the book'),
    defaulterEmail: swap.requesterEmail, ownerEmail: swap.ownerEmail, amount: st.sellerReceives, dueAt: '', forfeitedAt: new Date(),
    payoutStatus: st.sellerReceives > 0 ? 'TO_PAY_OWNER' : 'NO_DEPOSIT',
    note: 'Sale closed by the buyer: price ₹' + st.price + ' − ₹' + st.sellerFee + ' platform fee.' + (note ? ' Buyer: ' + note : '')
  };
  salePartnerPayout_(swap, st, rec, sheet, headers);
  sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  try {
    appendStageEvent({ swapId: swap.obj.id, stage: 'OUTCOME', party: 'requester', actionType: 'sale_closed', actorEmail: caller, note: 'Buyer is happy; payout ₹' + st.sellerReceives + ' created.' });
  } catch (e) { /* the payout record is the source of truth */ }

  const account = readPayoutAccount_(swap.ownerEmail);
  returnNotify_(swap.ownerEmail, 'sale_payout_due', 'Your sale is complete',
    'The buyer has the book and closed the purchase. SwapSutra will send you ₹' + st.sellerReceives + (st.partnerSeller
      ? ' (₹' + st.price + (st.commission ? ' minus ' + Math.round(st.commissionRate * 100) + '% commission' : '') + ') with your monthly payout'
      : ' (₹' + st.price + ' minus the ₹' + st.sellerFee + ' platform fee)') +
    (account ? ' to ' + account.upiId + '.' : '. Add your UPI ID in the exchange\'s Delivery panel so we can pay you.'),
    swap.obj.id, 'sale_closed_seller_' + swap.obj.id);
  returnNotify_(caller, 'sale_closed_buyer', 'Thank you — purchase closed',
    'Enjoy the book!' + (hasRatedPlatform_(caller) ? '' : ' Rate the exchange in its room — it moves to My orders after that.'),
    swap.obj.id, 'sale_closed_buyer_' + swap.obj.id, { whatsapp: false });
  returnNotify_('swapsutra@gmail.com', 'sale_payout_admin', 'Pay a seller',
    'Sale ' + swap.obj.id + ' closed by the buyer. Pay ₹' + st.sellerReceives + ' to ' + swap.ownerEmail + (account ? ' (' + account.upiId + ')' : ' (no UPI yet)') + ' and mark it paid.',
    swap.obj.id, 'sale_closed_admin_' + swap.obj.id, { whatsapp: false });
  return { success: true, payout: st.sellerReceives, reviewUrl: GOOGLE_REVIEW_URL, message: 'Purchase closed. The seller will be paid.' };
}

/**
 * Hourly (from runReturnDeadlines): a buyer who confirmed receipt but has
 * neither closed the purchase nor reported a problem for 7 days — the
 * seller is paid anyway, so their money is never stuck. The buyer is
 * reminded at 5 days first.
 */
const SALE_AUTO_RELEASE_DAYS = 7;
function runSaleAutoRelease_() {
  const summary = { released: 0, reminded: 0 };
  const swaps = readSheetObjects_(getOrCreateSheet('SwapRequests', DB_SCHEMA.SwapRequests)).rows.map(r => r.obj)
    .filter(o => String(o.serviceType || '').toUpperCase() === 'SELL' && saleEscrowAppliesToSwap_(o));
  if (!swaps.length) return summary;
  const eventsBySwap = journeyEventsBySwap_();
  const payouts = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj);
  const sheet = getReturnForfeitSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  swaps.forEach(o => {
    const id = String(o.id);
    if (payouts.some(p => String(p.swapId) === id && String(p.leg) === 'sale')) return;
    const got = (eventsBySwap[id] || []).filter(e => e.leg === 'outbound' && e.event === 'received')
      .map(e => new Date(e.createdAt).getTime()).filter(t => isFinite(t));
    if (!got.length) return;
    const ageDays = (Date.now() - Math.min.apply(null, got)) / (24 * 60 * 60 * 1000);
    if (swapHasOpenDispute(id)) return;
    const swap = loadSwapForCirculation(id);
    if (!swap || !saleEscrowActive_(swap)) return;
    if (ageDays >= 5 && ageDays < SALE_AUTO_RELEASE_DAYS) {
      returnNotify_(swap.requesterEmail, 'sale_close_reminder', 'Please close your purchase',
        'You confirmed receiving "' + (o.requestedBookTitle || 'the book') + '". Close the purchase if you are happy, or report a problem — otherwise the payment is released to the seller in ' + Math.ceil(SALE_AUTO_RELEASE_DAYS - ageDays) + ' days.',
        id, 'sale_close_remind_' + id, { whatsapp: true });
      summary.reminded++;
      return;
    }
    if (ageDays < SALE_AUTO_RELEASE_DAYS) return;
    const st = saleStatusFor_(swap);
    const rec = {
      id: generateId('SS_PAYOUT_'), swapId: id, leg: 'sale', bookTitle: String(o.requestedBookTitle || 'the book'),
      defaulterEmail: swap.requesterEmail, ownerEmail: swap.ownerEmail, amount: st.sellerReceives, dueAt: '', forfeitedAt: new Date(),
      payoutStatus: st.sellerReceives > 0 ? 'TO_PAY_OWNER' : 'NO_DEPOSIT',
      note: 'Released automatically: received ' + SALE_AUTO_RELEASE_DAYS + '+ days ago, no problem reported. Price ₹' + st.price + ' − ₹' + st.sellerFee + '.'
    };
    salePartnerPayout_(swap, st, rec, sheet, headers);
    sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
    payouts.push(rec);
    summary.released++;
    returnNotify_(swap.ownerEmail, 'sale_payout_due', 'Your sale payment is released',
      'The buyer received "' + (o.requestedBookTitle || 'the book') + '" over ' + SALE_AUTO_RELEASE_DAYS + ' days ago with no problem reported, so SwapSutra is paying you ₹' + st.sellerReceives + '.',
      id, 'sale_auto_seller_' + id);
    returnNotify_('swapsutra@gmail.com', 'sale_payout_admin', 'Pay a seller (auto-released)',
      'Sale ' + id + ': pay ₹' + st.sellerReceives + ' to ' + swap.ownerEmail + '.', id, 'sale_auto_admin_' + id, { whatsapp: false });
  });
  return summary;
}


/* ════════════════════════════════════════════════════════════════════════
   EXCHANGE ROOM — one place for the whole exchange (Oct 2026, owner's rules)
   ────────────────────────────────────────────────────────────────────────
   Chat, condition protection and the delivery/stages panels are now ONE
   room. Both readers chat in it, and every step is recorded in it — each
   step also posts a line into the chat, so the conversation is the record.
   The same 16 steps run for every kind of exchange (sell, rent, lend, swap);
   steps 10–14 (the return) apply only where the book comes back.

     1  Requested                       swap request created
     2  Accepted                        owner accepts → the room opens
     3  Book condition video            sender(s), BEFORE payment; 48 hours
     4  Payment — or close              payer(s), 48 hours after step 3,
                                        or the request closes by itself
     5  Book packaging video            sender(s)
     6  Meeting point or courier        either reader
     7  Place / courier + tracking ID   in person: the pinned place;
                                        courier: courier name + tracking ID
     8  Book handover video             sender(s)
     9  Delivered + received            sender marks delivered, receiver
                                        records the unboxing video and marks
                                        received (a buyer also says "happy")
    10  21 days with the reader         the return deadline is running
    11  7 days left → reminder          posted into the chat
    12  +7 days, or return route        the reader with the book may ask +7
                                        in the next 3 days; the owner agrees.
                                        Then: courier or in person, back
    13  Return videos                   packaging + condition + handover
    14  Returned + received             both mark it
    15  Reflect & rate                  each reader rates the other and
                                        SwapSutra (Google review optional)
    16  Closed                          the room disappears from both
                                        readers' chats; SwapSutra keeps it

   The room is derived from the records that already exist (payments,
   videos, the journey ledger, return deadlines, ratings) — nothing new is
   trusted from the client. computeExchangeRoom_ is pure, so the rules are
   tested without a spreadsheet.
   ════════════════════════════════════════════════════════════════════════ */

const ROOM_WINDOW_HOURS = 48;          // condition video, then payment
const ROOM_REMIND_HOURS = 24;          // a nudge half-way through each window
// Exchanges accepted before the room existed get their 48 hours from here.
const ROOM_TIMERS_START_ISO = '2026-10-09T00:00:00+05:30';
const ROOM_RATING_WINDOW_DAYS = 7;     // the room closes by itself after this
const ROOM_HOUR_MS = 60 * 60 * 1000;
const PLATFORM_FEEDBACK_SHEET = 'PlatformFeedback';
const PLATFORM_FEEDBACK_HEADERS = ['id', 'swapId', 'email', 'role', 'platformRating', 'platformComment', 'readerRating', 'createdAt'];
const ROOM_CLOSED_STATUSES = ['', 'pending', 'declined', 'rejected', 'cancelled', 'expired'];

const ROOM_STEP_TITLES = {
  1: 'Requested',
  2: 'Accepted',
  3: 'Book condition video',
  4: 'Payment — or close',
  5: 'Book packaging video',
  6: 'Meeting point or courier',
  7: 'Place, or courier & tracking ID',
  8: 'Book handover video',
  9: 'Delivered & received — both mark',
  10: '21 days with the reader',
  11: 'Reminder: 7 days left',
  12: '+7 days, or choose how to return',
  13: 'Return: packaging, condition & handover videos',
  14: 'Returned & received — both mark',
  15: 'Reflect & rate',
  16: 'Room closed (saved with SwapSutra)'
};

function roomSwapAccepted_(status) {
  return ROOM_CLOSED_STATUSES.indexOf(String(status || '').trim().toLowerCase()) === -1;
}

/** The chat of an exchange is open while the request stands accepted. */
function roomChatOpen_(swapId) {
  try {
    const swap = loadSwapForCirculation(swapId);
    return !!swap && roomSwapAccepted_(swap.obj.status);
  } catch (err) {
    Logger.log('roomChatOpen_ failed: ' + err);
    return false;
  }
}

function roomName_(email) {
  try { return firstNameOnly(publicReaderName('', email) || humanizeEmailLocalPart(email)) || String(email).split('@')[0]; }
  catch (e) { return String(email || '').split('@')[0]; }
}

/** The parts of an address a parcel needs — nothing else about the buyer. */
function shippingOnlyAddress_(a) {
  const keep = ['name', 'line1', 'line2', 'landmark', 'area', 'city', 'state', 'pincode', 'phone'];
  const out = {};
  keep.forEach(k => { if (a[k] !== undefined && a[k] !== '') out[k] = a[k]; });
  return out;
}

/** Who sends and who receives on a leg, by role. */
function roomLegRoles_(leg) {
  if (leg === 'outbound' || leg === 'counter_return') return { sender: 'owner', receiver: 'requester' };
  return { sender: 'requester', receiver: 'owner' }; // counter, return
}

function roomOutLegs_(swapObj) {
  return String(swapObj.serviceType || 'SWAP').toUpperCase() === 'SWAP' ? ['outbound', 'counter'] : ['outbound'];
}

function roomBackLegs_(swapObj) {
  return returnLegsFor_(swapObj).map(l => l.leg);
}

/** The step a video belongs to, for the chat line. */
function roomStepForVideo_(leg, kind) {
  const back = leg === 'return' || leg === 'counter_return';
  if (kind === 'RECEIVING') return back ? 14 : 9;
  if (back) return 13;
  return kind === 'QUALITY' ? 3 : kind === 'PACKING' ? 5 : 8;
}

function roomIntroMessage_(request) {
  const type = String((request && request.serviceType) || 'SWAP').toUpperCase();
  const back = type === 'RENT' || type === 'LEND' || (type === 'SWAP' && String(request.swapPreference || '').toLowerCase() === 'temporary');
  return '🛡️ This is your exchange room. Chat here, and follow the steps at the top — every step is recorded here.\n\n' +
    '3. The book\'s condition video (by whoever sends a book) — within 48 hours\n' +
    '4. Payment through SwapSutra — within 48 hours after that, or the request closes\n' +
    '5. Packaging video · 6. Meet in person or courier · 7. Place, or courier + tracking ID\n' +
    '8. Handover video · 9. Sender marks delivered, receiver records the unboxing video and marks received\n' +
    (back ? '10–14. 21 days with the reader; with 7 days left you can ask for +7 once (the owner agrees); then the return, with the same videos, and both mark it\n' : '') +
    '15. Rate each other and SwapSutra · 16. The room closes — SwapSutra keeps the record.\n\n' +
    'Do not share phone numbers, addresses, OTPs or UPI PINs in the chat.';
}

/** Posts one line into the exchange chat, as SwapSutra. Never throws. */
function roomPost_(swapId, message) {
  try {
    const chat = findChatBySwapId(swapId);
    const chatId = chat && (chat.chatId || chat.id);
    if (!chatId) return;
    sendChatMessage({ chatId: chatId, senderEmail: 'swapsutra@gmail.com', senderRole: 'Admin', message: message });
  } catch (err) {
    Logger.log('roomPost_ failed: ' + err);
  }
}

/**
 * Has this reader ever rated SwapSutra? (9 Oct 2026, owner's rule: SwapSutra
 * — and the Google review — is asked for once per reader, not every exchange.)
 */
function hasRatedPlatform_(email) {
  const e = normalizeEmail(email);
  if (!e) return false;
  return readSheetObjects_(getPlatformFeedbackSheet_()).rows
    .some(r => normalizeEmail(r.obj.email) === e && Number(r.obj.platformRating) > 0);
}

/** swapId → true for every exchange this reader has already reflected on (rated). */
function ratedSwapIdsFor_(email) {
  const e = normalizeEmail(email);
  const out = {};
  if (!e) return out;
  readSheetObjects_(getPlatformFeedbackSheet_()).rows.forEach(r => {
    if (normalizeEmail(r.obj.email) === e) out[String(r.obj.swapId)] = true;
  });
  return out;
}

function getPlatformFeedbackSheet_() {
  const s = getOrCreateSheet(PLATFORM_FEEDBACK_SHEET, PLATFORM_FEEDBACK_HEADERS);
  ensureSheetHeaders(s, PLATFORM_FEEDBACK_HEADERS);
  return s;
}

/**
 * THE room, from plain inputs (pure). Input:
 *   swapObj, ownerEmail, requesterEmail, viewerRole ('owner'|'requester'|'admin'),
 *   acceptedAtMs, chatStatus, fee {payers, allApproved}, videos[], events[]
 *   (journey rows), returnState, extensions[], readerRatings[], feedback[],
 *   roomEvents[] (stage events with stage ROOM), disputeOpen, myAddressSaved,
 *   myPayoutAccount, nowMs
 */
function computeExchangeRoom_(input) {
  const o = input.swapObj || {};
  const now = typeof input.nowMs === 'number' ? input.nowMs : Date.now();
  const type = String(o.serviceType || 'SWAP').toUpperCase();
  const emailOf = { owner: normalizeEmail(input.ownerEmail), requester: normalizeEmail(input.requesterEmail) };
  const viewer = input.viewerRole || '';
  const outLegs = roomOutLegs_(o);
  const backLegs = roomBackLegs_(o);
  const needsReturn = backLegs.length > 0;
  const videos = input.videos || [];
  const events = (input.events || []).slice().sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
  const roomEvents = input.roomEvents || [];
  const fee = input.fee || { payers: [], allApproved: true };
  const ret = input.returnState || { applies: false };
  const t = v => { const x = new Date(v).getTime(); return isFinite(x) ? x : NaN; };
  const iso = ms => isFinite(ms) ? new Date(ms).toISOString() : '';
  const when = v => { const ms = typeof v === 'number' ? v : t(v); return isFinite(ms) ? returnDateLabel_(new Date(ms)) : ''; };

  const status = String(o.status || '').trim().toLowerCase();
  const accepted = roomSwapAccepted_(o.status);
  const archived = String(input.chatStatus || '') === 'Archived';
  const closedEarly = !accepted && status !== 'pending' && status !== '';

  // ── per leg ──────────────────────────────────────────────────────────
  const video = (leg, kind) => {
    const r = roomLegRoles_(leg);
    const who = kind === 'RECEIVING' ? emailOf[r.receiver] : emailOf[r.sender];
    const list = videos.filter(v => String(v.leg) === leg && v.kind === kind && normalizeEmail(v.uploaderEmail) === who)
      .sort((a, b) => t(a.createdAt) - t(b.createdAt));
    return list.length ? list[list.length - 1] : null;
  };
  const legEvents = leg => events.filter(e => String(e.leg) === leg);
  const legInfo = leg => {
    const r = roomLegRoles_(leg);
    const ev = legEvents(leg);
    const dispatched = ev.filter(e => e.event === 'dispatched' && String(e.awb || '').trim()).pop() || null;
    const senderMark = ev.find(e => e.event === 'handed_over' || (e.event === 'delivered' && normalizeEmail(e.actorEmail) === emailOf[r.sender])) || null;
    const received = ev.find(e => e.event === 'received') || null;
    const v = {};
    ['QUALITY', 'PACKING', 'HANDOVER', 'RECEIVING'].forEach(k => {
      const x = video(leg, k);
      v[k] = x ? { done: true, url: x.url || '', at: iso(t(x.createdAt)), recordedInApp: String(x.recordedInApp) === 'true' } : { done: false };
    });
    return {
      leg: leg, sender: r.sender, receiver: r.receiver,
      youSend: viewer === r.sender, youReceive: viewer === r.receiver,
      videos: v,
      courierName: dispatched ? dispatched.courierName || '' : '',
      awb: dispatched ? String(dispatched.awb || '') : '',
      trackingUrl: dispatched ? courierTrackingUrl(dispatched.courierName, dispatched.awb) : '',
      senderMarkedAt: senderMark ? iso(t(senderMark.createdAt)) : '',
      receivedAt: received ? iso(t(received.createdAt)) : ''
    };
  };
  const out = outLegs.map(legInfo);
  const back = backLegs.map(legInfo);

  const routeOf = isBack => {
    const rs = events.filter(e => e.event === 'route_set' && ((String(e.leg) === 'return') === isBack));
    const r = rs.length ? rs[rs.length - 1] : null;
    if (!r) return null;
    const lat = r.lat === '' || r.lat === undefined ? null : Number(r.lat);
    const lng = r.lng === '' || r.lng === undefined ? null : Number(r.lng);
    return { method: r.method, note: r.note || '', lat: isFinite(lat) ? lat : null, lng: isFinite(lng) ? lng : null,
      setBy: normalizeEmail(r.actorEmail) === emailOf.owner ? 'owner' : 'requester', at: iso(t(r.createdAt)) };
  };
  const outRoute = routeOf(false);
  const backRoute = routeOf(true);

  const all = (legs, fn) => legs.length > 0 && legs.every(fn);
  const has = (l, k) => l.videos[k].done;
  const roomEvent = name => roomEvents.filter(e => e.actionType === name).pop() || null;
  const noticeEvent = roomEvent('extension_notice');
  const doneEvent = roomEvent('exchange_done');
  const closedEvent = roomEvent('room_closed');

  // ── raw step completion ──────────────────────────────────────────────
  const raw = {};
  raw[1] = true;
  raw[2] = accepted || archived;
  raw[3] = all(out, l => has(l, 'QUALITY'));
  raw[4] = !!fee.allApproved;
  raw[5] = all(out, l => has(l, 'PACKING'));
  raw[6] = !!outRoute;
  raw[7] = !!outRoute && (outRoute.method !== 'courier' || all(out, l => !!l.awb));
  raw[8] = all(out, l => has(l, 'HANDOVER'));
  raw[9] = all(out, l => !!l.senderMarkedAt && !!l.receivedAt);
  if (needsReturn) {
    raw[10] = !!noticeEvent || !!backRoute;
    raw[11] = !!noticeEvent || !!backRoute;
    raw[12] = !!backRoute;
    raw[13] = all(back, l => has(l, 'QUALITY') && has(l, 'PACKING') && has(l, 'HANDOVER')) &&
      (!backRoute || backRoute.method !== 'courier' || all(back, l => !!l.awb));
    raw[14] = all(back, l => !!l.senderMarkedAt && !!l.receivedAt);
  }
  const ratedBy = role => (input.feedback || []).some(f => normalizeEmail(f.email) === emailOf[role]);
  raw[15] = ratedBy('owner') && ratedBy('requester');
  raw[16] = archived;

  // A later step being done means the earlier ones are behind us (this
  // also carries exchanges that began before the room existed).
  const order = [];
  for (let n = 1; n <= 16; n++) if (needsReturn || n < 10 || n > 14) order.push(n);
  const done = {};
  order.forEach(n => { done[n] = !!raw[n]; });
  for (let i = order.length - 2; i >= 0; i--) {
    const n = order[i];
    if (n === 15) continue; // closing without rating (timeout) does not mean both rated
    if (done[order[i + 1]] && order[i + 1] !== 16) done[n] = true;
    if (n < 15 && done[16] && !closedEarly) done[n] = true;
  }
  const exchangeDone = !closedEarly && (needsReturn ? !!done[14] : !!done[9]);

  // ── deadlines ────────────────────────────────────────────────────────
  const clockStart = Math.max(isFinite(input.acceptedAtMs) ? input.acceptedAtMs : now, t(ROOM_TIMERS_START_ISO));
  const conditionDoneAt = raw[3] ? Math.max.apply(null, out.map(l => t(l.videos.QUALITY.at))) : NaN;
  const conditionBy = clockStart + ROOM_WINDOW_HOURS * ROOM_HOUR_MS;
  const payBy = (isFinite(conditionDoneAt) ? Math.max(conditionDoneAt, clockStart) : NaN) + ROOM_WINDOW_HOURS * ROOM_HOUR_MS;
  const unpaid = (fee.payers || []).filter(p => p.adminStatus === 'NOT_SUBMITTED' || p.adminStatus === 'ADMIN_REJECTED' || !p.adminStatus);
  const paymentPhase = accepted && !done[4];

  // ── steps for the screen ─────────────────────────────────────────────
  const firstOpen = order.find(n => !done[n]);
  const current = closedEarly ? 16 : (firstOpen || 16);
  const sale = type === 'SELL';
  const titles = Object.assign({}, ROOM_STEP_TITLES);
  if (sale) { titles[4] = 'Payment (book price + fee) — or close'; titles[9] = 'Delivered & received — buyer closes the purchase'; }
  const legNames = l => out.length > 1 ? (l.sender === viewer ? 'your book' : 'their book') : 'the book';
  const detail = {};
  detail[3] = (out.length > 1 ? 'Each of you records your own book\'s condition' : (viewer === 'owner' ? 'You record the book\'s condition' : 'The owner records the book\'s condition')) +
    ' — before anyone pays.' + (paymentPhase && !raw[3] ? ' Due by ' + when(conditionBy) + '.' : '');
  detail[4] = (fee.payers || []).length
    ? (fee.payers || []).map(p => (p.payerRole === viewer ? 'You' : p.payerRole === 'owner' ? 'The owner' : 'The requester') + ': ₹' + p.requiredAmount + ' — ' +
      (p.adminStatus === 'ADMIN_APPROVED' ? 'verified' : p.adminStatus === 'ADMIN_PENDING' ? 'paid, SwapSutra is verifying' : p.adminStatus === 'ADMIN_REJECTED' ? 'not accepted, pay again' : 'to pay')).join(' · ')
    : 'Nothing to pay on this exchange.';
  if (paymentPhase && raw[3] && unpaid.length) detail[4] += ' · Pay by ' + when(payBy) + ', or the request closes.';
  detail[6] = outRoute ? (outRoute.method === 'courier' ? 'Courier' : 'In person') : 'Decide together in the chat; either of you records it.';
  detail[7] = outRoute ? (outRoute.method === 'courier'
    ? out.map(l => legNames(l) + ': ' + (l.awb ? l.courierName + ' ' + l.awb : 'tracking ID to add')).join(' · ')
    : (outRoute.note || 'Meeting point pinned')) : '';
  detail[9] = out.map(l => legNames(l) + ': ' + (l.senderMarkedAt ? 'delivered ✓' : 'delivered —') + ' / ' + (l.receivedAt ? 'received ✓' : 'received —')).join(' · ');
  if (needsReturn) {
    detail[10] = ret.started ? 'Return due by ' + when(ret.dueAt) + (ret.daysLeft > 0 ? ' (' + ret.daysLeft + ' days left)' : '') + '. You can return it any time before.' : 'Starts when the book reaches the reader.';
    detail[11] = noticeEvent ? 'Reminder posted in the chat.' : 'Posted in the chat when 7 days are left.';
    const w = ret.extensionWindow || {};
    detail[12] = (ret.pendingExtension ? '+7 days asked — waiting for the owner. ' : ret.extensionDays ? 'Extended by ' + ret.extensionDays + ' days. ' :
      w.opensAt ? '+7 days can be asked for between ' + when(w.opensAt) + ' and ' + when(w.closesAt) + '. ' : '') +
      (backRoute ? 'Return route: ' + (backRoute.method === 'courier' ? 'courier' : 'in person' + (backRoute.note ? ' — ' + backRoute.note : '')) : 'Then choose: courier or in person.');
    detail[14] = back.map(l => (l.sender === viewer ? 'you send' : 'they send') + ': ' + (l.senderMarkedAt ? 'returned ✓' : 'returned —') + ' / ' + (l.receivedAt ? 'received ✓' : 'received —')).join(' · ');
  }
  detail[15] = 'Owner ' + (ratedBy('owner') ? '✓' : '—') + ' · Requester ' + (ratedBy('requester') ? '✓' : '—');
  const at = {};
  at[1] = iso(t(o.createdAt));
  at[2] = iso(input.acceptedAtMs);
  at[6] = outRoute ? outRoute.at : '';
  at[11] = noticeEvent ? iso(t(noticeEvent.createdAt)) : '';
  at[12] = backRoute ? backRoute.at : '';
  at[16] = closedEvent ? iso(t(closedEvent.createdAt)) : '';

  const steps = [];
  for (let n = 1; n <= 16; n++) {
    const applies = needsReturn || n < 10 || n > 14;
    let state;
    if (!applies) state = 'skipped';
    else if (done[n]) state = 'done';
    else if (closedEarly) state = n === 16 ? 'done' : 'closed';
    else if (n === current) state = 'current';
    else state = 'upcoming';
    steps.push({ n: n, title: titles[n], state: state,
      detail: !applies ? (sale ? 'Not needed — a sale is final.' : 'Not needed — this exchange is permanent.') : (detail[n] || ''),
      at: at[n] || '' });
  }

  // ── what the viewer can do now ───────────────────────────────────────
  const actions = [];
  const me = viewer === 'owner' || viewer === 'requester' ? viewer : '';
  const push = a => actions.push(a);
  const blocked = !me || closedEarly || archived || input.disputeOpen;
  if (!blocked) {
    if (paymentPhase) {
      out.filter(l => l.youSend && !has(l, 'QUALITY')).forEach(l => push({ type: 'video', step: 3, leg: l.leg, kind: 'QUALITY' }));
      const myFee = (fee.payers || []).find(p => p.payerRole === me);
      if (raw[3] && myFee && unpaid.indexOf(myFee) !== -1) push({ type: 'pay', step: 4, amount: myFee.requiredAmount });
      push({ type: 'close', step: 4 });
    } else if (accepted && !done[9]) {
      const legSteps = (legs, route, firstStep) => {
        // firstStep: 3 on the way out, 13 on the way back
        const isBack = firstStep === 13;
        legs.filter(l => l.youSend).forEach(l => {
          if (!has(l, 'QUALITY')) push({ type: 'video', step: isBack ? 13 : 3, leg: l.leg, kind: 'QUALITY' });
          if (!has(l, 'PACKING')) push({ type: 'video', step: isBack ? 13 : 5, leg: l.leg, kind: 'PACKING' });
        });
        if (!route) { push({ type: 'setRoute', step: isBack ? 12 : 6, phase: isBack ? 'back' : 'out' }); return; }
        if (route.method === 'courier') {
          if (legs.some(l => l.youReceive) && !input.myAddressSaved) push({ type: 'address', step: isBack ? 12 : 7 });
          legs.filter(l => l.youSend && !l.awb && has(l, 'QUALITY') && has(l, 'PACKING'))
            .forEach(l => push({ type: 'courier', step: isBack ? 13 : 7, leg: l.leg }));
        }
        legs.filter(l => l.youSend).forEach(l => {
          if (!has(l, 'HANDOVER')) push({ type: 'video', step: isBack ? 13 : 8, leg: l.leg, kind: 'HANDOVER' });
          else if (!l.senderMarkedAt && has(l, 'QUALITY') && has(l, 'PACKING') && (route.method !== 'courier' || l.awb)) {
            push({ type: 'markDelivered', step: isBack ? 14 : 9, leg: l.leg, method: route.method });
          }
        });
        legs.filter(l => l.youReceive && !l.receivedAt).forEach(l => {
          if (!has(l, 'RECEIVING')) push({ type: 'video', step: isBack ? 14 : 9, leg: l.leg, kind: 'RECEIVING' });
          else push({ type: 'markReceived', step: isBack ? 14 : 9, leg: l.leg, sale: sale && l.leg === 'outbound' && input.saleEscrow !== false });
        });
      };
      legSteps(out, outRoute, 3);
    } else if (accepted && needsReturn && !done[14]) {
      const w = ret.extensionWindow || {};
      const canAsk = type === 'SWAP' || me === 'requester';
      if (!backRoute && w.open && canAsk && !ret.pendingExtension) push({ type: 'requestExtension', step: 12, days: 7, closesAt: w.closesAt });
      if (ret.pendingExtension && normalizeEmail(ret.pendingExtension.requestedBy) !== emailOf[me] && (type === 'SWAP' || me === 'owner')) {
        push({ type: 'answerExtension', step: 12, extensionId: ret.pendingExtension.id, days: ret.pendingExtension.days, reason: ret.pendingExtension.reason || '' });
      }
      if (!backRoute) push({ type: 'setRoute', step: 12, phase: 'back' });
      else {
        // Reuse the leg logic for the way back.
        const legsB = back;
        legsB.filter(l => l.youSend).forEach(l => {
          if (!has(l, 'PACKING')) push({ type: 'video', step: 13, leg: l.leg, kind: 'PACKING' });
          if (!has(l, 'QUALITY')) push({ type: 'video', step: 13, leg: l.leg, kind: 'QUALITY' });
        });
        if (backRoute.method === 'courier') {
          if (legsB.some(l => l.youReceive) && !input.myAddressSaved) push({ type: 'address', step: 12 });
          legsB.filter(l => l.youSend && !l.awb && has(l, 'QUALITY') && has(l, 'PACKING')).forEach(l => push({ type: 'courier', step: 13, leg: l.leg }));
        }
        legsB.filter(l => l.youSend).forEach(l => {
          if (!has(l, 'HANDOVER')) push({ type: 'video', step: 13, leg: l.leg, kind: 'HANDOVER' });
          else if (!l.senderMarkedAt && has(l, 'QUALITY') && has(l, 'PACKING') && (backRoute.method !== 'courier' || l.awb)) {
            push({ type: 'markDelivered', step: 14, leg: l.leg, method: backRoute.method });
          }
        });
        legsB.filter(l => l.youReceive && !l.receivedAt).forEach(l => {
          if (!has(l, 'RECEIVING')) push({ type: 'video', step: 14, leg: l.leg, kind: 'RECEIVING' });
          else push({ type: 'markReceived', step: 14, leg: l.leg, sale: false });
        });
      }
    }
    if (exchangeDone && !ratedBy(me)) push({ type: 'rate', step: 15 });
  }
  // Money owed to the viewer needs somewhere to go.
  if (me && !closedEarly && !input.myPayoutAccount) {
    const owedSale = sale && me === 'owner' && input.saleEscrow !== false;
    const owedRefund = exchangeDone && (fee.payers || []).some(p => p.payerRole === me && Number(p.depositAmount || 0) > 0);
    const owedRent = type === 'RENT' && me === 'owner' && exchangeDone && rentChargeFor_(o) > 0;
    if (owedSale || owedRefund || owedRent) push({ type: 'payoutAccount', step: sale ? 9 : (needsReturn ? 14 : 9) });
  }

  // What the viewer is waiting for, when there is nothing for them to do.
  let waitingOn = '';
  const otherName = me === 'owner' ? 'the other reader' : me === 'requester' ? (type === 'SELL' ? 'the seller' : 'the owner') : 'the readers';
  if (closedEarly) waitingOn = '';
  else if (input.disputeOpen) waitingOn = 'A problem was reported. SwapSutra is reviewing the videos; the steps are paused until then.';
  else if (archived) waitingOn = '';
  else if (!actions.some(a => a.type !== 'close' && a.type !== 'payoutAccount')) {
    if (paymentPhase && !raw[3]) waitingOn = 'Waiting for ' + otherName + ' to record the book\'s condition video.';
    else if (paymentPhase && unpaid.length) waitingOn = 'Waiting for the payment.';
    else if (paymentPhase) waitingOn = 'SwapSutra is verifying the payment — usually within a few hours.';
    else if (needsReturn && done[9] && !done[12] && !(ret.extensionWindow || {}).open) waitingOn = ret.started ? 'Enjoy the book. The return is due by ' + when(ret.dueAt) + '.' : '';
    else if (exchangeDone && ratedBy(me)) waitingOn = 'Thanks for rating. The room closes once ' + otherName + ' rates too (or in ' + ROOM_RATING_WINDOW_DAYS + ' days).';
    else if (firstOpen) waitingOn = 'Waiting for ' + otherName + ' — step ' + firstOpen + ': ' + titles[firstOpen] + '.';
  }

  return {
    type: type,
    needsReturn: needsReturn,
    accepted: accepted,
    closed: closedEarly || archived,
    closedReason: closedEarly ? (closedEvent ? closedEvent.note : 'This request was closed.') : (archived ? (closedEvent ? closedEvent.note : 'Exchange complete.') : ''),
    current: current,
    steps: steps,
    actions: actions,
    waitingOn: waitingOn,
    legs: { out: out, back: back },
    route: { out: outRoute, back: backRoute },
    deadlines: {
      conditionBy: paymentPhase && !raw[3] ? iso(conditionBy) : '',
      payBy: paymentPhase && raw[3] && unpaid.length ? iso(payBy) : ''
    },
    exchangeDone: exchangeDone,
    exchangeDoneAt: doneEvent ? iso(t(doneEvent.createdAt)) : '',
    finishedRecorded: !!doneEvent,
    noticePosted: !!noticeEvent,
    rated: { owner: ratedBy('owner'), requester: ratedBy('requester') },
    _raw: raw,
    _timers: { clockStart: clockStart, conditionBy: conditionBy, payBy: payBy, conditionDone: !!raw[3], unpaidRoles: unpaid.map(p => p.payerRole) }
  };
}

/** Loads everything the room needs for one exchange. */
function roomInputFor_(swap, viewerEmail, nowMs) {
  const id = String(swap.obj.id);
  const viewer = normalizeEmail(viewerEmail);
  const chat = findChatBySwapId(id) || {};
  const role = viewer === swap.ownerEmail ? 'owner' : viewer === swap.requesterEmail ? 'requester' : (isAuthenticatedAdmin() ? 'admin' : '');
  let acceptedAtMs = new Date(chat.createdAt).getTime();
  if (!isFinite(acceptedAtMs)) acceptedAtMs = new Date(swap.obj.updatedAt || swap.obj.createdAt).getTime();
  const fee = securityFeeStatus(swap, viewer, role === 'admin');
  const stageEvents = loadStageEvents(id);
  const ratings = readSheetObjects_(getReaderRatingsSheet()).rows.map(r => r.obj).filter(r => String(r.swapId) === id);
  const feedback = readSheetObjects_(getPlatformFeedbackSheet_()).rows.map(r => r.obj).filter(r => String(r.swapId) === id);
  const extensions = readSheetObjects_(getReturnExtensionSheet_()).rows.map(r => r.obj).filter(o => String(o.swapId) === id);
  return {
    swapObj: swap.obj,
    ownerEmail: swap.ownerEmail,
    requesterEmail: swap.requesterEmail,
    viewerRole: role,
    acceptedAtMs: acceptedAtMs,
    chatStatus: chat.chatStatus || '',
    chatId: chat.chatId || chat.id || '',
    fee: fee,
    videos: vmsVideosForSwap_(id),
    events: journeyEventsBySwap_()[id] || [],
    returnState: returnStateForSwap_(swap),
    extensions: extensions,
    readerRatings: ratings,
    feedback: feedback,
    roomEvents: stageEvents.filter(e => e.stage === 'ROOM'),
    disputeOpen: swapHasOpenDispute(id),
    myAddressSaved: !!(viewer && readDeliveryAddress(viewer)),
    myPayoutAccount: viewer ? readPayoutAccount_(viewer) : null,
    saleEscrow: String(swap.obj.serviceType || '').toUpperCase() === 'SELL' ? saleEscrowActive_(swap) : false,
    nowMs: nowMs
  };
}

/** Action: getExchangeRoom { swapId } — either reader, or SwapSutra. */
function getExchangeRoom(data) {
  try {
    const caller = normalizeEmail(getAuthenticatedEmail());
    if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to open the exchange.' };
    const swap = loadSwapForCirculation(String((data && data.swapId) || '').trim());
    if (!swap) return { success: false, message: 'That exchange could not be found.' };
    if (!callerIsPartyTo(swap, caller) && !isAuthenticatedAdmin()) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
    const input = roomInputFor_(swap, caller);
    const room = computeExchangeRoom_(input);
    delete room._raw; delete room._timers;
    // 9 Oct 2026: on a courier route the addresses come WITH the room (which
    // refreshes every 20 s), so the sender sees the receiver's address as
    // soon as it is saved — it used to be fetched once and never again.
    // Same rule as getDeliveryAddress: a party, payment verified, courier
    // route for a trip still to happen, room open.
    let delivery = null;
    const outDone = room.steps.some(st => st.n === 9 && st.state === 'done');
    const courierLeft = !room.closed && input.fee.allApproved &&
      ((room.route.out && room.route.out.method === 'courier' && !outDone) ||
       (room.route.back && room.route.back.method === 'courier' && !room.exchangeDone));
    if (courierLeft && (input.viewerRole === 'owner' || input.viewerRole === 'requester')) {
      const other = caller === swap.ownerEmail ? swap.requesterEmail : swap.ownerEmail;
      delivery = { theirAddress: readDeliveryAddress(other), myAddress: readDeliveryAddress(caller) };
      // A partner gets only what a parcel needs (9 Oct 2026, owner's rule).
      if (delivery.theirAddress && approvedPartner_(caller)) {
        let recipient = '';
        try { recipient = String((findRowByEmail_('Users', normalizeEmail(other)) || {}).name || ''); } catch (e) { recipient = ''; }
        delivery.theirAddress = shippingOnlyAddress_(Object.assign({}, delivery.theirAddress, { name: recipient }));
      }
    }
    const ret = input.returnState || {};
    const pending = ret.pendingExtension ? { id: ret.pendingExtension.id, days: ret.pendingExtension.days, reason: ret.pendingExtension.reason || '',
      youAsked: normalizeEmail(ret.pendingExtension.requestedBy) === caller } : null;
    return Object.assign({ success: true, swapId: swap.obj.id, role: input.viewerRole, chatId: input.chatId,
      bookTitle: String(swap.obj.requestedBookTitle || ''),
      otherName: approvedPartner_(caller) ? 'the buyer' : roomName_(caller === swap.ownerEmail ? swap.requesterEmail : swap.ownerEmail),
      disputeOpen: input.disputeOpen,
      payment: { payers: input.fee.payers, allApproved: input.fee.allApproved, upi: paymentDetails_() },
      returnInfo: ret.applies && ret.started ? { dueAt: ret.dueAt, daysLeft: ret.daysLeft, overdue: ret.overdue, extensionDays: ret.extensionDays,
        window: ret.extensionWindow || null, pendingExtension: pending } : null,
      sale: String(swap.obj.serviceType || '').toUpperCase() === 'SELL' ? saleStatusFor_(swap) : null,
      // A rental: the rent comes out of the deposit at the end (9 Oct 2026).
      rentCharge: rentChargeFor_(swap.obj),
      // A swap: the ₹10 fee is taken from the deposit refund (9 Oct 2026).
      feeFromDeposit: input.viewerRole === 'owner' || input.viewerRole === 'requester'
        ? feeTakenFromDeposit_(swap.obj, input.viewerRole === 'owner' ? swap.ownerEmail : swap.requesterEmail, myFeeRecord_(swap.obj.id, input.viewerRole)) : 0,
      // SwapSutra is rated once per reader; and the room closes for a reader
      // as soon as they have reflected & rated.
      platformRated: hasRatedPlatform_(caller),
      closedForYou: !!(input.viewerRole && room.rated && room.rated[input.viewerRole]),
      payoutAccount: input.myPayoutAccount,
      myAddressSaved: input.myAddressSaved,
      delivery: delivery,
      stampCode: vmsStampCode_(swap.obj.id),
      couriers: Object.keys(COURIERS),
      reviewUrl: GOOGLE_REVIEW_URL,
      policy: RETURN_POLICY_TEXT
    }, room);
  } catch (err) {
    return { success: false, message: err.toString() };
  }
}

/** The legs a phase covers. */
function roomPhaseOfLeg_(leg) {
  return leg === 'return' || leg === 'counter_return' ? 'back' : 'out';
}

/**
 * Action: exchangeRoomAction { swapId, act, ... } — the steps that are not
 * a video or a payment (those use vmsStartUpload… and submitSecurityFeePayment).
 *   close              before payment is complete: closes the request
 *   setRoute           { phase: out|back, method, meetingLat, meetingLng, meetingPoint }
 *   courierDetails     { leg, courierName, awb }
 *   markDelivered      { leg }              the sender
 *   markReceived       { leg, happy? }      the receiver (a buyer must be happy)
 *   requestExtension   { reason? }          +7, in the window
 *   answerExtension    { extensionId, accept }
 *   rate               { readerRating, readerComment?, platformRating, platformComment? }
 */
function exchangeRoomAction(data) {
  try {
    const caller = normalizeEmail(getAuthenticatedEmail());
    if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to continue.' };
    const swapId = String((data && data.swapId) || '').trim();
    const swap = loadSwapForCirculation(swapId);
    if (!swap) return { success: false, message: 'That exchange could not be found.' };
    const role = swapPartyRole(swap, caller);
    if (!role) return { success: false, error: 'UNAUTHORIZED', message: 'This exchange is not yours.' };
    const act = String((data && data.act) || '');
    const input = roomInputFor_(swap, caller);
    const room = computeExchangeRoom_(input);
    if (room.closed) return { success: false, error: 'ROOM_CLOSED', message: 'This exchange room is closed.' };
    if (input.disputeOpen && act !== 'close') {
      return { success: false, error: 'DISPUTE_OPEN', message: 'A problem is being reviewed on this exchange. The steps are paused until SwapSutra decides.' };
    }
    const name = roomName_(caller);
    const title = String(swap.obj.requestedBookTitle || 'the book');
    const allowed = type => room.actions.some(a => a.type === type && (!data.leg || !a.leg || a.leg === data.leg));
    const legOk = (leg) => (room.legs.out.concat(room.legs.back)).find(l => l.leg === leg) || null;

    if (act === 'close') {
      if (input.fee.allApproved) return { success: false, message: 'The payment is already complete, so the request can no longer be closed here. Report a problem if something is wrong.' };
      return roomCloseRequest_(swap, caller, 'Closed by ' + name + ' before payment' + (data.reason ? ': ' + String(data.reason).slice(0, 120) : '') + '.', false);
    }

    if (act === 'setRoute') {
      const phase = String(data.phase || 'out') === 'back' ? 'back' : 'out';
      if (!room.actions.some(a => a.type === 'setRoute' && a.phase === phase)) {
        return { success: false, error: 'STEP_LOCKED', message: phase === 'back' ? 'The return route is chosen after the book has been delivered and received.' : 'The route is chosen once the payment is verified.' };
      }
      return setSwapRoute({ swapId: swapId, method: data.method, meetingLat: data.meetingLat, meetingLng: data.meetingLng, meetingPoint: data.meetingPoint, phase: phase });
    }

    if (act === 'courierDetails') {
      const leg = String(data.leg || '');
      const l = legOk(leg);
      if (!l || !l.youSend) return { success: false, error: 'WRONG_PARTY', message: 'Only the reader sending this book adds its tracking ID.' };
      if (!allowed('courier')) return { success: false, error: 'STEP_LOCKED', message: 'Record the condition and packaging videos first, on a courier route.' };
      const courierName = String(data.courierName || '').trim();
      const awb = String(data.awb || '').trim().toUpperCase();
      if (!Object.prototype.hasOwnProperty.call(COURIERS, courierName)) return { success: false, message: 'Choose the courier company.' };
      if (!/^[A-Z0-9-]{4,40}$/.test(awb)) return { success: false, message: 'Enter the tracking ID (AWB) exactly as on the receipt.' };
      const res = appendJourneyEvent({ swapId: swapId, leg: leg, event: 'dispatched', actorEmail: caller, method: 'courier', courierName: courierName, awb: awb,
        note: 'Posted with ' + courierName }, swap);
      if (res && res.success === false) return res;
      roomPost_(swapId, '📦 Step ' + (roomPhaseOfLeg_(leg) === 'back' ? 13 : 7) + ' · ' + name + ' posted ' + (roomPhaseOfLeg_(leg) === 'back' ? 'the book back' : 'the book') +
        ' with ' + courierName + '. Tracking ID: ' + awb + '.');
      return { success: true, message: 'Tracking ID saved. Now record the handover video.' };
    }

    if (act === 'markDelivered') {
      const leg = String(data.leg || '');
      const l = legOk(leg);
      if (!l || !l.youSend) return { success: false, error: 'WRONG_PARTY', message: 'Only the reader sending this book marks it delivered.' };
      if (l.senderMarkedAt) return { success: false, message: 'You have already marked this book delivered.' };
      if (!allowed('markDelivered')) {
        const missing = ['QUALITY', 'PACKING', 'HANDOVER'].filter(k => !l.videos[k].done);
        return { success: false, error: missing.length ? 'VIDEO_REQUIRED' : 'STEP_LOCKED', missing: missing,
          message: missing.length ? 'Record the ' + missing.map(k => VMS_KIND_LABELS[k]).join(', the ') + ' first.' : 'Add the courier and tracking ID first.' };
      }
      const route = roomPhaseOfLeg_(leg) === 'back' ? room.route.back : room.route.out;
      const res = appendJourneyEvent({ swapId: swapId, leg: leg, event: route && route.method === 'courier' ? 'delivered' : 'handed_over', actorEmail: caller,
        method: route ? route.method : '', note: 'Marked delivered by the sender' }, swap);
      if (res && res.success === false) return res;
      roomPost_(swapId, '✅ Step ' + (roomPhaseOfLeg_(leg) === 'back' ? 14 : 9) + ' · ' + name + ' marked ' + (roomPhaseOfLeg_(leg) === 'back' ? 'the book returned' : 'the book delivered') + '.');
      roomAfterMark_(swap);
      return { success: true, message: 'Marked delivered.' };
    }

    if (act === 'markReceived') {
      const leg = String(data.leg || '');
      const l = legOk(leg);
      if (!l || !l.youReceive) return { success: false, error: 'WRONG_PARTY', message: 'Only the reader receiving this book marks it received.' };
      if (l.receivedAt) return { success: false, message: 'You have already marked this book received.' };
      if (!l.videos.RECEIVING.done) return { success: false, error: 'VIDEO_REQUIRED', missing: ['RECEIVING'], message: 'Record the receiving / unboxing video first — start before you open the parcel.' };
      if (!allowed('markReceived')) return { success: false, error: 'STEP_LOCKED', message: 'This book is not on its way to you yet.' };
      const isSale = String(swap.obj.serviceType || '').toUpperCase() === 'SELL' && leg === 'outbound';
      const happy = data && (data.happy === true || data.happy === 'true');
      if (isSale && saleEscrowActive_(swap) && !happy) {
        return { success: false, error: 'NOT_HAPPY', message: 'If something is wrong with the book, report a problem instead — SwapSutra will review the videos before the seller is paid.' };
      }
      const res = appendJourneyEvent({ swapId: swapId, leg: leg, event: 'received', actorEmail: caller, method: '', note: happy ? 'Received — happy with the book' : 'Received' }, swap);
      if (res && res.success === false) return res;
      roomPost_(swapId, '📗 Step ' + (roomPhaseOfLeg_(leg) === 'back' ? 14 : 9) + ' · ' + name + ' marked ' + (roomPhaseOfLeg_(leg) === 'back' ? 'their book received back' : 'the book received') + (happy ? ' and is happy with it' : '') + '.');
      let saleResult = null;
      if (isSale && saleEscrowActive_(swap)) saleResult = confirmSaleComplete({ swapId: swapId, happy: true });
      roomAfterMark_(swap);
      return { success: true, message: isSale ? 'Purchase closed — the seller will be paid. Enjoy the book!' : 'Marked received.', sale: saleResult };
    }

    if (act === 'requestExtension') {
      if (!allowed('requestExtension')) {
        const w = (input.returnState || {}).extensionWindow || {};
        return { success: false, error: 'EXTENSION_WINDOW', message: w.used ? 'An extension can be asked for once per exchange.'
          : w.opensAt ? '+7 days can be asked for in the 3 days after the 7-days-left reminder.' : 'There is no return date to extend yet.' };
      }
      const res = requestReturnExtension({ swapId: swapId, days: 7, reason: data.reason });
      if (res && res.success) roomPost_(swapId, '⏳ Step 12 · ' + name + ' asked for 7 more days' + (data.reason ? ' — "' + String(data.reason).slice(0, 120) + '"' : '') + '. The owner can agree or decline at the top of this room.');
      return res;
    }

    if (act === 'answerExtension') {
      if (!allowed('answerExtension')) return { success: false, error: 'WRONG_PARTY', message: 'There is no extension request for you to answer.' };
      const accept = data && (data.accept === true || data.accept === 'true');
      const res = respondReturnExtension({ swapId: swapId, extensionId: data.extensionId, accept: accept });
      if (res && res.success) {
        const st = returnStateForSwap_(swap);
        roomPost_(swapId, accept ? '✅ Step 12 · ' + name + ' agreed to +7 days. The return is now due by ' + returnDateLabel_(new Date(st.dueAt)) + '.'
          : '✖️ Step 12 · ' + name + ' declined the extension. The return is due by ' + returnDateLabel_(new Date(st.dueAt)) + ' — choose courier or in person to start it.');
      }
      return res;
    }

    if (act === 'rate') return roomRate_(swap, caller, role, data, room);

    return { success: false, message: 'Unknown step.' };
  } catch (err) {
    return { success: false, message: err.toString() };
  }
}

/** After a delivered/received mark: if that finished the exchange, record it. */
function roomAfterMark_(swap) {
  try {
    const room = computeExchangeRoom_(roomInputFor_(swap, swap.ownerEmail));
    if (room.exchangeDone && !room.finishedRecorded) roomFinishExchange_(swap, room);
  } catch (err) {
    Logger.log('roomAfterMark_ failed: ' + err);
  }
}

/** The books have arrived (and come back, where they must): open the rating step. */
function roomFinishExchange_(swap, room) {
  const id = String(swap.obj.id);
  appendStageEvent({ swapId: id, stage: 'ROOM', party: 'system', actionType: 'exchange_done', actorEmail: 'swapsutra@gmail.com',
    note: room && room.needsReturn ? 'Returned and received by both readers.' : 'Delivered and received.' });
  markSwapCompletedInChat(swap);
  const created = roomCreateRefunds_(swap);
  const refunds = created.filter(r => /^refund:/.test(String(r.leg)));
  const rentRec = created.find(r => String(r.leg) === 'rent');
  roomPost_(id, '🎉 ' + (room && room.needsReturn ? 'Step 14 done — the book is back with its owner.' : 'Step 9 done — the exchange is complete.') +
    (rentRec ? ' The rent, ₹' + rentRec.amount + ', comes out of the deposit and goes to the owner.' : '') +
    (refunds.length ? ' SwapSutra will refund ₹' + refunds.map(r => r.amount).join(' and ₹') + ' of security deposit to the UPI ID in your settings' +
      (created.some(r => /^fee:/.test(String(r.leg))) ? ' (the ₹10 platform fee is taken from each deposit).' : '.') : '') +
    '\n\nStep 15 · Reflect & rate: rate each other and SwapSutra at the top of this room. The room then closes (it stays saved with SwapSutra).');
  [swap.ownerEmail, swap.requesterEmail].forEach(email => {
    try {
      createNotification(email, 'room_rate', 'Exchange complete — please rate', 'Rate the other reader and SwapSutra to close the exchange room for "' +
        (swap.obj.requestedBookTitle || 'the book') + '".', id, { link: '/profile', dedupeKey: 'room_done_' + id + '_' + email });
    } catch (e) { /* the chat line above is enough */ }
  });
}

/**
 * Deposit refunds once the exchange is complete: every verified deposit
 * goes back to the reader who paid it — unless it was forfeited (late
 * return) or SwapSutra decided it in a dispute. Waits while a dispute is
 * open. Idempotent: one refund record per reader.
 */
function roomCreateRefunds_(swap) {
  const id = String(swap.obj.id);
  if (swapHasOpenDispute(id)) return [];
  const sheet = getReturnForfeitSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  const existing = readSheetObjects_(sheet).rows.map(r => r.obj).filter(f => String(f.swapId) === id);
  const created = [];
  loadSecurityFeeRows(id).rows.map(r => r.obj).forEach(rec => {
    if (rec.adminStatus !== 'ADMIN_APPROVED') return;
    const deposit = feeRecordBreakdown_(rec).depositAmount;
    if (!(deposit > 0)) return;
    const role = rec.payerRole;
    // The deposit that protected a late-returned book is the owner's now.
    const forfeitLeg = role === 'requester' ? 'return' : 'counter_return';
    if (existing.some(f => String(f.leg) === forfeitLeg)) return;
    if (existing.some(f => /^dispute:/.test(String(f.leg)) && String(f.leg).split(':').pop() === role)) return;
    if (existing.some(f => String(f.leg) === 'refund:' + role)) return;
    const title = String(swap.obj.requestedBookTitle || 'the book');

    // A rental (owner's rule, 9 Oct 2026): the rent comes out of the
    // renter's deposit and goes to the book's owner; the rest is refunded.
    let rent = 0;
    if (role === 'requester' && String(swap.obj.serviceType || '').toUpperCase() === 'RENT') {
      rent = Math.min(deposit, rentChargeFor_(swap.obj));
      if (rent > 0 && !existing.some(f => String(f.leg) === 'rent')) {
        const rentRec = {
          id: generateId('SS_RENT_'), swapId: id, leg: 'rent', bookTitle: title,
          defaulterEmail: normalizeEmail(rec.payerEmail), ownerEmail: swap.ownerEmail, amount: rent, dueAt: '', forfeitedAt: new Date(),
          payoutStatus: 'TO_PAY_OWNER', note: 'Rent for "' + title + '", taken from the renter\'s ₹' + deposit + ' deposit.'
        };
        // A partner owner (9 Oct 2026): commission kept, paid with the month's statement.
        const rentParts = partnerPayoutParts_(swap.ownerEmail, rent, rentRec.forfeitedAt);
        if (rentParts) {
          rentRec.amount = rentParts.net; rentRec.grossAmount = rent; rentRec.payoutCycle = rentParts.cycle;
          rentRec.note += rentParts.commission ? ' Partner: − ₹' + rentParts.commission + ' commission.' : ' Partner: no commission.';
          appendCommissionRow_(sheet, headers, id, title, swap.ownerEmail, rentParts.commission, rentParts.cycle, Math.round(rentParts.rate * 100) + '% commission on ₹' + rent + ' rent.');
        }
        sheet.appendRow(headers.map(k => rentRec[k] !== undefined ? rentRec[k] : ''));
        existing.push(rentRec);
        created.push(rentRec);
        try {
          returnNotify_(swap.ownerEmail, 'room_rent_due', 'Your rent is on its way',
            '"' + title + '" is back with you. SwapSutra will send you the rent, ₹' + rent + (readPayoutAccount_(swap.ownerEmail) ? '.' : ' — add your UPI ID in Profile → Settings so we can pay you.'),
            id, 'room_rent_owner_' + id);
          returnNotify_('swapsutra@gmail.com', 'room_rent_admin', 'Pay rent to an owner',
            'Exchange ' + id + ': pay ₹' + rent + ' rent to ' + swap.ownerEmail + ' (from the renter\'s deposit) and mark it paid in Admin → Payouts.', id, 'room_rent_admin_' + id, { whatsapp: false });
        } catch (e) { /* the payout record is the source of truth */ }
      }
    }
    // A swap (9 Oct 2026): SwapSutra's ₹10 fee comes out of the refund.
    const feeCut = Math.max(0, Math.min(deposit - rent, feeTakenFromDeposit_(swap.obj, rec.payerEmail, rec)));
    if (feeCut > 0 && !existing.some(f => String(f.leg) === 'fee:' + role)) {
      const feeRec = {
        id: generateId('SS_FEE_KEPT_'), swapId: id, leg: 'fee:' + role, bookTitle: title,
        defaulterEmail: normalizeEmail(rec.payerEmail), ownerEmail: 'swapsutra@gmail.com', amount: feeCut, dueAt: '', forfeitedAt: new Date(),
        payoutStatus: 'KEPT_AS_FEE', note: 'Platform fee taken from the ₹' + deposit + ' deposit.'
      };
      sheet.appendRow(headers.map(k => feeRec[k] !== undefined ? feeRec[k] : ''));
      existing.push(feeRec);
      created.push(feeRec);
    }
    const refundAmount = deposit - rent - feeCut;
    if (!(refundAmount > 0)) return;
    const rec2 = {
      id: generateId('SS_REFUND_'), swapId: id, leg: 'refund:' + role, bookTitle: title,
      defaulterEmail: '', ownerEmail: normalizeEmail(rec.payerEmail), amount: refundAmount, dueAt: '', forfeitedAt: new Date(),
      payoutStatus: 'TO_PAY_OWNER',
      note: rent > 0 ? 'Deposit refund: ₹' + deposit + ' deposit − ₹' + rent + ' rent paid to the owner.'
        : feeCut > 0 ? 'Deposit refund: ₹' + deposit + ' deposit − ₹' + feeCut + ' platform fee.'
        : 'Security deposit refund — exchange completed.'
    };
    sheet.appendRow(headers.map(k => rec2[k] !== undefined ? rec2[k] : ''));
    existing.push(rec2);
    created.push(rec2);
    try {
      returnNotify_('swapsutra@gmail.com', 'room_refund_admin', 'Refund a security deposit',
        'Exchange ' + id + ' is complete. Refund ₹' + refundAmount + ' to ' + rec.payerEmail + (rent > 0 ? ' (₹' + deposit + ' deposit − ₹' + rent + ' rent)' : feeCut > 0 ? ' (₹' + deposit + ' deposit − ₹' + feeCut + ' platform fee)' : '') + ' and mark it paid in Admin → Payouts.', id, 'room_refund_admin_' + id + '_' + role, { whatsapp: false });
    } catch (e) { /* the payout record is the source of truth */ }
  });
  return created;
}

/** The rent agreed for a rental (monthly rent × months, set on the server at request time). */
function rentChargeFor_(swapObj) {
  if (String(swapObj.serviceType || '').toUpperCase() !== 'RENT') return 0;
  const amount = Math.round(Number(swapObj.amount || 0));
  if (amount > 0) return amount;
  const monthly = Number(swapObj.monthlyRent || 0);
  const months = Math.max(1, Math.ceil(Number(swapObj.durationDays || 30) / 30));
  return monthly > 0 ? Math.round(monthly * months) : 0;
}

/** Closes a request before (or instead of) payment. Anything already paid is refunded. */
function roomCloseRequest_(swap, actorEmail, reason, automatic) {
  const id = String(swap.obj.id);
  const statusIdx = swap.headers.indexOf('status');
  if (statusIdx !== -1) swap.sheet.getRange(swap.rowIndex + 1, statusIdx + 1).setValue(automatic ? 'Expired' : 'Cancelled');
  const upd = swap.headers.indexOf('updatedAt');
  if (upd !== -1) swap.sheet.getRange(swap.rowIndex + 1, upd + 1).setValue(new Date());
  swap.obj.status = automatic ? 'Expired' : 'Cancelled';

  // Money already sent comes back in full (fee included — nothing happened).
  const sheet = getReturnForfeitSheet_();
  const headers = ensureSheetHeaders(sheet, RETURN_FORFEIT_HEADERS);
  const existing = readSheetObjects_(sheet).rows.map(r => r.obj).filter(f => String(f.swapId) === id);
  const refunds = [];
  loadSecurityFeeRows(id).rows.map(r => r.obj).forEach(rec => {
    if (rec.adminStatus !== 'ADMIN_APPROVED' && rec.adminStatus !== 'ADMIN_PENDING') return;
    if (existing.some(f => String(f.leg) === 'refund:' + rec.payerRole)) return;
    const amount = Number(rec.requiredAmount || 0);
    if (!(amount > 0)) return;
    const r = { id: generateId('SS_REFUND_'), swapId: id, leg: 'refund:' + rec.payerRole, bookTitle: String(swap.obj.requestedBookTitle || 'the book'),
      defaulterEmail: '', ownerEmail: normalizeEmail(rec.payerEmail), amount: amount, dueAt: '', forfeitedAt: new Date(), payoutStatus: 'TO_PAY_OWNER',
      note: 'Request closed before the exchange — full refund.' + (rec.adminStatus === 'ADMIN_PENDING' ? ' Check the payment arrived first (UTR ' + (rec.utr || '?') + ').' : '') };
    sheet.appendRow(headers.map(k => r[k] !== undefined ? r[k] : ''));
    refunds.push(r);
  });

  appendStageEvent({ swapId: id, stage: 'ROOM', party: automatic ? 'system' : swapPartyRole(swap, actorEmail) || 'system', actionType: 'room_closed',
    actorEmail: normalizeEmail(actorEmail) || 'swapsutra@gmail.com', note: reason });
  roomArchive_(swap, '🔒 Step 4 · ' + reason + (refunds.length ? ' Anything already paid will be refunded in full.' : '') + ' This room is now closed.', reason);
  [swap.ownerEmail, swap.requesterEmail].forEach(email => {
    try {
      returnNotify_(email, 'room_request_closed', 'Request closed', '"' + (swap.obj.requestedBookTitle || 'The book') + '": ' + reason +
        (refunds.some(r => r.ownerEmail === email) ? ' Your payment will be refunded in full.' : ''), id, 'room_closed_' + id + '_' + email, { whatsapp: !!automatic });
    } catch (e) { /* best effort */ }
  });
  refunds.forEach(r => {
    try {
      returnNotify_('swapsutra@gmail.com', 'room_refund_admin', 'Refund a closed request',
        'Request ' + id + ' closed (' + reason + '). Refund ₹' + r.amount + ' to ' + r.ownerEmail + '.', id, 'room_close_refund_' + r.id, { whatsapp: false });
    } catch (e) { /* the payout record is the source of truth */ }
  });
  return { success: true, closed: true, message: 'The request is closed.' };
}

/** Archives the exchange chat: it leaves both readers' chats; SwapSutra keeps it. */
function roomArchive_(swap, lastMessage, reason) {
  const id = String(swap.obj.id);
  if (lastMessage) roomPost_(id, lastMessage);
  try {
    const sheet = getOrCreateSheet('Chats', []);
    const headers = ensureSheetHeaders(sheet, ['chatId', 'swapId', 'chatStatus', 'archivedAt', 'archivedReason', 'archivedBy']);
    const values = sheet.getDataRange().getValues();
    const swapIdx = headers.indexOf('swapId');
    for (let r = 1; r < values.length; r++) {
      if (String(values[r][swapIdx]) !== id) continue;
      sheet.getRange(r + 1, headers.indexOf('chatStatus') + 1).setValue('Archived');
      sheet.getRange(r + 1, headers.indexOf('archivedAt') + 1).setValue(new Date());
      sheet.getRange(r + 1, headers.indexOf('archivedReason') + 1).setValue(String(reason || '').slice(0, 200));
      sheet.getRange(r + 1, headers.indexOf('archivedBy') + 1).setValue('System');
      try { chatThreadCacheClear_(values[r][headers.indexOf('chatId')]); } catch (e) { /* cache is advisory */ }
    }
  } catch (err) {
    Logger.log('roomArchive_ failed: ' + err);
  }
}

/** Step 15: rate the other reader and SwapSutra. When both have, the room closes. */
function roomRate_(swap, caller, role, data, room) {
  const id = String(swap.obj.id);
  if (!room.exchangeDone) return { success: false, error: 'STEP_LOCKED', message: 'Rating opens once the exchange is complete.' };
  if (room.rated[role]) return { success: false, error: 'ALREADY_RATED', message: 'You have already rated this exchange.' };
  const readerRating = Math.round(Number(data && data.readerRating));
  // SwapSutra is rated once per reader: on later exchanges only the other
  // reader is rated (and no Google review is asked for again).
  const firstPlatformRating = !hasRatedPlatform_(caller);
  const platformRating = firstPlatformRating ? Math.round(Number(data && data.platformRating)) : 0;
  if (!(readerRating >= 1 && readerRating <= 5)) return { success: false, message: 'Rate the other reader from 1 to 5 stars.' };
  if (firstPlatformRating && !(platformRating >= 1 && platformRating <= 5)) return { success: false, message: 'Rate SwapSutra from 1 to 5 stars.' };
  const readerComment = String((data && data.readerComment) || '').trim().slice(0, 500);
  const platformComment = firstPlatformRating ? String((data && data.platformComment) || '').trim().slice(0, 500) : '';
  // Free text is public-ish (a reader's rating shows on their profile): no contact details.
  if ([readerComment, platformComment].some(c => c && scanMessageForPII(c).blocked)) {
    return { success: false, blocked: true, message: 'Please leave phone numbers, emails and addresses out of your comments.' };
  }
  // An exchange that finished before the room recorded it: record it now
  // (this also marks the chat Completed, which the reader rating needs).
  if (!room.finishedRecorded) roomFinishExchange_(swap, room);

  const rr = rateCounterparty({ swapId: id, rating: readerRating, comment: readerComment });
  if (!rr.success && rr.error !== 'ALREADY_RATED') return rr;
  const sheet = getPlatformFeedbackSheet_();
  const headers = ensureSheetHeaders(sheet, PLATFORM_FEEDBACK_HEADERS);
  const rec = { id: generateId('SS_PFB_'), swapId: id, email: caller, role: role, platformRating: platformRating || '', platformComment: platformComment,
    readerRating: readerRating, createdAt: new Date() };
  sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  roomPost_(id, '⭐ Step 15 · ' + roomName_(caller) + ' shared their reflection and rating. The exchange has moved to their My orders.');
  if (firstPlatformRating && platformRating <= 2) {
    try {
      returnNotify_('swapsutra@gmail.com', 'room_low_rating', 'Low SwapSutra rating (' + platformRating + '★)',
        'Exchange ' + id + ': ' + caller + ' rated SwapSutra ' + platformRating + '/5. ' + platformComment, id, 'room_low_' + rec.id, { whatsapp: false });
    } catch (e) { /* best effort */ }
  }
  const otherRole = role === 'owner' ? 'requester' : 'owner';
  let closed = false;
  if (room.rated[otherRole]) {
    appendStageEvent({ swapId: id, stage: 'ROOM', party: 'system', actionType: 'room_closed', actorEmail: 'swapsutra@gmail.com', note: 'Exchange complete — both readers rated.' });
    roomArchive_(swap, '🏁 Step 16 · Both of you have rated. This exchange is complete and the room is now closed — it disappears from your chats, and SwapSutra keeps the full record. Happy reading!', 'Exchange complete — both readers rated.');
    closed = true;
  }
  // The room closes for this reader now (it leaves their chats and moves to
  // My orders); for the other reader when they rate too, or after 7 days.
  const askReview = firstPlatformRating && platformRating >= 4;
  return { success: true, closed: closed, closedForYou: true, reviewUrl: askReview ? GOOGLE_REVIEW_URL : '',
    message: askReview ? 'Thank you! This exchange is now in My orders. If you have a minute, a Google review helps other readers find SwapSutra.'
      : 'Thank you — this exchange is now in My orders.' };
}

/**
 * Hourly (from runReturnDeadlines): the room's clocks.
 *   • condition video not recorded within 48 hours of acceptance → closes
 *   • not paid within 48 hours of the condition video → closes
 *     (a payment that was submitted and is being verified is never closed)
 *   • reminders half-way through each
 *   • with 7 days left on a return: the +7 reminder in the chat
 *   • finished exchanges: completion record, refunds (after a dispute too)
 *   • rooms still open 7 days after completion close by themselves
 */
function runExchangeRoomTicks_(nowMs) {
  const started = Date.now();
  const now = typeof nowMs === 'number' ? nowMs : Date.now();
  const summary = { checked: 0, closed: 0, reminders: 0, notices: 0, finished: 0, archived: 0, errors: 0 };
  const rows = readSheetObjects_(getOrCreateSheet('SwapRequests', DB_SCHEMA.SwapRequests)).rows.map(r => r.obj);
  rows.forEach(o => {
    if (Date.now() - started > 4 * 60 * 1000) return;
    if (!roomSwapAccepted_(o.status)) return;
    try {
      const swap = loadSwapForCirculation(String(o.id));
      if (!swap) return;
      const input = roomInputFor_(swap, swap.ownerEmail, now);
      if (!input.chatId || String(input.chatStatus) === 'Archived') return;
      summary.checked++;
      const room = computeExchangeRoom_(input);
      const id = String(o.id);
      const title = String(o.requestedBookTitle || 'the book');
      const tm = room._timers;
      const legsOut = room.legs.out;

      if (!room._raw[4] && !input.disputeOpen) {
        if (!tm.conditionDone) {
          if (now > tm.conditionBy) {
            roomCloseRequest_(swap, '', 'Closed automatically: the book condition video was not recorded within 48 hours of acceptance.', true);
            summary.closed++;
            return;
          }
          if (now > tm.conditionBy - (ROOM_WINDOW_HOURS - ROOM_REMIND_HOURS) * ROOM_HOUR_MS) {
            legsOut.filter(l => !l.videos.QUALITY.done).forEach(l => {
              const email = l.sender === 'owner' ? swap.ownerEmail : swap.requesterEmail;
              returnNotify_(email, 'room_condition_reminder', 'Record the condition video for "' + title + '"',
                'The other reader is waiting. Record the book\'s condition video in the exchange room by ' + returnDateLabel_(new Date(tm.conditionBy)) + ', or the request closes.',
                id, 'room_cond_rem_' + id + '_' + l.leg);
              summary.reminders++;
            });
          }
        } else if (tm.unpaidRoles.length) {
          if (now > tm.payBy) {
            roomCloseRequest_(swap, '', 'Closed automatically: the payment was not made within 48 hours.', true);
            summary.closed++;
            return;
          }
          if (now > tm.payBy - (ROOM_WINDOW_HOURS - ROOM_REMIND_HOURS) * ROOM_HOUR_MS) {
            tm.unpaidRoles.forEach(r => {
              const email = r === 'owner' ? swap.ownerEmail : swap.requesterEmail;
              returnNotify_(email, 'room_payment_reminder', 'Pay for "' + title + '" to continue',
                'The condition video is in. Pay through the exchange room by ' + returnDateLabel_(new Date(tm.payBy)) + ', or the request closes automatically.',
                id, 'room_pay_rem_' + id + '_' + r);
              summary.reminders++;
            });
          }
        }
      }

      // The +7 reminder, in the chat, with 7 days left.
      const ret = input.returnState || {};
      if (room.needsReturn && room._raw[9] && !room.route.back && !room.noticePosted && ret.started && !ret.overdue &&
          new Date(ret.dueAt).getTime() - now <= RETURN_EXTENSION_NOTICE_DAYS * RETURN_DAY_MS) {
        appendStageEvent({ swapId: id, stage: 'ROOM', party: 'system', actionType: 'extension_notice', actorEmail: 'swapsutra@gmail.com', note: 'Due ' + ret.dueAt });
        const w = ret.extensionWindow || {};
        roomPost_(id, '⏰ Step 11 · 7 days left: "' + title + '" is due back by ' + returnDateLabel_(new Date(ret.dueAt)) + '.\n\n' +
          'Step 12 · Need longer? The reader who has the book can ask for +7 days ' + (w.closesAt ? 'until ' + returnDateLabel_(new Date(w.closesAt)) : 'in the next 3 days') +
          ' (once); it applies if the owner agrees. Otherwise choose courier or in person to return it.');
        returnLegsFor_(o).forEach(l => {
          const email = l.borrower === 'owner' ? swap.ownerEmail : swap.requesterEmail;
          returnNotify_(email, 'room_extension_notice', '7 days left to return "' + title + '"',
            'Return it by ' + returnDateLabel_(new Date(ret.dueAt)) + '. Need longer? Ask for +7 days in the exchange room in the next 3 days — the owner has to agree.',
            id, 'room_notice_' + id + '_' + l.leg);
        });
        summary.notices++;
      }

      if (room.exchangeDone && !room.finishedRecorded) {
        roomFinishExchange_(swap, room);
        summary.finished++;
        return;
      }
      if (room.exchangeDone) {
        roomCreateRefunds_(swap);
        const doneAt = new Date(room.exchangeDoneAt).getTime();
        if (isFinite(doneAt) && now - doneAt > ROOM_RATING_WINDOW_DAYS * RETURN_DAY_MS && !input.disputeOpen) {
          appendStageEvent({ swapId: id, stage: 'ROOM', party: 'system', actionType: 'room_closed', actorEmail: 'swapsutra@gmail.com', note: 'Closed ' + ROOM_RATING_WINDOW_DAYS + ' days after completion.' });
          roomArchive_(swap, '🏁 Step 16 · This exchange finished ' + ROOM_RATING_WINDOW_DAYS + ' days ago, so the room is now closed. SwapSutra keeps the full record. Happy reading!', 'Closed ' + ROOM_RATING_WINDOW_DAYS + ' days after completion.');
          summary.archived++;
        }
      }
    } catch (err) {
      summary.errors++;
      Logger.log('runExchangeRoomTicks_ failed for ' + o.id + ': ' + err);
    }
  });
  return summary;
}


/**
 * A Drive folder by name, created if missing — kept under one parent
 * ("SwapSutra_Exchanges") so exchange videos and proofs don't clutter the
 * Drive root. (8 Oct 2026: vmsStartUpload and uploadSwapProof called this,
 * but it had never been defined — every video upload failed with
 * "getOrCreateFolder is not defined".)
 */
const EXCHANGE_FOLDERS_ROOT = 'SwapSutra_Exchanges';
let __SS_EXCHANGE_ROOT__ = null;
function getOrCreateFolder(name) {
  if (!__SS_EXCHANGE_ROOT__) {
    const roots = DriveApp.getFoldersByName(EXCHANGE_FOLDERS_ROOT);
    __SS_EXCHANGE_ROOT__ = roots.hasNext() ? roots.next() : DriveApp.createFolder(EXCHANGE_FOLDERS_ROOT);
  }
  const found = __SS_EXCHANGE_ROOT__.getFoldersByName(String(name));
  return found.hasNext() ? found.next() : __SS_EXCHANGE_ROOT__.createFolder(String(name));
}


/**
 * 8 Oct 2026: approving a host enquiry called sendApprovalEmail, which had
 * never been defined (the approval crashed). A short branded note; returns
 * true when sent.
 */
function sendApprovalEmail(email, name, kind) {
  try {
    const to = normalizeEmail(email);
    if (!to) return false;
    const content = '<p>Hi ' + String(name || 'there').replace(/</g, '&lt;') + ',</p>' +
      '<p>Good news — your ' + String(kind || 'request').replace(/</g, '&lt;') + ' with SwapSutra has been approved. We will be in touch with the next steps.</p>';
    const htmlBody = getBrandedEmailTemplate('Approved', content, 'https://swapsutra.in', 'Open SwapSutra');
    const res = sendSwapSutraEmail({ to: to, subject: 'Your SwapSutra ' + (kind || 'request') + ' is approved', htmlBody: htmlBody });
    return res !== false;
  } catch (err) {
    Logger.log('sendApprovalEmail failed: ' + err);
    return false;
  }
}


/* ════════════════════════════════════════════════════════════════════════
   GOOGLE LOCATION for meeting points (Oct 2026, owner's request)
   ────────────────────────────────────────────────────────────────────────
   The meeting-point picker finds places with Google, through Apps Script's
   built-in Maps service (no API key, no billing):
     geocodePlace     { query }        → up to 5 places, India first
     reversePlace     { lat, lng }     → the address at a point
     resolveMapsLink  { url }          → a pasted Google Maps link (also the
                                          short maps.app.goo.gl kind) → a point
   Signed-in readers only, and answers are cached for a day, which keeps
   well inside the Maps service's daily quota.
   ════════════════════════════════════════════════════════════════════════ */

const PLACE_CACHE_SECONDS = 24 * 60 * 60;
const MAPS_LINK_HOSTS = /^(?:maps\.app\.goo\.gl|goo\.gl|g\.co|maps\.google\.[a-z.]+|(?:www\.)?google\.[a-z.]+)$/i;

function placeCacheGet_(key) {
  try { const v = CacheService.getScriptCache().get(key); return v ? JSON.parse(v) : null; } catch (e) { return null; }
}
function placeCachePut_(key, value) {
  try { CacheService.getScriptCache().put(key, JSON.stringify(value), PLACE_CACHE_SECONDS); } catch (e) { /* cache is advisory */ }
}

/** Google geocoder results → [{ label, address, lat, lng }]. */
function placesFromGeocode_(res) {
  return ((res && res.results) || []).slice(0, 5).map(r => {
    const loc = r.geometry && r.geometry.location;
    const pin = loc ? cleanLatLng_(loc.lat, loc.lng) : null;
    if (!pin) return null;
    const address = String(r.formatted_address || '');
    return { label: cleanPlaceLabel_(address.split(',')[0]), address: address.slice(0, 160), lat: pin.lat, lng: pin.lng };
  }).filter(Boolean);
}

/** Action: geocodePlace { query } */
function geocodePlace(data) {
  if (!normalizeEmail(getAuthenticatedEmail())) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to search for a place.' };
  const query = String((data && data.query) || '').replace(/\s+/g, ' ').trim().slice(0, 120);
  if (query.length < 3) return { success: false, message: 'Type at least 3 letters of the place.' };
  const key = 'geo:' + query.toLowerCase();
  const cached = placeCacheGet_(key);
  if (cached) return { success: true, places: cached };
  try {
    const places = placesFromGeocode_(Maps.newGeocoder().setRegion('in').setLanguage('en').geocode(query));
    placeCachePut_(key, places);
    return { success: true, places: places, message: places.length ? '' : 'Google found no place by that name. Try adding the area or city.' };
  } catch (err) {
    Logger.log('geocodePlace failed: ' + err);
    return { success: false, message: 'Place search is busy right now. Use your current location or paste a Google Maps link.' };
  }
}

/** Action: reversePlace { lat, lng } — the address at a point (for naming a pin). */
function reversePlace(data) {
  if (!normalizeEmail(getAuthenticatedEmail())) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in first.' };
  const pin = cleanLatLng_(data && data.lat, data && data.lng);
  if (!pin) return { success: false, message: 'That location could not be read.' };
  const key = 'rev:' + pin.lat.toFixed(4) + ',' + pin.lng.toFixed(4);
  const cached = placeCacheGet_(key);
  if (cached) return { success: true, place: cached };
  try {
    const place = placesFromGeocode_(Maps.newGeocoder().setLanguage('en').reverseGeocode(pin.lat, pin.lng))[0] || null;
    const out = place ? Object.assign({}, place, { lat: pin.lat, lng: pin.lng }) : { label: '', address: '', lat: pin.lat, lng: pin.lng };
    placeCachePut_(key, out);
    return { success: true, place: out };
  } catch (err) {
    return { success: true, place: { label: '', address: '', lat: pin.lat, lng: pin.lng } };
  }
}

/** Coordinates (and a place name, if any) written in a Google Maps URL. Pure. */
function pointFromMapsUrl_(url) {
  const u = String(url || '');
  let dec = u;
  try { dec = decodeURIComponent(u); } catch (e) { dec = u; }
  const pick = (re) => { const m = re.exec(dec); return m ? cleanLatLng_(m[1], m[2]) : null; };
  // !3d…!4d… is the place itself; @lat,lng is only where the map was centred.
  const pin = pick(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/)
    || pick(/[?&](?:q|query|ll|destination|daddr|center|sll)=(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/)
    || pick(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);
  const placeMatch = /\/place\/([^/@?]+)/.exec(dec) || /[?&](?:q|query)=([^&]+)/.exec(dec);
  let name = placeMatch ? placeMatch[1].replace(/\+/g, ' ') : '';
  if (/^-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?$/.test(name)) name = '';
  return { pin: pin, name: cleanPlaceLabel_(name) };
}

/** Action: resolveMapsLink { url } — a Google Maps link a reader pasted. */
function resolveMapsLink(data) {
  if (!normalizeEmail(getAuthenticatedEmail())) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in first.' };
  let url = String((data && data.url) || '').trim();
  const found = /https?:\/\/[^\s]+/.exec(url);   // a "Share" text often has words around the link
  url = found ? found[0] : url;
  let host = '';
  try { host = /^https?:\/\/([^/?#]+)/i.exec(url)[1]; } catch (e) { host = ''; }
  if (!host || !MAPS_LINK_HOSTS.test(host)) return { success: false, message: 'Paste a Google Maps link (from Share → Copy link in Google Maps).' };
  const cached = placeCacheGet_('lnk:' + url);
  if (cached) return { success: true, place: cached };
  try {
    // Short links redirect to the full one; follow a few hops by hand.
    let current = url;
    for (let hop = 0; hop < 4; hop++) {
      if (pointFromMapsUrl_(current).pin) break;
      const res = UrlFetchApp.fetch(current, { followRedirects: false, muteHttpExceptions: true });
      const h = res.getHeaders() || {};
      const next = h.Location || h.location;
      if (!next) break;
      current = next;
    }
    const got = pointFromMapsUrl_(current);
    let place = null;
    if (got.pin) place = { label: got.name, address: '', lat: got.pin.lat, lng: got.pin.lng };
    else if (got.name) {
      const g = placesFromGeocode_(Maps.newGeocoder().setRegion('in').setLanguage('en').geocode(got.name))[0];
      if (g) place = g;
    }
    if (!place) return { success: false, message: 'That link has no location in it. In Google Maps, open the place, tap Share → Copy link, and paste it here.' };
    placeCachePut_('lnk:' + url, place);
    return { success: true, place: place };
  } catch (err) {
    Logger.log('resolveMapsLink failed: ' + err);
    return { success: false, message: 'That link could not be opened. Try searching the place by name instead.' };
  }
}


/* ════════════════════════════════════════════════════════════════════════
   MY ORDERS (9 Oct 2026, owner's request)
   ────────────────────────────────────────────────────────────────────────
   When an exchange room closes, the book leaves the cart and appears under
   "My orders": the book, who it was with, what kind of exchange, when, and
   what this reader paid — book price, deposit and fee separately — with
   the deposit refund (or the seller's payout) and where it stands.
   An exchange is an order once it is complete AND its room has closed
   (both readers rated, or 7 days passed), sorted into sold / received /
   swapped / rented / lent. A rented, lent or temporarily swapped book that
   has reached the reader but not come back yet is listed under "in return
   process" (its room is still open). Requests that closed without an
   exchange (cancelled / not paid in 48 h) are not orders.
   ════════════════════════════════════════════════════════════════════════ */

const ORDER_KIND = {
  requester: { SELL: 'Bought', RENT: 'Rented', LEND: 'Borrowed', SWAP: 'Swapped' },
  owner: { SELL: 'Sold', RENT: 'Rented out', LEND: 'Lent', SWAP: 'Swapped' }
};
// The sections of My orders (owner's request, 9 Oct 2026): sold, received,
// swapped, rented, lent — and "in return process" for a book that is out
// with a reader (or on its way back) right now.
function orderCategory_(role, type) {
  if (type === 'SELL') return role === 'owner' ? 'sold' : 'received';
  if (type === 'SWAP') return 'swapped';
  if (type === 'RENT') return 'rented';
  if (type === 'LEND') return 'lent';
  return 'received';
}

/** Action: getMyOrders — the caller's finished exchanges, newest first. */
function getMyOrders() {
  try {
    const caller = normalizeEmail(getAuthenticatedEmail());
    if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to see your orders.' };
    const swapsT = readSheetObjects_(getOrCreateSheet('SwapRequests', DB_SCHEMA.SwapRequests));
    const mine = swapsT.rows.filter(r => {
      const p = resolveSwapRequestParties(swapsT.headers, swapsT.headers.map(h => r.obj[h]));
      return normalizeEmail(p.requesterEmail) === caller || normalizeEmail(p.ownerEmail) === caller;
    }).map(r => String(r.obj.id));
    if (!mine.length) return { success: true, orders: [] };

    const idSet = {}; mine.forEach(id => { idSet[id] = true; });
    const ratedByMe = ratedSwapIdsFor_(caller);
    const roomEvents = {};
    readSheetObjects_(getStageEventsSheet()).rows.forEach(r => {
      const o = r.obj;
      if (!idSet[String(o.swapId)] || o.stage !== 'ROOM') return;
      (roomEvents[String(o.swapId)] = roomEvents[String(o.swapId)] || []).push(o);
    });
    const chats = {};
    readSheetObjects_(getOrCreateSheet('Chats', [])).rows.forEach(r => { if (idSet[String(r.obj.swapId)]) chats[String(r.obj.swapId)] = r.obj; });
    const fees = {};
    readSheetObjects_(getSecurityFeeSheet()).rows.forEach(r => { if (idSet[String(r.obj.swapId)]) (fees[String(r.obj.swapId)] = fees[String(r.obj.swapId)] || []).push(r.obj); });
    const payouts = {};
    readSheetObjects_(getReturnForfeitSheet_()).rows.forEach(r => { if (idSet[String(r.obj.swapId)]) (payouts[String(r.obj.swapId)] = payouts[String(r.obj.swapId)] || []).push(r.obj); });

    const orders = [];
    mine.forEach(id => {
      const evs = roomEvents[id] || [];
      const done = evs.filter(e => e.actionType === 'exchange_done').pop();
      // Until the room closes (both rated, or 7 days after completion) it
      // stays in the cart, where the reader rates; then it is an order.
      const roomClosed = String((chats[id] || {}).chatStatus || '') === 'Archived' || evs.some(e => e.actionType === 'room_closed') || !!ratedByMe[id];
      let inReturn = null;
      if (!done) {
        // Not finished — but a book that has reached the reader and has to
        // come back is listed under "In return process".
        const swapR = loadSwapForCirculation(id);
        if (!swapR || !swapNeedsReturn(swapR) || !roomSwapAccepted_(swapR.obj.status) || roomClosed) return;
        const roomR = computeExchangeRoom_(roomInputFor_(swapR, caller));
        const out = roomR.steps.find(st => st.n === 9);
        if (!out || out.state !== 'done' || roomR.exchangeDone || roomR.closed) return;
        const cur = roomR.steps.find(st => st.n === roomR.current) || {};
        const rs = roomInputFor_(swapR, caller).returnState || {};
        inReturn = { step: roomR.current, stepTitle: cur.title || '', dueAt: rs.dueAt || '', daysLeft: rs.daysLeft, overdue: !!rs.overdue,
          onItsWay: !!roomR.route.back };
      } else if (!roomClosed) return;
      const swap = loadSwapForCirculation(id);
      if (!swap) return;
      const role = caller === swap.ownerEmail ? 'owner' : 'requester';
      const type = String(swap.obj.serviceType || 'SWAP').toUpperCase();
      const chat = chats[id] || {};

      // What this reader paid, from their verified payment.
      const myFee = (fees[id] || []).find(f => f.payerRole === role && f.adminStatus === 'ADMIN_APPROVED');
      const b = myFee ? feeRecordBreakdown_(myFee) : { depositAmount: 0, platformFee: 0, saleAmount: 0 };
      const paid = myFee ? { total: Number(myFee.requiredAmount || 0), sale: b.saleAmount, deposit: b.depositAmount, fee: b.platformFee } : null;

      // The deposit back to this reader, or forfeited.
      let deposit = null;
      if (paid && paid.deposit > 0) {
        const p = payouts[id] || [];
        const refund = p.find(x => String(x.leg) === 'refund:' + role);
        const forfeitLeg = role === 'requester' ? 'return' : 'counter_return';
        const forfeit = p.find(x => String(x.leg) === forfeitLeg || (/^dispute:/.test(String(x.leg)) && String(x.leg).split(':').pop() === role && Number(x.amount) > 0));
        const rentRow = p.find(x => String(x.leg) === 'rent');
        const rentCut = rentRow ? Number(rentRow.amount || 0) : 0;
        const feeRow = p.find(x => String(x.leg) === 'fee:' + role);
        const feeCut = feeRow ? Number(feeRow.amount || 0) : (role === 'requester' || role === 'owner' ? feeTakenFromDeposit_(swap.obj, caller, myFee) : 0);
        deposit = forfeit ? { amount: paid.deposit, status: 'forfeited', note: 'Forfeited' + (forfeit.amount ? ' (₹' + forfeit.amount + ')' : '') }
          : refund ? { amount: Number(refund.amount || paid.deposit), status: refund.payoutStatus === 'PAID_TO_OWNER' ? 'refunded' : 'refund_due', paidAt: refund.paidAt || '', rent: rentCut, fee: feeCut, of: paid.deposit }
          : rentCut >= paid.deposit ? { amount: 0, status: 'rent_used', rent: rentCut, of: paid.deposit }
          : { amount: paid.deposit, status: 'held', rent: role === 'requester' ? rentChargeFor_(swap.obj) : 0, fee: feeCut, of: paid.deposit };
      }
      // A seller's payout, or an owner's rent.
      let payout = null;
      if (role === 'owner' && (type === 'SELL' || type === 'RENT')) {
        const p = (payouts[id] || []).find(x => String(x.leg) === (type === 'SELL' ? 'sale' : 'rent'));
        if (p) payout = { amount: Number(p.amount || 0), status: p.payoutStatus === 'PAID_TO_OWNER' ? 'paid' : 'due', paidAt: p.paidAt || '', kind: type === 'SELL' ? 'sale' : 'rent' };
      }
      const other = role === 'owner' ? swap.requesterEmail : swap.ownerEmail;
      orders.push({
        swapId: id,
        bookId: String(swap.obj.requestedBookId || chat.bookId || ''),
        bookTitle: String(swap.obj.requestedBookTitle || 'A book'),
        offeredBook: type === 'SWAP' ? String(swap.obj.offeredBook || '') : '',
        serviceType: type,
        role: role,
        kind: (ORDER_KIND[role] || {})[type] || 'Exchanged',
        category: inReturn ? 'in_return' : orderCategory_(role, type),
        inReturn: inReturn,
        chatId: inReturn ? String(chat.chatId || '') : '',
        swapPreference: String(swap.obj.swapPreference || ''),
        otherName: approvedPartner_(caller) ? 'Buyer' : roomName_(other),
        price: Number(swap.obj.amount || 0),
        paid: paid,
        deposit: deposit,
        payout: payout,
        completedAt: done && done.createdAt ? new Date(done.createdAt).toISOString() : '',
        roomClosed: true
      });
    });
    orders.sort((a, b) => (a.category === 'in_return' ? 0 : 1) - (b.category === 'in_return' ? 0 : 1) ||
      new Date(b.completedAt || 0) - new Date(a.completedAt || 0));
    return { success: true, orders: orders };
  } catch (err) {
    return { success: false, message: err.toString() };
  }
}


/* ════════════════════════════════════════════════════════════════════════
   WISHLIST — saved books (9 Oct 2026, owner's request: "books me add to
   wishlist ka option")
   ────────────────────────────────────────────────────────────────────────
   A reader hearts a listed book; it is kept against their account (so it
   follows them across devices) and shown in Cart → Wishlist, above the
   books they have asked the community to find. One row per reader + book.
   ════════════════════════════════════════════════════════════════════════ */

const WISHLIST_SHEET = 'Wishlist';
const WISHLIST_HEADERS = ['id', 'email', 'bookId', 'bookTitle', 'createdAt'];
const WISHLIST_MAX = 300;

function getWishlistSheet_() {
  const s = getOrCreateSheet(WISHLIST_SHEET, WISHLIST_HEADERS);
  ensureSheetHeaders(s, WISHLIST_HEADERS);
  return s;
}

/** Action: getWishlist — the caller's saved book ids, newest first. */
function getWishlist() {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to see your wishlist.' };
  const items = readSheetObjects_(getWishlistSheet_()).rows.map(r => r.obj)
    .filter(o => normalizeEmail(o.email) === caller)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .map(o => ({ bookId: String(o.bookId), bookTitle: String(o.bookTitle || ''), savedAt: o.createdAt ? new Date(o.createdAt).toISOString() : '' }));
  return { success: true, items: items };
}

/** Action: toggleWishlist { bookId, saved?: true|false } — add or remove one book. */
function toggleWishlist(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in to save books to your wishlist.' };
  const bookId = String((data && data.bookId) || '').trim().slice(0, 80);
  if (!bookId) return { success: false, message: 'Which book?' };
  const sheet = getWishlistSheet_();
  const t = readSheetObjects_(sheet);
  const mine = t.rows.filter(r => normalizeEmail(r.obj.email) === caller);
  const existing = mine.find(r => String(r.obj.bookId) === bookId);
  const want = data && data.saved !== undefined ? (data.saved === true || data.saved === 'true') : !existing;
  if (want && !existing) {
    if (mine.length >= WISHLIST_MAX) return { success: false, message: 'Your wishlist is full (' + WISHLIST_MAX + ' books). Remove a few first.' };
    let title = String((data && data.bookTitle) || '').slice(0, 200);
    try { const b = findBookById(bookId); if (b && b.title) title = String(b.title); } catch (e) { /* the title sent is fine */ }
    const rec = { id: generateId('SS_WISH_'), email: caller, bookId: bookId, bookTitle: title, createdAt: new Date() };
    sheet.appendRow(t.headers.length ? t.headers.map(h => rec[h] !== undefined ? rec[h] : '') : WISHLIST_HEADERS.map(h => rec[h]));
  } else if (!want && existing) {
    sheet.deleteRow(existing.rowIndex + 1);
  }
  return { success: true, saved: want, message: want ? 'Saved to your wishlist.' : 'Removed from your wishlist.' };
}


/* ════════════════════════════════════════════════════════════════════════
   SWAPSUTRA PARTNERS — bookstores, authors, publishers and promoters
   (9 Oct 2026, owner's rules)
   ────────────────────────────────────────────────────────────────────────
   • A partner registers separately from readers (/partners): their own
     form per type, a Google location, documents (whose name the business
     is registered in, the owner's Aadhaar (masked) and PAN, a business
     proof), and a contract they sign by typing their name. The admin
     approves, asks for changes, rejects or suspends from Management.
   • Documents go to a PRIVATE Drive folder (never shared); only the admin
     opens them. Only the last 4 digits of Aadhaar are kept as text.
   • An approved partner lists as many books as they like, each with a
     stock count, and pays no ₹10 platform fee (the buyer still pays ₹10).
   • Commission: 2% of every payout (sale price, rent). A partner approved
     "commission-free" pays 0% for the first year from approval, then 2%.
     Payouts are paid monthly, after the month ends.
   • Promotion (the Library banner + ads): free for the first 6 months
     from approval, then ₹100 for every 2 months, paid by UPI and verified
     by the admin. The partner chooses whether to show a banner and
     whether to run ads; banners and ads are checked by the admin first.
   • A partner never sees a buyer's details — only the shipping address of
     an order they have to post. Shipping and delivery are the partner's
     responsibility (see their contract).
   ════════════════════════════════════════════════════════════════════════ */

const PARTNER_TYPES = ['bookstore', 'author', 'publisher', 'promoter'];
const PARTNER_TYPE_LABEL = { bookstore: 'Bookstore', author: 'Author', publisher: 'Publisher', promoter: 'Promoter' };
/** Bump a type's version when its contract text changes; partners sign the current one. */
const PARTNER_CONTRACT_VERSIONS = { bookstore: 'bookstore-2026-10-09', author: 'author-2026-10-09', publisher: 'publisher-2026-10-09', promoter: 'promoter-2026-10-09' };
const PARTNER_HEADERS = [
  'id', 'type', 'email', 'status', 'name', 'contactName', 'phone', 'about', 'website', 'instagram',
  'address', 'city', 'pincode', 'lat', 'lng', 'placeLabel', 'registeredName', 'gstin', 'panNumber', 'aadhaarLast4',
  'docsJson', 'typeFieldsJson', 'showBanner', 'runAds', 'bannerImageUrl', 'bannerHeadline', 'bannerTagline', 'bannerStatus', 'bannerNote',
  'contractVersion', 'contractSignedName', 'contractSignedAt', 'commissionPlan', 'commissionFreeUntil', 'approvedAt', 'approvedBy',
  'adsFreeUntil', 'reviewNote', 'createdAt', 'updatedAt', 'submittedAt'
];
const PARTNER_STATUSES = ['PENDING', 'CHANGES_REQUESTED', 'APPROVED', 'REJECTED', 'SUSPENDED'];
const PARTNER_AD_PAYMENT_HEADERS = ['id', 'partnerId', 'email', 'amount', 'months', 'utr', 'screenshotUrl', 'status', 'periodFrom', 'periodTo', 'reviewedBy', 'reviewedAt', 'reason', 'createdAt'];
const PARTNER_DOC_MAX_BYTES = 4 * 1024 * 1024;
/** Which documents each type must upload (key → label). */
const PARTNER_DOCS = {
  bookstore: { aadhaar: "Owner's Aadhaar (masked)", pan: "Owner's PAN card", businessProof: 'Shop registration / GST / Udyam / trade licence' },
  author: { aadhaar: 'Aadhaar (masked)', pan: 'PAN card' },
  publisher: { aadhaar: "Signatory's Aadhaar (masked)", pan: 'PAN card (business or signatory)', businessProof: 'Company / GST / Udyam registration' },
  promoter: { aadhaar: 'Aadhaar (masked)', pan: 'PAN card' }
};
const PARTNER_OPTIONAL_DOCS = { businessProof: 'Business proof (optional)', other: 'Any other document (optional)' };

function partnerCommissionRate_() { const n = Number(readScriptProperty_('PARTNER_COMMISSION_PERCENT')); return (isFinite(n) && n >= 0 && n <= 50 ? n : 2) / 100; }
function partnerAdFee_() { const n = Number(readScriptProperty_('PARTNER_AD_FEE')); return isFinite(n) && n > 0 ? Math.round(n) : 100; }
const PARTNER_AD_PERIOD_MONTHS = 2;
const PARTNER_FREE_PROMO_MONTHS = 6;
const PARTNER_FREE_COMMISSION_MONTHS = 12;

function addMonths_(date, months) {
  const d = new Date(date.getTime());
  const day = d.getDate();
  d.setMonth(d.getMonth() + months);
  if (d.getDate() < day) d.setDate(0); // 31 Jan + 1 month → 28/29 Feb
  return d;
}
/** "2026-10" for a date, in India time — a payout's month. */
function istMonth_(date) { return new Date(new Date(date).getTime() + 5.5 * 3600e3).toISOString().slice(0, 7); }

function partnerSheet_() {
  const sheet = getOrCreateSheet('Partners', PARTNER_HEADERS);
  ensureSheetHeaders(sheet, PARTNER_HEADERS);
  return sheet;
}
function partnerRows_() { return readSheetObjects_(partnerSheet_()); }
function partnerByEmail_(email) {
  const e = normalizeEmail(email);
  if (!e) return null;
  const hit = partnerRows_().rows.find(r => normalizeEmail(r.obj.email) === e);
  return hit || null;
}
/** The approved (not suspended) partner record for an email, or null. Cached per run. */
let __SS_PARTNER_CACHE__ = null;
function approvedPartner_(email) {
  const e = normalizeEmail(email);
  if (!e) return null;
  if (!__SS_PARTNER_CACHE__) {
    __SS_PARTNER_CACHE__ = {};
    try {
      partnerRows_().rows.forEach(r => { if (String(r.obj.status) === 'APPROVED') __SS_PARTNER_CACHE__[normalizeEmail(r.obj.email)] = r.obj; });
    } catch (err) { /* no partners sheet yet */ }
  }
  return __SS_PARTNER_CACHE__[e] || null;
}
function resetPartnerCache_() { __SS_PARTNER_CACHE__ = null; }
function setPartnerFields_(rowIndex, headers, fields) {
  const sheet = partnerSheet_();
  Object.keys(fields).forEach(k => {
    const i = headers.indexOf(k);
    if (i !== -1) sheet.getRange(rowIndex + 1, i + 1).setValue(fields[k]);
  });
  resetPartnerCache_();
}

/** 2% (or 0% inside a commission-free first year) for a payout made at `at`. */
function partnerCommissionRateAt_(partner, at) {
  if (!partner) return 0;
  const when = at ? new Date(at) : new Date();
  if (String(partner.commissionPlan) === 'free_first_year' && partner.commissionFreeUntil && when < new Date(partner.commissionFreeUntil)) return 0;
  return partnerCommissionRate_();
}
function partnerCommissionFor_(partner, amount, at) {
  const rate = partnerCommissionRateAt_(partner, at);
  return { rate: rate, commission: Math.round(Math.max(0, Number(amount) || 0) * rate * 100) / 100 };
}

/** Promotion (banner + ads): free months, paid months, and what is due. */
function partnerPromotionState_(partner, payments, now) {
  now = now || new Date();
  const freeUntil = partner.adsFreeUntil ? new Date(partner.adsFreeUntil) : null;
  const approved = (payments || []).filter(p => String(p.status) === 'APPROVED' && p.periodTo);
  const paidUntil = approved.reduce((m, p) => { const t = new Date(p.periodTo); return !m || t > m ? t : m; }, null);
  const activeUntil = [freeUntil, paidUntil].filter(Boolean).reduce((m, t) => (!m || t > m ? t : m), null);
  const pending = (payments || []).find(p => String(p.status) === 'SUBMITTED') || null;
  const active = String(partner.status) === 'APPROVED' && !!activeUntil && now <= activeUntil;
  return {
    freeUntil: freeUntil ? freeUntil.toISOString() : '', paidUntil: paidUntil ? paidUntil.toISOString() : '',
    activeUntil: activeUntil ? activeUntil.toISOString() : '', active: active,
    inFreePeriod: !!freeUntil && now <= freeUntil,
    fee: partnerAdFee_(), months: PARTNER_AD_PERIOD_MONTHS,
    dueSoon: !!activeUntil && active && (activeUntil - now) < 10 * 24 * 3600e3,
    pendingPayment: pending ? { id: pending.id, utr: pending.utr, submittedAt: pending.createdAt } : null
  };
}
function partnerAdPaymentSheet_() {
  const sheet = getOrCreateSheet('PartnerAdPayments', PARTNER_AD_PAYMENT_HEADERS);
  ensureSheetHeaders(sheet, PARTNER_AD_PAYMENT_HEADERS);
  return sheet;
}
function partnerAdPayments_(partnerId) {
  return readSheetObjects_(partnerAdPaymentSheet_()).rows.map(r => r.obj).filter(p => !partnerId || String(p.partnerId) === String(partnerId));
}
/** Is this approved partner's promotion running right now (and do they want it)? */
function partnerPromotionLive_(partner, what) {
  if (!partner || String(partner.status) !== 'APPROVED') return false;
  if (what === 'banner' && !truthy_(partner.showBanner)) return false;
  if (what === 'ads' && !truthy_(partner.runAds)) return false;
  return partnerPromotionState_(partner, partnerAdPayments_(partner.id)).active;
}
function truthy_(v) { return v === true || ['true', 'yes', '1'].indexOf(String(v).toLowerCase()) !== -1; }

// ── Validation ────────────────────────────────────────────────────────────
function cleanPartnerText_(v, max) { return mugText_(v, max); }
function validPan_(v) { return /^[A-Z]{5}[0-9]{4}[A-Z]$/.test(String(v || '').trim().toUpperCase()); }
function validGstin_(v) { return /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(String(v || '').trim().toUpperCase()); }

/** Shared by submit and the tests. Returns { errors, clean }. */
function validatePartnerApplication_(d, existingDocs) {
  d = d || {};
  const errors = {};
  const type = String(d.type || '').toLowerCase();
  if (PARTNER_TYPES.indexOf(type) === -1) errors.type = 'Choose bookstore, author, publisher or promoter.';
  const clean = {
    type: type,
    name: cleanPartnerText_(d.name, 100), contactName: cleanPartnerText_(d.contactName, 80),
    phone: String(d.phone || '').replace(/[^\d+]/g, '').slice(0, 15),
    about: cleanPartnerText_(d.about, 600), website: '', instagram: cleanPartnerText_(d.instagram, 80),
    address: cleanPartnerText_(d.address, 300), city: cleanPartnerText_(d.city, 60), pincode: String(d.pincode || '').trim(),
    lat: Number(d.lat), lng: Number(d.lng), placeLabel: cleanPartnerText_(d.placeLabel, 120),
    registeredName: cleanPartnerText_(d.registeredName, 120), gstin: String(d.gstin || '').trim().toUpperCase(),
    panNumber: String(d.panNumber || '').trim().toUpperCase(), aadhaarLast4: String(d.aadhaarLast4 || '').trim(),
    showBanner: truthy_(d.showBanner), runAds: truthy_(d.runAds),
    typeFields: {}
  };
  const web = String(d.website || '').trim();
  if (web) { if (/^https:\/\/[^\s]+$/i.test(web)) clean.website = web.slice(0, 300); else errors.website = 'The website must start with https://.'; }
  const nameLabel = { bookstore: 'Bookstore name', author: 'Author name (as on your books)', publisher: 'Publisher / imprint name', promoter: 'Agency / promoter name' }[type] || 'Name';
  if (clean.name.length < 2) errors.name = nameLabel + ' is required.';
  if (clean.contactName.length < 2) errors.contactName = 'Your full name is required.';
  if (!/^(\+91)?[6-9]\d{9}$/.test(clean.phone)) errors.phone = 'Enter a 10-digit Indian mobile number.';
  if (!/^\d{6}$/.test(clean.pincode)) errors.pincode = 'Enter a 6-digit pincode.';
  if (clean.city.length < 2) errors.city = 'City is required.';
  if (type === 'bookstore' || type === 'publisher') {
    if (clean.address.length < 8) errors.address = 'Enter the full address.';
    if (!(isFinite(clean.lat) && isFinite(clean.lng) && Math.abs(clean.lat) <= 90 && Math.abs(clean.lng) <= 180 && (clean.lat || clean.lng))) errors.location = 'Pin your location on Google Maps.';
  }
  if (!(isFinite(clean.lat) && isFinite(clean.lng)) || (!clean.lat && !clean.lng)) { clean.lat = ''; clean.lng = ''; }
  if (clean.registeredName.length < 2) errors.registeredName = type === 'bookstore' || type === 'publisher'
    ? 'Whose name is the business registered in?' : 'Your name as on your PAN card.';
  if (!validPan_(clean.panNumber)) errors.panNumber = 'Enter the PAN number (like ABCDE1234F).';
  if (!/^\d{4}$/.test(clean.aadhaarLast4)) errors.aadhaarLast4 = 'Enter the last 4 digits of the Aadhaar.';
  if (clean.gstin && !validGstin_(clean.gstin)) errors.gstin = 'That GSTIN does not look right (15 characters).';
  // Type-specific details.
  const tf = d.typeFields || {};
  const pick = (k, max) => { clean.typeFields[k] = cleanPartnerText_(tf[k], max || 200); return clean.typeFields[k]; };
  if (type === 'bookstore') { pick('storeType', 60); pick('openingHours', 120); pick('genres', 200); }
  if (type === 'author') { pick('penName', 80); if (!pick('booksPublished', 400)) errors.booksPublished = 'Name at least one of your books.'; pick('genres', 200); }
  if (type === 'publisher') { pick('imprints', 200); pick('yearEstablished', 4); pick('genres', 200); }
  if (type === 'promoter') { if (!pick('promotes', 300)) errors.promotes = 'What do you promote (books, authors, events)?'; pick('clients', 300); }
  // Documents: new uploads (data URLs) or ones already on file.
  const have = existingDocs || {};
  const docs = d.docs || {};
  Object.keys(PARTNER_DOCS[type] || {}).forEach(k => {
    if (!have[k] && !docs[k]) errors['doc_' + k] = 'Upload: ' + PARTNER_DOCS[type][k] + '.';
  });
  Object.keys(docs).forEach(k => {
    if (!(PARTNER_DOCS[type] || {})[k] && !PARTNER_OPTIONAL_DOCS[k]) return;
    const m = /^data:(image\/(?:jpeg|png|webp)|application\/pdf);base64,([A-Za-z0-9+\/=]+)$/.exec(String(docs[k] || ''));
    if (!m) errors['doc_' + k] = 'Upload a JPG, PNG, WebP or PDF.';
    else if (m[2].length * 0.75 > PARTNER_DOC_MAX_BYTES) errors['doc_' + k] = 'Each document must be under 4 MB.';
  });
  // The contract.
  if (!truthy_(d.agree)) errors.agree = 'Read and accept the partner agreement.';
  const signed = cleanPartnerText_(d.signedName, 80);
  if (signed.length < 2 || signed.toLowerCase() !== clean.contactName.toLowerCase()) errors.signedName = 'Type your full name exactly as above to sign.';
  if (type && String(d.contractVersion || '') !== PARTNER_CONTRACT_VERSIONS[type]) errors.contract = 'The agreement has been updated — please reload the page and read it again.';
  clean.signedName = signed;
  return { errors: errors, clean: clean };
}

/** Saves partner documents to a private folder. Returns { key: { id, name, mime } }. */
function savePartnerDocs_(partnerId, docs) {
  const out = {};
  const keys = Object.keys(docs || {});
  if (!keys.length) return out;
  const root = getOrCreateFolder('SwapSutra_Partner_Documents');
  const found = root.getFoldersByName(String(partnerId));
  const folder = found.hasNext() ? found.next() : root.createFolder(String(partnerId));
  keys.forEach(k => {
    const m = /^data:(image\/(?:jpeg|png|webp)|application\/pdf);base64,([A-Za-z0-9+\/=]+)$/.exec(String(docs[k] || ''));
    if (!m) return;
    const ext = m[1] === 'application/pdf' ? 'pdf' : m[1].split('/')[1];
    const file = folder.createFile(Utilities.newBlob(Utilities.base64Decode(m[2]), m[1], k + '_' + Date.now() + '.' + ext));
    // Deliberately NOT shared: identity documents stay private to SwapSutra.
    out[k] = { id: file.getId(), mime: m[1], at: new Date().toISOString() };
  });
  return out;
}
function parseJson_(v, fallback) { try { const o = JSON.parse(String(v || '')); return o && typeof o === 'object' ? o : fallback; } catch (e) { return fallback; } }

/** Action: submitPartnerApplication — a new application, or a resubmission after "changes requested". */
function submitPartnerApplication(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Verify your email first.' };
  const existing = partnerByEmail_(caller);
  if (existing && ['APPROVED', 'SUSPENDED'].indexOf(String(existing.obj.status)) !== -1) {
    return { success: false, error: 'ALREADY_PARTNER', message: 'This email is already a SwapSutra partner. Update your details from your partner dashboard.' };
  }
  if (existing && String(existing.obj.status) === 'PENDING') {
    return { success: false, error: 'UNDER_REVIEW', message: 'Your application is being reviewed. We will email you as soon as it is decided.' };
  }
  const prevDocs = existing ? parseJson_(existing.obj.docsJson, {}) : {};
  if (existing && String(existing.obj.type) !== String((data || {}).type)) {
    // A different type is a different form: documents start again.
    Object.keys(prevDocs).forEach(k => delete prevDocs[k]);
  }
  const v = validatePartnerApplication_(data, prevDocs);
  if (Object.keys(v.errors).length) return { success: false, errors: v.errors, message: 'Please fix the highlighted fields.' };
  const c = v.clean;
  const lock = LockService.getScriptLock();
  lock.waitLock(15000);
  try {
    const t = partnerRows_();
    const id = existing ? String(existing.obj.id) : generateId('SS_PARTNER_');
    let docs;
    try { docs = Object.assign({}, prevDocs, savePartnerDocs_(id, (data || {}).docs)); }
    catch (err) { Logger.log('savePartnerDocs_ failed: ' + err); return { success: false, message: 'Your documents could not be saved. Please try again.' }; }
    const now = new Date();
    const rec = {
      id: id, type: c.type, email: caller, status: 'PENDING', name: c.name, contactName: c.contactName, phone: c.phone, about: c.about,
      website: c.website, instagram: c.instagram, address: c.address, city: c.city, pincode: c.pincode, lat: c.lat, lng: c.lng,
      placeLabel: c.placeLabel, registeredName: c.registeredName, gstin: c.gstin, panNumber: c.panNumber, aadhaarLast4: c.aadhaarLast4,
      docsJson: JSON.stringify(docs), typeFieldsJson: JSON.stringify(c.typeFields), showBanner: c.showBanner ? 'TRUE' : 'FALSE', runAds: c.runAds ? 'TRUE' : 'FALSE',
      contractVersion: PARTNER_CONTRACT_VERSIONS[c.type], contractSignedName: c.signedName, contractSignedAt: now, reviewNote: '',
      updatedAt: now, submittedAt: now
    };
    if (existing) setPartnerFields_(existing.rowIndex, t.headers, rec);
    else {
      rec.createdAt = now;
      const headers = ensureSheetHeaders(partnerSheet_(), PARTNER_HEADERS);
      partnerSheet_().appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
      resetPartnerCache_();
    }
    try {
      returnNotify_('swapsutra@gmail.com', 'partner_application', 'New partner application',
        PARTNER_TYPE_LABEL[c.type] + ' "' + c.name + '" (' + caller + ') applied. Review it in Management → Partners.', '', 'partner_app_' + id + '_' + now.getTime(), { whatsapp: false });
    } catch (e) { /* the application is saved */ }
    return { success: true, id: id, message: 'Application received. SwapSutra will check your documents and email you, usually within 2 working days.' };
  } finally {
    lock.releaseLock();
  }
}

/** What the partner should do next, in order. */
function partnerNextSteps_(p, promo, ctx) {
  const steps = [];
  const st = String(p.status);
  if (st === 'PENDING') steps.push({ key: 'wait', text: 'SwapSutra is checking your documents. We will email you when it is decided.' });
  if (st === 'CHANGES_REQUESTED') steps.push({ key: 'fix', text: 'Update your application: ' + (p.reviewNote || 'see the note from SwapSutra') + '.', urgent: true });
  if (st === 'REJECTED') steps.push({ key: 'rejected', text: 'Your application was not approved' + (p.reviewNote ? ': ' + p.reviewNote : '.') });
  if (st === 'SUSPENDED') steps.push({ key: 'suspended', text: 'Your partner account is paused' + (p.reviewNote ? ': ' + p.reviewNote : '.') + ' Write to swapsutra@gmail.com.' });
  if (st !== 'APPROVED') return steps;
  if (!ctx.payoutAccount) steps.push({ key: 'payout', text: 'Add the UPI ID your monthly payouts should go to.', urgent: true });
  (ctx.orders || []).filter(o => o.nextStep).forEach(o => steps.push({ key: 'order_' + o.swapId, text: '"' + o.bookTitle + '": ' + o.nextStep, swapId: o.swapId, urgent: !!o.urgent }));
  if (!ctx.books) steps.push({ key: 'list', text: 'List your books — there is no limit, and you can set how many copies you have.' });
  if (truthy_(p.showBanner) && !p.bannerImageUrl) steps.push({ key: 'banner', text: 'Upload your banner for the Library page.' });
  if (String(p.bannerStatus) === 'REJECTED') steps.push({ key: 'banner_fix', text: 'Your banner needs a change' + (p.bannerNote ? ': ' + p.bannerNote : '.') });
  if ((truthy_(p.showBanner) || truthy_(p.runAds)) && !promo.active && !promo.pendingPayment) steps.push({ key: 'promo_pay', text: 'Your free promotion has ended — pay ₹' + promo.fee + ' for ' + promo.months + ' months to keep your banner and ads on SwapSutra.', urgent: true });
  else if (promo.dueSoon && !promo.inFreePeriod && !promo.pendingPayment) steps.push({ key: 'promo_due', text: 'Your promotion ends on ' + returnDateLabel_(new Date(promo.activeUntil)) + '. Pay ₹' + promo.fee + ' to continue for ' + promo.months + ' more months.' });
  else if (promo.dueSoon && promo.inFreePeriod && !promo.pendingPayment) steps.push({ key: 'promo_free_end', text: 'Your 6 free months of promotion end on ' + returnDateLabel_(new Date(promo.activeUntil)) + '. After that it is ₹' + promo.fee + ' for ' + promo.months + ' months.' });
  return steps;
}

/** A partner's orders: book, amount, status, the step they must do — never who the buyer is. */
function partnerOrders_(email) {
  const swaps = readSheetObjects_(getOrCreateSheet('SwapRequests', DB_SCHEMA.SwapRequests)).rows.map(r => r.obj)
    .filter(o => normalizeEmail(o.ownerEmail) === email && ['pending', 'declined', 'rejected'].indexOf(String(o.status || '').toLowerCase()) === -1);
  const out = [];
  swaps.slice(-60).forEach(o => {
    const item = { swapId: String(o.id), bookTitle: String(o.requestedBookTitle || 'A book'), serviceType: String(o.serviceType || '').toUpperCase(),
      amount: Number(o.amount || 0), status: String(o.status || ''), createdAt: o.createdAt ? new Date(o.createdAt).toISOString() : '', nextStep: '', step: 0 };
    try {
      const swap = loadSwapForCirculation(String(o.id));
      if (swap) {
        const room = computeExchangeRoom_(roomInputFor_(swap, email));
        item.step = room.current || 0;
        item.closed = !!room.closed;
        const mine = (room.actions || [])[0];
        if (!room.closed && mine) {
          const s = (room.steps || []).find(x => x.n === room.current) || {};
          item.nextStep = 'step ' + room.current + ' — ' + (s.title || 'open the exchange room');
          item.urgent = true;
        }
      }
    } catch (e) { /* the order still lists */ }
    out.push(item);
  });
  return out.reverse();
}

/** Money: what the partner has earned, what SwapSutra kept, what was paid and what is due — by month. */
function partnerEarnings_(email) {
  const rows = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj)
    .filter(f => normalizeEmail(f.ownerEmail) === email && ['sale', 'rent'].indexOf(String(f.leg)) !== -1);
  const commissions = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj)
    .filter(f => String(f.leg) === 'commission' && normalizeEmail(f.defaulterEmail) === email);
  const months = {};
  const add = (cycle) => (months[cycle] = months[cycle] || { month: cycle, gross: 0, commission: 0, net: 0, paid: 0, due: 0, items: 0 });
  rows.forEach(f => {
    const cycle = String(f.payoutCycle || istMonth_(f.forfeitedAt || new Date()));
    const m = add(cycle);
    const net = Number(f.amount || 0);
    const gross = Number(f.grossAmount || 0) || net;
    m.gross += gross; m.net += net; m.items++;
    if (String(f.payoutStatus) === 'PAID_TO_OWNER') m.paid += net; else if (String(f.payoutStatus) === 'TO_PAY_OWNER') m.due += net;
  });
  commissions.forEach(f => { add(String(f.payoutCycle || istMonth_(f.forfeitedAt || new Date()))).commission += Number(f.amount || 0); });
  const list = Object.keys(months).sort().reverse().map(k => {
    const m = months[k];
    ['gross', 'commission', 'net', 'paid', 'due'].forEach(x => { m[x] = Math.round(m[x] * 100) / 100; });
    m.payableFrom = m.month + '-01';
    return m;
  });
  const total = list.reduce((t, m) => ({ gross: t.gross + m.gross, commission: t.commission + m.commission, net: t.net + m.net, paid: t.paid + m.paid, due: t.due + m.due }),
    { gross: 0, commission: 0, net: 0, paid: 0, due: 0 });
  return { months: list, total: total };
}

function partnerPublicView_(p, forAdmin) {
  const docs = parseJson_(p.docsJson, {});
  const out = {
    id: p.id, type: p.type, typeLabel: PARTNER_TYPE_LABEL[p.type] || p.type, email: p.email, status: p.status, name: p.name, contactName: p.contactName,
    phone: p.phone, about: p.about, website: p.website, instagram: p.instagram, address: p.address, city: p.city, pincode: p.pincode,
    lat: p.lat === '' ? null : Number(p.lat), lng: p.lng === '' ? null : Number(p.lng), placeLabel: p.placeLabel,
    registeredName: p.registeredName, gstin: p.gstin,
    panMasked: p.panNumber ? String(p.panNumber).slice(0, 2) + '•••••' + String(p.panNumber).slice(-3) : '', aadhaarLast4: p.aadhaarLast4,
    typeFields: parseJson_(p.typeFieldsJson, {}),
    showBanner: truthy_(p.showBanner), runAds: truthy_(p.runAds), bannerImageUrl: p.bannerImageUrl, bannerHeadline: p.bannerHeadline,
    bannerTagline: p.bannerTagline, bannerStatus: p.bannerStatus || '', bannerNote: p.bannerNote || '',
    contractVersion: p.contractVersion, contractSignedName: p.contractSignedName,
    contractSignedAt: p.contractSignedAt ? new Date(p.contractSignedAt).toISOString() : '',
    currentContractVersion: PARTNER_CONTRACT_VERSIONS[p.type] || '',
    commissionPlan: p.commissionPlan || 'standard', commissionFreeUntil: p.commissionFreeUntil ? new Date(p.commissionFreeUntil).toISOString() : '',
    commissionNow: partnerCommissionRateAt_(p, new Date()) * 100,
    approvedAt: p.approvedAt ? new Date(p.approvedAt).toISOString() : '', reviewNote: p.reviewNote || '',
    submittedAt: p.submittedAt ? new Date(p.submittedAt).toISOString() : '',
    docs: Object.keys(docs).map(k => ({ key: k, label: (PARTNER_DOCS[p.type] || {})[k] || PARTNER_OPTIONAL_DOCS[k] || k, at: docs[k].at || '' }))
  };
  if (forAdmin) {
    out.panNumber = p.panNumber;
    out.docs = Object.keys(docs).map(k => ({ key: k, label: (PARTNER_DOCS[p.type] || {})[k] || PARTNER_OPTIONAL_DOCS[k] || k, at: docs[k].at || '',
      url: 'https://drive.google.com/file/d/' + docs[k].id + '/view', mime: docs[k].mime }));
  }
  return out;
}

/** Action: getMyPartner — the partner dashboard. */
function getMyPartner() {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!caller) return { success: false, error: 'SESSION_REQUIRED', message: 'Sign in first.' };
  const hit = partnerByEmail_(caller);
  const base = { success: true, email: caller, contractVersions: PARTNER_CONTRACT_VERSIONS, requiredDocs: PARTNER_DOCS,
    adFee: partnerAdFee_(), adMonths: PARTNER_AD_PERIOD_MONTHS, commissionPercent: partnerCommissionRate_() * 100, upi: paymentDetails_() };
  if (!hit) return Object.assign(base, { partner: null });
  const p = hit.obj;
  const payments = partnerAdPayments_(p.id);
  const promo = partnerPromotionState_(p, payments);
  const approved = String(p.status) === 'APPROVED';
  const orders = approved ? partnerOrders_(caller) : [];
  const books = approved ? partnerBooks_(caller) : [];
  const ads = approved ? adRows_().rows.map(r => r.obj).filter(a => String(a.partnerId) === String(p.id) && String(a.status) !== 'removed')
    .map(a => ({ id: a.id, kind: a.kind, sponsor: a.sponsor, headline: a.headline, tagline: a.tagline, imageUrl: a.imageUrl, linkUrl: a.linkUrl, bookId: a.bookId,
      ctaLabel: a.ctaLabel, placement: a.placement, status: a.status, reviewNote: a.reviewNote || '', clicks: Number(a.clicks) || 0 })) : [];
  const payoutAccount = readPayoutAccount_(caller);
  return Object.assign(base, {
    partner: partnerPublicView_(p, false),
    promotion: promo,
    adPayments: payments.map(x => ({ id: x.id, amount: Number(x.amount || 0), utr: x.utr, status: x.status, periodFrom: x.periodFrom ? new Date(x.periodFrom).toISOString() : '',
      periodTo: x.periodTo ? new Date(x.periodTo).toISOString() : '', reason: x.reason || '', createdAt: x.createdAt ? new Date(x.createdAt).toISOString() : '' })).reverse(),
    earnings: approved ? partnerEarnings_(caller) : null,
    orders: orders, books: books, ads: ads, payoutAccount: payoutAccount,
    nextSteps: partnerNextSteps_(p, promo, { payoutAccount: payoutAccount, orders: orders, books: books.length })
  });
}

function partnerBooks_(email) {
  const values = getOrCreateSheet('Books', getBookHeaders()).getDataRange().getValues();
  if (values.length <= 1) return [];
  const h = values[0].map(x => String(x).trim());
  const col = k => h.indexOf(k);
  return values.slice(1).filter(r => normalizeEmail(r[col('ownerEmail')]) === email && String(r[col('status')] || '').toLowerCase() !== 'removed')
    .map(r => ({ id: String(r[col('id')]), title: String(r[col('title')] || ''), author: String(r[col('author')] || ''), status: String(r[col('status')] || ''),
      stock: r[col('stock')] === '' || r[col('stock')] === undefined ? 1 : Number(r[col('stock')]) || 0,
      sellPrice: Number(r[col('ownerSellPrice')] || 0) || null }));
}

/** Action: updatePartnerProfile — the details an approved partner may change themselves. */
function updatePartnerProfile(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const hit = partnerByEmail_(caller);
  if (!hit) return { success: false, error: 'NOT_PARTNER', message: 'Register as a partner first.' };
  const d = data || {};
  const fields = {};
  const errors = {};
  if (d.about !== undefined) fields.about = cleanPartnerText_(d.about, 600);
  if (d.instagram !== undefined) fields.instagram = cleanPartnerText_(d.instagram, 80);
  if (d.website !== undefined) {
    const w = String(d.website || '').trim();
    if (w && !/^https:\/\/[^\s]+$/i.test(w)) errors.website = 'The website must start with https://.'; else fields.website = w;
  }
  if (d.phone !== undefined) {
    const ph = String(d.phone || '').replace(/[^\d+]/g, '');
    if (!/^(\+91)?[6-9]\d{9}$/.test(ph)) errors.phone = 'Enter a 10-digit Indian mobile number.'; else fields.phone = ph;
  }
  if (d.lat !== undefined && d.lng !== undefined) {
    const lat = Number(d.lat), lng = Number(d.lng);
    if (isFinite(lat) && isFinite(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180) { fields.lat = lat; fields.lng = lng; fields.placeLabel = cleanPartnerText_(d.placeLabel, 120); }
    else errors.location = 'Pin your location on Google Maps.';
  }
  if (d.showBanner !== undefined) fields.showBanner = truthy_(d.showBanner) ? 'TRUE' : 'FALSE';
  if (d.runAds !== undefined) fields.runAds = truthy_(d.runAds) ? 'TRUE' : 'FALSE';
  if (d.bannerHeadline !== undefined || d.bannerTagline !== undefined) {
    fields.bannerHeadline = cleanPartnerText_(d.bannerHeadline, 90);
    fields.bannerTagline = cleanPartnerText_(d.bannerTagline, 160);
    if (hit.obj.bannerImageUrl) { fields.bannerStatus = 'PENDING'; fields.bannerNote = ''; }
  }
  if (Object.keys(errors).length) return { success: false, errors: errors, message: 'Please fix the highlighted fields.' };
  fields.updatedAt = new Date();
  setPartnerFields_(hit.rowIndex, partnerRows_().headers, fields);
  return { success: true, message: 'Saved.' };
}

/** Action: uploadPartnerBanner { dataUrl } — the banner shown on the Library page (checked by the admin first). */
function uploadPartnerBanner(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const hit = partnerByEmail_(caller);
  if (!hit) return { success: false, error: 'NOT_PARTNER', message: 'Register as a partner first.' };
  const saved = savePublicImage_(data, 'SwapSutra_Partner_Banners', 'banner_' + hit.obj.id + '_');
  if (!saved.success) return saved;
  setPartnerFields_(hit.rowIndex, partnerRows_().headers, { bannerImageUrl: saved.url, bannerStatus: 'PENDING', bannerNote: '', updatedAt: new Date() });
  try {
    returnNotify_('swapsutra@gmail.com', 'partner_banner', 'A partner banner to check',
      '"' + hit.obj.name + '" uploaded a new banner. Approve it in Management → Partners.', '', 'partner_banner_' + hit.obj.id + '_' + Date.now(), { whatsapp: false });
  } catch (e) { /* saved */ }
  return { success: true, url: saved.url, message: 'Banner uploaded. SwapSutra will check it before it goes on the Library page.' };
}

/** Action: savePartnerAd — a partner's own ad; it waits for the admin's approval. */
function savePartnerAd(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const hit = partnerByEmail_(caller);
  if (!hit || String(hit.obj.status) !== 'APPROVED') return { success: false, error: 'NOT_PARTNER', message: 'Only an approved partner can place ads.' };
  const p = hit.obj;
  const d = Object.assign({}, data || {});
  const all = adRows_();
  const id = String(d.id || '').trim();
  const mine = id ? all.rows.find(r => String(r.obj.id) === id && String(r.obj.partnerId) === String(p.id)) : null;
  if (id && !mine) return { success: false, message: 'That ad is not yours.' };
  const wanted = String(d.status || '').toLowerCase();
  if (mine && (wanted === 'removed' || wanted === 'paused')) {
    const sheet = adSheet_();
    sheet.getRange(mine.rowIndex + 1, all.headers.indexOf('status') + 1).setValue(wanted);
    return { success: true, id: id };
  }
  d.kind = p.type === 'author' ? 'author' : p.type === 'bookstore' ? 'bookstore' : (AD_KINDS.indexOf(String(d.kind)) !== -1 ? d.kind : 'book');
  d.sponsor = p.name;
  d.status = 'live'; // validated as a live ad; stored as pending below
  const v = validateSponsoredAd_(d);
  if (Object.keys(v.errors).length) return { success: false, errors: v.errors, message: 'Please fix the highlighted fields.' };
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const sheet = adSheet_();
    const headers = all.headers;
    const now = new Date().toISOString();
    const rec = mine ? Object.assign({}, mine.obj) : { id: 'AD-' + Utilities.getUuid().slice(0, 8).toUpperCase(), clicks: 0, createdAt: now, createdBy: caller, partnerId: p.id };
    Object.keys(v.clean).forEach(k => { rec[k] = v.clean[k]; });
    rec.status = 'pending';
    rec.reviewNote = '';
    rec.updatedAt = now;
    const row = headers.map(h => rec[h] !== undefined ? rec[h] : '');
    if (mine) sheet.getRange(mine.rowIndex + 1, 1, 1, row.length).setValues([row]);
    else sheet.appendRow(row);
    try {
      returnNotify_('swapsutra@gmail.com', 'partner_ad', 'A partner ad to approve',
        '"' + p.name + '" sent an ad: "' + rec.headline + '". Approve it in Management → Ads.', '', 'partner_ad_' + rec.id + '_' + Date.now(), { whatsapp: false });
    } catch (e) { /* saved */ }
    return { success: true, id: rec.id, message: 'Sent to SwapSutra for approval.' };
  } finally {
    lock.releaseLock();
  }
}

/** Action: submitPartnerAdPayment { utr, fileData } — ₹100 for 2 more months of promotion. */
function submitPartnerAdPayment(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  const hit = partnerByEmail_(caller);
  if (!hit || String(hit.obj.status) !== 'APPROVED') return { success: false, error: 'NOT_PARTNER', message: 'Only an approved partner can pay for promotion.' };
  const utr = String((data || {}).utr || '').trim().toUpperCase();
  if (!/^[A-Z0-9]{8,30}$/.test(utr)) return { success: false, errors: { utr: 'Enter the UTR / transaction reference (8–30 letters or digits).' }, message: 'Enter the UTR.' };
  const payments = partnerAdPayments_(hit.obj.id);
  if (payments.some(p => String(p.status) === 'SUBMITTED')) return { success: false, message: 'Your last payment is still being checked.' };
  if (payments.some(p => String(p.utr).toUpperCase() === utr)) return { success: false, errors: { utr: 'This UTR was already sent.' }, message: 'This UTR was already sent.' };
  let shot = '';
  if ((data || {}).fileData) {
    const saved = savePublicImage_({ dataUrl: data.fileData }, 'SwapSutra_Partner_Payments', 'adpay_' + hit.obj.id + '_');
    if (!saved.success) return saved;
    shot = saved.url;
  }
  const rec = { id: generateId('SS_ADPAY_'), partnerId: hit.obj.id, email: caller, amount: partnerAdFee_(), months: PARTNER_AD_PERIOD_MONTHS,
    utr: utr, screenshotUrl: shot, status: 'SUBMITTED', createdAt: new Date() };
  const sheet = partnerAdPaymentSheet_();
  const headers = ensureSheetHeaders(sheet, PARTNER_AD_PAYMENT_HEADERS);
  sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  try {
    returnNotify_('swapsutra@gmail.com', 'partner_ad_payment', 'A partner paid for promotion',
      '"' + hit.obj.name + '" paid ₹' + rec.amount + ' (UTR ' + utr + '). Verify it in Management → Partners.', '', 'partner_adpay_' + rec.id, { whatsapp: false });
  } catch (e) { /* saved */ }
  return { success: true, message: 'Payment sent. SwapSutra will verify it, usually within a day.' };
}

/** Action: setPartnerBookStock { bookId, stock } — how many copies a partner has. */
function setPartnerBookStock(data) {
  const caller = normalizeEmail(getAuthenticatedEmail());
  if (!approvedPartner_(caller)) return { success: false, error: 'NOT_PARTNER', message: 'Only an approved partner keeps stock counts.' };
  const stock = Math.floor(Number((data || {}).stock));
  if (!isFinite(stock) || stock < 0 || stock > 9999) return { success: false, message: 'Stock must be a number from 0 to 9999.' };
  const sheet = getOrCreateSheet('Books', getBookHeaders());
  const headers = ensureSheetHeaders(sheet, getBookHeaders());
  const values = sheet.getDataRange().getValues();
  const id = String((data || {}).bookId || '');
  for (let r = 1; r < values.length; r++) {
    if (String(values[r][headers.indexOf('id')]) !== id) continue;
    if (normalizeEmail(values[r][headers.indexOf('ownerEmail')]) !== caller) return { success: false, message: 'That book is not yours.' };
    sheet.getRange(r + 1, headers.indexOf('stock') + 1).setValue(stock);
    try { invalidateLibraryCache(); } catch (e) { /* cache refreshes on its own */ }
    return { success: true, stock: stock, message: stock ? stock + ' in stock.' : 'Out of stock — it no longer shows in the Library.' };
  }
  return { success: false, message: 'Book not found.' };
}

/** One copy sold: a partner's stock goes down by one (never below 0). */
function decrementPartnerStock_(bookId, ownerEmail) {
  if (!bookId || !approvedPartner_(ownerEmail)) return;
  try {
    const sheet = getOrCreateSheet('Books', getBookHeaders());
    const headers = ensureSheetHeaders(sheet, getBookHeaders());
    const values = sheet.getDataRange().getValues();
    for (let r = 1; r < values.length; r++) {
      if (String(values[r][headers.indexOf('id')]) !== String(bookId)) continue;
      const cur = values[r][headers.indexOf('stock')];
      const n = cur === '' || cur === undefined ? 1 : Number(cur) || 0;
      sheet.getRange(r + 1, headers.indexOf('stock') + 1).setValue(Math.max(0, n - 1));
      try { invalidateLibraryCache(); } catch (e) { /* ignore */ }
      return;
    }
  } catch (e) { Logger.log('decrementPartnerStock_ failed: ' + e); }
}

/**
 * The payout rows for a partner (sale or rent): the partner's net, SwapSutra's
 * commission kept, and the month it is paid in. Used by the sale and rent paths.
 */
function partnerPayoutParts_(ownerEmail, gross, at) {
  const partner = approvedPartner_(ownerEmail);
  if (!partner) return null;
  const c = partnerCommissionFor_(partner, gross, at);
  return { partner: partner, rate: c.rate, commission: c.commission, net: Math.round((gross - c.commission) * 100) / 100, cycle: istMonth_(at || new Date()) };
}
function appendCommissionRow_(sheet, headers, swapId, title, partnerEmail, amount, cycle, note) {
  if (!(amount > 0)) return null;
  const rec = { id: generateId('SS_COMMISSION_'), swapId: swapId, leg: 'commission', bookTitle: title, defaulterEmail: normalizeEmail(partnerEmail),
    ownerEmail: 'swapsutra@gmail.com', amount: amount, dueAt: '', forfeitedAt: new Date(), payoutStatus: 'KEPT_AS_FEE', payoutCycle: cycle, note: note };
  sheet.appendRow(headers.map(k => rec[k] !== undefined ? rec[k] : ''));
  return rec;
}

// ── Admin ─────────────────────────────────────────────────────────────────
function adminListPartners() {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const payments = partnerAdPayments_();
  const items = partnerRows_().rows.map(r => r.obj).map(p => {
    const v = partnerPublicView_(p, true);
    const mine = payments.filter(x => String(x.partnerId) === String(p.id));
    v.promotion = partnerPromotionState_(p, mine);
    v.payoutAccount = readPayoutAccount_(p.email);
    return v;
  }).reverse();
  const pendingPayments = payments.filter(p => String(p.status) === 'SUBMITTED').map(x => ({
    id: x.id, partnerId: x.partnerId, email: x.email, amount: Number(x.amount || 0), utr: x.utr, screenshotUrl: x.screenshotUrl,
    createdAt: x.createdAt ? new Date(x.createdAt).toISOString() : '',
    partnerName: ((partnerRows_().rows.find(r => String(r.obj.id) === String(x.partnerId)) || {}).obj || {}).name || ''
  }));
  return { success: true, items: items, pendingPayments: pendingPayments, monthly: adminPartnerMonthly_(),
    commissionPercent: partnerCommissionRate_() * 100, adFee: partnerAdFee_(), adMonths: PARTNER_AD_PERIOD_MONTHS };
}

/** Monthly statements per partner: due after the month ends. */
function adminPartnerMonthly_() {
  const rows = readSheetObjects_(getReturnForfeitSheet_()).rows.map(r => r.obj).filter(f => f.payoutCycle && ['sale', 'rent'].indexOf(String(f.leg)) !== -1);
  const groups = {};
  rows.forEach(f => {
    const key = normalizeEmail(f.ownerEmail) + '|' + f.payoutCycle;
    const g = groups[key] = groups[key] || { email: normalizeEmail(f.ownerEmail), month: String(f.payoutCycle), net: 0, due: 0, paid: 0, items: 0 };
    g.net += Number(f.amount || 0); g.items++;
    if (String(f.payoutStatus) === 'TO_PAY_OWNER') g.due += Number(f.amount || 0); else if (String(f.payoutStatus) === 'PAID_TO_OWNER') g.paid += Number(f.amount || 0);
  });
  const thisMonth = istMonth_(new Date());
  return Object.keys(groups).map(k => {
    const g = groups[k];
    const p = approvedPartner_(g.email) || ((partnerByEmail_(g.email) || {}).obj) || {};
    g.partnerName = p.name || g.email; g.partnerId = p.id || '';
    g.payable = g.month < thisMonth; // a month is paid after it ends
    g.payTo = readPayoutAccount_(g.email);
    ['net', 'due', 'paid'].forEach(x => { g[x] = Math.round(g[x] * 100) / 100; });
    return g;
  }).sort((a, b) => (a.month < b.month ? 1 : -1));
}

/** Admin action: adminReviewPartner { id, decision, note } */
function adminReviewPartner(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const d = data || {};
  const t = partnerRows_();
  const hit = t.rows.find(r => String(r.obj.id) === String(d.id));
  if (!hit) return { success: false, message: 'Partner not found.' };
  const p = hit.obj;
  const decision = String(d.decision || '');
  const note = cleanPartnerText_(d.note, 400);
  const now = new Date();
  const admin = normalizeEmail(getAuthenticatedEmail());
  const fields = { updatedAt: now };
  let title = '', body = '';
  if (decision === 'approve' || decision === 'approve_free_year') {
    if (['PENDING', 'CHANGES_REQUESTED', 'REJECTED'].indexOf(String(p.status)) === -1) return { success: false, message: 'Only an application waiting for review can be approved.' };
    fields.status = 'APPROVED'; fields.approvedAt = now; fields.approvedBy = admin; fields.reviewNote = '';
    fields.adsFreeUntil = addMonths_(now, PARTNER_FREE_PROMO_MONTHS);
    fields.commissionPlan = decision === 'approve_free_year' ? 'free_first_year' : 'standard';
    fields.commissionFreeUntil = decision === 'approve_free_year' ? addMonths_(now, PARTNER_FREE_COMMISSION_MONTHS) : '';
    ensurePartnerUserRow_(p);
    title = 'You are a SwapSutra partner';
    body = 'Welcome! "' + p.name + '" is approved. List as many books as you like, and your banner and ads are free until ' + returnDateLabel_(fields.adsFreeUntil) + '. ' +
      (decision === 'approve_free_year' ? 'No commission for your first year (until ' + returnDateLabel_(fields.commissionFreeUntil) + '); after that SwapSutra keeps ' + (partnerCommissionRate_() * 100) + '% of payouts.'
        : 'SwapSutra keeps ' + (partnerCommissionRate_() * 100) + '% of each payout; payouts are made monthly.');
  } else if (decision === 'request_changes') {
    if (!note) return { success: false, message: 'Say what needs to change.' };
    fields.status = 'CHANGES_REQUESTED'; fields.reviewNote = note;
    title = 'Please update your partner application'; body = 'SwapSutra needs a change before approving "' + p.name + '": ' + note;
  } else if (decision === 'reject') {
    if (!note) return { success: false, message: 'Give a reason.' };
    fields.status = 'REJECTED'; fields.reviewNote = note;
    title = 'Your partner application'; body = 'SwapSutra could not approve "' + p.name + '": ' + note;
  } else if (decision === 'suspend') {
    if (String(p.status) !== 'APPROVED') return { success: false, message: 'Only an approved partner can be paused.' };
    fields.status = 'SUSPENDED'; fields.reviewNote = note;
    title = 'Your partner account is paused'; body = '"' + p.name + '" is paused' + (note ? ': ' + note : '.');
  } else if (decision === 'reinstate') {
    if (String(p.status) !== 'SUSPENDED') return { success: false, message: 'Only a paused partner can be reinstated.' };
    fields.status = 'APPROVED'; fields.reviewNote = '';
    title = 'Your partner account is active again'; body = '"' + p.name + '" is active on SwapSutra again.';
  } else if (decision === 'plan_standard' || decision === 'plan_free_year') {
    if (String(p.status) !== 'APPROVED') return { success: false, message: 'Change the plan of an approved partner.' };
    const from = p.approvedAt ? new Date(p.approvedAt) : now;
    fields.commissionPlan = decision === 'plan_free_year' ? 'free_first_year' : 'standard';
    fields.commissionFreeUntil = decision === 'plan_free_year' ? addMonths_(from, PARTNER_FREE_COMMISSION_MONTHS) : '';
  } else {
    return { success: false, message: 'Unknown decision.' };
  }
  setPartnerFields_(hit.rowIndex, t.headers, fields);
  if (title) {
    try {
      returnNotify_(p.email, 'partner_review', title, body, '', 'partner_review_' + p.id + '_' + decision + '_' + now.getTime());
      sendSwapSutraEmail({ to: p.email, subject: title, body: body + '\n\nYour partner dashboard: ' + BASE_APP_URL + '/partners' });
    } catch (e) { /* the decision is saved */ }
  }
  return { success: true };
}

/** An approved partner gets a member row so they can sign in, list and sell. */
function ensurePartnerUserRow_(p) {
  const email = normalizeEmail(p.email);
  if (!email || emailExistsInUsersSheet(email)) return;
  const headers = ["id", "name", "email", "phone", "area", "pincode", "genres", "bio", "membershipStatus", "paymentStatus", "createdAt", "updatedAt"];
  const sheet = getOrCreateSheet('Users', headers);
  const h = ensureSheetHeaders(sheet, headers);
  const rec = { id: generateId('SS_USER_'), name: p.name, email: email, phone: p.phone, area: p.city, pincode: p.pincode, genres: '',
    bio: PARTNER_TYPE_LABEL[p.type] + ' on SwapSutra', membershipStatus: 'PARTNER', paymentStatus: 'Not required', createdAt: new Date(), updatedAt: new Date() };
  sheet.appendRow(h.map(k => rec[k] !== undefined ? rec[k] : ''));
}

/** Admin action: adminReviewPartnerBanner { id, approve, note } */
function adminReviewPartnerBanner(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const t = partnerRows_();
  const hit = t.rows.find(r => String(r.obj.id) === String((data || {}).id));
  if (!hit) return { success: false, message: 'Partner not found.' };
  const approve = truthy_((data || {}).approve);
  const note = cleanPartnerText_((data || {}).note, 300);
  if (!approve && !note) return { success: false, message: 'Say what needs to change.' };
  setPartnerFields_(hit.rowIndex, t.headers, { bannerStatus: approve ? 'APPROVED' : 'REJECTED', bannerNote: approve ? '' : note, updatedAt: new Date() });
  try {
    returnNotify_(hit.obj.email, 'partner_banner_review', approve ? 'Your banner is live' : 'Your banner needs a change',
      approve ? 'Your banner now shows on the SwapSutra Library page.' : 'SwapSutra could not use your banner: ' + note, '', 'partner_banner_rev_' + hit.obj.id + '_' + Date.now());
  } catch (e) { /* saved */ }
  return { success: true };
}

/** Admin action: adminReviewPartnerAdPayment { id, approve, reason } — a verified payment adds 2 months. */
function adminReviewPartnerAdPayment(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const sheet = partnerAdPaymentSheet_();
  const t = readSheetObjects_(sheet);
  const hit = t.rows.find(r => String(r.obj.id) === String((data || {}).id));
  if (!hit) return { success: false, message: 'Payment not found.' };
  if (String(hit.obj.status) !== 'SUBMITTED') return { success: false, message: 'This payment was already reviewed.' };
  const partnerHit = partnerRows_().rows.find(r => String(r.obj.id) === String(hit.obj.partnerId));
  if (!partnerHit) return { success: false, message: 'Partner not found.' };
  const approve = truthy_((data || {}).approve);
  const reason = cleanPartnerText_((data || {}).reason, 300);
  if (!approve && !reason) return { success: false, message: 'Give a reason.' };
  const now = new Date();
  const set = (k, v) => { const i = t.headers.indexOf(k); if (i !== -1) sheet.getRange(hit.rowIndex + 1, i + 1).setValue(v); };
  set('status', approve ? 'APPROVED' : 'REJECTED'); set('reviewedBy', normalizeEmail(getAuthenticatedEmail())); set('reviewedAt', now); set('reason', reason);
  let to = null;
  if (approve) {
    // The 2 months start when the current promotion ends (or today, if it has ended).
    const promo = partnerPromotionState_(partnerHit.obj, partnerAdPayments_(partnerHit.obj.id).filter(p => String(p.id) !== String(hit.obj.id)));
    const from = promo.activeUntil && new Date(promo.activeUntil) > now ? new Date(promo.activeUntil) : now;
    to = addMonths_(from, Number(hit.obj.months) || PARTNER_AD_PERIOD_MONTHS);
    set('periodFrom', from); set('periodTo', to);
  }
  try {
    returnNotify_(partnerHit.obj.email, 'partner_ad_payment_review', approve ? 'Promotion extended' : 'Payment not verified',
      approve ? 'Thank you — your banner and ads run until ' + returnDateLabel_(to) + '.' : 'SwapSutra could not verify your ₹' + hit.obj.amount + ' payment: ' + reason,
      '', 'partner_adpay_rev_' + hit.obj.id);
  } catch (e) { /* saved */ }
  return { success: true, periodTo: to ? to.toISOString() : '' };
}

/** Admin action: adminMarkPartnerMonthPaid { email, month, note } — pays a partner's whole month. */
function adminMarkPartnerMonthPaid(data) {
  if (!isAuthenticatedAdmin()) return { success: false, error: 'ADMIN_ONLY', message: 'Admins only.' };
  const email = normalizeEmail((data || {}).email);
  const month = String((data || {}).month || '');
  if (!email || !/^\d{4}-\d{2}$/.test(month)) return { success: false, message: 'Pick a partner and a month.' };
  if (month >= istMonth_(new Date())) return { success: false, message: 'A month is paid after it ends.' };
  const sheet = getReturnForfeitSheet_();
  const t = readSheetObjects_(sheet);
  const rows = t.rows.filter(r => r.obj.payoutCycle === month && normalizeEmail(r.obj.ownerEmail) === email
    && ['sale', 'rent'].indexOf(String(r.obj.leg)) !== -1 && String(r.obj.payoutStatus) === 'TO_PAY_OWNER');
  if (!rows.length) return { success: false, message: 'Nothing is due for that month.' };
  const now = new Date();
  const admin = normalizeEmail(getAuthenticatedEmail());
  const note = String((data || {}).note || '').slice(0, 200);
  let total = 0;
  rows.forEach(r => {
    const set = (k, v) => { const i = t.headers.indexOf(k); if (i !== -1) sheet.getRange(r.rowIndex + 1, i + 1).setValue(v); };
    set('payoutStatus', 'PAID_TO_OWNER'); set('paidAt', now); set('paidBy', admin);
    if (note) set('note', String(r.obj.note || '') + ' Paid: ' + note);
    total += Number(r.obj.amount || 0);
  });
  total = Math.round(total * 100) / 100;
  try {
    returnNotify_(email, 'partner_month_paid', 'SwapSutra has paid you ₹' + total,
      'Your payout for ' + month + ' (' + rows.length + ' order' + (rows.length === 1 ? '' : 's') + ', after commission) has been sent.', '', 'partner_paid_' + email + '_' + month);
  } catch (e) { /* saved */ }
  return { success: true, total: total, count: rows.length };
}

/** Partner banners for the Library banner (approved, chosen, promotion running). */
function partnerBannerAds_() {
  const out = [];
  try {
    partnerRows_().rows.map(r => r.obj).forEach(p => {
      if (String(p.status) !== 'APPROVED' || String(p.bannerStatus) !== 'APPROVED' || !p.bannerImageUrl) return;
      if (!partnerPromotionLive_(p, 'banner')) return;
      const link = /^https:\/\//i.test(String(p.website || '')) ? String(p.website)
        : (p.lat !== '' && p.lng !== '' && isFinite(Number(p.lat)) ? 'https://www.google.com/maps/search/?api=1&query=' + Number(p.lat) + ',' + Number(p.lng) : '');
      if (!link) return;
      out.push({ id: 'PB-' + p.id, kind: p.type === 'author' ? 'author' : p.type === 'bookstore' ? 'bookstore' : 'book', sponsor: mugText_(p.name, 80),
        headline: mugText_(p.bannerHeadline || p.name, 90), tagline: mugText_(p.bannerTagline || (p.city ? PARTNER_TYPE_LABEL[p.type] + ' · ' + p.city : ''), 160),
        imageUrl: String(p.bannerImageUrl), linkUrl: link, bookId: '', ctaLabel: p.type === 'bookstore' && !p.website ? 'Find the store' : '',
        placement: 'banner', partner: true, partnerType: p.type });
    });
  } catch (e) { Logger.log('partnerBannerAds_ failed: ' + e); }
  return out;
}

/** Revenue from partners: promotion fees verified, commission kept. */
function partnerRevenue_() {
  let adFees = 0, adPayments = 0, commission = 0;
  try {
    partnerAdPayments_().forEach(p => { if (String(p.status) === 'APPROVED') { adFees += Number(p.amount || 0); adPayments++; } });
    readSheetObjects_(getReturnForfeitSheet_()).rows.forEach(r => { if (String(r.obj.leg) === 'commission') commission += Number(r.obj.amount || 0); });
  } catch (e) { /* no sheets yet */ }
  return { partnerAdFees: adFees, partnerAdPayments: adPayments, partnerCommission: Math.round(commission * 100) / 100 };
}
